// update-meal-course.mjs — run from the analytix360 root:  node update-meal-course.mjs
// Adds the MEAL Professional Certificate course to the course player (/learn/meal):
// 6 modules, 24 lessons, a Beginner → Expert practice lab and a quiz per module, the new
// XLSForm lab (KoboToolbox / ODK form builder with live preview), intro videos in EN/FR and
// French for everything. Also renames catalogue Module 5 to "Data Analysis with Excel, SPSS and Stata".
// All-or-nothing: if any check fails, nothing is written.
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { dirname } from "path";
const fail = (m) => { console.error("STOPPED, nothing written: " + m); process.exit(1); };
if (!existsSync("client/src/lms/registry.ts")) fail("client/src/lms/registry.ts not found — run this from the analytix360 folder");
if (!existsSync("client/src/lms/labs/FormLab.tsx")) fail("run update-mosp-practice.mjs first (the Practice exercise lab type is needed)");
const TEXT = {"client/src/lms/labs/xpath.ts":"// A small evaluator for the XPath subset used in XLSForm (KoboToolbox, ODK, SurveyCTO):\n// ${field} references, \".\" for the current answer, and / or / not(), = != < <= > >=,\n// + - * div mod, and the functions selected(), count-selected(), string-length(), regex(),\n// if(), coalesce(), concat(), int(), number(), round(), true(), false().\n// Answers are strings (\"\" when empty); select_multiple answers are space-separated choice names.\n\nexport type XVal = string | number | boolean;\nexport type XEnv = { get: (name: string) => string; self?: string };\n\ntype Tok = { t: \"num\"; v: number } | { t: \"str\"; v: string } | { t: \"ref\"; v: string } | { t: \"dot\" } | { t: \"id\"; v: string } | { t: \"op\"; v: string };\n\nexport class XPathError extends Error {}\n\nfunction tokenize(src: string): Tok[] {\n  const out: Tok[] = [];\n  let i = 0;\n  while (i < src.length) {\n    const c = src[i] ?? \"\";\n    if (/\\s/.test(c)) { i++; continue; }\n    if (c === \"$\" && src[i + 1] === \"{\") {\n      const j = src.indexOf(\"}\", i);\n      if (j < 0) throw new XPathError(\"Missing } after ${\");\n      out.push({ t: \"ref\", v: src.slice(i + 2, j).trim() }); i = j + 1; continue;\n    }\n    if (c === \"'\" || c === '\"' || c === \"‘\" || c === \"’\" || c === \"“\" || c === \"”\") {\n      const close = c === \"‘\" || c === \"’\" ? /['’‘]/ : c === \"“\" || c === \"”\" ? /[\"”“]/ : new RegExp(c);\n      let j = i + 1; while (j < src.length && !close.test(src[j] ?? \"\")) j++;\n      if (j >= src.length) throw new XPathError(\"Missing closing quote\");\n      out.push({ t: \"str\", v: src.slice(i + 1, j) }); i = j + 1; continue;\n    }\n    const num = src.slice(i).match(/^\\d+(\\.\\d+)?/);\n    if (num) { out.push({ t: \"num\", v: Number(num[0]) }); i += num[0].length; continue; }\n    if (c === \".\" && !/\\d/.test(src[i + 1] ?? \"\")) { out.push({ t: \"dot\" }); i++; continue; }\n    const id = src.slice(i).match(/^[A-Za-z_][A-Za-z0-9_-]*/);\n    if (id) { out.push({ t: \"id\", v: id[0] }); i += id[0].length; continue; }\n    const two = src.slice(i, i + 2);\n    if ([\"!=\", \"<=\", \">=\"].includes(two)) { out.push({ t: \"op\", v: two }); i += 2; continue; }\n    if (\"=<>+-*(),\".includes(c)) { out.push({ t: \"op\", v: c }); i++; continue; }\n    throw new XPathError(`Unexpected character \"${c}\"`);\n  }\n  return out;\n}\n\ntype Node =\n  | { k: \"lit\"; v: XVal } | { k: \"ref\"; name: string } | { k: \"dot\" }\n  | { k: \"bin\"; op: string; a: Node; b: Node } | { k: \"neg\"; x: Node } | { k: \"fn\"; name: string; args: Node[] };\n\nexport function parse(src: string): Node {\n  const toks = tokenize(src);\n  let p = 0;\n  const peek = () => toks[p];\n  const isOp = (v: string) => { const t = peek(); return !!t && t.t === \"op\" && t.v === v; };\n  const expect = (v: string) => { if (!isOp(v)) throw new XPathError(`Expected \"${v}\"`); p++; };\n  const bin = (next: () => Node, ops: string[], words: string[] = []): Node => {\n    let a = next();\n    for (;;) {\n      const t = peek();\n      if (t && t.t === \"op\" && ops.includes(t.v)) { p++; a = { k: \"bin\", op: t.v, a, b: next() }; continue; }\n      if (t && t.t === \"id\" && words.includes(t.v)) { p++; a = { k: \"bin\", op: t.v, a, b: next() }; continue; }\n      return a;\n    }\n  };\n  const or = (): Node => bin(and, [], [\"or\"]);\n  const and = (): Node => bin(cmp, [], [\"and\"]);\n  const cmp = (): Node => bin(add, [\"=\", \"!=\", \"<\", \"<=\", \">\", \">=\"]);\n  const add = (): Node => bin(mul, [\"+\", \"-\"]);\n  const mul = (): Node => bin(unary, [\"*\"], [\"div\", \"mod\"]);\n  const unary = (): Node => (isOp(\"-\") ? (p++, { k: \"neg\", x: unary() }) : primary());\n  const primary = (): Node => {\n    const t = peek();\n    if (!t) throw new XPathError(\"The formula ends too early\");\n    p++;\n    if (t.t === \"num\") return { k: \"lit\", v: t.v };\n    if (t.t === \"str\") return { k: \"lit\", v: t.v };\n    if (t.t === \"ref\") return { k: \"ref\", name: t.v };\n    if (t.t === \"dot\") return { k: \"dot\" };\n    if (t.t === \"op\" && t.v === \"(\") { const e = or(); expect(\")\"); return e; }\n    if (t.t === \"id\" && isOp(\"(\")) {\n      p++;\n      const args: Node[] = [];\n      if (!isOp(\")\")) { args.push(or()); while (isOp(\",\")) { p++; args.push(or()); } }\n      expect(\")\");\n      return { k: \"fn\", name: t.v, args };\n    }\n    if (t.t === \"id\" && (t.v === \"true\" || t.v === \"false\")) return { k: \"lit\", v: t.v === \"true\" };\n    throw new XPathError(t.t === \"id\" ? `Unknown word \"${t.v}\" (field names are written \\${name})` : \"Unexpected symbol\");\n  };\n  if (!toks.length) throw new XPathError(\"Empty formula\");\n  const e = or();\n  if (p !== toks.length) throw new XPathError(\"Unexpected text after the formula\");\n  return e;\n}\n\nconst num = (v: XVal): number => (typeof v === \"number\" ? v : typeof v === \"boolean\" ? (v ? 1 : 0) : v.trim() === \"\" ? NaN : Number(v));\nconst str = (v: XVal): string => (typeof v === \"string\" ? v : typeof v === \"boolean\" ? (v ? \"true\" : \"false\") : Number.isNaN(v) ? \"\" : String(v));\nexport const truthy = (v: XVal): boolean => (typeof v === \"boolean\" ? v : typeof v === \"number\" ? v !== 0 && !Number.isNaN(v) : v !== \"\");\n\nconst FNS: Record<string, (a: XVal[]) => XVal> = {\n  selected: (a) => str(a[0] ?? \"\").split(/\\s+/).includes(str(a[1] ?? \"\")),\n  \"count-selected\": (a) => str(a[0] ?? \"\").split(/\\s+/).filter(Boolean).length,\n  \"string-length\": (a) => str(a[0] ?? \"\").length,\n  not: (a) => !truthy(a[0] ?? false),\n  regex: (a) => { try { return new RegExp(str(a[1] ?? \"\")).test(str(a[0] ?? \"\")); } catch { return false; } },\n  if: (a) => (truthy(a[0] ?? false) ? (a[1] ?? \"\") : (a[2] ?? \"\")),\n  coalesce: (a) => (str(a[0] ?? \"\") !== \"\" ? (a[0] ?? \"\") : (a[1] ?? \"\")),\n  concat: (a) => a.map(str).join(\"\"),\n  int: (a) => Math.trunc(num(a[0] ?? NaN)),\n  number: (a) => num(a[0] ?? NaN),\n  round: (a) => { const f = 10 ** num(a[1] ?? 0); return Math.round(num(a[0] ?? NaN) * f) / f; },\n  true: () => true,\n  false: () => false,\n};\n\nexport function evaluate(n: Node, env: XEnv): XVal {\n  switch (n.k) {\n    case \"lit\": return n.v;\n    case \"ref\": return env.get(n.name);\n    case \"dot\": return env.self ?? \"\";\n    case \"neg\": return -num(evaluate(n.x, env));\n    case \"fn\": {\n      const f = FNS[n.name];\n      if (!f) throw new XPathError(`Unknown function ${n.name}()`);\n      return f(n.args.map((a) => evaluate(a, env)));\n    }\n    case \"bin\": {\n      if (n.op === \"or\") return truthy(evaluate(n.a, env)) || truthy(evaluate(n.b, env));\n      if (n.op === \"and\") return truthy(evaluate(n.a, env)) && truthy(evaluate(n.b, env));\n      const a = evaluate(n.a, env), b = evaluate(n.b, env);\n      if ([\"+\", \"-\", \"*\", \"div\", \"mod\"].includes(n.op)) {\n        const x = num(a), y = num(b);\n        return n.op === \"+\" ? x + y : n.op === \"-\" ? x - y : n.op === \"*\" ? x * y : n.op === \"div\" ? x / y : x % y;\n      }\n      // Comparisons: numeric when either side is a number (or both look numeric), otherwise text.\n      const numeric = typeof a === \"number\" || typeof b === \"number\" || typeof a === \"boolean\" || typeof b === \"boolean\";\n      if (n.op === \"=\" || n.op === \"!=\") {\n        const eq = numeric ? num(a) === num(b) : str(a) === str(b);\n        return n.op === \"=\" ? eq : !eq;\n      }\n      const x = num(a), y = num(b);\n      if (Number.isNaN(x) || Number.isNaN(y)) return false;\n      return n.op === \"<\" ? x < y : n.op === \"<=\" ? x <= y : n.op === \">\" ? x > y : x >= y;\n    }\n  }\n}\n\n/** Field names referenced as ${name}. */\nexport function refsOf(src: string): string[] {\n  return [...new Set([...src.matchAll(/\\$\\{\\s*([^}\\s]+)\\s*\\}/g)].map((m) => m[1] ?? \"\"))];\n}\n/** Literal numbers and strings in an expression (used to build test values). */\nexport function literalsOf(src: string): { nums: number[]; strs: string[] } {\n  const nums = [...src.matchAll(/(?<![\\w$])(\\d+(?:\\.\\d+)?)/g)].map((m) => Number(m[1]));\n  const strs = [...src.matchAll(/['\"‘’“”]([^'\"‘’“”]*)['\"‘’“”]/g)].map((m) => m[1] ?? \"\");\n  return { nums, strs };\n}\n\nexport function safeEval(src: string, env: XEnv): { ok: true; v: XVal } | { ok: false; error: string } {\n  try { return { ok: true, v: evaluate(parse(src), env) }; } catch (e) { return { ok: false, error: e instanceof Error ? e.message : String(e) }; }\n}\n","client/src/lms/labs/xlsform.ts":"import type { XlsCheck, XlsChoice, XlsRow } from \"../types\";\nimport { literalsOf, parse, refsOf, safeEval, truthy, type XEnv, type XVal } from \"./xpath\";\n\n// Form model shared by the XLSForm lab: question types, visibility (relevant), calculations,\n// constraints, and the checker that compares a learner's formula with the expected one by\n// evaluating both over many combinations of answers (so \"${age} >= 18\" = \"18 <= ${age}\").\n\nexport const norm = (s = \"\") => s.trim().replace(/\\s+/g, \" \").toLowerCase();\nexport const baseType = (row: XlsRow) => norm(row.type).replace(/^begin group$/, \"begin_group\").replace(/^end group$/, \"end_group\").split(\" \")[0] ?? \"\";\nexport const listOf = (row: XlsRow) => norm(row.type).split(\" \")[1] ?? \"\";\nexport const isRequired = (v = \"\") => /^(yes|true|true\\(\\))$/i.test(v.trim());\nexport const QUESTION_TYPES = [\"text\", \"integer\", \"decimal\", \"select_one\", \"select_multiple\", \"date\", \"note\", \"calculate\", \"geopoint\", \"image\", \"begin_group\", \"end_group\"];\n\nexport type Values = Record<string, string>;\n\n/** Which rows are visible, and the value of every field (answers + calculations; hidden fields count as empty). */\nexport function runForm(rows: XlsRow[], answers: Values) {\n  const values: Values = {};\n  const visible: boolean[] = [];\n  const errors: (string | null)[] = [];\n  const stack: boolean[] = [];\n  const env: XEnv = { get: (n) => values[n] ?? \"\" };\n  rows.forEach((r, i) => {\n    const t = baseType(r);\n    const inGroup = stack.every(Boolean);\n    let rel = true, err: string | null = null;\n    if ((r.relevant ?? \"\").trim()) { const e = safeEval(r.relevant ?? \"\", env); if (e.ok) rel = truthy(e.v); else { err = e.error; rel = true; } }\n    if (t === \"end_group\") { stack.pop(); visible[i] = false; errors[i] = null; return; }\n    if (t === \"begin_group\") { stack.push(inGroup && rel); visible[i] = inGroup && rel; errors[i] = err; return; }\n    const show = inGroup && rel;\n    visible[i] = show && t !== \"calculate\";\n    const name = (r.name ?? \"\").trim();\n    if (t === \"calculate\") {\n      const e = safeEval(r.calculation ?? \"\", env);\n      if (e.ok) values[name] = show ? toStr(e.v) : \"\"; else { values[name] = \"\"; err = err ?? e.error; }\n    } else if (name) values[name] = show ? answers[name] ?? \"\" : \"\";\n    errors[i] = err;\n  });\n  return { values, visible, errors };\n}\n\nconst toStr = (v: XVal) => (typeof v === \"boolean\" ? (v ? \"true\" : \"false\") : typeof v === \"number\" ? (Number.isNaN(v) ? \"\" : String(Math.round(v * 1e6) / 1e6)) : v);\n\n/** true / false / message when the answer breaks the constraint. */\nexport function constraintOk(row: XlsRow, value: string, values: Values): { ok: boolean; error?: string } {\n  const c = (row.constraint ?? \"\").trim();\n  if (!c || value === \"\") return { ok: true };\n  const e = safeEval(c, { get: (n) => values[n] ?? \"\", self: value });\n  if (!e.ok) return { ok: true, error: e.error };\n  return { ok: truthy(e.v) };\n}\n\n// ── Equivalence checking ────────────────────────────────────────────────────\nfunction domain(row: XlsRow | undefined, choices: XlsChoice[], lits: { nums: number[]; strs: string[] }): string[] {\n  const t = row ? baseType(row) : \"text\";\n  const names = choices.filter((c) => norm(c.list_name) === listOf(row ?? {})).map((c) => c.name.trim());\n  const numbers = () => {\n    const s = new Set<number>([0, 1, 25, 999, -1]);\n    for (const n of lits.nums) { s.add(n - 1); s.add(n); s.add(n + 1); s.add(n - 0.5); }\n    return [\"\", ...[...s].map(String)];\n  };\n  if (t === \"select_one\") return [\"\", ...names];\n  if (t === \"select_multiple\") return [\"\", ...names, names.slice(0, 2).join(\" \"), names.slice(1, 3).join(\" \"), names.join(\" \")].filter((v, i, a) => a.indexOf(v) === i);\n  if (t === \"integer\" || t === \"decimal\" || t === \"calculate\" || t === \"range\") return numbers();\n  if (t === \"date\") return [\"\", \"2026-01-15\"];\n  // Text answers: include phone-like and code-like values so regex() constraints are really tested.\n  return [\"\", \"abc\", \"612345678\", \"699001122\", \"712345678\", \"61234567\", \"6123456789\", \"6 12 34 56 78\", \"+237612345678\", \"AB-123\", ...lits.strs, ...numbers().slice(1, 4)].filter((v, i, a) => a.indexOf(v) === i);\n}\n\nfunction combos(domains: string[][], cap = 600): string[][] {\n  const total = domains.reduce((n, d) => n * Math.max(1, d.length), 1);\n  const out: string[][] = [];\n  if (total <= cap) {\n    const rec = (i: number, acc: string[]) => { if (i === domains.length) { out.push(acc); return; } for (const v of domains[i] ?? [\"\"]) rec(i + 1, [...acc, v]); };\n    rec(0, []);\n    return out;\n  }\n  let seed = 7;\n  const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };\n  for (let k = 0; k < cap; k++) out.push(domains.map((d) => d[rnd(d.length)] ?? \"\"));\n  return out;\n}\n\n/** Do two expressions behave the same for every tested combination of answers? */\nexport function sameLogic(mine: string, expected: string, rows: XlsRow[], choices: XlsChoice[], opts: { self?: XlsRow; asValue?: boolean } = {}): { ok: boolean; why?: string } {\n  const a = mine.trim(), b = expected.trim();\n  if (!a && !b) return { ok: true };\n  if (!a) return { ok: false, why: \"empty\" };\n  try { parse(a); } catch (e) { return { ok: false, why: e instanceof Error ? e.message : \"formula error\" }; }\n  const byName = new Map(rows.map((r) => [(r.name ?? \"\").trim(), r]));\n  const refs = [...new Set([...refsOf(a), ...refsOf(b)])];\n  const unknown = refsOf(a).filter((r) => !byName.has(r));\n  if (unknown.length) return { ok: false, why: `no question named ${unknown.join(\", \")}` };\n  const lits = literalsOf(a + \" \" + b);\n  const usesSelf = /(^|[^.\\w])\\.(?![\\w.])/.test(a + \" \" + b);\n  const vars = [...refs, ...(usesSelf ? [\".\"] : [])];\n  // ODK never checks a constraint on an empty answer, so \".\" is only tested with real values.\n  const domains = vars.map((v) => (v === \".\" ? domain(opts.self, choices, lits).filter((x) => x !== \"\") : domain(byName.get(v), choices, lits)));\n  for (const combo of combos(domains)) {\n    const vals: Record<string, string> = {};\n    vars.forEach((v, i) => { vals[v] = combo[i] ?? \"\"; });\n    // A calculation is only judged when every answer it uses is filled in (ODK recalculates once answers exist).\n    if (opts.asValue && vars.some((v) => (vals[v] ?? \"\") === \"\")) continue;\n    const env: XEnv = { get: (n) => vals[n] ?? \"\", self: vals[\".\"] ?? \"\" };\n    const x = safeEval(a, env), y = safeEval(b, env);\n    if (!x.ok) return { ok: false, why: x.error };\n    if (!y.ok) continue;\n    const same = opts.asValue ? toStr(x.v) === toStr(y.v) : truthy(x.v) === truthy(y.v);\n    if (!same) return { ok: false, why: \"gives a different result for some answers\" };\n  }\n  return { ok: true };\n}\n\nexport function runCheck(c: XlsCheck, rows: XlsRow[], choices: XlsChoice[]): boolean {\n  if (c.kind === \"choices\") {\n    const have = new Set(choices.filter((x) => norm(x.list_name) === norm(c.list)).map((x) => x.name.trim().toLowerCase()));\n    return c.names.every((n) => have.has(n.toLowerCase()));\n  }\n  const row = rows.find((r) => (r.name ?? \"\").trim() === c.name);\n  if (!row) return false;\n  if (c.type !== undefined && norm(row.type) !== norm(c.type)) return false;\n  if (c.required !== undefined && isRequired(row.required) !== c.required) return false;\n  if (c.labelHas !== undefined && !norm(row.label).includes(norm(c.labelHas))) return false;\n  if (c.relevant !== undefined && !sameLogic(row.relevant ?? \"\", c.relevant, rows, choices).ok) return false;\n  if (c.constraint !== undefined && !sameLogic(row.constraint ?? \"\", c.constraint, rows, choices, { self: row }).ok) return false;\n  if (c.calculation !== undefined && !sameLogic(row.calculation ?? \"\", c.calculation, rows, choices, { asValue: true }).ok) return false;\n  return true;\n}\n","client/src/lms/labs/XlsFormLab.tsx":"import { useEffect, useMemo, useState } from \"react\";\nimport { Camera, Check, Circle, MapPin, Plus, Smartphone, Trash2, X } from \"lucide-react\";\nimport type { Block, XlsChoice, XlsColumn, XlsRow } from \"../types\";\nimport type { ProgressApi } from \"../progress\";\nimport { LabFrame } from \"./LabFrame\";\nimport { baseType, constraintOk, isRequired, listOf, norm, runCheck, runForm, type Values } from \"./xlsform\";\nimport { parse } from \"./xpath\";\n\n// XLSForm lab: the learner edits the \"survey\" and \"choices\" sheets of a form, exactly as in\n// Excel for KoboToolbox / ODK / SurveyCTO, and sees the form work live in a phone preview\n// (skip logic, constraints, required questions, calculations).\ntype XBlock = Extract<Block, { type: \"xlsform\" }>;\n\nconst WIDTH: Record<XlsColumn, string> = {\n  type: \"min-w-[10rem]\", name: \"min-w-[8rem]\", label: \"min-w-[14rem]\", required: \"min-w-[5.5rem]\", relevant: \"min-w-[13rem]\",\n  constraint: \"min-w-[12rem]\", constraint_message: \"min-w-[12rem]\", calculation: \"min-w-[13rem]\", hint: \"min-w-[12rem]\",\n};\nconst EXPR: XlsColumn[] = [\"relevant\", \"constraint\", \"calculation\"];\nconst copy = <T,>(x: T): T => JSON.parse(JSON.stringify(x)) as T;\nconst parses = (s = \"\") => { if (!s.trim()) return true; try { parse(s); return true; } catch { return false; } };\n\nexport function XlsFormLab({ block, api }: { block: XBlock; api: ProgressApi }) {\n  const cols: XlsColumn[] = block.columns ?? [\"type\", \"name\", \"label\", \"required\", \"relevant\", \"constraint\"];\n  const [rows, setRows] = useState<XlsRow[]>(() => copy(block.survey));\n  const [choices, setChoices] = useState<XlsChoice[]>(() => copy(block.choices ?? []));\n  const [tab, setTab] = useState<\"survey\" | \"choices\">(\"survey\");\n  const [answers, setAnswers] = useState<Values>({});\n  const done = !!api.progress.labs[block.id];\n\n  const results = useMemo(() => block.checks.map((c) => runCheck(c, rows, choices)), [block.checks, rows, choices]);\n  const allOk = results.every(Boolean);\n  const touched = JSON.stringify(rows) !== JSON.stringify(block.survey) || JSON.stringify(choices) !== JSON.stringify(block.choices ?? []);\n  useEffect(() => { if (allOk && touched && !done) api.completeLab(block.id); }, [allOk, touched, done, api, block.id]);\n\n  const form = useMemo(() => runForm(rows, answers), [rows, answers]);\n  const setCell = (i: number, c: XlsColumn, v: string) => setRows((r) => r.map((row, j) => (j === i ? { ...row, [c]: v } : row)));\n  const setChoice = (i: number, c: keyof XlsChoice, v: string) => setChoices((r) => r.map((row, j) => (j === i ? { ...row, [c]: v } : row)));\n  const answer = (name: string, v: string) => setAnswers((a) => ({ ...a, [name]: v }));\n  const cell = \"lms-mono [font-variant-ligatures:none] w-full rounded-md border bg-[#0A0F1C] px-2 py-1.5 text-[0.8rem] text-white focus:border-[color:var(--acc-60)] focus:outline-none\";\n\n  return (\n    <LabFrame icon={Smartphone} kind=\"XLSForm lab\" level={block.level} title={block.title} task={block.task} done={done} hint={block.hint}\n      onReset={() => { setRows(copy(block.survey)); setChoices(copy(block.choices ?? [])); setAnswers({}); }}\n      onSolution={() => { setRows(copy(block.solution.survey)); setChoices(copy(block.solution.choices ?? block.choices ?? [])); setAnswers({}); }}>\n      <div className=\"grid gap-5 xl:grid-cols-[minmax(0,1.5fr)_minmax(17rem,1fr)]\">\n        {/* Workbook */}\n        <div className=\"min-w-0\">\n          <div role=\"tablist\" aria-label=\"Sheets\" className=\"mb-2 flex gap-1\">\n            {([\"survey\", \"choices\"] as const).map((t) => (\n              <button key={t} role=\"tab\" type=\"button\" aria-selected={tab === t} onClick={() => setTab(t)}\n                className={`lms-mono rounded-t-lg border-b-2 px-3 py-1.5 text-sm ${tab === t ? \"border-[color:var(--acc)] text-white\" : \"border-transparent text-[color:var(--muted)] hover:text-white\"}`}>{t}</button>\n            ))}\n          </div>\n          <div className=\"lms-scroll overflow-x-auto rounded-xl border border-[color:var(--line)]\" data-no-translate>\n            {tab === \"survey\" ? (\n              <table className=\"w-full border-collapse text-left\">\n                <thead className=\"bg-[color:var(--raised)]\"><tr>\n                  <th className=\"lms-mono w-8 px-2 py-2 text-xs text-[color:var(--muted)]\">#</th>\n                  {cols.map((c) => <th key={c} className={`lms-mono px-2 py-2 text-xs font-bold text-[color:var(--muted)] ${WIDTH[c]}`}>{c}</th>)}\n                  <th className=\"w-8\" />\n                </tr></thead>\n                <tbody>\n                  {rows.map((r, i) => (\n                    <tr key={i} className=\"border-t border-[color:var(--line)]\">\n                      <td className=\"lms-mono px-2 text-center text-xs text-[color:var(--muted)]\">{i + 2}</td>\n                      {cols.map((c) => {\n                        const bad = (EXPR.includes(c) && !parses(r[c])) || (c === \"type\" && !!r.type?.trim() && ![\"begin_group\", \"end_group\"].includes(baseType(r)) && ![\"text\", \"integer\", \"decimal\", \"select_one\", \"select_multiple\", \"date\", \"note\", \"calculate\", \"geopoint\", \"image\"].includes(baseType(r)));\n                        return (\n                          <td key={c} className=\"p-1\">\n                            <input aria-label={`${c}, row ${i + 2}`} value={r[c] ?? \"\"} spellCheck={false} autoComplete=\"off\" onChange={(e) => setCell(i, c, e.target.value)}\n                              className={`${cell} ${bad ? \"border-rose-400/70\" : \"border-transparent\"}`} />\n                          </td>\n                        );\n                      })}\n                      <td className=\"p-1\"><button type=\"button\" aria-label={`Delete row ${i + 2}`} onClick={() => setRows((x) => x.filter((_, j) => j !== i))} className=\"grid h-7 w-7 place-items-center rounded-md text-[color:var(--muted)] hover:bg-white/[0.06] hover:text-rose-300\"><Trash2 size={14} /></button></td>\n                    </tr>\n                  ))}\n                </tbody>\n              </table>\n            ) : (\n              <table className=\"w-full border-collapse text-left\">\n                <thead className=\"bg-[color:var(--raised)]\"><tr>\n                  <th className=\"lms-mono w-8 px-2 py-2 text-xs text-[color:var(--muted)]\">#</th>\n                  {([\"list_name\", \"name\", \"label\"] as const).map((c) => <th key={c} className=\"lms-mono min-w-[9rem] px-2 py-2 text-xs font-bold text-[color:var(--muted)]\">{c}</th>)}\n                  <th className=\"w-8\" />\n                </tr></thead>\n                <tbody>\n                  {choices.map((r, i) => (\n                    <tr key={i} className=\"border-t border-[color:var(--line)]\">\n                      <td className=\"lms-mono px-2 text-center text-xs text-[color:var(--muted)]\">{i + 2}</td>\n                      {([\"list_name\", \"name\", \"label\"] as const).map((c) => (\n                        <td key={c} className=\"p-1\"><input aria-label={`${c}, row ${i + 2}`} value={r[c]} spellCheck={false} autoComplete=\"off\" onChange={(e) => setChoice(i, c, e.target.value)} className={`${cell} border-transparent`} /></td>\n                      ))}\n                      <td className=\"p-1\"><button type=\"button\" aria-label={`Delete choice ${i + 2}`} onClick={() => setChoices((x) => x.filter((_, j) => j !== i))} className=\"grid h-7 w-7 place-items-center rounded-md text-[color:var(--muted)] hover:bg-white/[0.06] hover:text-rose-300\"><Trash2 size={14} /></button></td>\n                    </tr>\n                  ))}\n                </tbody>\n              </table>\n            )}\n          </div>\n          <button type=\"button\" onClick={() => (tab === \"survey\" ? setRows((r) => [...r, {}]) : setChoices((c) => [...c, { list_name: c[c.length - 1]?.list_name ?? \"\", name: \"\", label: \"\" }]))}\n            className=\"mt-2 inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-sm text-[color:var(--acc)] hover:bg-white/[0.05]\"><Plus size={15} /> Add a row</button>\n          <p className=\"mt-1 text-xs text-[color:var(--muted)]\">Refer to other questions as <code className=\"lms-code\">{\"${name}\"}</code>. In a constraint, the dot <code className=\"lms-code\">.</code> is the answer being checked. Cells with a formula error turn red.</p>\n        </div>\n\n        {/* Phone preview */}\n        <div className=\"min-w-0\">\n          <div className=\"mx-auto w-full max-w-[20rem] rounded-[2rem] border border-[color:var(--line)] bg-[#05080F] p-2.5 shadow-2xl\">\n            <div className=\"flex items-center justify-between rounded-t-[1.5rem] bg-[color:var(--acc)] px-4 py-2.5 text-[#0B1320]\">\n              <span className=\"text-sm font-bold\">Form preview</span>\n              <button type=\"button\" onClick={() => setAnswers({})} className=\"rounded-md bg-black/10 px-2 py-0.5 text-xs font-semibold hover:bg-black/20\">Clear answers</button>\n            </div>\n            <div className=\"lms-scroll grid max-h-[30rem] content-start gap-3 overflow-y-auto rounded-b-[1.5rem] bg-[#F4F6FA] p-4 text-[#1B2230]\" data-no-translate>\n              {rows.map((r, i) => {\n                if (!form.visible[i]) return null;\n                const t = baseType(r), name = (r.name ?? \"\").trim(), label = r.label?.trim() || name || \"(no label)\";\n                const v = answers[name] ?? \"\";\n                const opts = choices.filter((c) => norm(c.list_name) === listOf(r));\n                const con = constraintOk(r, v, form.values);\n                const field = \"w-full rounded-lg border border-[#CBD2DE] bg-white px-3 py-2 text-sm focus:border-[#2563EB] focus:outline-none\";\n                if (t === \"begin_group\") return <p key={i} className=\"border-b border-[#CBD2DE] pb-1 pt-1 text-xs font-bold uppercase tracking-wider text-[#4A5568]\">{label}</p>;\n                if (t === \"note\") return <p key={i} className=\"rounded-lg bg-[#E6ECF5] px-3 py-2 text-sm\">{label}</p>;\n                return (\n                  <div key={i} className=\"grid gap-1.5\">\n                    <p className=\"text-sm font-semibold leading-snug\">{label}{isRequired(r.required) && <span className=\"text-[#C53030]\"> *</span>}</p>\n                    {r.hint && <p className=\"-mt-1 text-xs text-[#5A6478]\">{r.hint}</p>}\n                    {t === \"select_one\" ? (\n                      <div className=\"grid gap-1\">{opts.map((o) => (\n                        <label key={o.name} className=\"flex items-center gap-2 text-sm\"><input type=\"radio\" name={`${block.id}-${name}`} checked={v === o.name} onChange={() => answer(name, o.name)} />{o.label || o.name}</label>\n                      ))}{!opts.length && <span className=\"text-xs text-[#C53030]\">No choices found for list \"{listOf(r)}\"</span>}</div>\n                    ) : t === \"select_multiple\" ? (\n                      <div className=\"grid gap-1\">{opts.map((o) => {\n                        const set = v.split(\" \").filter(Boolean), on = set.includes(o.name);\n                        return <label key={o.name} className=\"flex items-center gap-2 text-sm\"><input type=\"checkbox\" checked={on} onChange={() => answer(name, (on ? set.filter((x) => x !== o.name) : [...set, o.name]).join(\" \"))} />{o.label || o.name}</label>;\n                      })}{!opts.length && <span className=\"text-xs text-[#C53030]\">No choices found for list \"{listOf(r)}\"</span>}</div>\n                    ) : t === \"geopoint\" ? (\n                      <button type=\"button\" onClick={() => answer(name, \"4.0511 9.7679 12 5\")} className=\"inline-flex w-fit items-center gap-1.5 rounded-lg bg-[#1B2230] px-3 py-1.5 text-xs font-semibold text-white\"><MapPin size={13} />{v ? \"4.0511, 9.7679 (±5 m)\" : \"Record location\"}</button>\n                    ) : t === \"image\" ? (\n                      <button type=\"button\" onClick={() => answer(name, \"photo.jpg\")} className=\"inline-flex w-fit items-center gap-1.5 rounded-lg bg-[#1B2230] px-3 py-1.5 text-xs font-semibold text-white\"><Camera size={13} />{v ? \"photo.jpg\" : \"Take picture\"}</button>\n                    ) : (\n                      <input className={field} type={t === \"date\" ? \"date\" : \"text\"} inputMode={t === \"integer\" || t === \"decimal\" ? \"decimal\" : undefined} value={v}\n                        onChange={(e) => answer(name, t === \"integer\" ? e.target.value.replace(/[^\\d-]/g, \"\") : e.target.value)} aria-label={label} />\n                    )}\n                    {!con.ok && <p className=\"text-xs font-semibold text-[#C53030]\">{r.constraint_message?.trim() || \"Value not allowed\"}</p>}\n                  </div>\n                );\n              })}\n              {!form.visible.some(Boolean) && <p className=\"text-sm text-[#5A6478]\">No question to show yet.</p>}\n            </div>\n          </div>\n          {rows.some((r) => baseType(r) === \"calculate\") && (\n            <div className=\"mx-auto mt-3 w-full max-w-[20rem] rounded-xl border border-[color:var(--line)] px-3 py-2 text-xs text-[color:var(--muted)]\">\n              <p className=\"mb-1 font-semibold text-white\">Calculated values</p>\n              <ul className=\"lms-mono grid gap-0.5\" data-no-translate>{rows.filter((r) => baseType(r) === \"calculate\").map((r, i) => <li key={i}>{r.name}: {form.values[(r.name ?? \"\").trim()] || \"—\"}</li>)}</ul>\n            </div>\n          )}\n        </div>\n      </div>\n\n      {/* Checklist */}\n      <ul className=\"mt-4 grid gap-1.5 sm:grid-cols-2\">\n        {block.checks.map((c, i) => (\n          <li key={i} className={`flex items-start gap-2 text-sm ${results[i] ? \"text-emerald-200\" : \"text-[color:var(--muted)]\"}`}>\n            {results[i] ? <Check size={16} className=\"mt-0.5 shrink-0 text-emerald-400\" /> : touched ? <X size={16} className=\"mt-0.5 shrink-0 text-rose-300/70\" /> : <Circle size={16} className=\"mt-0.5 shrink-0\" />}\n            <span>{c.label}</span>\n          </li>\n        ))}\n      </ul>\n      {allOk && touched && <p className=\"lms-rise mt-3 rounded-xl bg-emerald-400/10 px-4 py-3 text-sm text-emerald-100\"><strong>Well done.</strong> Your form works. Try it in the preview.</p>}\n    </LabFrame>\n  );\n}\n","client/src/data/courses/meal.ts":"import type { LmsCourse } from \"../../lms/types\";\nimport { m1 } from \"./meal/m1\";\nimport { m2 } from \"./meal/m2\";\nimport { m3 } from \"./meal/m3\";\nimport { m4 } from \"./meal/m4\";\nimport { m5 } from \"./meal/m5\";\nimport { m6 } from \"./meal/m6\";\n\n// MEAL Professional Certificate (Monitoring, Evaluation, Accountability and Learning).\n// Original Analytix Engineering material. Tools: XLSForm, KoboToolbox, ODK, SurveyCTO,\n// CommCare, Excel, SPSS and Stata.\nexport const MEAL_COURSE: LmsCourse = {\n  id: \"meal\",\n  code: \"MEALPC\",\n  title: \"MEAL Professional Certificate\",\n  subtitle: \"Monitoring, Evaluation, Accountability and Learning for development and humanitarian programmes\",\n  accent: \"#2CC4DB\",\n  hours: 140,\n  certification: \"Analytix Engineering professional certificate with QR verification\",\n  introVideo: {\n    en: { src: \"/media/meal-intro-en.mp4\", poster: \"/media/meal-intro-en.jpg\" },\n    fr: { src: \"/media/meal-intro-fr.mp4\", poster: \"/media/meal-intro-fr.jpg\" },\n  },\n  modules: [m1, m2, m3, m4, m5, m6],\n};\n","client/src/data/courses/meal/m1.ts":"import type { Block, CourseModule } from \"../../../lms/types\";\n\n// MEAL Professional Certificate — Module 1: MEAL Foundations\n// Original Analytix Engineering material. All projects, organisations, people and figures are fictional.\n\nconst BE = \"BetterEvaluation\";\nconst OECD = \"OECD\";\nconst CHS = \"CHS Alliance\";\nconst ICRC = \"ICRC\";\nconst KOBO = \"KoboToolbox Support\";\n\nconst PILLARS = [\"Monitoring\", \"Evaluation\", \"Accountability\", \"Learning\"];\nconst STAGES = [\"Assessment and design\", \"Baseline\", \"Implementation monitoring\", \"Midterm review\", \"Final evaluation\", \"Closure and learning\"];\nconst WHO = [\"Community members\", \"Government health district\", \"Donor\", \"Implementing partner\"];\nconst YES_NO = [{ list_name: \"yes_no\", name: \"yes\", label: \"Yes\" }, { list_name: \"yes_no\", name: \"no\", label: \"No\" }];\n\nconst INTRO: Block = { type: \"p\", text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" };\n\nexport const m1: CourseModule = {\n  id: \"meal-m1\",\n  number: 1,\n  title: \"MEAL Foundations\",\n  summary: \"What MEAL is, how it fits the project cycle, who it serves, and the ethics of working with data about people.\",\n  hours: 12,\n  lessons: [\n    // ─────────────────────────────── LESSON 1 ───────────────────────────────\n    {\n      id: \"meal-m1-l1\",\n      title: \"What MEAL is and how the four pillars work together\",\n      minutes: 20,\n      objectives: [\n        \"Define monitoring, evaluation, accountability and learning and explain how they differ\",\n        \"Trace how data flows from monitoring into evaluation, accountability and learning\",\n        \"Explain what MEAL adds to classic M&E and to results-based management\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Every project promises change: more children vaccinated, cleaner water, better harvests. MEAL is the system a team uses to know whether that change is really happening, to answer to the people it serves, and to improve while there is still time. It is not a report written at the end; it is a way of working from the first day to the last.\" },\n        { type: \"h\", text: \"Four pillars, one system\" },\n        { type: \"table\", head: [\"Pillar\", \"Main question\", \"When\", \"Typical products\"], rows: [\n          [\"Monitoring\", \"Are we doing what we planned, on time and on budget?\", \"Continuously: weekly, monthly, quarterly\", \"Activity registers, monthly reports, indicator tracking table\"],\n          [\"Evaluation\", \"Did it work, for whom, and why?\", \"At set moments: midterm, end, sometimes after\", \"Baseline and endline studies, evaluation reports\"],\n          [\"Accountability\", \"Do affected people know, influence and trust what we do?\", \"Throughout the project\", \"Information sessions, complaints and feedback mechanism, feedback logs\"],\n          [\"Learning\", \"What should we keep, change or stop?\", \"Regularly, and at key decision points\", \"Review meetings, lessons-learned notes, adapted plans\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Monitoring and evaluation in one sentence each\", text: \"Monitoring counts and follows what the project does, all the time. Evaluation steps back at chosen moments to judge whether the project achieved its results and why. Monitoring tells you that attendance dropped; evaluation tells you whether the project changed anything that matters.\" },\n        { type: \"h\", text: \"How data flows between the pillars\" },\n        { type: \"steps\", title: \"One cycle of MEAL data\", items: [\n          \"Field teams record activities and results in registers or mobile forms (monitoring).\",\n          \"The MEAL officer compiles the data, checks its quality and updates the indicator tracking table.\",\n          \"Results and feedback are shared back with communities, who can question them or complain (accountability).\",\n          \"The team meets to review the figures and the feedback, and decides what to adjust (learning).\",\n          \"At midterm and at the end, evaluators use all this monitoring data, plus their own collection, to judge the results (evaluation).\",\n        ] },\n        { type: \"h\", text: \"From M&E to MEAL\" },\n        { type: \"p\", text: \"Classic M&E focused on collecting data for managers and donors. MEAL adds two pillars that change the direction of the flow. Accountability sends information and power back to affected people: they are told what the project plans, they can complain safely, and their feedback changes decisions. Learning makes sure the data is actually used to improve the work, not only filed in reports.\" },\n        { type: \"h\", text: \"Results-based management in one paragraph\" },\n        { type: \"p\", text: \"Results-based management (RBM) means steering a project by the results it achieves rather than by the activities it completes. You define the change you want at each level (outputs, outcomes, impact), set indicators and targets for each, measure progress regularly, and use the evidence to decide. MEAL is the engine that feeds RBM with reliable evidence.\" },\n        { type: \"form\", id: \"meal-m1-l1-pillars\", title: \"Classify the activities\", task: \"A nutrition project in the Far North region runs the activities below. Choose the MEAL pillar each one mainly belongs to.\",\n          hint: \"Monitoring follows activities continuously, evaluation judges results at set moments, accountability is about affected people's voice and information, learning is about using evidence to change the work.\",\n          fields: [\n            { kind: \"select\", label: \"Community health workers fill a monthly register of children screened for malnutrition\", options: PILLARS, answer: 0, explain: \"Routine, continuous counting of an activity is monitoring.\" },\n            { kind: \"select\", label: \"An external consultant compares malnutrition rates before and after the project\", options: PILLARS, answer: 1, explain: \"Judging whether the project changed outcomes, at a set moment, is evaluation.\" },\n            { kind: \"select\", label: \"A free hotline number is painted on the wall of each nutrition centre\", options: PILLARS, answer: 2, explain: \"A channel for complaints and feedback gives affected people a voice: accountability.\" },\n            { kind: \"select\", label: \"The team meets each quarter to discuss why screening fell in two health areas and changes the outreach schedule\", options: PILLARS, answer: 3, explain: \"Using evidence to adjust the plan is learning, also called adaptive management.\" },\n            { kind: \"select\", label: \"The MEAL officer updates the indicator tracking table every month\", options: PILLARS, answer: 0 },\n            { kind: \"select\", label: \"Village leaders are told which households were selected and why\", options: PILLARS, answer: 2, explain: \"Sharing selection criteria openly is part of being accountable to communities.\" },\n            { kind: \"select\", label: \"A midterm review asks mothers whether the cooking demonstrations changed what they feed their children\", options: PILLARS, answer: 1 },\n            { kind: \"select\", label: \"A two-page note on what worked in the pilot is shared with the team starting a similar project in the East region\", options: PILLARS, answer: 3 },\n          ] },\n        { type: \"check\", id: \"meal-m1-l1-c1\", question: \"Which statement best describes what MEAL adds to classic M&E?\", options: [\"More indicators and longer reports for the donor\", \"Accountability to affected people and the use of evidence to improve the work\", \"An external evaluation at the end of every project\", \"Replacing monitoring with evaluation\"], answer: 1, explain: \"MEAL keeps monitoring and evaluation, and adds accountability (information and voice for affected people) and learning (acting on evidence).\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"In a fictional WASH project in the Mayo-Tsanaga department, monitoring showed that 12 new water points were built on time. Feedback from the complaints box revealed that women avoided three of them because they were far from the villages and unsafe after dark. The team moved two planned water points. Monitoring alone would have reported success.\" },\n        { type: \"task\", id: \"meal-m1-l1-t1\", title: \"Practice\", items: [\n          \"Write one sentence that defines each of the four pillars in your own words\",\n          \"List three monitoring activities and one evaluation activity in a project you know\",\n          \"Identify how affected people can give feedback in that project, or note that they cannot\",\n          \"Describe one decision in that project that was, or could have been, changed by evidence\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Rainbow Framework: tasks in monitoring and evaluation\", url: \"https://www.betterevaluation.org/frameworks-guides/rainbow-framework\", source: BE },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 2 ───────────────────────────────\n    {\n      id: \"meal-m1-l2\",\n      title: \"MEAL across the project cycle\",\n      minutes: 20,\n      objectives: [\n        \"Place the main MEAL activities on the stages of the project cycle\",\n        \"Name the MEAL product expected at each stage, from assessment to closure\",\n        \"Calculate a first indicator as a percentage of its target\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"MEAL is not an activity you add in the last month. Each stage of the project cycle needs something specific from MEAL, and what you skip early cannot be repaired later: without a baseline, no evaluation can show how much changed.\" },\n        { type: \"h\", text: \"The project cycle and its MEAL moments\" },\n        { type: \"table\", head: [\"Stage\", \"Key MEAL question\", \"What MEAL produces\"], rows: [\n          [\"Assessment and design\", \"What are the needs, and what change do we aim for?\", \"Needs assessment, theory of change, logframe, draft indicators, MEAL plan\"],\n          [\"Baseline\", \"What is the situation before we start?\", \"Baseline report with starting values; confirmed targets\"],\n          [\"Implementation monitoring\", \"Are activities and outputs on track?\", \"Registers, monthly data, indicator tracking table, feedback log, quarterly reports\"],\n          [\"Midline or midterm review\", \"Are we on the way to the outcomes? What must change?\", \"Midterm review report, adjusted work plan\"],\n          [\"Endline or final evaluation\", \"What changed, for whom, and was it worth it?\", \"Endline survey, final evaluation report, management response\"],\n          [\"Closure and learning\", \"What do we keep, hand over and share?\", \"Lessons-learned note, final report, archived and anonymised datasets\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"The baseline comes before the activities\", text: \"Collect baseline data before the project starts working with the population. If distributions or trainings have already begun, your starting values are already affected and the change you report later will look smaller than it really is.\" },\n        { type: \"h\", text: \"Baseline, midline and endline\" },\n        { type: \"list\", items: [\n          \"Baseline: the starting value of each outcome indicator, measured with a method you can repeat.\",\n          \"Midline: the same measurement halfway through, used to correct course while there is time.\",\n          \"Endline: the same measurement at the end, compared with the baseline and the target.\",\n          \"Use the same questions, the same indicator definitions and a comparable sample each time, otherwise the figures cannot be compared.\",\n        ] },\n        { type: \"h\", text: \"Implementation monitoring: the monthly rhythm\" },\n        { type: \"steps\", title: \"A typical monthly cycle\", items: [\n          \"Field staff submit activity data and registers by a fixed date, for example the 5th of each month.\",\n          \"The MEAL officer checks completeness and consistency and follows up on gaps.\",\n          \"The indicator tracking table is updated with the month's figures and the cumulative total.\",\n          \"Feedback and complaints received during the month are summarised.\",\n          \"The team reviews the figures in a short meeting and records decisions.\",\n        ] },\n        { type: \"h\", text: \"A first taste of indicators: percentage of target\" },\n        { type: \"p\", text: \"The simplest progress measure divides what was achieved by what was planned. A result of 0.875 means 87.5% of the target is reached. Many teams use a simple rule to flag indicators that need attention, for example below 80% of the target at the time of reporting.\" },\n        { type: \"path\", items: [\"Home\", \"Number\", \"Percent Style\"], note: \"In Excel, shows a share such as 0.875 as 88%.\" },\n        { type: \"sheet\", id: \"meal-m1-l2-sheet\", title: \"Percentage of target achieved\", task: \"Six-month figures from a fictional WASH project in the East region. Fill **D2:D5** with the share of the target achieved, then **E2:E5** with `On track` when it is at least 80%, otherwise `Behind`.\",\n          data: [[\"Indicator\", \"Target\", \"Achieved\", \"% of target\", \"Status\"],\n            [\"Households reached with hygiene kits\", 1200, 1050, null, null],\n            [\"Latrines built\", 80, 52, null, null],\n            [\"Water points repaired\", 15, 15, null, null],\n            [\"People trained in hygiene promotion\", 400, 290, null, null]],\n          editable: [\"D2\", \"D3\", \"D4\", \"D5\", \"E2\", \"E3\", \"E4\", \"E5\"],\n          checks: [{ cell: \"D2\", equals: 0.875, tol: 0.001 }, { cell: \"D3\", equals: 0.65, tol: 0.001 }, { cell: \"D4\", equals: 1, tol: 0.001 }, { cell: \"D5\", equals: 0.725, tol: 0.001 },\n            { cell: \"E2\", equals: \"On track\" }, { cell: \"E3\", equals: \"Behind\" }, { cell: \"E4\", equals: \"On track\" }, { cell: \"E5\", equals: \"Behind\" }],\n          hint: \"The share is Achieved divided by Target: =C2/B2. For the status, test the share: =IF(D2>=0.8,\\\"On track\\\",\\\"Behind\\\").\",\n          solution: { D2: \"=C2/B2\", D3: \"=C3/B3\", D4: \"=C4/B4\", D5: \"=C5/B5\",\n            E2: \"=IF(D2>=0.8,\\\"On track\\\",\\\"Behind\\\")\", E3: \"=IF(D3>=0.8,\\\"On track\\\",\\\"Behind\\\")\", E4: \"=IF(D4>=0.8,\\\"On track\\\",\\\"Behind\\\")\", E5: \"=IF(D5>=0.8,\\\"On track\\\",\\\"Behind\\\")\" } },\n        { type: \"form\", id: \"meal-m1-l2-stages\", title: \"Match products to stages\", task: \"For each MEAL product of a fictional food security project in the Adamawa region, choose the stage of the project cycle where it is mainly produced.\",\n          hint: \"Ask yourself when the product is needed: before activities start, during them, halfway, at the end, or after the project closes.\",\n          fields: [\n            { kind: \"select\", label: \"A household survey measuring food consumption before the first seed distribution\", options: STAGES, answer: 1, explain: \"Starting values measured before activities are the baseline.\" },\n            { kind: \"select\", label: \"A logframe with draft indicators and a MEAL plan\", options: STAGES, answer: 0 },\n            { kind: \"select\", label: \"A monthly table of seed kits distributed per village\", options: STAGES, answer: 2 },\n            { kind: \"select\", label: \"A report after 18 months of a 36-month project recommending changes to the training approach\", options: STAGES, answer: 3, explain: \"A review halfway through, used to correct course, is the midterm review.\" },\n            { kind: \"select\", label: \"An independent report judging the relevance, effectiveness and sustainability of the project\", options: STAGES, answer: 4 },\n            { kind: \"select\", label: \"An anonymised dataset archived with a note on what to repeat in the next project\", options: STAGES, answer: 5 },\n          ] },\n        { type: \"check\", id: \"meal-m1-l2-c1\", question: \"A project starts distributing hygiene kits in January, and the baseline survey is carried out in March. What is the main problem?\", options: [\"The survey will cost more\", \"The starting values are already influenced by the project, so the change will be underestimated\", \"The donor does not accept surveys in March\", \"There is no problem as long as the same questionnaire is used at endline\"], answer: 1, explain: \"A baseline must describe the situation before the project acts. After two months of distributions, some change has already happened and will not be counted.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"In a fictional education project in the South-West region, school closures delayed the baseline. Instead of skipping it, the MEAL officer used enrolment registers from the previous school year held by the sub-divisional delegation as starting values, and documented this choice in the baseline report so that evaluators could interpret the figures correctly.\" },\n        { type: \"task\", id: \"meal-m1-l2-t1\", title: \"Practice\", items: [\n          \"Draw the project cycle of a project you know and write one MEAL product under each stage\",\n          \"Find out whether that project had a baseline, and when it was collected compared with the first activities\",\n          \"Build the percentage-of-target table from the lab for three indicators of your own project\",\n          \"Agree with your team on the threshold that flags an indicator as behind\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Evaluation criteria\", url: \"https://www.oecd.org/en/topics/sub-issues/development-co-operation-evaluation-and-effectiveness/evaluation-criteria.html\", source: OECD },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 3 ───────────────────────────────\n    {\n      id: \"meal-m1-l3\",\n      title: \"Roles, stakeholders and donor expectations\",\n      minutes: 20,\n      objectives: [\n        \"Distinguish the MEAL responsibilities of MEAL officers, programme staff and enumerators\",\n        \"Identify what communities, government, donors and partners each need from MEAL\",\n        \"Check a project against typical donor requirements on indicators, reporting, data quality and safeguarding\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"MEAL works only when everyone knows their part. The MEAL officer designs the system and keeps it honest, but most data is collected by programme staff and enumerators, and it is used by many people outside the team, each with different needs.\" },\n        { type: \"h\", text: \"Who does what inside the team\" },\n        { type: \"table\", head: [\"Role\", \"Main MEAL tasks\", \"Common mistake to avoid\"], rows: [\n          [\"MEAL officer or manager\", \"Designs the MEAL plan and tools, trains staff, checks data quality, analyses, reports, organises learning\", \"Doing all the data collection alone and becoming a bottleneck\"],\n          [\"Programme or project staff\", \"Fill registers and forms correctly, use the data in planning, share feedback from the field\", \"Seeing MEAL as the MEAL officer's job only\"],\n          [\"Enumerators and data collectors\", \"Collect data following the protocol, obtain consent, respect confidentiality, report problems\", \"Filling in missing answers from memory or guessing\"],\n          [\"Project manager\", \"Makes decisions based on the evidence and makes time for review meetings\", \"Reading the figures only when the donor report is due\"],\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"MEAL is everyone's job\", text: \"Write MEAL tasks into every job description and work plan: who fills which register, by which date, and who reviews it. A clear responsibility list prevents most data gaps.\" },\n        { type: \"h\", text: \"Stakeholders outside the team\" },\n        { type: \"table\", head: [\"Stakeholder\", \"What they need from MEAL\", \"How MEAL serves them\"], rows: [\n          [\"Communities and affected people\", \"Information on the project, a safe way to complain, results that concern them\", \"Information sessions, feedback mechanism, sharing results back in local languages\"],\n          [\"Government (ministries, regional delegations, health districts)\", \"Data aligned with national indicators and systems, coordination\", \"Using national indicator definitions, sharing reports, reporting in national systems\"],\n          [\"Donors\", \"Evidence that funds produce the agreed results, compliance with the grant\", \"Indicator tracking, periodic reports, evaluations, data quality checks\"],\n          [\"Implementing partners\", \"Clear tools and deadlines, feedback on their data, support\", \"Joint training, common forms, regular data reviews\"],\n        ] },\n        { type: \"h\", text: \"What donors typically expect\" },\n        { type: \"list\", items: [\n          \"Indicators: a logframe with defined indicators, often a mix of the donor's standard indicators and project-specific ones, with baselines and targets.\",\n          \"Reporting frequency: usually quarterly or half-yearly progress reports and an annual or final report, with deadlines written in the grant agreement.\",\n          \"Data quality: data that is valid, reliable, timely, precise and has integrity; some donors run data quality assessments on site.\",\n          \"Disaggregation: results broken down at least by sex and age, and often by disability or location.\",\n          \"Safeguarding: a code of conduct, protection from sexual exploitation and abuse, and rapid reporting of incidents through confidential channels.\",\n          \"Accountability: evidence that affected people were informed and consulted and that complaints were handled.\",\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Read the grant agreement first\", text: \"Reporting templates, indicator definitions and deadlines differ from one donor to another. List every MEAL requirement of the agreement in the MEAL plan in the first month; discovering one at the final report is too late.\" },\n        { type: \"h\", text: \"Map your stakeholders\" },\n        { type: \"steps\", title: \"A quick stakeholder mapping\", items: [\n          \"List everyone who produces, uses or is affected by the project's data.\",\n          \"For each one, write the information they need and how often.\",\n          \"Note the format that suits them: dashboard, report, meeting, radio message, community meeting.\",\n          \"Assign a person in the team responsible for each flow of information.\",\n          \"Add these flows to the MEAL plan and review them every six months.\",\n        ] },\n        { type: \"form\", id: \"meal-m1-l3-needs\", title: \"Who needs this information?\", task: \"A fictional maternal health project works with a health district in the Centre region. Choose the stakeholder who mainly needs each piece of information.\",\n          hint: \"Think about who acts on the information: communities need what concerns their access and their rights, the district needs data for its own system, the donor needs evidence on the agreed results, the partner needs operational feedback.\",\n          fields: [\n            { kind: \"select\", label: \"The opening days of the mobile clinic and how to complain about the service\", options: WHO, answer: 0, explain: \"Practical information and a complaints channel serve the people using the service.\" },\n            { kind: \"select\", label: \"Monthly antenatal visits using the national indicator definitions, for the health information system\", options: WHO, answer: 1 },\n            { kind: \"select\", label: \"Progress against the logframe targets and the quarterly financial burn rate\", options: WHO, answer: 2 },\n            { kind: \"select\", label: \"Feedback on errors found in the registers of the three health centres the partner supervises\", options: WHO, answer: 3 },\n            { kind: \"select\", label: \"The results of the midterm review presented in a village meeting in the local language\", options: WHO, answer: 0, explain: \"Sharing results back with communities closes the loop and is a core part of accountability.\" },\n            { kind: \"select\", label: \"Confirmation that a safeguarding incident was reported within the agreed deadline\", options: WHO, answer: 2 },\n          ] },\n        { type: \"check\", id: \"meal-m1-l3-c1\", question: \"An enumerator cannot find a respondent and fills in the questionnaire from what the neighbour says, without noting it. What is the main issue?\", options: [\"The questionnaire takes longer to complete\", \"The data is no longer valid for that household and the protocol was broken\", \"The donor will ask for more indicators\", \"Nothing, as long as the answers look plausible\"], answer: 1, explain: \"Answers must come from the intended respondent. Replacing them without recording it damages validity and integrity; the enumerator should record the household as not reached and inform the supervisor.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"Health districts in Cameroon report routine data to the Ministry of Public Health through the national health information system. A fictional NGO supporting a health district agreed to use the same indicator definitions and to enter its data in the district's system before its own report. The district trusted the figures, and the NGO avoided two conflicting sets of numbers.\" },\n        { type: \"task\", id: \"meal-m1-l3-t1\", title: \"Practice\", items: [\n          \"Write the MEAL tasks of each role in your team in a simple table\",\n          \"List the external stakeholders of your project and what each needs from MEAL\",\n          \"Find the reporting deadlines and indicator requirements in one grant agreement you work with\",\n          \"Check whether your project's results are disaggregated by sex and age\",\n          \"Identify the confidential channel for reporting a safeguarding incident in your organisation\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Core Humanitarian Standard on Quality and Accountability\", url: \"https://www.corehumanitarianstandard.org/\", source: CHS },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 4 ───────────────────────────────\n    {\n      id: \"meal-m1-l4\",\n      title: \"Ethics: do no harm, informed consent and data protection\",\n      minutes: 25,\n      objectives: [\n        \"Apply the do-no-harm principle when planning data collection\",\n        \"Build an informed consent step that ends the interview when consent is refused\",\n        \"Protect personal data through minimisation, anonymisation, secure storage and controlled sharing\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Data about people can hurt them. A list of displaced households, a survivor's story or a photo of a child can expose people to stigma, violence or exclusion if it is collected carelessly or ends up in the wrong hands. Ethics is not paperwork added to MEAL; it decides what you may collect, how and from whom.\" },\n        { type: \"h\", text: \"Do no harm in data collection\" },\n        { type: \"list\", items: [\n          \"Ask only what you will use, and do not ask sensitive questions just because they might be interesting.\",\n          \"Think about who could see the interview: neighbours, family members, armed actors.\",\n          \"Do not raise expectations: say clearly that taking part does not guarantee assistance.\",\n          \"Keep interviews short; people's time has a cost, especially during a crisis.\",\n          \"Know the referral pathway: if someone needs help, you must know where to refer them.\",\n        ] },\n        { type: \"h\", text: \"Informed consent\" },\n        { type: \"p\", text: \"Consent is informed when the person understands who you are, why you ask, what happens to the answers, and that they can refuse or stop at any time without losing any assistance. It must be given freely, before any question, in a language the person understands.\" },\n        { type: \"steps\", title: \"A short consent script\", items: [\n          \"Introduce yourself and your organisation, and show your badge.\",\n          \"Explain the purpose of the survey and how long it takes.\",\n          \"Say that taking part is voluntary and that refusing will not affect any assistance.\",\n          \"Explain that answers are confidential and that names will not appear in reports.\",\n          \"Say that the person can skip any question or stop at any time.\",\n          \"Ask whether they have questions, then ask clearly: do you agree to take part?\",\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Minors and sensitive topics\", text: \"For children under 18, obtain the consent of a parent or guardian and the child's own agreement, and interview them in a visible but private place. Never ask about individual experiences of gender-based violence in a general survey: such questions need specially trained staff, a private setting and a working referral pathway.\" },\n        { type: \"h\", text: \"Build consent into the form\" },\n        { type: \"p\", text: \"In a mobile form, make consent a required question at the start and make the rest of the form relevant only when the answer is yes. The enumerator then cannot continue by mistake after a refusal.\" },\n        { type: \"path\", items: [\"Projects\", \"New\", \"Build from scratch\"], note: \"Creates a new form in KoboToolbox; you can also upload an XLSForm file.\" },\n        { type: \"xlsform\", id: \"meal-m1-l4-xls\", title: \"Add a consent question\", task: \"Replace the placeholder in row 3 with a **required** consent question named `consent` (type `select_one yes_no`). Make the **interview** group relevant only when consent is yes, then add a row at the end: a note named `refused` that appears only when consent is no.\",\n          hint: \"Row 3: type select_one yes_no, name consent, required yes. Group relevant: ${consent} = 'yes'. Last row: type note, name refused, relevant ${consent} = 'no'.\",\n          columns: [\"type\", \"name\", \"label\", \"required\", \"relevant\"],\n          survey: [\n            { type: \"note\", name: \"intro\", label: \"Read the consent script to the respondent.\" },\n            { type: \"note\", name: \"placeholder\", label: \"Replace this row with the consent question\" },\n            { type: \"begin_group\", name: \"interview\", label: \"Household interview\" },\n            { type: \"integer\", name: \"hh_size\", label: \"How many people live in this household?\" },\n            { type: \"select_one yes_no\", name: \"water_treated\", label: \"Do you treat your drinking water?\" },\n            { type: \"end_group\", name: \"interview_end\" },\n          ],\n          choices: YES_NO,\n          checks: [\n            { label: \"consent is a select_one yes_no question\", kind: \"field\", name: \"consent\", type: \"select_one yes_no\" },\n            { label: \"consent is required\", kind: \"field\", name: \"consent\", required: true },\n            { label: \"the interview group appears only when consent = yes\", kind: \"field\", name: \"interview\", relevant: \"${consent} = 'yes'\" },\n            { label: \"a note named refused appears only when consent = no\", kind: \"field\", name: \"refused\", type: \"note\", relevant: \"${consent} = 'no'\" },\n          ],\n          solution: { survey: [\n            { type: \"note\", name: \"intro\", label: \"Read the consent script to the respondent.\" },\n            { type: \"select_one yes_no\", name: \"consent\", label: \"Do you agree to take part in this interview?\", required: \"yes\" },\n            { type: \"begin_group\", name: \"interview\", label: \"Household interview\", relevant: \"${consent} = 'yes'\" },\n            { type: \"integer\", name: \"hh_size\", label: \"How many people live in this household?\" },\n            { type: \"select_one yes_no\", name: \"water_treated\", label: \"Do you treat your drinking water?\" },\n            { type: \"end_group\", name: \"interview_end\" },\n            { type: \"note\", name: \"refused\", label: \"Thank the person and end the interview.\", relevant: \"${consent} = 'no'\" },\n          ] } },\n        { type: \"h\", text: \"Protect the data\" },\n        { type: \"table\", head: [\"Principle\", \"In practice\"], rows: [\n          [\"Data minimisation\", \"Collect only the variables the indicators need. If you do not need names or phone numbers for analysis, do not collect them.\"],\n          [\"Anonymisation\", \"Replace names with codes, keep the list linking codes to names separately, and remove GPS points or exact villages before sharing datasets.\"],\n          [\"Secure storage\", \"Use password-protected phones and accounts, send data to the server as soon as there is a connection, and delete it from the phones afterwards.\"],\n          [\"Controlled sharing\", \"Share only aggregated or anonymised data, only with people who need it, through agreed channels. Never send beneficiary lists in open messaging groups.\"],\n          [\"Retention\", \"Decide in advance how long personal data is kept and who deletes it at the end of the project.\"],\n        ] },\n        { type: \"form\", id: \"meal-m1-l4-dilemmas\", title: \"What would you do?\", task: \"Choose the most ethical response to each situation.\",\n          hint: \"Protect the person first, then the data. When in doubt, collect less, share less and refer to trained staff.\",\n          fields: [\n            { kind: \"select\", label: \"During a household survey, a woman starts describing violence by her husband.\", options: [\"Record every detail in the form\", \"Listen calmly, do not probe, offer the referral information and inform your supervisor without writing her name\", \"Ask the husband for his version\", \"Tell her the survey is not about that and move on\"], answer: 1, explain: \"Enumerators are not trained to handle disclosures. Listen, do not probe, give referral information and keep her identity confidential.\" },\n            { kind: \"select\", label: \"A local authority asks for the full list of displaced households with their phone numbers.\", options: [\"Send it by WhatsApp to be helpful\", \"Send it only if the request is written\", \"Explain the data protection rules and offer aggregated figures; refer the request to your manager\", \"Refuse any contact with the authority\"], answer: 2, explain: \"Personal data is shared only for a clear purpose, with consent, and through an agreed procedure. Aggregated figures usually meet the need.\" },\n            { kind: \"select\", label: \"You want to interview 15-year-old students about school attendance.\", options: [\"Their own agreement is enough\", \"Obtain parental consent and the student's assent, and interview in a visible, private place\", \"Ask the teacher to answer for them\", \"Interview them only in groups so consent is not needed\"], answer: 1 },\n            { kind: \"select\", label: \"An enumerator's tablet with unsent interviews is stolen.\", options: [\"Wait to see if it is found\", \"Report the incident at once, change the account password and assess who could be affected\", \"Re-interview the households without telling anyone\", \"Buy a new tablet and continue\"], answer: 1, explain: \"A data breach must be reported quickly so the team can limit harm, for example by revoking access to the server account.\" },\n            { kind: \"select\", label: \"The draft form asks for the respondent's name, ethnic group and exact GPS location, but no indicator uses them.\", options: [\"Keep them, they may be useful later\", \"Remove them: collect only what the indicators need\", \"Keep them but make them optional\", \"Keep only the ethnic group\"], answer: 1, explain: \"Data minimisation: every sensitive variable you do not collect is one that cannot leak.\" },\n          ] },\n        { type: \"check\", id: \"meal-m1-l4-c1\", question: \"Which practice best protects respondents when you share a survey dataset with a partner?\", options: [\"Sending the full dataset in a password-protected Excel file\", \"Removing names, phone numbers and GPS points and sharing only the variables the partner needs\", \"Asking the partner to promise not to share it\", \"Sharing it only on paper\"], answer: 1, explain: \"Anonymisation and minimisation remove the risk at its source. A password or a promise protects the file, not the people in it.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"In a fictional shelter project in the North-West region, beneficiary lists with names and neighbourhoods were circulating in a large WhatsApp group of volunteers. The MEAL officer replaced them with coded lists, kept the key file on a password-protected laptop, and trained volunteers to call the office to confirm a household instead of forwarding lists.\" },\n        { type: \"task\", id: \"meal-m1-l4-t1\", title: \"Practice\", items: [\n          \"Write a consent script of six sentences for a survey in your project, in English and French\",\n          \"Add a required consent question and a relevant condition to one of your XLSForms\",\n          \"List every personal variable in that form and remove the ones no indicator uses\",\n          \"Find out where your project's data is stored and who has access to it\",\n          \"Write down the referral contacts enumerators should give in case of a disclosure\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Handbook on data protection in humanitarian action\", url: \"https://www.icrc.org/en/data-protection-humanitarian-action-handbook\", source: ICRC },\n          { label: \"Adding skip logic in the Formbuilder\", url: \"https://support.kobotoolbox.org/skip_logic.html\", source: KOBO },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── PRACTICE ───────────────────────────────\n    {\n      id: \"meal-m1-practice\",\n      title: \"Practice lab: MEAL foundations in the field\",\n      minutes: 35,\n      objectives: [\n        \"Classify project activities by MEAL pillar and project stage\",\n        \"Calculate achievement against targets for a set of sites\",\n        \"Build consent and eligibility logic into a mobile form\",\n        \"Calculate indicators correctly from data with refusals and missing answers\",\n      ],\n      blocks: [\n        INTRO,\n        { type: \"h\", text: \"Exercise 1: An immunisation project in a health district\" },\n        { type: \"form\", id: \"meal-pr-m1-district\", level: \"beginner\", title: \"Pillars and stages\", task: \"A fictional project supports routine immunisation in a health district of the Littoral region. Answer each question.\",\n          hint: \"Monitoring is continuous, evaluation judges results at set moments, accountability gives people information and voice, learning turns evidence into decisions. The baseline comes before the activities.\",\n          fields: [\n            { kind: \"select\", label: \"Nurses record every vaccination in the health centre register\", options: PILLARS, answer: 0 },\n            { kind: \"select\", label: \"A suggestion box and a phone number are placed in each vaccination post\", options: PILLARS, answer: 2 },\n            { kind: \"select\", label: \"Supervisors adjust the outreach calendar after seeing low coverage in two health areas\", options: PILLARS, answer: 3 },\n            { kind: \"select\", label: \"A coverage survey after three years compares results with the starting values\", options: PILLARS, answer: 1 },\n            { kind: \"select\", label: \"The survey that measured immunisation coverage before the project began is the…\", options: STAGES, answer: 1, explain: \"Starting values measured before activities form the baseline.\" },\n            { kind: \"select\", label: \"The monthly table of children vaccinated per health area belongs to…\", options: STAGES, answer: 2 },\n          ] },\n        { type: \"h\", text: \"Exercise 2: A school feeding programme\" },\n        { type: \"sheet\", id: \"meal-pr-m1-feeding\", level: \"intermediate\", title: \"Meals served against plan\",\n          task: \"Term figures from five schools of a fictional school feeding programme in the Far North. Fill **D2:D6** with the share of planned meals served, **B7:C7** with the totals, **D7** with the overall share, and **D8** with the number of schools below 80%.\",\n          data: [[\"School\", \"Meals planned\", \"Meals served\", \"% served\"],\n            [\"EP Mora I\", 9000, 8550, null],\n            [\"EP Kolofata\", 7500, 5400, null],\n            [\"EP Tokombéré\", 6000, 6120, null],\n            [\"EP Mokolo Centre\", 8200, 6970, null],\n            [\"EP Koza\", 4800, 3500, null],\n            [\"Total\", null, null, null],\n            [\"Schools below 80%\", null, null, null]],\n          editable: [\"D2\", \"D3\", \"D4\", \"D5\", \"D6\", \"B7\", \"C7\", \"D7\", \"D8\"],\n          checks: [{ cell: \"D2\", equals: 0.95, tol: 0.001 }, { cell: \"D3\", equals: 0.72, tol: 0.001 }, { cell: \"D4\", equals: 1.02, tol: 0.001 }, { cell: \"D5\", equals: 0.85, tol: 0.001 }, { cell: \"D6\", equals: 0.7292, tol: 0.001 },\n            { cell: \"B7\", equals: 35500 }, { cell: \"C7\", equals: 30540 }, { cell: \"D7\", equals: 0.8603, tol: 0.001 }, { cell: \"D8\", equals: 2 }],\n          hint: \"Each share is served divided by planned. The overall share is total served divided by total planned (=C7/B7), not the average of the five shares, because schools have different sizes. Count low schools with COUNTIF(D2:D6,\\\"<0.8\\\").\",\n          solution: { D2: \"=C2/B2\", D3: \"=C3/B3\", D4: \"=C4/B4\", D5: \"=C5/B5\", D6: \"=C6/B6\", B7: \"=SUM(B2:B6)\", C7: \"=SUM(C2:C6)\", D7: \"=C7/B7\", D8: \"=COUNTIF(D2:D6,\\\"<0.8\\\")\" } },\n        { type: \"h\", text: \"Exercise 3: A WASH household survey\" },\n        { type: \"xlsform\", id: \"meal-pr-m1-wash\", level: \"advanced\", title: \"Consent and eligibility logic\", task: \"A fictional WASH NGO interviews adults only. Make **consent** required. Show **age** only when consent is yes, make it required and accept 10 to 110. Show the **household** group only when consent is yes and age is at least 18. Then add a note named `end_note` at the end that appears when consent is no or the person is under 18.\",\n          hint: \"Group relevant: ${consent} = 'yes' and ${age} >= 18. Age constraint: . >= 10 and . <= 110. End note relevant: ${consent} = 'no' or ${age} < 18.\",\n          columns: [\"type\", \"name\", \"label\", \"required\", \"relevant\", \"constraint\"],\n          survey: [\n            { type: \"select_one yes_no\", name: \"consent\", label: \"Do you agree to take part in this interview?\" },\n            { type: \"integer\", name: \"age\", label: \"How old are you?\" },\n            { type: \"begin_group\", name: \"household\", label: \"Water and sanitation\" },\n            { type: \"select_one source\", name: \"water_source\", label: \"Main source of drinking water\" },\n            { type: \"select_one yes_no\", name: \"latrine\", label: \"Does the household use a latrine?\" },\n            { type: \"end_group\", name: \"household_end\" },\n          ],\n          choices: [...YES_NO, { list_name: \"source\", name: \"borehole\", label: \"Borehole\" }, { list_name: \"source\", name: \"well\", label: \"Protected well\" }, { list_name: \"source\", name: \"river\", label: \"River or stream\" }],\n          checks: [\n            { label: \"consent is required\", kind: \"field\", name: \"consent\", required: true },\n            { label: \"age appears only when consent = yes\", kind: \"field\", name: \"age\", relevant: \"${consent} = 'yes'\" },\n            { label: \"age is required\", kind: \"field\", name: \"age\", required: true },\n            { label: \"age accepts 10 to 110 only\", kind: \"field\", name: \"age\", constraint: \". >= 10 and . <= 110\" },\n            { label: \"household group only for consenting adults\", kind: \"field\", name: \"household\", relevant: \"${consent} = 'yes' and ${age} >= 18\" },\n            { label: \"end_note appears when consent = no or age < 18\", kind: \"field\", name: \"end_note\", type: \"note\", relevant: \"${consent} = 'no' or ${age} < 18\" },\n          ],\n          solution: { survey: [\n            { type: \"select_one yes_no\", name: \"consent\", label: \"Do you agree to take part in this interview?\", required: \"yes\" },\n            { type: \"integer\", name: \"age\", label: \"How old are you?\", required: \"yes\", relevant: \"${consent} = 'yes'\", constraint: \". >= 10 and . <= 110\" },\n            { type: \"begin_group\", name: \"household\", label: \"Water and sanitation\", relevant: \"${consent} = 'yes' and ${age} >= 18\" },\n            { type: \"select_one source\", name: \"water_source\", label: \"Main source of drinking water\" },\n            { type: \"select_one yes_no\", name: \"latrine\", label: \"Does the household use a latrine?\" },\n            { type: \"end_group\", name: \"household_end\" },\n            { type: \"note\", name: \"end_note\", label: \"Thank the person and end the interview.\", relevant: \"${consent} = 'no' or ${age} < 18\" },\n          ] } },\n        { type: \"h\", text: \"Exercise 4: Post-distribution monitoring in a refugee response\" },\n        { type: \"sheet\", id: \"meal-pr-m1-pdm\", level: \"expert\", title: \"Indicators from messy survey data\",\n          task: \"Post-distribution monitoring at a fictional refugee-hosting site in the East region. Interviews without consent must be excluded, even if data was entered by mistake. Fill **H2:H7**.\",\n          data: [[\"ID\", \"Sex\", \"Consent\", \"Kit received\", \"Days waited\", null, \"Measure\", \"Result\"],\n            [\"R01\", \"F\", \"Yes\", \"Yes\", 5, null, \"Valid interviews (consent = Yes)\", null],\n            [\"R02\", \"M\", \"Yes\", \"No\", null, null, \"Valid interviews with a kit answer\", null],\n            [\"R03\", \"F\", \"No\", \"Yes\", 3, null, \"% of them who received the kit\", null],\n            [\"R04\", \"F\", \"Yes\", \"Yes\", 9, null, \"Women with consent who received the kit\", null],\n            [\"R05\", \"M\", \"Yes\", null, null, null, \"Average days waited, valid recipients\", null],\n            [\"R06\", \"F\", \"Yes\", \"No\", null, null, \"Valid interviews missing the kit answer\", null],\n            [\"R07\", \"M\", \"Yes\", \"Yes\", 4],\n            [\"R08\", \"F\", \"Yes\", \"Yes\", 12],\n            [\"R09\", \"M\", \"No\", null, null]],\n          editable: [\"H2\", \"H3\", \"H4\", \"H5\", \"H6\", \"H7\"],\n          checks: [{ cell: \"H2\", equals: 7 }, { cell: \"H3\", equals: 6 }, { cell: \"H4\", equals: 0.6667, tol: 0.001 }, { cell: \"H5\", equals: 3 }, { cell: \"H6\", equals: 7.5, tol: 0.01 }, { cell: \"H7\", equals: 1 }],\n          hint: \"Every measure must include the condition Consent = Yes. Count Yes and No kit answers separately with COUNTIFS and add them. The percentage divides the Yes answers by H3, not by H2. Use AVERAGEIFS with two conditions for the days. H7 is the difference between H2 and H3.\",\n          solution: { H2: \"=COUNTIF(C2:C10,\\\"Yes\\\")\", H3: \"=COUNTIFS(C2:C10,\\\"Yes\\\",D2:D10,\\\"Yes\\\")+COUNTIFS(C2:C10,\\\"Yes\\\",D2:D10,\\\"No\\\")\", H4: \"=COUNTIFS(C2:C10,\\\"Yes\\\",D2:D10,\\\"Yes\\\")/H3\", H5: \"=COUNTIFS(B2:B10,\\\"F\\\",C2:C10,\\\"Yes\\\",D2:D10,\\\"Yes\\\")\", H6: \"=AVERAGEIFS(E2:E10,C2:C10,\\\"Yes\\\",D2:D10,\\\"Yes\\\")\", H7: \"=H2-H3\" } },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"meal-m1-quiz\",\n    title: \"Module 1 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"Which activity is monitoring rather than evaluation?\", options: [\"An endline survey comparing results with the baseline\", \"Counting the hygiene kits distributed each month\", \"A midterm review judging whether outcomes are likely\", \"An independent study of the project's sustainability\"], answer: 1, explain: \"Monitoring follows activities and outputs continuously. The other three judge results at set moments, which is evaluation.\" },\n      { id: \"q2\", question: \"What does the accountability pillar mainly add to M&E?\", options: [\"More frequent donor reports\", \"External auditors\", \"Information, voice and a safe way to complain for affected people\", \"A larger MEAL budget\"], answer: 2, explain: \"Accountability is about the people the project serves: they are informed, consulted, and can complain safely, and their feedback changes decisions.\" },\n      { id: \"q3\", question: \"When should the baseline be collected?\", options: [\"Before the project starts working with the population\", \"After the first distribution, when people know the project\", \"At the midterm review\", \"Only if the donor asks for it\"], answer: 0, explain: \"The baseline describes the situation before the project acts. Collected later, it already includes some of the project's effect.\" },\n      { id: \"q4\", question: \"A project planned 400 trainees and trained 290. What is the percentage of target achieved?\", options: [\"29%\", \"65%\", \"138%\", \"72.5%\"], answer: 3, explain: \"290 ÷ 400 = 0.725, that is 72.5% of the target.\" },\n      { id: \"q5\", question: \"Who should fill in activity registers correctly and use the data in planning?\", options: [\"Only the MEAL officer\", \"Only the donor\", \"Programme staff, with support from the MEAL officer\", \"Only external evaluators\"], answer: 2, explain: \"Programme staff produce most routine data. The MEAL officer designs tools, trains and checks quality, but cannot collect everything alone.\" },\n      { id: \"q6\", question: \"Which requirement is typical of donors regarding results?\", options: [\"Results reported only as a total, without breakdown\", \"Results disaggregated at least by sex and age\", \"No indicators, only stories\", \"Monthly external evaluations\"], answer: 1, explain: \"Most donors ask for disaggregation by sex and age, and often by disability or location, to see who benefits.\" },\n      { id: \"q7\", question: \"What is data minimisation?\", options: [\"Compressing data files before sending them\", \"Deleting all data at the end of each month\", \"Reducing the sample size\", \"Collecting only the personal data the indicators actually need\"], answer: 3, explain: \"Every sensitive variable you do not collect is one that cannot be lost, leaked or misused.\" },\n      { id: \"q8\", question: \"In an XLSForm, how do you stop the interview when consent is refused?\", options: [\"Make consent required and set the rest of the form relevant only when ${consent} = 'yes'\", \"Put the consent question at the end of the form\", \"Add a constraint on every question\", \"Ask the enumerator to close the form manually\"], answer: 0, explain: \"A required consent question with the rest of the form in a group relevant on consent = yes makes it impossible to continue after a refusal.\" },\n    ],\n  },\n};\n","client/src/data/courses/meal/m2.ts":"import type { CourseModule } from \"../../../lms/types\";\n\n// MEAL Professional Certificate — Module 2: MEAL Planning.\n// Original Analytix Engineering material. All projects, organisations, people and figures are fictional.\n\nconst BE = \"BetterEvaluation\";\nconst LEVELS = [\"Inputs\", \"Activities\", \"Outputs\", \"Outcomes\", \"Impact\"];\n\nexport const m2: CourseModule = {\n  id: \"meal-m2\",\n  number: 2,\n  title: \"MEAL Planning\",\n  summary: \"Theory of Change, logframes, SMART indicators, indicator reference sheets and the MEAL plan.\",\n  hours: 20,\n  lessons: [\n    // ───────────────────────────── LESSON 1 ─────────────────────────────\n    {\n      id: \"meal-m2-l1\",\n      title: \"Theory of Change and the results chain\",\n      minutes: 20,\n      objectives: [\n        \"Explain the five levels of the results chain and how they connect\",\n        \"Write the if-then logic of a project with its assumptions and risks\",\n        \"Place project statements at the right results level\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Every project is a bet: if we do these things, then these changes will follow. A Theory of Change makes that bet explicit, so the team, the donor and the communities can see how the work is supposed to lead to results, and so the MEAL team knows what to measure at each step.\" },\n        { type: \"h\", text: \"What a Theory of Change is\" },\n        { type: \"p\", text: \"A Theory of Change is a short narrative and a diagram that explain how and why a set of activities should lead to a long-term change. It starts from the problem, names the change you want, and traces the pathway backwards to what the project will actually do. It also states the assumptions: the conditions that must hold for each step to lead to the next. The logframe in the next lesson is a more compact, table version of the same logic.\" },\n        { type: \"h\", text: \"The results chain\" },\n        { type: \"table\", head: [\"Level\", \"Question it answers\", \"Example: girls' education in the Far North\", \"Who controls it\"], rows: [\n          [\"Inputs\", \"What resources do we use?\", \"Budget of 95 000 000 FCFA, 6 staff, school kits, a vehicle\", \"The project\"],\n          [\"Activities\", \"What do we do?\", \"Train teachers, run parent sessions, distribute kits, pay fees for the poorest girls\", \"The project\"],\n          [\"Outputs\", \"What do we deliver directly?\", \"120 teachers trained, 2 400 girls receive kits, 40 parent sessions held\", \"The project, mostly\"],\n          [\"Outcomes\", \"What changes for people?\", \"More girls enrol and stay in school; parents support girls' schooling\", \"Shared with communities and partners\"],\n          [\"Impact\", \"What long-term change do we contribute to?\", \"Girls complete primary school and have better life chances\", \"Many actors over many years\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Control goes down as you go up\", text: \"A project controls its inputs, activities and outputs. Outcomes depend on people choosing to change, and impact depends on many actors. That is why you are accountable for outputs, you manage towards outcomes, and you contribute to impact.\" },\n        { type: \"h\", text: \"If-then logic, assumptions and risks\" },\n        { type: \"p\", text: \"Read the chain from the bottom up as a series of if-then statements. Each arrow hides an assumption. For the girls' education example:\" },\n        { type: \"list\", ordered: true, items: [\n          \"If teachers are trained in gender-sensitive teaching and girls receive kits, then girls feel welcome and equipped in class (assumption: trained teachers stay in their posts).\",\n          \"If girls feel welcome and parents see the value of school, then more girls enrol and fewer drop out (assumption: schools stay open and the security situation allows travel to school).\",\n          \"If more girls stay in school, then more girls complete primary school (assumption: families do not face a new food crisis that pushes girls into work or early marriage).\",\n        ] },\n        { type: \"table\", head: [\"Term\", \"Meaning\", \"Example\"], rows: [\n          [\"Assumption\", \"A condition outside the project's control that must hold for the next level to follow\", \"Schools remain open during the school year\"],\n          [\"Risk\", \"Something that could happen and stop the chain; the opposite of an assumption\", \"Armed attacks close schools in two communes\"],\n          [\"Mitigation\", \"What the project does to reduce a risk it cannot control\", \"Agree temporary learning spaces with the inspectorate\"],\n        ] },\n        { type: \"steps\", title: \"Build a Theory of Change with your team\", items: [\n          \"Agree on the problem and its main causes, using needs assessment data and community consultations.\",\n          \"Write the long-term change you want to contribute to (impact) in one sentence.\",\n          \"Work backwards: which changes in behaviour or practice (outcomes) must happen first, and which products and services (outputs) will cause them?\",\n          \"List the activities and inputs needed to deliver each output.\",\n          \"Under each arrow, write the assumption that must hold, and check it with people who know the context.\",\n          \"Draw the diagram on one page and review it at least once a year as you learn.\",\n        ] },\n        { type: \"path\", items: [\"Insert\", \"SmartArt\"], note: \"In Word or PowerPoint, a Process layout gives a quick first diagram of the results chain.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A health NGO in Maroua reports each quarter that it trained 60 community health workers and held 300 awareness sessions. The donor asks: did more women give birth in a health facility? The team had only planned output indicators. With a Theory of Change drawn at the start, the outcome would have been clear and measured from the baseline.\" },\n        { type: \"form\", id: \"meal-m2-l1-lab\", title: \"Place each statement at the right level\",\n          task: \"A fictional maternal health project works in one health district of the Far North. Choose the results level of each statement.\",\n          hint: \"Ask: is it a resource (input), something the team does (activity), something delivered and counted (output), a change in what people do (outcome), or a long-term change in health (impact)?\",\n          fields: [\n            { kind: \"select\", label: \"A budget of 18 000 000 FCFA for delivery kits and training\", options: LEVELS, answer: 0, explain: \"Money, staff and materials are inputs.\" },\n            { kind: \"select\", label: \"Train community health workers on danger signs in pregnancy\", options: LEVELS, answer: 1, explain: \"A verb describing what the team does is an activity.\" },\n            { kind: \"select\", label: \"45 community health workers trained on danger signs in pregnancy\", options: LEVELS, answer: 2, explain: \"The direct, countable product of the training is an output.\" },\n            { kind: \"select\", label: \"2 400 home visits made to pregnant women\", options: LEVELS, answer: 2, explain: \"Visits delivered by the project are outputs, even when the number is large.\" },\n            { kind: \"select\", label: \"More pregnant women attend at least four antenatal visits\", options: LEVELS, answer: 3, explain: \"A change in what women do is an outcome.\" },\n            { kind: \"select\", label: \"Fewer mothers die from pregnancy-related causes in the district\", options: LEVELS, answer: 4, explain: \"A long-term change in health status is impact, to which many actors contribute.\" },\n            { kind: \"select\", label: \"Which statement is an assumption between the outputs and the outcomes?\", options: [\"45 health workers are trained\", \"Health facilities have midwives on duty when women arrive\", \"The project buys delivery kits\", \"Maternal deaths fall\"], answer: 1, explain: \"Women will only keep using the facility if staff are there. The project does not control staffing, so it is an assumption to monitor.\" },\n          ] },\n        { type: \"check\", id: \"meal-m2-l1-c1\", question: \"A water project reports: \\\"20 boreholes drilled and handed over to water committees\\\". At which level is this result?\", options: [\"Inputs\", \"Activity\", \"Outputs\", \"Outcome\"], answer: 2, explain: \"Boreholes built and handed over are delivered by the project, so they are outputs. The outcome would be households using safe water from them.\" },\n        { type: \"task\", id: \"meal-m2-l1-t1\", title: \"Practice\", items: [\n          \"Pick a project you know and write its impact in one sentence\",\n          \"List two outcomes and three outputs that lead to that impact\",\n          \"Write the chain as three if-then sentences\",\n          \"Add one assumption under each arrow and one risk with its mitigation\",\n          \"Draw the chain on one page with SmartArt or on paper\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Develop programme theory / theory of change\", url: \"https://www.betterevaluation.org/frameworks-guides/rainbow-framework/define/develop-programme-theory-theory-change\", source: BE },\n        ] },\n      ],\n    },\n    // ───────────────────────────── LESSON 2 ─────────────────────────────\n    {\n      id: \"meal-m2-l2\",\n      title: \"Logframes and SMART indicators\",\n      minutes: 24,\n      objectives: [\n        \"Read and complete the four columns of a logframe\",\n        \"Distinguish output, outcome and impact indicators\",\n        \"Rewrite weak indicators so that they are SMART and disaggregated\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Most donors ask for a logical framework, or logframe: a one- or two-page table that summarises the project. It turns the Theory of Change into rows (the results levels) and columns (how you will know each result was achieved, and what must hold for it).\" },\n        { type: \"h\", text: \"The 4×4 logframe\" },\n        { type: \"table\", head: [\"Level\", \"Narrative summary\", \"Indicators\", \"Means of verification\", \"Assumptions\"], rows: [\n          [\"Impact (goal)\", \"Girls in 3 communes complete primary school\", \"Primary completion rate of girls\", \"School statistics from the sub-divisional inspectorate\", \"—\"],\n          [\"Outcome (purpose)\", \"More girls enrol and stay in school\", \"% of enrolled girls who finish the school year\", \"School registers, checked by term\", \"Schools stay open; families do not face a new food crisis\"],\n          [\"Outputs\", \"Teachers trained; girls equipped; parents engaged\", \"Number of teachers trained (by sex); number of girls receiving kits\", \"Training attendance sheets; distribution lists\", \"Trained teachers stay in their posts\"],\n          [\"Activities\", \"Train teachers; distribute kits; run parent sessions\", \"Budget and schedule (often shown instead of indicators)\", \"Financial reports; activity reports\", \"Kits arrive before the school year starts\"],\n        ] },\n        { type: \"p\", text: \"Read it in two directions. Vertically, each level plus its assumptions leads to the level above: if activities are done and the assumptions hold, then outputs are delivered, and so on. Horizontally, each result has an indicator that shows it was achieved and a means of verification that says where the evidence will come from.\" },\n        { type: \"h\", text: \"Output, outcome and impact indicators\" },\n        { type: \"table\", head: [\"Type\", \"What it measures\", \"Example\", \"Usual frequency\"], rows: [\n          [\"Outputs\", \"What the project delivered\", \"Number of hygiene kits distributed\", \"Monthly, from project records\"],\n          [\"Outcome\", \"Changes in knowledge, practice, access or use\", \"% of households washing hands with soap at key times\", \"Baseline, midline, endline surveys\"],\n          [\"Impact\", \"Long-term changes in well-being\", \"Prevalence of diarrhoea among children under 5\", \"Start and end, often from national surveys\"],\n        ] },\n        { type: \"h\", text: \"SMART criteria\" },\n        { type: \"table\", head: [\"Letter\", \"Meaning\", \"Question to ask\"], rows: [\n          [\"S\", \"Specific\", \"Does it say exactly what is measured and among whom?\"],\n          [\"M\", \"Measurable\", \"Can two people count it and get the same value?\"],\n          [\"A\", \"Achievable\", \"Is the target realistic with this budget and time?\"],\n          [\"R\", \"Relevant\", \"Does it really show the result it sits next to?\"],\n          [\"T\", \"Time-bound\", \"Does it say by when, or over what period?\"],\n        ] },\n        { type: \"table\", head: [\"Weak indicator\", \"SMART version\"], rows: [\n          [\"Improved hygiene in the camp\", \"% of refugee households in the camp with soap and water at the handwashing station, observed during the endline survey (target 70% by June 2027)\"],\n          [\"Farmers trained\", \"Number of farmers (by sex and age group) who completed at least 3 of the 4 training sessions on improved maize practices by December 2026\"],\n          [\"Better access to health care\", \"% of pregnant women in the target health areas who attended at least 4 antenatal visits during the reporting year\"],\n        ] },\n        { type: \"h\", text: \"Disaggregation and proxy indicators\" },\n        { type: \"list\", items: [\n          \"Disaggregate people-level indicators at least by sex and age group. Add disability status, location and displacement status (host community, IDP, refugee) when they matter for your project.\",\n          \"Plan disaggregation at design time: the questionnaire and registers must collect sex, age and location, or you cannot split the data later.\",\n          \"Use a proxy indicator when the real result is too costly or sensitive to measure directly, for example the number of meals eaten per day as a proxy for food security, or household assets as a proxy for income.\",\n          \"Keep indicators few: two or three per result are usually enough. Each indicator costs time and money to collect.\",\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Do not mix levels\", text: \"\\\"Number of people trained\\\" is an output indicator even if it sits in the outcome row of a draft logframe. An outcome indicator needs evidence that people changed what they know, do or use.\" },\n        { type: \"path\", items: [\"Insert\", \"Table\"], note: \"In Word, a table with 5 columns and 5 rows gives a header row plus the four logframe levels.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"An INGO in Bertoua prepares a proposal for a refugee livelihoods project in the East. The donor's template asks for sex- and age-disaggregated indicators and adds displacement status. The MEAL officer adds a \\\"refugee / host\\\" question to every registration form from the first day, so each report can show whether both communities benefit.\" },\n        { type: \"form\", id: \"meal-m2-l2-lab1\", title: \"Choose the SMART indicator\",\n          task: \"For each result, choose the indicator that is the most SMART. All projects are fictional.\",\n          hint: \"Look for what is counted, among whom, where, and by when. Vague verbs such as \\\"improve\\\" or \\\"strengthen\\\" are not measurable on their own.\",\n          fields: [\n            { kind: \"select\", label: \"Result: mothers practise exclusive breastfeeding\", options: [\"Improved infant feeding practices\", \"% of mothers of infants aged 0–5 months in the target health areas who report exclusive breastfeeding in the previous 24 hours, at endline (target 60%)\", \"Number of breastfeeding sessions held\", \"Mothers are aware of breastfeeding\"], answer: 1, explain: \"It names the group, the measurement, the place, the time and the target.\" },\n            { kind: \"select\", label: \"Result: youth start small businesses\", options: [\"Youth empowered economically\", \"Number of youth trained in entrepreneurship\", \"Number of youth aged 18–30 (by sex) running a business that is still active 6 months after receiving a start-up grant, by March 2027\", \"Youth businesses are successful\"], answer: 2, explain: \"Training is an output. The SMART outcome counts active businesses after a defined period.\" },\n            { kind: \"select\", label: \"Result: water committees manage boreholes\", options: [\"Committees are strong\", \"% of project boreholes still functional 12 months after handover, checked in a field visit (target 90%)\", \"Number of committees\", \"Good management of water points\"], answer: 1, explain: \"Functionality after 12 months is an observable sign of good management and has a clear time frame.\" },\n            { kind: \"select\", label: \"Which SMART letter is missing in \\\"Number of teachers trained in the Adamawa region\\\"?\", options: [\"Specific\", \"Measurable\", \"Relevant\", \"Time-bound\"], answer: 3, explain: \"There is no period or deadline. Add \\\"by the end of the 2026–2027 school year\\\".\" },\n            { kind: \"select\", label: \"\\\"Number of households receiving seed kits\\\" is an indicator of which type?\", options: [\"Inputs\", \"Outputs\", \"Outcome\", \"Impact\"], answer: 1, explain: \"Kits received are delivered by the project, so this is an output indicator.\" },\n            { kind: \"select\", label: \"Which is a sensible proxy for household income in a rural survey?\", options: [\"The number of assets the household owns, such as a radio, bicycle or livestock\", \"The number of project visits\", \"The household head's age\", \"The village name\"], answer: 0, explain: \"Income is hard to measure accurately, so surveys often use asset ownership as a proxy.\" },\n          ] },\n        { type: \"form\", id: \"meal-m2-l2-lab2\", title: \"Complete the logframe cells\",\n          task: \"A fictional malaria project distributes insecticide-treated nets in a health district of the South region. Choose the right content for each empty logframe cell.\",\n          hint: \"Means of verification say where the evidence comes from. Assumptions are outside the project's control. Outcome indicators measure use, not delivery.\",\n          fields: [\n            { kind: \"select\", label: \"Output \\\"Households receive nets\\\": best means of verification\", options: [\"Distribution lists signed by each household\", \"The national malaria strategy\", \"An endline focus group\", \"The project budget\"], answer: 0, explain: \"Signed distribution lists record every net handed out.\" },\n            { kind: \"select\", label: \"Outcome \\\"Children sleep under a net\\\": best indicator\", options: [\"Number of nets distributed\", \"% of children under 5 who slept under a treated net the previous night, from a household survey\", \"Number of malaria awareness sessions\", \"Cost per net\"], answer: 1, explain: \"The outcome is net use, measured by asking about the previous night in a survey.\" },\n            { kind: \"select\", label: \"Outcome \\\"Children sleep under a net\\\": best means of verification\", options: [\"Warehouse stock cards\", \"Baseline and endline household surveys with observation of nets\", \"The donor's website\", \"Staff timesheets\"], answer: 1, explain: \"Surveys that also observe whether a net is hanging give credible evidence of use.\" },\n            { kind: \"select\", label: \"Assumption between the output and the outcome\", options: [\"The project buys 30 000 nets\", \"Households are willing to hang and use the nets rather than sell them\", \"Staff are trained\", \"The project has a vehicle\"], answer: 1, explain: \"Whether people use the nets depends on them, not on the project. It must be written and monitored.\" },\n            { kind: \"select\", label: \"Impact \\\"Fewer children fall ill with malaria\\\": best indicator\", options: [\"Number of nets per household\", \"Malaria cases among children under 5 per 1 000, from health facility data\", \"% of nets distributed on time\", \"Number of posters printed\"], answer: 1, explain: \"Illness rates show the long-term change. Health facility data is the usual source.\" },\n          ] },\n        { type: \"check\", id: \"meal-m2-l2-c1\", question: \"In a logframe, what does the \\\"means of verification\\\" column contain?\", options: [\"The activities of the project\", \"The source of the data that shows the indicator's value\", \"The risks that could stop the project\", \"The budget of each result\"], answer: 1, explain: \"Means of verification say where the evidence comes from: registers, survey reports, attendance sheets, health data and so on.\" },\n        { type: \"task\", id: \"meal-m2-l2-t1\", title: \"Practice\", items: [\n          \"Draw an empty 4×4 logframe in Word for the project you used in Lesson 1\",\n          \"Fill the narrative summary column from your Theory of Change\",\n          \"Write one indicator per level and check each one against the five SMART questions\",\n          \"Add the disaggregation you need for every people-level indicator\",\n          \"Write one assumption per level and one means of verification per indicator\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Logframe\", url: \"https://www.betterevaluation.org/methods-approaches/methods/logframe\", source: BE },\n        ] },\n      ],\n    },\n    // ───────────────────────────── LESSON 3 ─────────────────────────────\n    {\n      id: \"meal-m2-l3\",\n      title: \"Indicator reference sheets\",\n      minutes: 22,\n      objectives: [\n        \"List the fields of an indicator reference sheet and explain why each one matters\",\n        \"Define an indicator precisely with its numerator, denominator and unit\",\n        \"Calculate an indicator value and compare it with its target\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"An indicator name in a logframe is only a label. Two officers can read \\\"ANC coverage\\\" and calculate it in two different ways. The indicator reference sheet (IRS), also called a performance indicator reference sheet (PIRS), is a one-page definition that makes sure everyone measures the same thing, in the same way, every time.\" },\n        { type: \"h\", text: \"Why each indicator needs a reference sheet\" },\n        { type: \"p\", text: \"Staff change, partners collect data, and projects last several years. Without a written definition, the value reported in year 3 may not be comparable with the baseline. The IRS also forces the team to check early that the data can actually be collected, by whom and at what cost.\" },\n        { type: \"table\", head: [\"Field\", \"What to write\"], rows: [\n          [\"Definition\", \"What exactly is counted, with any terms explained (for example what \\\"skilled\\\" or \\\"functional\\\" means)\"],\n          [\"Numerator / denominator\", \"For a percentage: who is counted on top, and the total population it is divided by\"],\n          [\"Unit\", \"Number, percentage, ratio, score or FCFA\"],\n          [\"Data source and method\", \"Register, survey, observation, health data; how the data is collected\"],\n          [\"Frequency\", \"How often the value is calculated and reported\"],\n          [\"Responsible\", \"The role that collects, checks and reports the data\"],\n          [\"Disaggregation\", \"Sex, age group, location, displacement status, disability\"],\n          [\"Baseline\", \"The value at the start, with its date and source\"],\n          [\"Target\", \"The value to reach, and by when, with intermediate targets if needed\"],\n        ] },\n        { type: \"h\", text: \"Worked example: antenatal care coverage\" },\n        { type: \"table\", head: [\"Field\", \"Content\"], rows: [\n          [\"Indicator\", \"% of pregnant women registered at a first antenatal visit who completed at least 4 antenatal visits\"],\n          [\"Definition\", \"A woman counts when her antenatal card or the facility register shows 4 or more visits for the same pregnancy\"],\n          [\"Numerator\", \"Number of women with 4 or more antenatal visits during the period\"],\n          [\"Denominator\", \"Number of women registered at a first antenatal visit during the same period\"],\n          [\"Unit\", \"Percentage\"],\n          [\"Data source and method\", \"Antenatal registers of the 4 supported health facilities, compiled monthly\"],\n          [\"Frequency\", \"Collected monthly, reported quarterly\"],\n          [\"Responsible\", \"Facility midwives collect; the project MEAL officer checks and compiles\"],\n          [\"Disaggregation\", \"Health area; age group of the woman (under 20, 20 and over)\"],\n          [\"Baseline\", \"38% (fictional value, January to December 2025 registers)\"],\n          [\"Target\", \"60% by December 2027\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Same people, same period\", text: \"The numerator must be a subset of the denominator, taken over the same period and area. Dividing women with 4 visits in one district by first visits in another, or mixing years, gives a number that means nothing.\" },\n        { type: \"h\", text: \"Common errors\" },\n        { type: \"list\", items: [\n          \"A denominator that changes from report to report (all women one quarter, registered women the next).\",\n          \"Averaging percentages of facilities of very different sizes instead of dividing the total numerator by the total denominator.\",\n          \"A target written in a different unit from the indicator, such as a number of women when the indicator is a percentage.\",\n          \"No baseline, so progress cannot be shown.\",\n        ] },\n        { type: \"steps\", title: \"Calculate the indicator in Excel\", items: [\n          \"Enter the numerator and denominator of each facility or area in two columns.\",\n          \"Divide the numerator by the denominator on each row, for example =C2/B2.\",\n          \"Add the totals with SUM, then divide the total numerator by the total denominator.\",\n          \"Divide the result by the target to get the % of target achieved.\",\n          \"Format the result cells as percentages.\",\n        ] },\n        { type: \"path\", items: [\"Home\", \"Number\", \"Percent Style\"], note: \"Shows 0.55 as 55%. The cell still holds 0.55, which is what your formulas use.\" },\n        { type: \"sheet\", id: \"meal-m2-l3-sheet\", title: \"Antenatal care coverage by health area\",\n          task: \"Fictional data for the ANC indicator above. Fill **D2:D5** with the coverage of each health area, **B6:D6** with the totals and the overall coverage, and **D8** with the % of target achieved.\",\n          data: [\n            [\"Health area\", \"Registered at ANC1\", \"4+ ANC visits\", \"Coverage\"],\n            [\"Health area A\", 220, 121, null],\n            [\"Health area B\", 180, 72, null],\n            [\"Health area C\", 150, 96, null],\n            [\"Health area D\", 250, 140, null],\n            [\"Total\", null, null, null],\n            [\"Target\", null, null, 0.6],\n            [\"% of target achieved\", null, null, null],\n          ],\n          editable: [\"D2\", \"D3\", \"D4\", \"D5\", \"B6\", \"C6\", \"D6\", \"D8\"],\n          checks: [\n            { cell: \"D2\", equals: 0.55, tol: 0.001 }, { cell: \"D3\", equals: 0.4, tol: 0.001 }, { cell: \"D4\", equals: 0.64, tol: 0.001 }, { cell: \"D5\", equals: 0.56, tol: 0.001 },\n            { cell: \"B6\", equals: 800 }, { cell: \"C6\", equals: 429 }, { cell: \"D6\", equals: 0.53625, tol: 0.001 }, { cell: \"D8\", equals: 0.89375, tol: 0.001 },\n          ],\n          hint: \"Coverage is numerator divided by denominator: =C2/B2. The overall coverage is =C6/B6, not the average of D2:D5. The % of target achieved is =D6/D7.\",\n          solution: { D2: \"=C2/B2\", D3: \"=C3/B3\", D4: \"=C4/B4\", D5: \"=C5/B5\", B6: \"=SUM(B2:B5)\", C6: \"=SUM(C2:C5)\", D6: \"=C6/B6\", D8: \"=D6/D7\" } },\n        { type: \"form\", id: \"meal-m2-l3-lab2\", title: \"Complete an indicator reference sheet\",\n          task: \"A fictional food assistance project for displaced households in the North-West uses the indicator \\\"% of targeted households with an acceptable Food Consumption Score (FCS)\\\". Choose the right content for each field of its reference sheet.\",\n          hint: \"The FCS is calculated for each surveyed household. The indicator counts households in the acceptable range, divided by all surveyed households.\",\n          fields: [\n            { kind: \"select\", label: \"Numerator\", options: [\"Number of households that received food vouchers\", \"Number of surveyed targeted households whose FCS is in the acceptable range\", \"Average FCS of surveyed households\", \"Total number of households in the commune\"], answer: 1, explain: \"Only households in the acceptable range are counted on top.\" },\n            { kind: \"select\", label: \"Denominator\", options: [\"Number of targeted households surveyed in the same round\", \"Number of vouchers printed\", \"Number of enumerators\", \"Population of the region\"], answer: 0, explain: \"The denominator is all surveyed targeted households, including those with poor or borderline scores.\" },\n            { kind: \"select\", label: \"Unit\", options: [\"FCFA\", \"Number of meals\", \"Percentage\", \"Kilograms\"], answer: 2 },\n            { kind: \"select\", label: \"Data source and method\", options: [\"Distribution lists\", \"Household survey on a random sample of targeted households, asking about foods eaten in the last 7 days\", \"The warehouse stock report\", \"Staff interviews\"], answer: 1, explain: \"The FCS is built from a 7-day food recall asked in a household survey.\" },\n            { kind: \"select\", label: \"Frequency\", options: [\"Every day\", \"Baseline, then after each distribution cycle and at endline\", \"Once, at the end only\", \"Whenever a staff member has time\"], answer: 1, explain: \"Post-distribution monitoring after each cycle lets the team react during the project, not only at the end.\" },\n            { kind: \"select\", label: \"Most useful disaggregation for this project\", options: [\"Colour of the voucher\", \"Sex of the household head and displacement status (IDP / host)\", \"Enumerator's name\", \"Day of the week\"], answer: 1, explain: \"Comparing female- and male-headed households, and IDPs and hosts, shows who is being left behind.\" },\n          ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"In a health district of the Far North, a project and the district team both report ANC coverage. The project divides by women registered at ANC1; the district divides by the estimated number of pregnancies in the population. Neither is wrong, but the figures differ by 20 points. Writing the definition in the IRS, and noting the difference in reports, avoids a painful meeting with the donor.\" },\n        { type: \"check\", id: \"meal-m2-l3-c1\", question: \"Facility A has 90 of 100 children vaccinated and facility B has 10 of 50. What is the overall vaccination coverage?\", options: [\"55%, the average of 90% and 20%\", \"66.7%, 100 vaccinated out of 150\", \"50%\", \"90%\"], answer: 1, explain: \"Add the numerators and the denominators, then divide: 100 ÷ 150 = 66.7%. Averaging the two percentages ignores that facility A serves twice as many children.\" },\n        { type: \"task\", id: \"meal-m2-l3-t1\", title: \"Practice\", items: [\n          \"Choose one outcome indicator from your logframe\",\n          \"Write its full reference sheet using the nine fields in this lesson\",\n          \"Check that the numerator is a subset of the denominator\",\n          \"Ask a colleague to calculate the indicator from your sheet alone and compare results\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Recommended performance indicator reference sheet\", url: \"https://usaidlearninglab.org/resources/recommended-performance-indicator-reference-sheet\", source: \"USAID Learning Lab\" },\n        ] },\n      ],\n    },\n    // ───────────────────────────── LESSON 4 ─────────────────────────────\n    {\n      id: \"meal-m2-l4\",\n      title: \"The MEAL plan: methods, calendar, roles and budget\",\n      minutes: 24,\n      objectives: [\n        \"Build a MEAL plan table that links each indicator to a method, frequency and owner\",\n        \"Draw up a data collection and reporting calendar\",\n        \"Estimate a MEAL budget and check it against the 5–10% rule of thumb\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"The logframe says what you will measure; the MEAL plan says how, when, by whom and at what cost. It is the working document the MEAL team uses every week, and the first thing an auditor or donor monitor asks to see.\" },\n        { type: \"h\", text: \"The MEAL plan table\" },\n        { type: \"table\", head: [\"Indicator\", \"Method and tool\", \"Frequency\", \"Responsible\", \"Used for\"], rows: [\n          [\"Number of teachers trained (by sex)\", \"Attendance sheets entered in Excel\", \"After each training\", \"Education officer\", \"Monthly report\"],\n          [\"% of enrolled girls who finish the school year\", \"School register review in KoboToolbox\", \"Each term\", \"MEAL assistant with head teachers\", \"Quarterly review, donor report\"],\n          [\"Parents' attitudes to girls' schooling\", \"Focus group discussions and key informant interviews\", \"Baseline and endline\", \"MEAL officer\", \"Evaluation, learning workshop\"],\n          [\"Complaints received and resolved\", \"Hotline and suggestion boxes, complaints log\", \"Continuous, reviewed monthly\", \"Accountability officer\", \"Management meeting\"],\n        ] },\n        { type: \"h\", text: \"Choosing methods\" },\n        { type: \"list\", items: [\n          \"Routine monitoring from project records (registers, distribution lists, attendance sheets) for output indicators.\",\n          \"Household or individual surveys on a sample for outcome indicators at baseline, midline and endline.\",\n          \"Focus group discussions and key informant interviews to understand why things change or do not.\",\n          \"Post-distribution monitoring after cash, voucher or in-kind distributions.\",\n          \"A complaints and feedback mechanism that runs all the time, not only during surveys.\",\n        ] },\n        { type: \"path\", items: [\"Projects\", \"New\", \"Build from scratch\"], note: \"In KoboToolbox, start a new form for a survey or a monitoring checklist. Forms work offline once downloaded to the phone.\" },\n        { type: \"h\", text: \"The data collection calendar\" },\n        { type: \"table\", head: [\"Activity\", \"Q1\", \"Q2\", \"Q3\", \"Q4\"], rows: [\n          [\"Baseline survey\", \"X\", \"\", \"\", \"\"],\n          [\"Monthly monitoring of outputs\", \"X\", \"X\", \"X\", \"X\"],\n          [\"Post-distribution monitoring\", \"\", \"X\", \"\", \"X\"],\n          [\"Quarterly review meeting\", \"X\", \"X\", \"X\", \"X\"],\n          [\"Annual learning workshop\", \"\", \"\", \"\", \"X\"],\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Plan around the context\", text: \"Avoid field surveys during the peak rainy season when roads are cut, during exams for school surveys, and during major religious holidays. Plan enough time for data entry and cleaning before each report deadline.\" },\n        { type: \"h\", text: \"Roles and responsibilities\" },\n        { type: \"table\", head: [\"Role\", \"Main MEAL responsibilities\"], rows: [\n          [\"Project manager\", \"Uses the data for decisions; approves the MEAL plan and reports\"],\n          [\"MEAL officer\", \"Writes the MEAL plan and IRS, designs tools, trains enumerators, checks data quality, analyses and reports\"],\n          [\"Field staff and partners\", \"Fill registers and monitoring forms correctly and on time\"],\n          [\"Enumerators\", \"Collect survey data following the protocol and consent rules\"],\n          [\"Communities\", \"Give feedback, take part in reviews and hear the results\"],\n        ] },\n        { type: \"h\", text: \"Budgeting MEAL\" },\n        { type: \"p\", text: \"A common rule of thumb is to plan about 5–10% of the total project budget for MEAL. Small projects with a large external evaluation may need more; large delivery projects with simple outputs may need less. What matters is that each activity in the MEAL plan has a line in the budget.\" },\n        { type: \"list\", items: [\n          \"Staff: MEAL officer and assistants, or the share of their time charged to the project.\",\n          \"Surveys: enumerator allowances, transport, training, printing, phones or tablets and power banks.\",\n          \"Evaluation: external consultant fees for a midterm or final evaluation.\",\n          \"Accountability and learning: hotline, suggestion boxes, review meetings and learning workshops.\",\n        ] },\n        { type: \"sheet\", id: \"meal-m2-l4-sheet\", title: \"Check a MEAL budget\",\n          task: \"A fictional 3-year education project has a total budget of 320 000 000 FCFA. Fill **B8** with the total MEAL budget, **B10** with its share of the project budget, **B11** with \\\"OK\\\" if the share is between 5% and 10% (inclusive) and \\\"Review\\\" otherwise, and **B12** with the share of the MEAL budget spent on the final evaluation.\",\n          data: [\n            [\"MEAL line item\", \"Cost (FCFA)\"],\n            [\"Baseline survey\", 3500000],\n            [\"Final evaluation (external)\", 9000000],\n            [\"MEAL officer (50% of time)\", 7200000],\n            [\"Tablets and power banks\", 1800000],\n            [\"Routine monitoring visits\", 2400000],\n            [\"Learning workshops\", 1100000],\n            [\"Total MEAL budget\", null],\n            [\"Total project budget\", 320000000],\n            [\"MEAL share of project budget\", null],\n            [\"Within 5–10%?\", null],\n            [\"Evaluation share of MEAL budget\", null],\n          ],\n          editable: [\"B8\", \"B10\", \"B11\", \"B12\"],\n          checks: [{ cell: \"B8\", equals: 25000000 }, { cell: \"B10\", equals: 0.078125, tol: 0.0005 }, { cell: \"B11\", equals: \"OK\" }, { cell: \"B12\", equals: 0.36, tol: 0.001 }],\n          hint: \"B8 is a SUM of B2:B7. B10 divides B8 by B9. B11 needs IF with AND: =IF(AND(B10>=5%,B10<=10%),\\\"OK\\\",\\\"Review\\\"). B12 is the evaluation line divided by the MEAL total.\",\n          solution: { B8: \"=SUM(B2:B7)\", B10: \"=B8/B9\", B11: \"=IF(AND(B10>=0.05,B10<=0.1),\\\"OK\\\",\\\"Review\\\")\", B12: \"=B3/B8\" } },\n        { type: \"h\", text: \"The reporting cycle\" },\n        { type: \"steps\", items: [\n          \"Monthly: field teams submit activity data; the MEAL officer checks and updates the indicator tracking table.\",\n          \"Quarterly: the team reviews progress against targets and agrees corrective actions; a short report goes to the donor if required.\",\n          \"Annually: an annual report, a learning workshop with partners and communities, and an update of the Theory of Change if needed.\",\n          \"End of project: final evaluation, final report and sharing of results with communities.\",\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A local NGO in Bamenda submits a proposal with no MEAL lines apart from a final evaluation. The donor asks for 7% of the budget for MEAL and a MEAL plan. The MEAL officer adds a baseline survey, a half-time assistant, phones for offline KoboToolbox collection and a feedback hotline, and links each line to an indicator in the plan.\" },\n        { type: \"check\", id: \"meal-m2-l4-c1\", question: \"A project has a total budget of 150 000 000 FCFA. The MEAL lines add up to 4 500 000 FCFA. What does the rule of thumb suggest?\", options: [\"The MEAL budget is 3%, below the usual 5–10%: check whether key MEAL activities are missing\", \"The MEAL budget is 30%, far too high\", \"The MEAL budget is exactly right at 10%\", \"MEAL should not have its own budget\"], answer: 0, explain: \"4 500 000 ÷ 150 000 000 = 3%. That is below the usual range, so check that surveys, staff time and accountability costs are all budgeted.\" },\n        { type: \"task\", id: \"meal-m2-l4-t1\", title: \"Practice\", items: [\n          \"Turn your logframe indicators into a MEAL plan table with method, frequency, responsible and use\",\n          \"Draw a 12-month data collection calendar that avoids the rainy season peak in your area\",\n          \"List every MEAL cost and total it in Excel\",\n          \"Calculate the MEAL share of your project budget and compare it with 5–10%\",\n          \"Write who receives each report and when\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Monitoring\", url: \"https://www.betterevaluation.org/methods-approaches/themes/monitoring\", source: BE },\n          { label: \"Manage an evaluation or evaluation system\", url: \"https://www.betterevaluation.org/frameworks-guides/rainbow-framework/manage\", source: BE },\n        ] },\n      ],\n    },\n    // ───────────────────────────── PRACTICE ─────────────────────────────\n    {\n      id: \"meal-m2-practice\",\n      title: \"Practice lab: planning MEAL for real projects\",\n      minutes: 35,\n      objectives: [\n        \"Place results of a livelihoods project on the results chain\",\n        \"Track output indicators against targets for a nutrition project\",\n        \"Judge indicators, means of verification and assumptions in an education logframe\",\n        \"Calculate a WASH outcome indicator and analyse progress towards its target\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" },\n        { type: \"h\", text: \"Exercise 1: A livelihoods project in the West\" },\n        { type: \"form\", id: \"meal-pr-m2-levels\", level: \"beginner\", title: \"Where does each result belong?\",\n          task: \"A fictional project supports women's savings groups and poultry farming in the West region. Choose the results level of each statement.\",\n          hint: \"Resources are inputs, verbs are activities, things delivered are outputs, changes in practice or income are outcomes, and long-term well-being is impact.\",\n          fields: [\n            { kind: \"select\", label: \"Two livelihoods officers and a motorbike\", options: LEVELS, answer: 0, explain: \"Staff and equipment are inputs.\" },\n            { kind: \"select\", label: \"Set up village savings and loan associations\", options: LEVELS, answer: 1 },\n            { kind: \"select\", label: \"30 savings groups formed with 750 members\", options: LEVELS, answer: 2, explain: \"Groups formed are delivered by the project: an output.\" },\n            { kind: \"select\", label: \"Group members use loans to start or expand a poultry business\", options: LEVELS, answer: 3, explain: \"A change in what members do is an outcome.\" },\n            { kind: \"select\", label: \"Members' households have a higher and more stable income\", options: LEVELS, answer: 3, explain: \"Income change within the project period is usually an outcome. Impact is broader and longer term.\" },\n            { kind: \"select\", label: \"Poverty falls in the participating communities\", options: LEVELS, answer: 4 },\n            { kind: \"select\", label: \"Distribute 5 000 day-old chicks\", options: LEVELS, answer: 1, explain: \"The verb \\\"distribute\\\" describes an activity. \\\"5 000 chicks distributed\\\" would be an output.\" },\n          ] },\n        { type: \"h\", text: \"Exercise 2: Nutrition outputs in the East\" },\n        { type: \"sheet\", id: \"meal-pr-m2-itt\", level: \"intermediate\", title: \"Output indicators against targets\",\n          task: \"Fictional quarterly data from a nutrition project for refugee and host communities. Fill **D2:D5** with the % of target achieved, **E2:E5** with \\\"On track\\\" when it is at least 90% and \\\"Behind\\\" otherwise, and **E6** with the number of indicators on track.\",\n          data: [\n            [\"Output indicator\", \"Target\", \"Achieved\", \"% of target\", \"Status\"],\n            [\"Children 6–59 months screened (MUAC)\", 4000, 3520, null, null],\n            [\"Children with SAM referred for treatment\", 180, 126, null, null],\n            [\"Caregivers trained on infant feeding\", 600, 642, null, null],\n            [\"Community health workers trained\", 40, 40, null, null],\n            [null, null, null, \"Indicators on track\", null],\n          ],\n          editable: [\"D2\", \"D3\", \"D4\", \"D5\", \"E2\", \"E3\", \"E4\", \"E5\", \"E6\"],\n          checks: [\n            { cell: \"D2\", equals: 0.88, tol: 0.001 }, { cell: \"D3\", equals: 0.7, tol: 0.001 }, { cell: \"D4\", equals: 1.07, tol: 0.001 }, { cell: \"D5\", equals: 1, tol: 0.001 },\n            { cell: \"E2\", equals: \"Behind\" }, { cell: \"E3\", equals: \"Behind\" }, { cell: \"E4\", equals: \"On track\" }, { cell: \"E5\", equals: \"On track\" }, { cell: \"E6\", equals: 2 },\n          ],\n          hint: \"% of target is =C2/B2. The status is =IF(D2>=0.9,\\\"On track\\\",\\\"Behind\\\"). Count the statuses with COUNTIF(E2:E5,\\\"On track\\\"). Values above 100% are possible.\",\n          solution: { D2: \"=C2/B2\", D3: \"=C3/B3\", D4: \"=C4/B4\", D5: \"=C5/B5\", E2: \"=IF(D2>=0.9,\\\"On track\\\",\\\"Behind\\\")\", E3: \"=IF(D3>=0.9,\\\"On track\\\",\\\"Behind\\\")\", E4: \"=IF(D4>=0.9,\\\"On track\\\",\\\"Behind\\\")\", E5: \"=IF(D5>=0.9,\\\"On track\\\",\\\"Behind\\\")\", E6: \"=COUNTIF(E2:E5,\\\"On track\\\")\" } },\n        { type: \"h\", text: \"Exercise 3: An education logframe in the North-West\" },\n        { type: \"form\", id: \"meal-pr-m2-logframe\", level: \"advanced\", title: \"Review an accelerated learning logframe\",\n          task: \"A fictional accelerated learning programme helps out-of-school IDP children aged 9–14 catch up on literacy and numeracy. Review its logframe and answer each question.\",\n          hint: \"Think about what each column is for, which level an indicator measures, and whether it is SMART. For the calculations, divide first, then compare with the target.\",\n          fields: [\n            { kind: \"select\", label: \"The outcome \\\"Children gain basic literacy\\\" has the indicator \\\"Number of learners enrolled\\\". What is wrong?\", options: [\"Nothing, it is a good outcome indicator\", \"It measures an output (enrolment), not the change in literacy\", \"It is not disaggregated by region\", \"It is an impact indicator\"], answer: 1, explain: \"Enrolment shows the service reached children. The outcome needs evidence of learning, for example the % of learners passing a literacy test.\" },\n            { kind: \"select\", label: \"Best indicator for \\\"Children gain basic literacy\\\"\", options: [\"% of learners (by sex and age) who pass the end-of-cycle reading test, at the end of each 9-month cycle\", \"Number of reading books distributed\", \"Learners are happier\", \"Number of teachers recruited\"], answer: 0 },\n            { kind: \"select\", label: \"Best means of verification for that indicator\", options: [\"Enrolment forms\", \"Results of a standard reading test given by trained assessors, entered in a database\", \"Photos of classes\", \"The donor contract\"], answer: 1, explain: \"Test results given in the same way to every learner are credible, comparable evidence.\" },\n            { kind: \"select\", label: \"Which is an assumption, not a result?\", options: [\"Facilitators trained\", \"Learning centres equipped\", \"Families do not have to move again during the cycle\", \"Learners pass the reading test\"], answer: 2, explain: \"Further displacement is outside the project's control and would break the chain.\" },\n            { kind: \"select\", label: \"Which disaggregation matters most for this indicator?\", options: [\"Sex, age group and disability status\", \"Colour of the classroom\", \"Name of the facilitator only\", \"None, the total is enough\"], answer: 0, explain: \"Girls, older learners and children with disabilities often drop out or struggle more. Without disaggregation you cannot see it.\" },\n            { kind: \"text\", label: \"At the end of the cycle, 208 of 320 learners passed the reading test. Type the pass rate as a whole-number percentage.\", pattern: \"^65\\\\s*%?$\", example: \"65\", placeholder: \"%\", mono: true, explain: \"208 ÷ 320 = 0.65, so 65% of learners passed.\" },\n            { kind: \"text\", label: \"The target is 70%. Type the % of target achieved, rounded to a whole number.\", pattern: \"^93\\\\s*%?$|^92[.,]9\\\\d*\\\\s*%?$\", example: \"93\", placeholder: \"%\", mono: true, explain: \"65% ÷ 70% = 0.929, so about 93% of the target is achieved.\" },\n          ] },\n        { type: \"h\", text: \"Exercise 4: WASH outcome in the Far North\" },\n        { type: \"sheet\", id: \"meal-pr-m2-wash\", level: \"expert\", title: \"From the reference sheet to the target analysis\",\n          task: \"The IRS defines the indicator as surveyed households that treat their drinking water, divided by all surveyed households. Fictional endline data by village is below; one village could not be surveyed. Fill **H4** with the overall value, **H5** with the value for Mora commune only, **H6** with the % of target achieved, **H7** with the progress from baseline to target, **H8** with the status, and **H9** with the number of villages without data.\",\n          data: [\n            [\"Village\", \"Commune\", \"HH surveyed\", \"HH treating water\", null, null, \"Measure\", \"Value\"],\n            [\"MR-01\", \"Mora\", 48, 22, null, null, \"Baseline\", 0.32],\n            [\"MR-02\", \"Mora\", 52, 30, null, null, \"Target\", 0.6],\n            [\"MK-01\", \"Mokolo\", 40, 18, null, null, \"Current value\", null],\n            [\"MK-02\", \"Mokolo\", null, null, null, null, \"Value, Mora\", null],\n            [\"KZ-01\", \"Koza\", 45, 27, null, null, \"% of target\", null],\n            [\"KZ-02\", \"Koza\", 55, 26, null, null, \"Progress to target\", null],\n            [\"MR-03\", \"Mora\", 60, 33, null, null, \"Status\", null],\n            [null, null, null, null, null, null, \"Villages without data\", null],\n          ],\n          editable: [\"H4\", \"H5\", \"H6\", \"H7\", \"H8\", \"H9\"],\n          checks: [\n            { cell: \"H4\", equals: 0.52, tol: 0.001 }, { cell: \"H5\", equals: 0.53125, tol: 0.001 }, { cell: \"H6\", equals: 0.866667, tol: 0.001 },\n            { cell: \"H7\", equals: 0.714286, tol: 0.001 }, { cell: \"H8\", equals: \"Monitor\" }, { cell: \"H9\", equals: 1 },\n          ],\n          hint: \"Pool the data: =SUM(D2:D8)/SUM(C2:C8), not the average of village percentages. For Mora use SUMIF on column B for both the numerator and the denominator. Progress is (current − baseline) ÷ (target − baseline). Status: \\\"On track\\\" from 80% progress, \\\"Monitor\\\" from 50%, otherwise \\\"Off track\\\" (IFS or nested IF). COUNTBLANK finds the village without data.\",\n          solution: {\n            H4: \"=SUM(D2:D8)/SUM(C2:C8)\",\n            H5: \"=SUMIF(B2:B8,\\\"Mora\\\",D2:D8)/SUMIF(B2:B8,\\\"Mora\\\",C2:C8)\",\n            H6: \"=H4/H3\",\n            H7: \"=(H4-H2)/(H3-H2)\",\n            H8: \"=IFS(H7>=0.8,\\\"On track\\\",H7>=0.5,\\\"Monitor\\\",TRUE,\\\"Off track\\\")\",\n            H9: \"=COUNTBLANK(C2:C8)\",\n          } },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"meal-m2-quiz\",\n    title: \"Module 2 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"\\\"500 hygiene kits distributed\\\" is a result at which level?\", options: [\"Inputs\", \"Outputs\", \"Outcome\", \"Impact\"], answer: 1, explain: \"Kits distributed are delivered directly by the project, so this is an output.\" },\n      { id: \"q2\", question: \"What is an assumption in a Theory of Change?\", options: [\"An activity the project will carry out\", \"A target value for an indicator\", \"A condition outside the project's control that must hold for the next level to follow\", \"The budget of the project\"], answer: 2, explain: \"Assumptions link the levels. If they fail, the chain breaks even when the project does everything it planned.\" },\n      { id: \"q3\", question: \"Which indicator is SMART?\", options: [\"% of targeted farmers (by sex) using improved seed in the 2027 main season, from the endline survey\", \"Improved agriculture\", \"Farmers are trained well\", \"More food in the region\"], answer: 0, explain: \"It is specific about who and what, measurable, relevant and time-bound.\" },\n      { id: \"q4\", question: \"In a logframe, where do you write \\\"Distribution lists signed by beneficiaries\\\"?\", options: [\"Narrative summary\", \"Indicators\", \"Assumptions\", \"Means of verification\"], answer: 3, explain: \"It is the source of evidence for an output indicator, so it belongs in the means of verification column.\" },\n      { id: \"q5\", question: \"Which field of an indicator reference sheet states the value at the start of the project?\", options: [\"Target\", \"Frequency\", \"Baseline\", \"Denominator\"], answer: 2, explain: \"The baseline is the starting value, with its date and source. Progress is measured against it.\" },\n      { id: \"q6\", question: \"Three health facilities report 30/50, 40/100 and 90/200 children vaccinated. What is the overall coverage?\", options: [\"45.7%\", \"48.3%, the average of the three rates\", \"60%\", \"40%\"], answer: 0, explain: \"Pool the data: 160 ÷ 350 = 45.7%. Averaging the three rates (60%, 40% and 45%) gives 48.3%, which overweights the small facility. Always divide the totals.\" },\n      { id: \"q7\", question: \"What share of the total budget is commonly suggested for MEAL?\", options: [\"Less than 1%\", \"About 25–30%\", \"Nothing: MEAL is covered by overheads\", \"About 5–10%\"], answer: 3, explain: \"About 5–10% is a common rule of thumb. Adjust it to the size of the project and the evaluation needs.\" },\n      { id: \"q8\", question: \"Why must disaggregation be planned at design time?\", options: [\"Because donors forbid adding it later\", \"Because data collection tools must record sex, age, location or status, or the data cannot be split later\", \"Because it reduces the sample size\", \"Because it replaces the baseline\"], answer: 1, explain: \"If a register or questionnaire does not record sex or age, nobody can disaggregate the results afterwards.\" },\n    ],\n  },\n};\n","client/src/data/courses/meal/m3.ts":"import type { Block, CourseModule } from \"../../../lms/types\";\n\n// MEAL Professional Certificate — Module 3: Data Collection Methods\n// Original Analytix Engineering material. All projects, organisations, people and figures are fictional.\n\nconst BE = \"BetterEvaluation\";\nconst XLSF = \"XLSForm\";\nconst ODK = \"ODK Docs\";\nconst SCTO = \"SurveyCTO Docs\";\n\nconst METHODS = [\"Household survey\", \"Registers and routine data\", \"Key informant interviews\", \"Focus group discussions\", \"Direct observation\"];\nconst DESIGNS = [\"Simple random sampling\", \"Systematic sampling\", \"Stratified sampling\", \"Cluster sampling\", \"Purposive sampling\"];\nconst PROBLEMS = [\"Leading question\", \"Double-barrelled question\", \"Overlapping or missing response options\", \"Vague or undefined term\", \"Too sensitive for this setting\"];\nconst YES_NO = [{ list_name: \"yes_no\", name: \"yes\", label: \"Yes\" }, { list_name: \"yes_no\", name: \"no\", label: \"No\" }];\n\nconst INTRO: Block = { type: \"p\", text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" };\n\nexport const m3: CourseModule = {\n  id: \"meal-m3\",\n  number: 3,\n  title: \"Data Collection Methods\",\n  summary: \"Surveys, interviews and focus groups, sampling, questionnaire design and data quality in the field.\",\n  hours: 20,\n  lessons: [\n    // ─────────────────────────────── LESSON 1 ───────────────────────────────\n    {\n      id: \"meal-m3-l1\",\n      title: \"Quantitative and qualitative methods\",\n      minutes: 20,\n      objectives: [\n        \"Describe the main data collection methods used in MEAL and what each one can tell you\",\n        \"Choose the method that fits an information need, a budget and a context\",\n        \"Combine methods and triangulate sources to strengthen your findings\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Every indicator in your MEAL plan needs a way of getting its data. Some questions ask how many or how much, and need numbers from many people. Others ask why or how, and need the words and experiences of a few well-chosen people. Choosing the right method is the first quality decision you make, long before the first interview.\" },\n        { type: \"h\", text: \"Quantitative and qualitative in one sentence each\" },\n        { type: \"callout\", tone: \"key\", title: \"Numbers and meaning\", text: \"Quantitative methods measure how many, how much and how often, using standard questions asked to a sample large enough to represent the population. Qualitative methods explore why and how, using open conversations with a small number of people chosen for what they know or have lived.\" },\n        { type: \"h\", text: \"The five methods you will use most\" },\n        { type: \"table\", head: [\"Method\", \"Type\", \"What it tells you\", \"Watch out for\"], rows: [\n          [\"Household survey\", \"Quantitative\", \"Prevalence, coverage and practices across a population, for example the share of households treating drinking water\", \"Costly and slow; needs a good sample and a tested questionnaire\"],\n          [\"Registers and routine data\", \"Quantitative\", \"Activities and services delivered over time: children vaccinated, kits distributed, pupils enrolled\", \"Only counts people who reached the service; quality depends on how registers are filled\"],\n          [\"Key informant interviews (KII)\", \"Qualitative\", \"Expert or insider views: a head of health district, a teacher, a traditional chief, a camp manager\", \"One person's view; choose informants from different positions\"],\n          [\"Focus group discussions (FGD)\", \"Qualitative\", \"Shared norms, perceptions and reasons within a group of 6 to 10 similar people\", \"Dominant voices; not for personal or sensitive topics\"],\n          [\"Direct observation\", \"Quantitative or qualitative\", \"What really happens: whether a latrine is used, whether soap is present, how a distribution is organised\", \"People behave differently when watched; needs a clear checklist\"],\n        ] },\n        { type: \"h\", text: \"When to use which\" },\n        { type: \"list\", items: [\n          \"You need a percentage for the whole target population, comparable at baseline and endline: household survey.\",\n          \"You need to follow outputs every month: registers and routine data, often from the health or education system.\",\n          \"You need to understand how a service or a decision works from people who know it well: key informant interviews.\",\n          \"You need to know how a community sees a problem or why people behave as they do: focus group discussions.\",\n          \"You need to check a physical condition or a practice without relying on what people say: direct observation.\",\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Organise focus groups by similarity\", text: \"Hold separate groups for women and men, for younger and older people, and for displaced and host households. People speak more freely among peers. Aim for 6 to 10 participants, one facilitator and one note-taker, and about 60 to 90 minutes.\" },\n        { type: \"form\", id: \"meal-m3-l1-methods\", title: \"Choose the method\", task: \"A fictional WASH and health project in the East region needs the information below. Choose the method that fits each need best.\",\n          hint: \"Ask: do I need a number for the population, a trend of services delivered, an expert view, a group's perceptions, or proof of a physical condition?\",\n          fields: [\n            { kind: \"select\", label: \"The share of households in the project area that treat their drinking water, for the baseline\", options: METHODS, answer: 0, explain: \"A population percentage that must be compared later calls for a household survey with a representative sample.\" },\n            { kind: \"select\", label: \"The number of children under 5 treated for diarrhoea each month in the four supported health centres\", options: METHODS, answer: 1, explain: \"Monthly service data already exists in health centre registers; use it rather than a new survey.\" },\n            { kind: \"select\", label: \"How the health district plans its supervision visits and what blocks them\", options: METHODS, answer: 2, explain: \"A few people inside the district team know this well: interview them as key informants.\" },\n            { kind: \"select\", label: \"Why many young women prefer the river to the new borehole\", options: METHODS, answer: 3, explain: \"Shared perceptions and social reasons are best explored in a focus group of young women.\" },\n            { kind: \"select\", label: \"Whether handwashing stations in 20 schools have water and soap on the day of the visit\", options: METHODS, answer: 4, explain: \"A physical condition is checked most reliably by looking, with a short observation checklist.\" },\n            { kind: \"select\", label: \"The views of the chief of a refugee-hosting village on how water committees are chosen\", options: METHODS, answer: 2 },\n          ] },\n        { type: \"h\", text: \"Mixed methods\" },\n        { type: \"p\", text: \"Most evaluations combine methods, because numbers without explanations and stories without scale both leave questions open. The order in which you combine them depends on what you need to know first.\" },\n        { type: \"table\", head: [\"Design\", \"How it works\", \"Example\"], rows: [\n          [\"Explanatory (numbers first)\", \"A survey finds a pattern, then interviews or FGDs explain it\", \"The survey shows low bed net use in one subdivision; FGDs reveal that nets are used for fishing\"],\n          [\"Exploratory (words first)\", \"FGDs or KIIs identify issues, then a survey measures how common they are\", \"FGDs list reasons for school dropout; the survey measures how many households cite each reason\"],\n          [\"Convergent (at the same time)\", \"Survey and qualitative work run in parallel and are compared at analysis\", \"A food security survey and KIIs with market traders are analysed together\"],\n        ] },\n        { type: \"h\", text: \"Triangulation\" },\n        { type: \"p\", text: \"Triangulation means checking a finding from more than one angle before you trust it. If the survey, the health centre registers and the focus groups all point the same way, you can report the finding with confidence. If they disagree, the disagreement itself is a finding to investigate.\" },\n        { type: \"list\", items: [\n          \"Triangulate methods: compare survey results with observation or FGDs.\",\n          \"Triangulate sources: compare what women, men, staff and local authorities say.\",\n          \"Triangulate data collectors: check whether results differ between enumerators or teams.\",\n        ] },\n        { type: \"check\", id: \"meal-m3-l1-c1\", question: \"A survey shows that 85% of households say they use a latrine, but observation finds that many latrines have no path and no signs of use. What should the MEAL officer do?\", options: [\"Report 85% because the survey is larger\", \"Report the observation only and drop the survey\", \"Treat the gap as a finding, explore it in FGDs, and report both sources with their limits\", \"Repeat the survey with more households\"], answer: 2, explain: \"When methods disagree, triangulation has done its job: it has revealed a possible reporting bias. Investigate the reason and report transparently.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A fictional livelihoods project in the Far North measured household income with a survey and found no change. Focus groups with women's savings groups explained why: income had risen, but women were reluctant to declare it in front of other household members. The team moved the income questions to a private moment and added observation of assets.\" },\n        { type: \"task\", id: \"meal-m3-l1-t1\", title: \"Practice\", items: [\n          \"List the outcome indicators of a project you know and write the method used for each\",\n          \"Identify one indicator that relies only on self-reported data and suggest a second source to triangulate it\",\n          \"Draft five guiding questions for a focus group on why people do or do not use a service\",\n          \"List three key informants for that project and the position of each\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Triangulation\", url: \"https://www.betterevaluation.org/methods-approaches/methods/triangulation\", source: BE },\n          { label: \"Key informant interviews\", url: \"https://www.betterevaluation.org/methods-approaches/methods/key-informant-interviews\", source: BE },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 2 ───────────────────────────────\n    {\n      id: \"meal-m3-l2\",\n      title: \"Sampling basics and sample size\",\n      minutes: 25,\n      objectives: [\n        \"Explain the key sampling terms and choose between probability and purposive sampling\",\n        \"Select a sampling design that fits the frame, the terrain and the reporting needs\",\n        \"Calculate a survey sample size with the design effect and a non-response adjustment\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"You rarely interview everyone. Sampling lets you talk to a few hundred households and still say something reliable about thousands, as long as the sample is drawn properly and is large enough. Get the sample wrong and even a perfect questionnaire will give misleading results.\" },\n        { type: \"h\", text: \"The vocabulary of sampling\" },\n        { type: \"table\", head: [\"Term\", \"Meaning\", \"Example\"], rows: [\n          [\"Population\", \"Everyone the result should describe\", \"All households in the 12 villages of the project\"],\n          [\"Sampling frame\", \"The list or map from which you draw the sample\", \"The beneficiary list, a village census, a list of schools\"],\n          [\"Sampling unit\", \"What you select\", \"A household, a pupil, a health centre, a village\"],\n          [\"Sample\", \"The units actually selected\", \"420 households drawn from the beneficiary list\"],\n          [\"Respondent\", \"The person who answers for the unit\", \"The adult in charge of meals in the household\"],\n        ] },\n        { type: \"h\", text: \"Probability sampling designs\" },\n        { type: \"table\", head: [\"Design\", \"How it works\", \"Use it when\"], rows: [\n          [\"Simple random\", \"Draw units at random from a complete list\", \"You have a good, complete list and units are easy to reach\"],\n          [\"Systematic\", \"Pick a random start, then every k-th unit (k = population ÷ sample)\", \"Units are in a list or pass by one after another, such as patients leaving a clinic\"],\n          [\"Stratified\", \"Split the population into groups (strata) and sample within each\", \"You must report results separately for groups, such as refugees and hosts, or three health districts\"],\n          [\"Cluster\", \"Select groups first (villages, blocks), then households inside them\", \"There is no list of households and the area is large; saves travel time\"],\n        ] },\n        { type: \"h\", text: \"Purposive sampling for qualitative work\" },\n        { type: \"p\", text: \"In probability sampling every unit has a known chance of being selected, which allows you to generalise and calculate a margin of error. Focus groups and key informant interviews do not aim to represent the population statistically. You choose participants on purpose for what they know or have lived: women who stopped attending antenatal care, chiefs of villages with and without a water point, the most and least successful savings groups. Keep going until new interviews stop bringing new ideas.\" },\n        { type: \"form\", id: \"meal-m3-l2-designs\", title: \"Choose the sampling design\", task: \"For each situation from fictional projects in Cameroon, choose the most suitable sampling design.\",\n          hint: \"A complete list and easy access suggests simple random; a flow of people suggests systematic; separate results per group suggests stratified; no list and a large area suggests cluster; qualitative work suggests purposive.\",\n          fields: [\n            { kind: \"select\", label: \"A phone survey of 150 people drawn from a complete list of 1 200 cash transfer recipients\", options: DESIGNS, answer: 0, explain: \"With a complete list and phone access, a simple random draw is easy and gives every recipient the same chance.\" },\n            { kind: \"select\", label: \"Exit interviews with every 6th woman leaving an antenatal clinic, after a random start\", options: DESIGNS, answer: 1 },\n            { kind: \"select\", label: \"A survey that must give separate results for refugee households and host households in the East region\", options: DESIGNS, answer: 2, explain: \"Stratify by population group and draw a sufficient sample in each stratum.\" },\n            { kind: \"select\", label: \"A nutrition survey across 60 villages of the Far North with no household list\", options: DESIGNS, answer: 3, explain: \"Select villages first, then list and draw households inside the selected villages.\" },\n            { kind: \"select\", label: \"Six focus groups with women leaders from villages with high and low school attendance\", options: DESIGNS, answer: 4, explain: \"Qualitative participants are chosen on purpose to cover contrasting situations.\" },\n            { kind: \"select\", label: \"A survey of pupils where each of the four subdivisions must have its own reliable estimate\", options: DESIGNS, answer: 2 },\n          ] },\n        { type: \"h\", text: \"The sample size formula for a proportion\" },\n        { type: \"p\", text: \"Most MEAL surveys estimate a proportion, such as the share of children sleeping under a net. The basic sample size depends on three choices: how confident you want to be (z), what proportion you expect (p) and how precise the result must be (the margin of error e).\" },\n        { type: \"code\", text: \"n = z² × p × (1 − p) ÷ e²\\n\\nz = 1.96 for 95% confidence\\np = expected proportion (use 0.5 if you have no idea: it gives the largest sample)\\ne = margin of error, for example 0.05 for ±5 percentage points\" },\n        { type: \"list\", items: [\n          \"Design effect (deff): cluster samples are less precise than simple random ones, because neighbours tend to be alike. Multiply n by the design effect, often 1.5 to 2 for household surveys.\",\n          \"Non-response: some households will be absent or refuse. Divide by (1 − expected non-response rate), for example by 0.9 for 10%.\",\n          \"Round up at the end, never down: a sample of 853.7 means 854 households.\",\n          \"Several strata: if each stratum needs its own estimate, calculate the sample size for each stratum separately.\",\n        ] },\n        { type: \"steps\", title: \"Worked example\", items: [\n          \"Expected proportion unknown, so p = 0.5; confidence 95%, so z = 1.96; margin of error e = 0.05.\",\n          \"Basic sample: 1.96² × 0.5 × 0.5 ÷ 0.05² = 384.16.\",\n          \"Cluster design with deff = 2: 384.16 × 2 = 768.32.\",\n          \"Expected non-response of 10%: 768.32 ÷ 0.9 = 853.69, rounded up to 854 households.\",\n          \"With 12 households per cluster: 854 ÷ 12 = 71.2, rounded up to 72 clusters.\",\n        ] },\n        { type: \"path\", items: [\"Formulas\", \"Math & Trig\", \"ROUNDUP\"], note: \"In Excel, ROUNDUP(value, 0) rounds up to the next whole number. Use ^ for powers, for example 1.96^2.\" },\n        { type: \"sheet\", id: \"meal-m3-l2-sheet\", title: \"Calculate the sample size\", task: \"A fictional food security baseline in the Adamawa region expects 40% of households to have a poor food consumption score. Fill **B9** with the basic sample size (not rounded), **B10** after the design effect, **B11** after non-response, rounded up, and **B12** with the number of clusters needed, rounded up.\",\n          data: [[\"Parameter\", \"Value\"],\n            [\"Confidence level\", \"95%\"],\n            [\"z\", 1.96],\n            [\"Expected proportion p\", 0.4],\n            [\"Margin of error e\", 0.05],\n            [\"Design effect\", 1.5],\n            [\"Expected non-response\", 0.1],\n            [\"Households per cluster\", 20],\n            [\"Basic sample n\", null],\n            [\"n × design effect\", null],\n            [\"Final sample (rounded up)\", null],\n            [\"Clusters needed\", null]],\n          editable: [\"B9\", \"B10\", \"B11\", \"B12\"],\n          checks: [{ cell: \"B9\", equals: 368.79, tol: 0.01 }, { cell: \"B10\", equals: 553.19, tol: 0.01 }, { cell: \"B11\", equals: 615 }, { cell: \"B12\", equals: 31 }],\n          hint: \"B9: =B3^2*B4*(1-B4)/B5^2. B10: =B9*B6. B11: =ROUNDUP(B10/(1-B7),0). B12: =ROUNDUP(B11/B8,0).\",\n          solution: { B9: \"=B3^2*B4*(1-B4)/B5^2\", B10: \"=B9*B6\", B11: \"=ROUNDUP(B10/(1-B7),0)\", B12: \"=ROUNDUP(B11/B8,0)\" } },\n        { type: \"callout\", tone: \"warning\", title: \"Small populations\", text: \"When the population is small, for example 600 households, the formula gives a sample close to the whole population. A finite population correction reduces it: n divided by (1 + (n − 1) ÷ N), where N is the population size. Apply it before the design effect and non-response.\" },\n        { type: \"check\", id: \"meal-m3-l2-c1\", question: \"Why do you multiply the sample size by a design effect in a cluster survey?\", options: [\"To compensate for households that refuse\", \"Because households in the same cluster tend to be similar, so each one adds less new information\", \"To make the survey cheaper\", \"Because the donor requires a larger sample\"], answer: 1, explain: \"Neighbours share the same water point, market and customs. The design effect restores the precision lost by sampling in clusters. Refusals are handled by the separate non-response adjustment.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A fictional NGO planned a single sample of 400 households for a survey covering both refugees and host communities in the East region. When the donor asked for separate results for each group, the MEAL officer recalculated a sample for each stratum, which almost doubled the fieldwork. Deciding the reporting groups before calculating the sample would have avoided the surprise.\" },\n        { type: \"task\", id: \"meal-m3-l2-t1\", title: \"Practice\", items: [\n          \"Write the population, sampling frame, sampling unit and respondent of a survey you know\",\n          \"Rebuild the sample size sheet from the lab in your own Excel file\",\n          \"Recalculate it with a margin of error of 7% and compare the fieldwork days needed\",\n          \"List the groups your donor wants results for and decide whether you need strata\",\n          \"Describe how you would choose participants for three focus groups in the same project\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Sample: Rainbow Framework\", url: \"https://www.betterevaluation.org/frameworks-guides/rainbow-framework/describe/sample\", source: BE },\n          { label: \"Simple random sampling\", url: \"https://www.betterevaluation.org/methods-approaches/methods/simple-random-sampling\", source: BE },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 3 ───────────────────────────────\n    {\n      id: \"meal-m3-l3\",\n      title: \"Questionnaire design, skip logic and pre-testing\",\n      minutes: 25,\n      objectives: [\n        \"Write clear questions with complete, non-overlapping response options\",\n        \"Add skip logic and constraints to a mobile questionnaire in XLSForm\",\n        \"Organise translation, back-translation and a pilot test before data collection\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"A questionnaire is a measuring instrument. If a question is unclear, leading or missing an option, every enumerator will measure something slightly different, and no analysis can repair it afterwards. Good questionnaires are short, follow the indicators, and are tested with real respondents before the survey starts.\" },\n        { type: \"p\", text: \"List every indicator the survey must calculate, then write only the questions needed for them, plus the few variables needed for disaggregation, such as sex, age group and location. A question that feeds no indicator and no decision should go.\" },\n        { type: \"h\", text: \"Question types\" },\n        { type: \"table\", head: [\"Type\", \"Use it for\", \"Example\"], rows: [\n          [\"Single choice\", \"One answer from a list\", \"What is the main source of drinking water?\"],\n          [\"Multiple choice\", \"Several answers allowed\", \"Which of these foods did the child eat yesterday?\"],\n          [\"Numeric\", \"Counts and amounts\", \"How many people live in this household?\"],\n          [\"Scale\", \"Satisfaction or agreement, on 3 to 5 points\", \"How satisfied are you with the distribution? Very, somewhat, not at all\"],\n          [\"Open\", \"Explanations and unexpected answers; use sparingly\", \"What would you change in the service?\"],\n        ] },\n        { type: \"h\", text: \"Wording and response options\" },\n        { type: \"list\", items: [\n          \"Use simple words that respondents use themselves, and define terms such as household or last week.\",\n          \"Avoid leading questions that suggest the expected answer.\",\n          \"Avoid double-barrelled questions that ask two things at once; split them.\",\n          \"Set a clear recall period: yesterday, the last 7 days, the last 30 days.\",\n          \"Make response options mutually exclusive and complete; add Other (specify), Don't know and Refused where needed.\",\n          \"Put easy questions first and sensitive ones later, once trust is built.\",\n        ] },\n        { type: \"form\", id: \"meal-m3-l3-fix\", title: \"Spot the problem\", task: \"A draft questionnaire for a fictional water and hygiene project in the Littoral region contains the questions below. Choose the main problem of each one.\",\n          hint: \"Does the question suggest an answer, ask two things, have gaps or overlaps in the options, use a word people will understand differently, or ask something too sensitive for a doorstep survey?\",\n          fields: [\n            { kind: \"select\", label: \"Don't you agree that the new borehole has improved your family's health?\", options: PROBLEMS, answer: 0, explain: \"The wording pushes the respondent to agree. Ask neutrally: has your family's health changed since the borehole opened?\" },\n            { kind: \"select\", label: \"Is the water point clean and is the water committee helpful?\", options: PROBLEMS, answer: 1, explain: \"A respondent may find the point clean but the committee unhelpful. Ask two separate questions.\" },\n            { kind: \"select\", label: \"Age of respondent: 18–25, 25–35, 35–50\", options: PROBLEMS, answer: 2, explain: \"25 and 35 appear in two groups, and people over 50 have no option. Use 18–24, 25–34, 35–49, 50 and over.\" },\n            { kind: \"select\", label: \"Do you wash your hands regularly?\", options: PROBLEMS, answer: 3, explain: \"Regularly means different things to different people. Ask about specific moments, such as before eating or after using the latrine.\" },\n            { kind: \"select\", label: \"In a doorstep survey with neighbours listening: has anyone in your household suffered sexual violence this year?\", options: PROBLEMS, answer: 4, explain: \"Such questions need trained staff, privacy and a referral pathway. They do not belong in a general household survey.\" },\n            { kind: \"select\", label: \"Monthly household income: less than 25 000 FCFA, 25 000 to 50 000 FCFA, more than 75 000 FCFA\", options: PROBLEMS, answer: 2, explain: \"Households earning between 50 000 and 75 000 FCFA have no option.\" },\n          ] },\n        { type: \"h\", text: \"Skip logic and constraints\" },\n        { type: \"p\", text: \"In a mobile form, skip logic shows a question only when it applies, and constraints refuse impossible answers at the moment of entry. In XLSForm, skip logic goes in the relevant column and validation in the constraint column, where a dot stands for the current answer.\" },\n        { type: \"table\", head: [\"Need\", \"Column\", \"Formula\"], rows: [\n          [\"Ask about care only if a child had fever\", \"relevant\", \"${child_fever} = 'yes'\"],\n          [\"Ask the other source only if Other was chosen\", \"relevant\", \"${water_source} = 'other'\"],\n          [\"Household size between 1 and 30\", \"constraint\", \". >= 1 and . <= 30\"],\n          [\"Children under 5 cannot exceed household size\", \"constraint\", \". <= ${hh_size}\"],\n        ] },\n        { type: \"path\", items: [\"Question settings\", \"Skip Logic\"], note: \"In the KoboToolbox Formbuilder, open a question's settings (gear icon); the Validation Criteria tab holds constraints.\" },\n        { type: \"xlsform\", id: \"meal-m3-l3-xls\", title: \"Add skip logic and constraints\", task: \"Complete this short household questionnaire for a fictional health project in the Centre region. Make **hh_size** accept 1 to 30 only, make **children_u5** accept no more than hh_size, show **child_fever** only when there is at least one child under 5, show **care_sought** only when a child had fever, and show **water_other** only when the water source is other.\",\n          hint: \"hh_size constraint: . >= 1 and . <= 30. children_u5 constraint: . <= ${hh_size}. Relevant: ${children_u5} > 0, then ${child_fever} = 'yes', then ${water_source} = 'other'.\",\n          columns: [\"type\", \"name\", \"label\", \"relevant\", \"constraint\", \"constraint_message\"],\n          survey: [\n            { type: \"integer\", name: \"hh_size\", label: \"How many people live in this household, including you?\" },\n            { type: \"integer\", name: \"children_u5\", label: \"How many of them are children under 5?\" },\n            { type: \"select_one yes_no\", name: \"child_fever\", label: \"In the last two weeks, did any child under 5 have fever?\" },\n            { type: \"select_one care\", name: \"care_sought\", label: \"Where did you first seek care for the fever?\" },\n            { type: \"select_one source\", name: \"water_source\", label: \"What is the main source of drinking water?\" },\n            { type: \"text\", name: \"water_other\", label: \"Specify the other source\" },\n          ],\n          choices: [...YES_NO,\n            { list_name: \"care\", name: \"health_centre\", label: \"Health centre\" }, { list_name: \"care\", name: \"chw\", label: \"Community health worker\" }, { list_name: \"care\", name: \"none\", label: \"No care sought\" },\n            { list_name: \"source\", name: \"tap\", label: \"Public tap\" }, { list_name: \"source\", name: \"well\", label: \"Protected well\" }, { list_name: \"source\", name: \"other\", label: \"Other\" }],\n          checks: [\n            { label: \"hh_size accepts 1 to 30 only\", kind: \"field\", name: \"hh_size\", constraint: \". >= 1 and . <= 30\" },\n            { label: \"children_u5 cannot exceed hh_size\", kind: \"field\", name: \"children_u5\", constraint: \". <= ${hh_size}\" },\n            { label: \"child_fever appears only when children_u5 > 0\", kind: \"field\", name: \"child_fever\", relevant: \"${children_u5} > 0\" },\n            { label: \"care_sought appears only when child_fever = yes\", kind: \"field\", name: \"care_sought\", relevant: \"${child_fever} = 'yes'\" },\n            { label: \"water_other appears only when water_source = other\", kind: \"field\", name: \"water_other\", relevant: \"${water_source} = 'other'\" },\n          ],\n          solution: { survey: [\n            { type: \"integer\", name: \"hh_size\", label: \"How many people live in this household, including you?\", constraint: \". >= 1 and . <= 30\", constraint_message: \"Enter a number between 1 and 30\" },\n            { type: \"integer\", name: \"children_u5\", label: \"How many of them are children under 5?\", constraint: \". <= ${hh_size}\", constraint_message: \"Cannot be more than the household size\" },\n            { type: \"select_one yes_no\", name: \"child_fever\", label: \"In the last two weeks, did any child under 5 have fever?\", relevant: \"${children_u5} > 0\" },\n            { type: \"select_one care\", name: \"care_sought\", label: \"Where did you first seek care for the fever?\", relevant: \"${child_fever} = 'yes'\" },\n            { type: \"select_one source\", name: \"water_source\", label: \"What is the main source of drinking water?\" },\n            { type: \"text\", name: \"water_other\", label: \"Specify the other source\", relevant: \"${water_source} = 'other'\" },\n          ] } },\n        { type: \"h\", text: \"Translation and back-translation\" },\n        { type: \"steps\", title: \"Getting the same question in every language\", items: [\n          \"Finalise the English or French master version first.\",\n          \"A translator who knows the local language and the topic translates it, for example into Fulfulde, Ewondo or Pidgin.\",\n          \"A second translator, who has not seen the original, translates it back into the master language.\",\n          \"Compare the back-translation with the original and discuss every difference in meaning.\",\n          \"Agree the wording of key terms, such as household or diarrhoea, and add them to the training manual.\",\n        ] },\n        { type: \"h\", text: \"Pilot the questionnaire\" },\n        { type: \"list\", items: [\n          \"Test the form with 10 to 20 respondents similar to the sample, but outside the sample villages.\",\n          \"Time each interview and note questions that cause hesitation, confusion or refusals.\",\n          \"Check that the skip logic works and that no respondent is stuck without a suitable option.\",\n          \"Export the pilot data and try to calculate every indicator from it.\",\n          \"Correct the form, record the version number, and retrain enumerators on the changes.\",\n        ] },\n        { type: \"check\", id: \"meal-m3-l3-c1\", question: \"What is the purpose of back-translation?\", options: [\"To check that the translated questionnaire keeps the same meaning as the original\", \"To make the questionnaire shorter\", \"To translate the answers into English for analysis\", \"To let respondents choose their language\"], answer: 0, explain: \"An independent translator converts the translation back into the original language, so differences in meaning become visible and can be corrected before fieldwork.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"During the pilot of a fictional nutrition survey in the Far North, enumerators found that the Fulfulde word chosen for diarrhoea was also used for ordinary stomach pain. Reported diarrhoea was twice as high as expected. The team agreed a more precise description with health workers and retrained enumerators before the main survey.\" },\n        { type: \"task\", id: \"meal-m3-l3-t1\", title: \"Practice\", items: [\n          \"Take a questionnaire from your project and link each question to the indicator it feeds\",\n          \"Find and rewrite one leading and one double-barrelled question\",\n          \"Check every set of response options for gaps and overlaps\",\n          \"Add at least two relevant conditions and one constraint to your XLSForm\",\n          \"Plan a pilot: where, with how many respondents, and who records the problems\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"XLSForm documentation: relevant and constraint\", url: \"https://xlsform.org/en/\", source: XLSF },\n          { label: \"Form logic\", url: \"https://docs.getodk.org/form-logic/\", source: ODK },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 4 ───────────────────────────────\n    {\n      id: \"meal-m3-l4\",\n      title: \"Enumerator training, supervision and data quality\",\n      minutes: 20,\n      objectives: [\n        \"Plan an enumerator training that combines theory, role plays and a field practice\",\n        \"Organise spot checks, back-checks and daily data review during fieldwork\",\n        \"Detect common enumerator errors in the data and decide on follow-up\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"The best questionnaire and sample are wasted if enumerators ask questions differently, skip households or invent answers. Data quality is built in three places: in training before fieldwork, in supervision during fieldwork, and in the daily review of data as it arrives on the server.\" },\n        { type: \"h\", text: \"A typical training agenda\" },\n        { type: \"table\", head: [\"Day\", \"Content\"], rows: [\n          [\"Day 1\", \"Project and survey objectives, ethics, consent, safeguarding, code of conduct, sampling and household selection rules\"],\n          [\"Day 2\", \"Question by question review in all languages, definitions of key terms, practice with the mobile form\"],\n          [\"Day 3\", \"Role plays in pairs, difficult situations, device care, sending data, the daily routine\"],\n          [\"Day 4\", \"Field practice in a village outside the sample, debriefing and final corrections to the form\"],\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Recruit more than you need\", text: \"Train about 10 to 20% more enumerators than required and select the final team from their test results and role plays. You then have replacements ready if someone falls ill or leaves.\" },\n        { type: \"h\", text: \"Supervision in the field\" },\n        { type: \"list\", items: [\n          \"Spot checks: the supervisor attends part of an interview unannounced and checks how questions are asked.\",\n          \"Back-checks: a different person revisits a random 5 to 10% of households and re-asks a few stable questions, such as household size or water source.\",\n          \"Daily debriefing: the team meets each evening to share problems and agree solutions.\",\n          \"Consistent rules: any change in instructions is written down and shared with all teams the same day.\",\n        ] },\n        { type: \"h\", text: \"Daily data review\" },\n        { type: \"steps\", title: \"Every evening, on the server\", items: [\n          \"Count interviews per enumerator and per cluster against the plan.\",\n          \"Look at interview duration: very short interviews suggest skipped questions or invented data.\",\n          \"Check the share of Don't know answers, refusals and missing values per enumerator.\",\n          \"Compare back-check answers with the original interviews and calculate the mismatch rate.\",\n          \"Send clear feedback to each team the next morning and record decisions.\",\n        ] },\n        { type: \"path\", items: [\"DATA\", \"Table\"], note: \"In a KoboToolbox project, the table view lets you review submissions and set a validation status such as Approved, Not approved or On hold.\" },\n        { type: \"h\", text: \"Common errors and what they look like\" },\n        { type: \"table\", head: [\"Error\", \"Sign in the data\", \"Response\"], rows: [\n          [\"Skipping questions to go faster\", \"Very short interviews; many No answers that avoid follow-up questions\", \"Spot checks, retraining, back-checks on that enumerator\"],\n          [\"Invented or copied interviews\", \"Identical answer patterns, interviews one or two minutes apart, GPS points in one place\", \"Back-checks; discard the data if confirmed\"],\n          [\"Wrong household selected\", \"Clusters with too many or too few interviews\", \"Review selection rules with the team\"],\n          [\"Misunderstood question\", \"One enumerator's answers very different from the others\", \"Clarify the question with the whole team\"],\n        ] },\n        { type: \"sheet\", id: \"meal-m3-l4-sheet\", title: \"Flag enumerators for follow-up\", task: \"Day 3 of a fictional household survey in the South region. Fill **F2:F6** with each enumerator's back-check mismatch rate, **G2:G6** with `Follow up` when the average interview lasts less than 20 minutes or the mismatch rate is above 15%, otherwise `OK`, and **F7** with the team's overall mismatch rate.\",\n          data: [[\"Enumerator\", \"Interviews\", \"Avg minutes\", \"Back-checks\", \"Mismatches\", \"Mismatch rate\", \"Flag\"],\n            [\"Aïcha\", 42, 38, 5, 0, null, null],\n            [\"Boris\", 55, 14, 6, 1, null, null],\n            [\"Clarisse\", 40, 35, 4, 1, null, null],\n            [\"Daniel\", 48, 31, 5, 0, null, null],\n            [\"Esther\", 60, 26, 6, 3, null, null],\n            [\"Team\", null, null, null, null, null]],\n          editable: [\"F2\", \"F3\", \"F4\", \"F5\", \"F6\", \"G2\", \"G3\", \"G4\", \"G5\", \"G6\", \"F7\"],\n          checks: [{ cell: \"F2\", equals: 0, tol: 0.001 }, { cell: \"F3\", equals: 0.1667, tol: 0.001 }, { cell: \"F4\", equals: 0.25, tol: 0.001 }, { cell: \"F5\", equals: 0, tol: 0.001 }, { cell: \"F6\", equals: 0.5, tol: 0.001 },\n            { cell: \"G2\", equals: \"OK\" }, { cell: \"G3\", equals: \"Follow up\" }, { cell: \"G4\", equals: \"Follow up\" }, { cell: \"G5\", equals: \"OK\" }, { cell: \"G6\", equals: \"Follow up\" },\n            { cell: \"F7\", equals: 0.1923, tol: 0.001 }],\n          hint: \"Mismatch rate: =E2/D2. Flag: =IF(OR(C2<20,F2>0.15),\\\"Follow up\\\",\\\"OK\\\"). The team rate divides total mismatches by total back-checks: =SUM(E2:E6)/SUM(D2:D6).\",\n          solution: { F2: \"=E2/D2\", F3: \"=E3/D3\", F4: \"=E4/D4\", F5: \"=E5/D5\", F6: \"=E6/D6\",\n            G2: \"=IF(OR(C2<20,F2>0.15),\\\"Follow up\\\",\\\"OK\\\")\", G3: \"=IF(OR(C3<20,F3>0.15),\\\"Follow up\\\",\\\"OK\\\")\", G4: \"=IF(OR(C4<20,F4>0.15),\\\"Follow up\\\",\\\"OK\\\")\", G5: \"=IF(OR(C5<20,F5>0.15),\\\"Follow up\\\",\\\"OK\\\")\", G6: \"=IF(OR(C6<20,F6>0.15),\\\"Follow up\\\",\\\"OK\\\")\",\n            F7: \"=SUM(E2:E6)/SUM(D2:D6)\" } },\n        { type: \"h\", text: \"Enumerator safety\" },\n        { type: \"list\", items: [\n          \"Check the security situation each morning with local authorities and the security focal point, especially in the North-West, South-West and Far North.\",\n          \"Work in pairs or teams, never alone, and share the daily route with the supervisor.\",\n          \"Carry identification and an authorisation letter, and introduce the team to the village chief first.\",\n          \"Agree a check-in time and a procedure if a team does not report back.\",\n          \"Stop an interview at once if the respondent or the enumerator is at risk.\",\n        ] },\n        { type: \"check\", id: \"meal-m3-l4-c1\", question: \"What is a back-check?\", options: [\"The supervisor reads each form before it is sent\", \"The enumerator re-reads the answers to the respondent at the end\", \"The server checks that all required questions are answered\", \"A different person revisits a random sample of households and re-asks a few questions to compare with the original answers\"], answer: 3, explain: \"Back-checks confirm that interviews really took place and that answers were recorded correctly. They work best when enumerators know they happen but not which households are chosen.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"In a fictional education survey in the Adamawa region, the daily review showed that one enumerator completed twelve interviews in a morning, each in under ten minutes, with GPS points a few metres apart. Back-checks found that most of the listed households had never been visited. The data was discarded, the households were re-interviewed, and the team introduced a minimum duration flag on the dashboard.\" },\n        { type: \"task\", id: \"meal-m3-l4-t1\", title: \"Practice\", items: [\n          \"Draft a four-day training agenda for your next survey\",\n          \"Choose five stable questions to re-ask in back-checks\",\n          \"Build the enumerator follow-up sheet from the lab for your own team\",\n          \"Write a one-page daily review checklist for the supervisor\",\n          \"List the security contacts and check-in procedure for your field area\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Collecting high-quality data\", url: \"https://docs.surveycto.com/04-monitoring-and-management/02-managing-for-quality/01.collecting-high-quality-data.html\", source: SCTO },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── PRACTICE ───────────────────────────────\n    {\n      id: \"meal-m3-practice\",\n      title: \"Practice lab: planning and running data collection\",\n      minutes: 40,\n      objectives: [\n        \"Choose methods and sampling designs for a new project\",\n        \"Diagnose and correct badly worded survey questions\",\n        \"Calculate a stratified sample size with design effect and non-response\",\n        \"Build several skip-logic rules and constraints into a screening form\",\n      ],\n      blocks: [\n        INTRO,\n        { type: \"h\", text: \"Exercise 1: An education project in the North-West region\" },\n        { type: \"form\", id: \"meal-pr-m3-education\", level: \"beginner\", title: \"Methods and sampling\", task: \"A fictional NGO supports displaced pupils returning to school in the North-West region. Answer each question.\",\n          hint: \"Numbers for a population need a survey or routine data; reasons and views need interviews or focus groups. Separate results per group call for strata; no list and scattered villages call for clusters.\",\n          fields: [\n            { kind: \"select\", label: \"Monthly attendance of pupils in the 25 supported schools\", options: METHODS, answer: 1, explain: \"Schools already keep attendance registers; collect them monthly.\" },\n            { kind: \"select\", label: \"Why some parents keep girls at home after the age of 12\", options: METHODS, answer: 3 },\n            { kind: \"select\", label: \"How the divisional delegation allocates new teachers\", options: METHODS, answer: 2 },\n            { kind: \"select\", label: \"Whether classrooms have enough benches and a working blackboard\", options: METHODS, answer: 4 },\n            { kind: \"select\", label: \"A survey must give separate results for displaced and host pupils\", options: DESIGNS, answer: 2 },\n            { kind: \"select\", label: \"Participants for focus groups with teachers from high- and low-performing schools\", options: DESIGNS, answer: 4 },\n          ] },\n        { type: \"h\", text: \"Exercise 2: A nutrition survey questionnaire\" },\n        { type: \"form\", id: \"meal-pr-m3-questions\", level: \"intermediate\", title: \"Diagnose and fix the questions\", task: \"A draft questionnaire for a fictional infant feeding survey in the North region has several weak questions. For each one, identify the problem, then choose the best replacement.\",\n          hint: \"A good replacement asks one thing, neutrally, with a clear recall period and complete options.\",\n          fields: [\n            { kind: \"select\", label: \"\\\"You breastfeed your baby, don't you?\\\" What is the problem?\", options: PROBLEMS, answer: 0 },\n            { kind: \"select\", label: \"Best replacement for that question\", options: [\"\\\"You surely breastfeed, like all good mothers?\\\"\", \"\\\"Was the baby breastfed yesterday, during the day or at night?\\\"\", \"\\\"Do you breastfeed and give porridge?\\\"\", \"\\\"Breastfeeding is important, isn't it?\\\"\"], answer: 1, explain: \"It is neutral, asks one thing and uses a clear recall period: yesterday, day or night.\" },\n            { kind: \"select\", label: \"\\\"Did the child eat meat and eggs yesterday?\\\" What is the problem?\", options: PROBLEMS, answer: 1 },\n            { kind: \"select\", label: \"Best replacement for that question\", options: [\"Keep it and accept yes or no\", \"Ask about meat, then ask about eggs, as two separate questions\", \"Ask whether the child ate well yesterday\", \"Ask only about eggs\"], answer: 1, explain: \"Two separate questions let you count each food group correctly.\" },\n            { kind: \"select\", label: \"\\\"Child's age in months: 0–6, 6–12, 12–24\\\" What is the problem?\", options: PROBLEMS, answer: 2 },\n            { kind: \"select\", label: \"Best replacement for those options\", options: [\"0–6, 6–12, 12–24, 24 and over\", \"Less than 1 year, 1 year or more\", \"Record the exact age in months as a number\", \"Young, medium, old\"], answer: 2, explain: \"Recording the exact age removes overlaps and gaps, and lets you build any age group during analysis, such as 0–5, 6–11 and 12–23 months.\" },\n          ] },\n        { type: \"h\", text: \"Exercise 3: A malaria survey across three health districts\" },\n        { type: \"sheet\", id: \"meal-pr-m3-strata\", level: \"advanced\", title: \"Stratified sample size\",\n          task: \"A fictional malaria project in the East region needs a reliable estimate of bed net use in each of three health districts. Fill **F2:F4** with the final sample for each district, rounded up, including its design effect and non-response. When a district's design effect is blank, use the default in **B8**. Then fill **F5** with the total and **F6** with the enumerator-days needed if one enumerator completes 8 interviews a day, rounded up.\",\n          data: [[\"District\", \"Expected p\", \"Margin e\", \"Design effect\", \"Non-response\", \"Final sample\"],\n            [\"Bertoua\", 0.3, 0.07, 1.5, 0.05, null],\n            [\"Batouri\", 0.5, 0.07, 2, 0.1, null],\n            [\"Abong-Mbang\", 0.2, 0.06, null, 0.15, null],\n            [\"Total\", null, null, null, null, null],\n            [\"Enumerator-days\", null, null, null, null, null],\n            [\"z\", 1.96],\n            [\"Default design effect\", 2]],\n          editable: [\"F2\", \"F3\", \"F4\", \"F5\", \"F6\"],\n          checks: [{ cell: \"F2\", equals: 260 }, { cell: \"F3\", equals: 436 }, { cell: \"F4\", equals: 402 }, { cell: \"F5\", equals: 1098 }, { cell: \"F6\", equals: 138 }],\n          hint: \"For each district: =ROUNDUP($B$7^2*B2*(1-B2)/C2^2*IF(D2=\\\"\\\",$B$8,D2)/(1-E2),0). The IF picks the default design effect when D is blank. Total with SUM, then =ROUNDUP(F5/8,0).\",\n          solution: { F2: \"=ROUNDUP($B$7^2*B2*(1-B2)/C2^2*IF(D2=\\\"\\\",$B$8,D2)/(1-E2),0)\", F3: \"=ROUNDUP($B$7^2*B3*(1-B3)/C3^2*IF(D3=\\\"\\\",$B$8,D3)/(1-E3),0)\", F4: \"=ROUNDUP($B$7^2*B4*(1-B4)/C4^2*IF(D4=\\\"\\\",$B$8,D4)/(1-E4),0)\", F5: \"=SUM(F2:F4)\", F6: \"=ROUNDUP(F5/8,0)\" } },\n        { type: \"h\", text: \"Exercise 4: A nutrition screening form in the Far North\" },\n        { type: \"xlsform\", id: \"meal-pr-m3-screening\", level: \"expert\", title: \"Screening logic and validation\", task: \"Community health workers of a fictional nutrition project screen children with this form. Make **consent** required and show the **child** group only when consent is yes. Make **age_months** required and limited to 0–59. Show **muac_mm** and **oedema** only from 6 months, and limit MUAC to 70–250 mm. Show **measles** only from 9 months. Show **refer_note** when MUAC is below 115 mm or oedema is yes, and show **caregiver_phone** in the same case, accepting only 9 digits starting with 6.\",\n          hint: \"Group: ${consent} = 'yes'. Age: . >= 0 and . <= 59. MUAC and oedema: ${age_months} >= 6. MUAC constraint: . >= 70 and . <= 250. Measles: ${age_months} >= 9. Referral: ${muac_mm} < 115 or ${oedema} = 'yes'. Phone constraint: regex(., '^6[0-9]{8}$').\",\n          columns: [\"type\", \"name\", \"label\", \"required\", \"relevant\", \"constraint\"],\n          survey: [\n            { type: \"select_one yes_no\", name: \"consent\", label: \"Does the caregiver agree to the screening?\" },\n            { type: \"begin_group\", name: \"child\", label: \"Child screening\" },\n            { type: \"integer\", name: \"age_months\", label: \"Age of the child in months\" },\n            { type: \"select_one sex\", name: \"sex\", label: \"Sex of the child\" },\n            { type: \"integer\", name: \"muac_mm\", label: \"MUAC in millimetres\" },\n            { type: \"select_one yes_no\", name: \"oedema\", label: \"Bilateral pitting oedema?\" },\n            { type: \"select_one yes_no\", name: \"measles\", label: \"Has the child received the measles vaccine?\" },\n            { type: \"end_group\", name: \"child_end\" },\n            { type: \"note\", name: \"refer_note\", label: \"Refer the child to the nearest outpatient nutrition site.\" },\n            { type: \"text\", name: \"caregiver_phone\", label: \"Caregiver's phone number for the referral follow-up\" },\n          ],\n          choices: [...YES_NO, { list_name: \"sex\", name: \"female\", label: \"Female\" }, { list_name: \"sex\", name: \"male\", label: \"Male\" }],\n          checks: [\n            { label: \"consent is required\", kind: \"field\", name: \"consent\", required: true },\n            { label: \"the child group appears only when consent = yes\", kind: \"field\", name: \"child\", relevant: \"${consent} = 'yes'\" },\n            { label: \"age_months is required\", kind: \"field\", name: \"age_months\", required: true },\n            { label: \"age_months accepts 0 to 59 only\", kind: \"field\", name: \"age_months\", constraint: \". >= 0 and . <= 59\" },\n            { label: \"muac_mm appears only from 6 months\", kind: \"field\", name: \"muac_mm\", relevant: \"${age_months} >= 6\" },\n            { label: \"muac_mm accepts 70 to 250 only\", kind: \"field\", name: \"muac_mm\", constraint: \". >= 70 and . <= 250\" },\n            { label: \"oedema appears only from 6 months\", kind: \"field\", name: \"oedema\", relevant: \"${age_months} >= 6\" },\n            { label: \"measles appears only from 9 months\", kind: \"field\", name: \"measles\", relevant: \"${age_months} >= 9\" },\n            { label: \"refer_note appears when MUAC < 115 or oedema = yes\", kind: \"field\", name: \"refer_note\", relevant: \"${muac_mm} < 115 or ${oedema} = 'yes'\" },\n            { label: \"caregiver_phone appears in the same case\", kind: \"field\", name: \"caregiver_phone\", relevant: \"${muac_mm} < 115 or ${oedema} = 'yes'\" },\n            { label: \"caregiver_phone accepts 9 digits starting with 6\", kind: \"field\", name: \"caregiver_phone\", constraint: \"regex(., '^6[0-9]{8}$')\" },\n          ],\n          solution: { survey: [\n            { type: \"select_one yes_no\", name: \"consent\", label: \"Does the caregiver agree to the screening?\", required: \"yes\" },\n            { type: \"begin_group\", name: \"child\", label: \"Child screening\", relevant: \"${consent} = 'yes'\" },\n            { type: \"integer\", name: \"age_months\", label: \"Age of the child in months\", required: \"yes\", constraint: \". >= 0 and . <= 59\" },\n            { type: \"select_one sex\", name: \"sex\", label: \"Sex of the child\" },\n            { type: \"integer\", name: \"muac_mm\", label: \"MUAC in millimetres\", relevant: \"${age_months} >= 6\", constraint: \". >= 70 and . <= 250\" },\n            { type: \"select_one yes_no\", name: \"oedema\", label: \"Bilateral pitting oedema?\", relevant: \"${age_months} >= 6\" },\n            { type: \"select_one yes_no\", name: \"measles\", label: \"Has the child received the measles vaccine?\", relevant: \"${age_months} >= 9\" },\n            { type: \"end_group\", name: \"child_end\" },\n            { type: \"note\", name: \"refer_note\", label: \"Refer the child to the nearest outpatient nutrition site.\", relevant: \"${muac_mm} < 115 or ${oedema} = 'yes'\" },\n            { type: \"text\", name: \"caregiver_phone\", label: \"Caregiver's phone number for the referral follow-up\", relevant: \"${muac_mm} < 115 or ${oedema} = 'yes'\", constraint: \"regex(., '^6[0-9]{8}$')\" },\n          ] } },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"meal-m3-quiz\",\n    title: \"Module 3 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"You want to understand why many mothers stopped attending a community nutrition session. Which method fits best?\", options: [\"A household survey of 800 households\", \"Monthly attendance registers\", \"Focus group discussions with mothers who stopped attending\", \"Observation of the sessions\"], answer: 2, explain: \"Reasons and perceptions are best explored in open discussion with the people concerned. Registers show that attendance fell, not why.\" },\n      { id: \"q2\", question: \"What does triangulation mean?\", options: [\"Checking a finding with several methods, sources or data collectors\", \"Using three enumerators per household\", \"Sampling in three stages\", \"Reporting results for three groups\"], answer: 0, explain: \"When different methods and sources point the same way, the finding is stronger; when they disagree, the gap needs investigating.\" },\n      { id: \"q3\", question: \"With z = 1.96, p = 0.5 and a margin of error of 0.1, what is the basic sample size, rounded up?\", options: [\"385\", \"49\", \"196\", \"97\"], answer: 3, explain: \"1.96² × 0.5 × 0.5 ÷ 0.1² = 96.04, rounded up to 97. Halving the margin of error to 0.05 would multiply it by four.\" },\n      { id: \"q4\", question: \"Which adjustment compensates for households that will be absent or refuse?\", options: [\"Multiplying by the design effect\", \"Dividing by (1 − expected non-response rate)\", \"Using p = 0.5\", \"Reducing the margin of error\"], answer: 1, explain: \"Dividing by 0.9 for 10% non-response ensures that enough completed interviews remain. The design effect addresses clustering, not refusals.\" },\n      { id: \"q5\", question: \"\\\"Are the teachers present and well trained?\\\" is an example of…\", options: [\"A leading question\", \"An open question\", \"A double-barrelled question\", \"A scale question\"], answer: 2, explain: \"It asks two things at once. A respondent may say teachers are present but not well trained; split it into two questions.\" },\n      { id: \"q6\", question: \"Which sampling design fits a survey of 50 villages with no household list?\", options: [\"Cluster sampling: select villages, then households within them\", \"Simple random sampling of households\", \"Purposive sampling of households\", \"Systematic sampling from the beneficiary list\"], answer: 0, explain: \"Without a household list, you first select clusters such as villages, then list and draw households inside them. Remember the design effect.\" },\n      { id: \"q7\", question: \"During daily data review, one enumerator's interviews last 8 minutes on average while the others take 35. What should you do first?\", options: [\"Delete all of that enumerator's data\", \"Ignore it: some enumerators are faster\", \"Increase the sample size\", \"Run spot checks and back-checks on that enumerator's households and discuss the findings with them\"], answer: 3, explain: \"A very short duration is a warning sign, not proof. Verify with back-checks and spot checks before deciding whether to discard data or retrain.\" },\n      { id: \"q8\", question: \"In XLSForm, which entry shows the question care_sought only when a child had fever?\", options: [\"constraint: ${child_fever} = 'yes'\", \"relevant: ${child_fever} = 'yes'\", \"required: ${child_fever}\", \"calculation: ${child_fever} = 'yes'\"], answer: 1, explain: \"The relevant column controls whether a question is shown. Constraints validate the answer to the question itself.\" },\n    ],\n  },\n};\n","client/src/data/courses/meal/m4.ts":"import type { Block, CourseModule, XlsChoice } from \"../../../lms/types\";\n\n// MEAL Professional Certificate — Module 4: Digital Data Collection Tools\n// Original Analytix Engineering material. All projects, organisations, people and figures are fictional.\n\nconst XLS = \"XLSForm\";\nconst KOBO = \"KoboToolbox Support\";\nconst ODK = \"ODK Docs\";\nconst SCTO = \"SurveyCTO\";\nconst DIMAGI = \"Dimagi\";\n\nconst TYPES = [\"text\", \"integer\", \"decimal\", \"select_one\", \"select_multiple\", \"date\", \"geopoint\", \"image\", \"note\", \"calculate\"];\nconst VALID = [\"Valid name\", \"Invalid name\"];\nconst TOOLS = [\"KoboToolbox\", \"ODK (Central and Collect)\", \"SurveyCTO\", \"CommCare\"];\nconst DEPLOY = [\n  \"Deploy the form\",\n  \"Send the finalized forms when a connection is available\",\n  \"Upload the XLSForm to a new project\",\n  \"Configure the collection app with the server URL and account\",\n  \"Fill and finalize interviews offline\",\n  \"Preview and test the form in the browser\",\n  \"Download the blank form to the phone\",\n];\nconst YES_NO: XlsChoice[] = [{ list_name: \"yes_no\", name: \"yes\", label: \"Yes\" }, { list_name: \"yes_no\", name: \"no\", label: \"No\" }];\nconst SEX: XlsChoice[] = [{ list_name: \"sex\", name: \"female\", label: \"Female\" }, { list_name: \"sex\", name: \"male\", label: \"Male\" }];\n\nconst INTRO: Block = { type: \"p\", text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" };\n\nexport const m4: CourseModule = {\n  id: \"meal-m4\",\n  number: 4,\n  title: \"Digital Data Collection Tools\",\n  summary: \"Build XLSForms and run digital surveys with KoboToolbox, ODK, SurveyCTO and CommCare.\",\n  hours: 24,\n  lessons: [\n    // ─────────────────────────────── LESSON 1 ───────────────────────────────\n    {\n      id: \"meal-m4-l1\",\n      title: \"Building forms in XLSForm\",\n      minutes: 25,\n      objectives: [\n        \"Describe the role of the survey, choices and settings sheets of an XLSForm\",\n        \"Choose the right question type and write valid names and choice lists\",\n        \"Build and extend a household form with required questions and a group\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Most digital survey tools used in humanitarian and development work read the same kind of file: an XLSForm. It is an ordinary Excel workbook in which each row describes a question. Once you can write an XLSForm, you can run the same questionnaire in KoboToolbox, ODK or SurveyCTO with little or no change.\" },\n        { type: \"h\", text: \"Three sheets make a form\" },\n        { type: \"table\", head: [\"Sheet\", \"What it holds\", \"Key columns\"], rows: [\n          [\"survey\", \"One row per question, note, calculation or group, in the order the enumerator sees them\", \"type, name, label, required, hint, relevant, constraint, calculation\"],\n          [\"choices\", \"The answer options of every select_one and select_multiple question\", \"list_name, name, label\"],\n          [\"settings (optional)\", \"Information about the form itself\", \"form_title, form_id, version, default_language\"],\n        ] },\n        { type: \"h\", text: \"The survey sheet: one row per question\" },\n        { type: \"table\", head: [\"Column\", \"What you write\", \"Example\"], rows: [\n          [\"type\", \"The question type, and for select questions the list name\", \"select_one yes_no\"],\n          [\"name\", \"A short unique variable name: it becomes the column header of your dataset\", \"hh_size\"],\n          [\"label\", \"The question text the enumerator reads\", \"How many people live in this household?\"],\n          [\"required\", \"yes when the question cannot be skipped\", \"yes\"],\n          [\"hint\", \"A short instruction shown under the label\", \"Include babies and elderly people\"],\n          [\"relevant\", \"A condition: the question appears only when it is true\", \"${consent} = 'yes'\"],\n        ] },\n        { type: \"h\", text: \"Question types you will use most\" },\n        { type: \"table\", head: [\"Type\", \"What it collects\", \"Typical use\"], rows: [\n          [\"text\", \"Free text\", \"Name of the village, other answer to specify\"],\n          [\"integer\", \"A whole number\", \"Household size, age in years, number of meals\"],\n          [\"decimal\", \"A number with decimals\", \"Weight in kg, area of a field in hectares\"],\n          [\"select_one list\", \"One answer from a list\", \"Sex, main water source, yes/no\"],\n          [\"select_multiple list\", \"Several answers from a list\", \"Crops grown, types of assistance received\"],\n          [\"date\", \"A calendar date\", \"Date of birth, date of the last distribution\"],\n          [\"geopoint\", \"GPS coordinates from the phone\", \"Location of a water point or a household\"],\n          [\"image\", \"A photo taken with the phone\", \"Photo of a completed latrine\"],\n          [\"note\", \"Text displayed, no answer\", \"Instructions, consent script, section titles\"],\n          [\"calculate\", \"A value computed from other answers, not shown\", \"Number of adults = household size minus children\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Naming rules\", text: \"A name starts with a letter or an underscore and contains only letters, digits and underscores: no spaces, no accents, no hyphens at the start. Every name in the survey sheet must be unique. Keep names short and in English or French consistently, for example hh_size, water_source, muac_mm.\" },\n        { type: \"h\", text: \"Choice lists and list_name\" },\n        { type: \"p\", text: \"A select question points to a list by its list_name: the type select_one water means the answers come from all rows of the choices sheet with list_name water. The choice name is what is stored in the data, the label is what the enumerator sees. One list can serve several questions, which is why a yes_no list is written only once.\" },\n        { type: \"code\", text: \"survey\\ntype                 name          label                                    required\\ntext                 village       Name of the village                      yes\\ninteger              hh_size       How many people live in this household?  yes\\nselect_one water     water_source  Main source of drinking water            yes\\n\\nchoices\\nlist_name   name       label\\nwater       borehole   Borehole\\nwater       well       Protected well\\nwater       river      River or stream\" },\n        { type: \"form\", id: \"meal-m4-l1-types\", title: \"Pick the type and check the names\", task: \"A fictional nutrition project in the North region is drafting its household form. Choose the question type for each item, then say whether each proposed name is valid.\",\n          hint: \"Whole numbers are integer, numbers with a comma are decimal, one answer from a list is select_one, several answers is select_multiple. A valid name has no spaces and does not start with a digit.\",\n          fields: [\n            { kind: \"select\", label: \"Number of children under five in the household\", options: TYPES, answer: 1 },\n            { kind: \"select\", label: \"Weight of the child in kilograms, for example 11.4\", options: TYPES, answer: 2, explain: \"A value with decimals needs the decimal type; integer would refuse 11.4.\" },\n            { kind: \"select\", label: \"Main source of drinking water (one answer)\", options: TYPES, answer: 3 },\n            { kind: \"select\", label: \"All the crops grown by the household this season\", options: TYPES, answer: 4, explain: \"Several answers from the same list call for select_multiple.\" },\n            { kind: \"select\", label: \"Location of the health post\", options: TYPES, answer: 6 },\n            { kind: \"select\", label: \"Photo of the ration card\", options: TYPES, answer: 7 },\n            { kind: \"select\", label: \"An instruction to the enumerator with no answer\", options: TYPES, answer: 8 },\n            { kind: \"select\", label: \"Number of adults, computed from household size minus children\", options: TYPES, answer: 9, explain: \"A calculate row computes a value from other answers without asking anything.\" },\n            { kind: \"select\", label: \"Proposed name: hh size\", options: VALID, answer: 1, explain: \"Names cannot contain spaces. Use hh_size.\" },\n            { kind: \"select\", label: \"Proposed name: 2nd_visit\", options: VALID, answer: 1, explain: \"Names must start with a letter or an underscore. Use visit_2 instead.\" },\n            { kind: \"select\", label: \"Proposed name: water_source\", options: VALID, answer: 0 },\n          ] },\n        { type: \"h\", text: \"Groups\" },\n        { type: \"p\", text: \"A group is opened by a begin_group row and closed by an end_group row. Everything between them forms a section, for example Household, Water or Health. Groups keep long forms readable, and a relevant condition written on the begin_group row applies to every question inside it.\" },\n        { type: \"path\", items: [\"Projects\", \"New\", \"Upload an XLSForm\"], note: \"Imports your XLSForm file into a new KoboToolbox project.\" },\n        { type: \"xlsform\", id: \"meal-m4-l1-xls\", title: \"Extend a household form\", task: \"A fictional food security survey in the Adamawa region. Make hh_size required. Replace the placeholder row with a select_one question named main_food using a new list food_source with the choices own_production, market and food_assistance. Add a date question named visit_date at the top, and put hh_size, main_food and meals inside a group named food.\",\n          hint: \"hh_size: required yes. Placeholder row: type select_one food_source, name main_food. In the choices sheet add three rows with list_name food_source. First row: type date, name visit_date. Add a begin_group row named food before hh_size and an end_group row after meals.\",\n          columns: [\"type\", \"name\", \"label\", \"required\"],\n          survey: [\n            { type: \"note\", name: \"intro\", label: \"Household food security survey\" },\n            { type: \"text\", name: \"village\", label: \"Name of the village\", required: \"yes\" },\n            { type: \"integer\", name: \"hh_size\", label: \"How many people live in this household?\" },\n            { type: \"note\", name: \"placeholder\", label: \"Replace this row with the main food source question\" },\n            { type: \"select_one yes_no\", name: \"meals\", label: \"Did adults eat at least two meals yesterday?\" },\n          ],\n          choices: YES_NO,\n          checks: [\n            { label: \"visit_date is a date question\", kind: \"field\", name: \"visit_date\", type: \"date\" },\n            { label: \"hh_size is required\", kind: \"field\", name: \"hh_size\", required: true },\n            { label: \"main_food is a select_one food_source question\", kind: \"field\", name: \"main_food\", type: \"select_one food_source\" },\n            { label: \"the food_source list has own_production, market and food_assistance\", kind: \"choices\", list: \"food_source\", names: [\"own_production\", \"market\", \"food_assistance\"] },\n            { label: \"a group named food is opened\", kind: \"field\", name: \"food\", type: \"begin_group\" },\n          ],\n          solution: {\n            survey: [\n              { type: \"date\", name: \"visit_date\", label: \"Date of the visit\", required: \"yes\" },\n              { type: \"note\", name: \"intro\", label: \"Household food security survey\" },\n              { type: \"text\", name: \"village\", label: \"Name of the village\", required: \"yes\" },\n              { type: \"begin_group\", name: \"food\", label: \"Food and household\" },\n              { type: \"integer\", name: \"hh_size\", label: \"How many people live in this household?\", required: \"yes\" },\n              { type: \"select_one food_source\", name: \"main_food\", label: \"Main source of food in the last month\", required: \"yes\" },\n              { type: \"select_one yes_no\", name: \"meals\", label: \"Did adults eat at least two meals yesterday?\" },\n              { type: \"end_group\", name: \"food_end\" },\n            ],\n            choices: [...YES_NO,\n              { list_name: \"food_source\", name: \"own_production\", label: \"Own production\" },\n              { list_name: \"food_source\", name: \"market\", label: \"Market purchase\" },\n              { list_name: \"food_source\", name: \"food_assistance\", label: \"Food assistance\" }],\n          } },\n        { type: \"check\", id: \"meal-m4-l1-c1\", question: \"A question has the type select_one crops, but the phone shows no answer options. What is the most likely cause?\", options: [\"The question is not required\", \"The choices sheet has no rows with list_name crops, or the list name is spelled differently\", \"select_one cannot be used for crops\", \"The label is too long\"], answer: 1, explain: \"The word after select_one must match a list_name in the choices sheet exactly. A typo such as crop instead of crops leaves the question without options, and most tools refuse to deploy the form.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A fictional NGO in Ngaoundéré keeps one master XLSForm per survey in a shared folder, with a change log in the settings sheet and English names for every variable, while labels are in French and English. When the Yaoundé office asks for the dataset, every column name is already clear and stable from one round to the next.\" },\n        { type: \"task\", id: \"meal-m4-l1-t1\", title: \"Practice\", items: [\n          \"Rewrite five questions of a paper questionnaire you use as rows of an XLSForm survey sheet\",\n          \"Create a yes_no list and one list with at least four choices in the choices sheet\",\n          \"Check that every name is unique, short and without spaces\",\n          \"Organise the form into at least two groups and add a hint to one question\",\n          \"Upload the file to a KoboToolbox project and open the preview\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"XLSForm documentation\", url: \"https://xlsform.org/en/\", source: XLS },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 2 ───────────────────────────────\n    {\n      id: \"meal-m4-l2\",\n      title: \"KoboToolbox and ODK: deploy, collect offline and sync\",\n      minutes: 25,\n      objectives: [\n        \"Deploy an XLSForm on a KoboToolbox or ODK Central server\",\n        \"Set up KoboCollect or ODK Collect to collect offline and send finalized forms\",\n        \"Manage form versions and solve the most common deployment problems\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"A digital survey has two halves: a server where forms are published and data is stored, and a mobile app that enumerators use in the field. The app works without a network; it needs a connection only to download the blank form and to send completed interviews. This is what makes digital collection possible in villages with weak or no coverage.\" },\n        { type: \"h\", text: \"The pieces of the system\" },\n        { type: \"table\", head: [\"Component\", \"KoboToolbox\", \"ODK\"], rows: [\n          [\"Server and web platform\", \"KoboToolbox, on the Global or the European Union server\", \"ODK Central, self-hosted or on paid ODK Cloud hosting\"],\n          [\"Android app for enumerators\", \"KoboCollect\", \"ODK Collect\"],\n          [\"Form design\", \"XLSForm upload or the online form builder\", \"XLSForm upload\"],\n          [\"Cost\", \"Free Community plan with monthly limits, paid plans above\", \"Free and open source; you pay for your own server or for ODK Cloud\"],\n        ] },\n        { type: \"h\", text: \"Which KoboToolbox server?\" },\n        { type: \"p\", text: \"KoboToolbox runs two public servers with separate accounts: the Global server (kf.kobotoolbox.org) and the European Union server (eu.kobotoolbox.org). The EU server replaced the former humanitarian server that was hosted with OCHA, and many humanitarian organisations use it. Create your account on the server your organisation uses, because a project on one server is invisible from the other.\" },\n        { type: \"callout\", tone: \"warning\", title: \"Match the app to the server\", text: \"KoboCollect must point to the collection URL of the same server as your account: kc.kobotoolbox.org for the Global server, kc-eu.kobotoolbox.org for the EU server. A phone set to the wrong server cannot log in or find your forms.\" },\n        { type: \"h\", text: \"From XLSForm to deployed form\" },\n        { type: \"path\", items: [\"Projects\", \"New\", \"Upload an XLSForm\"], note: \"Creates the project from your file; enter a project name and description, then create it.\" },\n        { type: \"steps\", title: \"Deploy in KoboToolbox\", items: [\n          \"Upload the XLSForm to a new project and fix any error message about types, names or lists.\",\n          \"Open the preview and test every skip rule and constraint in the browser.\",\n          \"Click Deploy on the project page: the form becomes available for collection.\",\n          \"Share the project with the enumerators' accounts, or use one collection account per team.\",\n          \"After any change, replace the form and redeploy it: a new version is created.\",\n        ] },\n        { type: \"p\", text: \"ODK Central follows the same logic: create a project, upload the XLSForm as a draft, test the draft, then publish it. Enumerators use App Users, and each phone is configured by scanning a QR code generated by Central.\" },\n        { type: \"h\", text: \"Collecting offline with KoboCollect or ODK Collect\" },\n        { type: \"steps\", title: \"On the enumerator's phone\", items: [\n          \"Install KoboCollect or ODK Collect from the Google Play Store.\",\n          \"Configure the project: enter the server URL, username and password, or scan the QR code.\",\n          \"With a connection, open Download form and select the blank forms of the survey.\",\n          \"In the field, start a new form for each interview; no network is needed.\",\n          \"At the end of the interview, finalize the form; save it as a draft only if it is incomplete.\",\n          \"When back in coverage, send the finalized forms and check that the list of forms ready to send is empty.\",\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Data lives on the phone until it is sent\", text: \"Finalized interviews stay on the device until they reach the server. Send at least once a day when you can, never uninstall the app or clear its data before sending, and check on the server that the number of submissions matches the enumerators' daily counts.\" },\n        { type: \"h\", text: \"Form versions\" },\n        { type: \"p\", text: \"Each time you change and redeploy a form, the server creates a new version. KoboToolbox sets the version automatically; in ODK you can control it in the version column of the settings sheet. Enumerators must download the new version before starting new interviews. Interviews already collected with the old version are still accepted, but avoid renaming or deleting questions during collection, because their data will be split across columns.\" },\n        { type: \"form\", id: \"meal-m4-l2-deploy\", title: \"Deploy, collect and troubleshoot\", task: \"A fictional WASH survey in the Far North region is about to start. First put the seven steps in the right order, then choose the best fix for each problem reported by the team.\",\n          hint: \"Work from the office to the field: file, test, deploy, then phones, then offline collection, then sending. For problems, ask whether the issue is on the server, in the app settings, or in what the enumerator did.\",\n          fields: [\n            { kind: \"select\", label: \"Step 1\", options: DEPLOY, answer: 2 },\n            { kind: \"select\", label: \"Step 2\", options: DEPLOY, answer: 5 },\n            { kind: \"select\", label: \"Step 3\", options: DEPLOY, answer: 0 },\n            { kind: \"select\", label: \"Step 4\", options: DEPLOY, answer: 3 },\n            { kind: \"select\", label: \"Step 5\", options: DEPLOY, answer: 6 },\n            { kind: \"select\", label: \"Step 6\", options: DEPLOY, answer: 4 },\n            { kind: \"select\", label: \"Step 7\", options: DEPLOY, answer: 1, explain: \"Enumerators collect offline and send when they find a connection, for example at the base in the evening.\" },\n            { kind: \"select\", label: \"An enumerator cannot see the survey in the list of forms to download.\", options: [\"Turn on the phone's GPS\", \"Check that the form is deployed and that the account on the phone has access to the project\", \"Delete the choices sheet\", \"Reinstall the app and clear its data\"], answer: 1, explain: \"Only deployed forms that the account can access appear in the download list.\" },\n            { kind: \"select\", label: \"After one week, the server shows 12 submissions, but the enumerators say they did 140 interviews.\", options: [\"The server deletes old submissions\", \"The form has too many questions\", \"The interviews are probably saved as drafts or were never sent; check the forms ready to send on each phone\", \"The enumerators must fill the forms again\"], answer: 2, explain: \"Data stays on the phone until it is finalized and sent. Check drafts and unsent forms before anything else.\" },\n            { kind: \"select\", label: \"You corrected a question and redeployed, but enumerators still see the old wording.\", options: [\"They must download the new version of the form before starting new interviews\", \"The server needs a day to update\", \"You must create a new project\", \"The change only appears in the export\"], answer: 0 },\n            { kind: \"select\", label: \"A new enumerator cannot log in. Your team's account is on the EU server.\", options: [\"Create a new account on the Global server\", \"Use the form builder instead\", \"Send the XLSForm by WhatsApp\", \"Set the server URL in the app to kc-eu.kobotoolbox.org\"], answer: 3, explain: \"The collection app must point to the same server as the account.\" },\n          ] },\n        { type: \"check\", id: \"meal-m4-l2-c1\", question: \"An enumerator works three days in a village without network. What happens to the interviews?\", options: [\"They are lost unless the phone has a connection\", \"They are stored on the phone and sent when the enumerator reaches a connection\", \"They are sent automatically by SMS\", \"They must be copied on paper\"], answer: 1, explain: \"KoboCollect and ODK Collect are built for offline work: finalized forms wait on the phone until they are sent.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"During a fictional baseline in Mayo-Sava, enumerators slept in villages without coverage for four days. The supervisor set a rule: finalize each interview immediately, send everything from the market town every fourth day, and report the daily number of interviews by SMS. The MEAL officer compared those counts with the server and spotted one phone whose forms had stayed in draft.\" },\n        { type: \"task\", id: \"meal-m4-l2-t1\", title: \"Practice\", items: [\n          \"Create a free KoboToolbox account on the server your organisation uses\",\n          \"Upload the XLSForm from Lesson 1, test it in the preview and deploy it\",\n          \"Install KoboCollect on an Android phone and connect it to your account\",\n          \"Fill three test interviews in airplane mode, then send them and find them on the server\",\n          \"Change one label, redeploy, and check that the phone gets the new version\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Setting up KoboCollect on Android\", url: \"https://support.kobotoolbox.org/kobocollect_on_android_latest.html\", source: KOBO },\n          { label: \"ODK Central\", url: \"https://docs.getodk.org/central-intro/\", source: ODK },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 3 ───────────────────────────────\n    {\n      id: \"meal-m4-l3\",\n      title: \"SurveyCTO and CommCare: when to choose them\",\n      minutes: 20,\n      objectives: [\n        \"Describe the main strengths of SurveyCTO and CommCare compared with KoboToolbox and ODK\",\n        \"Compare the licensing models of the four tools at a high level\",\n        \"Choose the right tool for a project using clear decision criteria\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"KoboToolbox and ODK cover most surveys. Two other tools are common in Central Africa for specific needs: SurveyCTO when security and quality control come first, and CommCare when frontline workers must follow the same people over many visits. Choosing well at the start saves months of workarounds.\" },\n        { type: \"h\", text: \"One family, different strengths\" },\n        { type: \"p\", text: \"KoboToolbox, ODK and SurveyCTO all use spreadsheet form definitions based on XLSForm, so your skills carry over; SurveyCTO adds some field types and functions of its own. CommCare is different: forms are built in its own web application builder and packaged into mobile apps with several modules.\" },\n        { type: \"h\", text: \"SurveyCTO: security and quality control\" },\n        { type: \"list\", items: [\n          \"Form encryption is built in and easy to switch on: data is encrypted on the phone and can only be read with the organisation's private key.\",\n          \"Quality control features such as automated quality checks, review and approval of submissions, and audio or text audits of interviews.\",\n          \"Support for phone surveys, web forms and advanced workflows used by research teams.\",\n          \"A paid subscription, with a free trial; hosting is provided by the vendor.\",\n        ] },\n        { type: \"h\", text: \"CommCare: follow people over time\" },\n        { type: \"list\", items: [\n          \"Case management: a case, such as a pregnant woman or a child in a nutrition programme, is registered once and updated at each follow-up visit.\",\n          \"Apps guide community health workers through visits, show who is due for a follow-up and can include counselling content.\",\n          \"Works offline by default and synchronises when a connection is available.\",\n          \"Developed by Dimagi, open source, with a free plan and paid plans for larger deployments.\",\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Longitudinal data in other tools\", text: \"ODK Central now offers Entities, and SurveyCTO has case management features, so simple follow-up is possible outside CommCare. For large programmes with many visits per person, reminders and referrals, CommCare remains the specialised choice.\" },\n        { type: \"h\", text: \"Licensing at a glance\" },\n        { type: \"table\", head: [\"Tool\", \"Cost model\", \"Hosting\"], rows: [\n          [\"KoboToolbox\", \"Free Community plan with limits; paid plans for higher volume\", \"Hosted by Kobo (Global or EU server), or your own server\"],\n          [\"ODK\", \"Free, open-source software\", \"Your own server, or paid ODK Cloud\"],\n          [\"SurveyCTO\", \"Paid subscription, free trial\", \"Hosted by the vendor\"],\n          [\"CommCare\", \"Free plan, paid plans by features and users\", \"Hosted by Dimagi, or self-hosted\"],\n        ] },\n        { type: \"h\", text: \"Decision criteria\" },\n        { type: \"table\", head: [\"Criterion\", \"Points towards\"], rows: [\n          [\"No budget, one-off survey, staff new to digital tools\", \"KoboToolbox\"],\n          [\"Data must stay on a server the organisation or ministry controls\", \"ODK Central, self-hosted\"],\n          [\"Highly sensitive data, strict encryption and quality control, research budget\", \"SurveyCTO\"],\n          [\"The same people are visited many times, with reminders and referrals\", \"CommCare\"],\n          [\"Rapid assessment to deploy in two or three days\", \"KoboToolbox or ODK\"],\n          [\"Existing team skills and the donor's or cluster's standard tool\", \"The tool the team already masters\"],\n        ] },\n        { type: \"form\", id: \"meal-m4-l3-tools\", title: \"Choose the right tool\", task: \"For each fictional situation in Cameroon, choose the tool that fits best.\",\n          hint: \"Look for the deciding need: no budget and speed, control of the server, strong security and quality control, or follow-up of the same people over time.\",\n          fields: [\n            { kind: \"select\", label: \"A small local NGO in Adamawa with no budget for software runs a one-off baseline of 400 households.\", options: TOOLS, answer: 0, explain: \"The free Community plan and the online builder make KoboToolbox the easiest start.\" },\n            { kind: \"select\", label: \"Community health workers in a health district visit pregnant women several times and must know who is due for the next visit.\", options: TOOLS, answer: 3, explain: \"Registering each woman as a case and updating it at every visit is what CommCare is built for.\" },\n            { kind: \"select\", label: \"A university research team runs a survey on sensitive attitudes, needs strong encryption and audio audits, and has a research budget.\", options: TOOLS, answer: 2 },\n            { kind: \"select\", label: \"A ministry wants all survey data on its own server in Yaoundé, managed by its IT unit.\", options: TOOLS, answer: 1, explain: \"ODK Central is free, open source and can be installed on a server the ministry controls.\" },\n            { kind: \"select\", label: \"A humanitarian organisation must launch a rapid needs assessment after floods within three days.\", options: TOOLS, answer: 0 },\n            { kind: \"select\", label: \"A nutrition programme follows each child admitted for treatment every week until discharge, with referral if the child does not improve.\", options: TOOLS, answer: 3 },\n          ] },\n        { type: \"check\", id: \"meal-m4-l3-c1\", question: \"What is the main reason to choose CommCare over a simple survey tool?\", options: [\"It is the only tool that works offline\", \"It uses the same XLSForm files as KoboToolbox\", \"It manages cases that are followed and updated over many visits\", \"It is always free\"], answer: 2, explain: \"All four tools work offline. CommCare's strength is case management for longitudinal follow-up by frontline workers.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A fictional consortium in the East region used KoboToolbox for its quarterly household surveys and CommCare for its community health workers' home visits. The MEAL officer linked the two only through shared village codes, which kept each tool doing what it does best without a costly integration.\" },\n        { type: \"task\", id: \"meal-m4-l3-t1\", title: \"Practice\", items: [\n          \"List the data collection needs of your project for the next twelve months\",\n          \"Mark which needs are one-off surveys and which involve following the same people\",\n          \"Check your data protection requirements and where the data may be hosted\",\n          \"Estimate your budget for software licences, phones and hosting\",\n          \"Write a one-paragraph recommendation of the tool to use, with two reasons\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"SurveyCTO documentation\", url: \"https://docs.surveycto.com/\", source: SCTO },\n          { label: \"CommCare\", url: \"https://commcare.dimagi.com/\", source: DIMAGI },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 4 ───────────────────────────────\n    {\n      id: \"meal-m4-l4\",\n      title: \"GPS, photos, validation and exporting data\",\n      minutes: 25,\n      objectives: [\n        \"Add GPS points and photos to a form and protect the privacy they put at risk\",\n        \"Write constraints with clear messages, including a regex for phone numbers, and calculate fields\",\n        \"Export data in the right format with labels or XML values\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"The best time to catch an error is while the enumerator is still in front of the respondent. Constraints refuse impossible answers on the spot, calculations do the arithmetic for the enumerator, and GPS points and photos provide evidence that is hard to fake. This lesson also covers how to get the data out in a format your analysis software understands.\" },\n        { type: \"h\", text: \"Location and photos\" },\n        { type: \"table\", head: [\"Type\", \"What it records\", \"Good practice\"], rows: [\n          [\"geopoint\", \"Latitude, longitude, altitude and accuracy of one point\", \"Capture outdoors, wait until the accuracy is below about 10 metres, make it required when the location is essential\"],\n          [\"image\", \"A photo from the camera\", \"Limit the photo size with max-pixels in the parameters column to save data and storage\"],\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"GPS points and photos are personal data\", text: \"A GPS point on a household or a face in a photo can identify a person as surely as a name. Collect them only when an indicator needs them, never photograph people without consent, avoid faces and documents, and remove or blur them before sharing any dataset.\" },\n        { type: \"h\", text: \"Constraints and messages\" },\n        { type: \"p\", text: \"A constraint is a condition the answer must meet. In the formula, a dot stands for the current answer. When the condition is false, the phone refuses the answer and shows the text of the constraint_message column. Constraints are not checked on empty answers; use required for that.\" },\n        { type: \"table\", head: [\"Rule\", \"constraint\", \"constraint_message\"], rows: [\n          [\"Age of an adult respondent\", \". >= 18 and . <= 100\", \"Age must be between 18 and 100\"],\n          [\"Children cannot outnumber the household\", \". <= ${hh_size}\", \"Cannot be more than the household size\"],\n          [\"At most three answers ticked\", \"count-selected(.) <= 3\", \"Choose three answers at most\"],\n          [\"A 9-digit Cameroon mobile number\", \"regex(., '^6[0-9]{8}$')\", \"9 digits starting with 6, no spaces\"],\n        ] },\n        { type: \"h\", text: \"Regex for phone numbers\" },\n        { type: \"p\", text: \"Cameroon mobile numbers have nine digits and start with 6. Store them in a text question, not an integer, so that the number is kept exactly as typed. The regex function then checks the pattern: the caret marks the start, 6 is the first digit, [0-9]{8} means eight more digits, and the dollar sign marks the end, so spaces, the +237 prefix or a missing digit are refused.\" },\n        { type: \"code\", text: \"type   name   label                      constraint                  constraint_message\\ntext   phone  Mobile Money number        regex(., '^6[0-9]{8}$')     9 digits starting with 6, no spaces\" },\n        { type: \"h\", text: \"Calculate fields\" },\n        { type: \"p\", text: \"A calculate row computes a value from earlier answers and stores it in the dataset without showing it. Use it to derive a figure, for example adults = household size minus children, or to classify a measurement. Other rows can then refer to it like any question, in a relevant condition or a note.\" },\n        { type: \"xlsform\", id: \"meal-m4-l4-xls\", title: \"Validate a registration form\", task: \"A fictional cash transfer project registers displaced households in the East region. Add constraints with messages: resp_age from 18 to 100, phone a 9-digit number starting with 6, and children no more than hh_size. Add a calculate row named adults equal to hh_size minus children, and make gps required.\",\n          hint: \"resp_age: . >= 18 and . <= 100. phone: regex(., '^6[0-9]{8}$'). children: . <= ${hh_size}. New row: type calculate, name adults, calculation ${hh_size} - ${children}. gps: required yes.\",\n          columns: [\"type\", \"name\", \"label\", \"required\", \"constraint\", \"constraint_message\", \"calculation\"],\n          survey: [\n            { type: \"text\", name: \"hh_code\", label: \"Household code\", required: \"yes\" },\n            { type: \"integer\", name: \"resp_age\", label: \"Age of the respondent\", required: \"yes\" },\n            { type: \"text\", name: \"phone\", label: \"Mobile Money phone number\" },\n            { type: \"integer\", name: \"hh_size\", label: \"How many people live in the household?\", required: \"yes\" },\n            { type: \"integer\", name: \"children\", label: \"How many of them are under 18?\", required: \"yes\" },\n            { type: \"geopoint\", name: \"gps\", label: \"Location of the shelter\" },\n          ],\n          checks: [\n            { label: \"resp_age accepts 18 to 100 only\", kind: \"field\", name: \"resp_age\", constraint: \". >= 18 and . <= 100\" },\n            { label: \"phone accepts 9 digits starting with 6\", kind: \"field\", name: \"phone\", constraint: \"regex(., '^6[0-9]{8}$')\" },\n            { label: \"children cannot exceed hh_size\", kind: \"field\", name: \"children\", constraint: \". <= ${hh_size}\" },\n            { label: \"adults is a calculate row: hh_size minus children\", kind: \"field\", name: \"adults\", type: \"calculate\", calculation: \"${hh_size} - ${children}\" },\n            { label: \"gps is required\", kind: \"field\", name: \"gps\", required: true },\n          ],\n          solution: { survey: [\n            { type: \"text\", name: \"hh_code\", label: \"Household code\", required: \"yes\" },\n            { type: \"integer\", name: \"resp_age\", label: \"Age of the respondent\", required: \"yes\", constraint: \". >= 18 and . <= 100\", constraint_message: \"Age must be between 18 and 100\" },\n            { type: \"text\", name: \"phone\", label: \"Mobile Money phone number\", constraint: \"regex(., '^6[0-9]{8}$')\", constraint_message: \"9 digits starting with 6, no spaces\" },\n            { type: \"integer\", name: \"hh_size\", label: \"How many people live in the household?\", required: \"yes\" },\n            { type: \"integer\", name: \"children\", label: \"How many of them are under 18?\", required: \"yes\", constraint: \". <= ${hh_size}\", constraint_message: \"Cannot be more than the household size\" },\n            { type: \"calculate\", name: \"adults\", label: \"\", calculation: \"${hh_size} - ${children}\" },\n            { type: \"geopoint\", name: \"gps\", label: \"Location of the shelter\", required: \"yes\" },\n          ] } },\n        { type: \"h\", text: \"Exporting your data\" },\n        { type: \"path\", items: [\"Data\", \"Downloads\"], note: \"In a KoboToolbox project, choose the export type and format, then create and download the export.\" },\n        { type: \"table\", head: [\"Export\", \"Best for\"], rows: [\n          [\"XLS\", \"Opening in Excel, especially with repeat groups\"],\n          [\"CSV\", \"Importing into Stata, R, Power BI or a database\"],\n          [\"SPSS Labels\", \"A syntax file that adds question and value labels to your data in SPSS\"],\n          [\"GPS coordinates (KML)\", \"Viewing locations in Google Earth or a GIS tool\"],\n          [\"Media attachments (ZIP)\", \"Downloading all photos at once\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Labels or XML values?\", text: \"An export with labels shows question texts as headers and choice labels as answers: easy to read, but long and language-dependent. An export with XML values uses the names, such as hh_size and borehole: short, stable and best for analysis software. Most MEAL officers analyse with XML values and use labels for sharing tables with colleagues.\" },\n        { type: \"check\", id: \"meal-m4-l4-c1\", question: \"Why store a phone number in a text question with a regex constraint rather than in an integer question?\", options: [\"Integer questions cannot be required\", \"Text is kept exactly as typed and the regex controls the number of digits and the first digit\", \"Regex only works on integer questions\", \"Text questions are encrypted automatically\"], answer: 1, explain: \"A phone number is a code, not a quantity. As text it keeps its exact digits, and regex(., '^6[0-9]{8}$') enforces the Cameroon mobile format.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"In a fictional cash transfer project in Bertoua, 14% of Mobile Money numbers in the first registration round were wrong, and payments bounced. After adding the regex constraint and a second question asking the enumerator to retype the number, errors fell to almost zero in the next round.\" },\n        { type: \"task\", id: \"meal-m4-l4-t1\", title: \"Practice\", items: [\n          \"Add a constraint and a clear constraint_message to every numeric question of one of your forms\",\n          \"Add a phone question with the Cameroon regex and test it with five correct and wrong numbers\",\n          \"Add one calculate field and display it in a note to check it\",\n          \"Export the same data with labels and with XML values and compare the two files\",\n          \"Decide which GPS and photo fields must be removed before sharing the dataset\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Form logic: constraints, relevance and calculations\", url: \"https://docs.getodk.org/form-logic/\", source: ODK },\n          { label: \"Exporting and downloading your data\", url: \"https://support.kobotoolbox.org/export_download.html\", source: KOBO },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── PRACTICE ───────────────────────────────\n    {\n      id: \"meal-m4-practice\",\n      title: \"Practice lab: building digital forms\",\n      minutes: 40,\n      objectives: [\n        \"Build a short XLSForm with basic question types and a choice list\",\n        \"Write skip logic based on a select_multiple question\",\n        \"Write constraints, a phone regex and calculations\",\n        \"Build a complete screening module with groups, relevant rules, constraints and a calculation\",\n      ],\n      blocks: [\n        INTRO,\n        { type: \"h\", text: \"Exercise 1: Weekly market price monitoring\" },\n        { type: \"xlsform\", id: \"meal-pr-m4-market\", level: \"beginner\", title: \"Four basic questions and a choice list\", task: \"A fictional food security project monitors prices in markets of the North region. Below the note, add four questions: a required text question named market, a date question named visit_date, a select_one question named commodity using a new list commodity with the choices maize, sorghum and rice, and a required integer question named price for the price of one kilogram in FCFA.\",\n          hint: \"Types: text, date, select_one commodity, integer. Set required to yes for market and price. In the choices sheet, add three rows with list_name commodity and the names maize, sorghum, rice.\",\n          columns: [\"type\", \"name\", \"label\", \"required\"],\n          survey: [\n            { type: \"note\", name: \"intro\", label: \"Weekly market price monitoring\" },\n          ],\n          choices: [],\n          checks: [\n            { label: \"market is a required text question\", kind: \"field\", name: \"market\", type: \"text\", required: true },\n            { label: \"visit_date is a date question\", kind: \"field\", name: \"visit_date\", type: \"date\" },\n            { label: \"commodity is a select_one commodity question\", kind: \"field\", name: \"commodity\", type: \"select_one commodity\" },\n            { label: \"the commodity list has maize, sorghum and rice\", kind: \"choices\", list: \"commodity\", names: [\"maize\", \"sorghum\", \"rice\"] },\n            { label: \"price is a required integer question\", kind: \"field\", name: \"price\", type: \"integer\", required: true },\n          ],\n          solution: {\n            survey: [\n              { type: \"note\", name: \"intro\", label: \"Weekly market price monitoring\" },\n              { type: \"text\", name: \"market\", label: \"Name of the market\", required: \"yes\" },\n              { type: \"date\", name: \"visit_date\", label: \"Date of the visit\" },\n              { type: \"select_one commodity\", name: \"commodity\", label: \"Commodity\" },\n              { type: \"integer\", name: \"price\", label: \"Price of one kilogram (FCFA)\", required: \"yes\" },\n            ],\n            choices: [\n              { list_name: \"commodity\", name: \"maize\", label: \"Maize\" },\n              { list_name: \"commodity\", name: \"sorghum\", label: \"Sorghum\" },\n              { list_name: \"commodity\", name: \"rice\", label: \"Rice\" },\n            ],\n          } },\n        { type: \"h\", text: \"Exercise 2: Post-distribution monitoring of livelihood support\" },\n        { type: \"xlsform\", id: \"meal-pr-m4-pdm\", level: \"intermediate\", title: \"Skip logic with select_multiple\", task: \"A fictional livelihoods project supports refugee and host households near Garoua-Boulaï. Make support required and add the choice other to its list. Show cash_amount only when cash was received, tools_used only when tools were received and other_support only when other was ticked. Finally add a calculate row named n_support that counts the types of support ticked.\",\n          hint: \"Use selected(): cash_amount relevant selected(${support}, 'cash'); tools_used relevant selected(${support}, 'tools'); other_support relevant selected(${support}, 'other'). The count is count-selected(${support}).\",\n          columns: [\"type\", \"name\", \"label\", \"required\", \"relevant\", \"calculation\"],\n          survey: [\n            { type: \"select_multiple support\", name: \"support\", label: \"Which support did your household receive in the last three months?\" },\n            { type: \"integer\", name: \"cash_amount\", label: \"Total cash received (FCFA)\" },\n            { type: \"select_one yes_no\", name: \"tools_used\", label: \"Is the household still using the tools?\" },\n            { type: \"text\", name: \"other_support\", label: \"Describe the other support received\" },\n          ],\n          choices: [...YES_NO,\n            { list_name: \"support\", name: \"cash\", label: \"Cash\" },\n            { list_name: \"support\", name: \"seeds\", label: \"Seeds\" },\n            { list_name: \"support\", name: \"tools\", label: \"Farming tools\" },\n            { list_name: \"support\", name: \"training\", label: \"Training\" }],\n          checks: [\n            { label: \"support is required\", kind: \"field\", name: \"support\", required: true },\n            { label: \"the support list includes other\", kind: \"choices\", list: \"support\", names: [\"cash\", \"seeds\", \"tools\", \"training\", \"other\"] },\n            { label: \"cash_amount appears only when cash is ticked\", kind: \"field\", name: \"cash_amount\", relevant: \"selected(${support}, 'cash')\" },\n            { label: \"tools_used appears only when tools is ticked\", kind: \"field\", name: \"tools_used\", relevant: \"selected(${support}, 'tools')\" },\n            { label: \"other_support appears only when other is ticked\", kind: \"field\", name: \"other_support\", relevant: \"selected(${support}, 'other')\" },\n            { label: \"n_support counts the ticked answers\", kind: \"field\", name: \"n_support\", type: \"calculate\", calculation: \"count-selected(${support})\" },\n          ],\n          solution: {\n            survey: [\n              { type: \"select_multiple support\", name: \"support\", label: \"Which support did your household receive in the last three months?\", required: \"yes\" },\n              { type: \"integer\", name: \"cash_amount\", label: \"Total cash received (FCFA)\", relevant: \"selected(${support}, 'cash')\" },\n              { type: \"select_one yes_no\", name: \"tools_used\", label: \"Is the household still using the tools?\", relevant: \"selected(${support}, 'tools')\" },\n              { type: \"text\", name: \"other_support\", label: \"Describe the other support received\", relevant: \"selected(${support}, 'other')\" },\n              { type: \"calculate\", name: \"n_support\", label: \"\", calculation: \"count-selected(${support})\" },\n            ],\n            choices: [...YES_NO,\n              { list_name: \"support\", name: \"cash\", label: \"Cash\" },\n              { list_name: \"support\", name: \"seeds\", label: \"Seeds\" },\n              { list_name: \"support\", name: \"tools\", label: \"Farming tools\" },\n              { list_name: \"support\", name: \"training\", label: \"Training\" },\n              { list_name: \"support\", name: \"other\", label: \"Other\" }],\n          } },\n        { type: \"h\", text: \"Exercise 3: Validation rules for a school census\" },\n        { type: \"form\", id: \"meal-pr-m4-school\", level: \"advanced\", title: \"Write the constraints and calculations\", task: \"A fictional education project runs a school census in the South region. The form has the integer questions boys, girls and total_pupils, a text question head_phone and an integer question teacher_age. Type each formula exactly as you would write it in the XLSForm.\",\n          hint: \"In a constraint, the dot is the current answer. Other questions are written ${name}. Division in XLSForm is div, not a slash. The phone regex is regex(., '^6[0-9]{8}$').\",\n          fields: [\n            { kind: \"text\", mono: true, label: \"constraint on girls: cannot be more than total_pupils\", pattern: String.raw`^(\\.\\s*<=\\s*\\$\\{total_pupils\\}|\\$\\{total_pupils\\}\\s*>=\\s*\\.)$`, example: \". <= ${total_pupils}\", explain: \"The dot is the number of girls being typed; it must not exceed the total already entered.\" },\n            { kind: \"text\", mono: true, label: \"constraint on teacher_age: from 18 to 65\", pattern: String.raw`^(\\.\\s*>=\\s*18\\s+and\\s+\\.\\s*<=\\s*65|\\.\\s*<=\\s*65\\s+and\\s+\\.\\s*>=\\s*18)$`, example: \". >= 18 and . <= 65\", explain: \"Both limits are joined with and; the phone refuses 17 or 70.\" },\n            { kind: \"text\", mono: true, label: \"constraint on head_phone: 9 digits starting with 6\", pattern: String.raw`^regex\\(\\s*\\.\\s*,\\s*['\"]\\^6(\\[0-9\\]|\\\\d)\\{8\\}\\$['\"]\\s*\\)$`, example: \"regex(., '^6[0-9]{8}$')\", explain: \"The caret and the dollar sign force the whole answer to match, so 237677123456 or 67712345 are refused.\" },\n            { kind: \"text\", mono: true, label: \"calculation of a field pupils_check: boys plus girls\", pattern: String.raw`^(\\$\\{boys\\}\\s*\\+\\s*\\$\\{girls\\}|\\$\\{girls\\}\\s*\\+\\s*\\$\\{boys\\})$`, example: \"${boys} + ${girls}\" },\n            { kind: \"text\", mono: true, label: \"calculation of girls_share: girls divided by total_pupils\", pattern: String.raw`^(round\\(\\s*)?\\$\\{girls\\}\\s*div\\s*\\$\\{total_pupils\\}(\\s*,\\s*\\d\\s*\\))?$`, example: \"${girls} div ${total_pupils}\", explain: \"XLSForm divides with div. You can wrap it in round(..., 2) to keep two decimals.\" },\n            { kind: \"select\", label: \"Where should the rule that boys plus girls equals total_pupils be written?\", options: [\"As a constraint on total_pupils: . = ${boys} + ${girls}\", \"In the label of total_pupils\", \"As a relevant condition on boys\", \"It cannot be checked in the form\"], answer: 0, explain: \"Placing it on the last of the three questions lets the enumerator correct the figures while still at the school.\" },\n            { kind: \"select\", label: \"The head teacher has no phone and the question is left empty. What does the regex constraint do?\", options: [\"It refuses the empty answer\", \"It replaces it with 0\", \"Nothing: constraints are not checked on empty answers\", \"It deletes the question\"], answer: 2, explain: \"Constraints apply only to answers that exist. If the number is compulsory, also set required to yes.\" },\n          ] },\n        { type: \"h\", text: \"Exercise 4: Nutrition screening of children under five\" },\n        { type: \"xlsform\", id: \"meal-pr-m4-muac\", level: \"expert\", title: \"A complete screening module\", task: \"A fictional nutrition project screens children aged 6 to 59 months in the Far North with a MUAC tape (in mm). Make consent required. Wrap the child questions (from age_months to referred) in a group named child shown only when consent is yes. Add constraints with messages: age_months from 6 to 59 and muac from 80 to 230. Add a calculate row muac_class giving 'sam' when there is oedema or MUAC is below 115, 'mam' when MUAC is below 125, otherwise 'normal'. Show refer_note and referred only when there is oedema or MUAC is below 125, and end_note only when consent is no.\",\n          hint: \"Group relevant: ${consent} = 'yes'. Constraints: . >= 6 and . <= 59; . >= 80 and . <= 230. Calculation: if(${oedema} = 'yes' or ${muac} < 115, 'sam', if(${muac} < 125, 'mam', 'normal')). Referral relevant: ${oedema} = 'yes' or ${muac} < 125. End note relevant: ${consent} = 'no'.\",\n          columns: [\"type\", \"name\", \"label\", \"required\", \"relevant\", \"constraint\", \"constraint_message\", \"calculation\"],\n          survey: [\n            { type: \"select_one yes_no\", name: \"consent\", label: \"Does the caregiver agree to the screening?\" },\n            { type: \"integer\", name: \"age_months\", label: \"Age of the child in months\", required: \"yes\" },\n            { type: \"select_one sex\", name: \"sex\", label: \"Sex of the child\", required: \"yes\" },\n            { type: \"integer\", name: \"muac\", label: \"MUAC in millimetres\", required: \"yes\" },\n            { type: \"select_one yes_no\", name: \"oedema\", label: \"Bilateral pitting oedema on both feet?\", required: \"yes\" },\n            { type: \"note\", name: \"refer_note\", label: \"Refer the child to the nearest health centre with the referral slip.\" },\n            { type: \"select_one yes_no\", name: \"referred\", label: \"Was the referral slip given?\" },\n            { type: \"note\", name: \"end_note\", label: \"Thank the caregiver and end the screening.\" },\n          ],\n          choices: [...YES_NO, ...SEX],\n          checks: [\n            { label: \"consent is required\", kind: \"field\", name: \"consent\", required: true },\n            { label: \"the child group appears only when consent = yes\", kind: \"field\", name: \"child\", type: \"begin_group\", relevant: \"${consent} = 'yes'\" },\n            { label: \"age_months accepts 6 to 59 only\", kind: \"field\", name: \"age_months\", constraint: \". >= 6 and . <= 59\" },\n            { label: \"muac accepts 80 to 230 only\", kind: \"field\", name: \"muac\", constraint: \". >= 80 and . <= 230\" },\n            { label: \"muac_class gives sam, mam or normal\", kind: \"field\", name: \"muac_class\", type: \"calculate\", calculation: \"if(${oedema} = 'yes' or ${muac} < 115, 'sam', if(${muac} < 125, 'mam', 'normal'))\" },\n            { label: \"refer_note appears when oedema = yes or MUAC < 125\", kind: \"field\", name: \"refer_note\", relevant: \"${oedema} = 'yes' or ${muac} < 125\" },\n            { label: \"referred appears when oedema = yes or MUAC < 125\", kind: \"field\", name: \"referred\", relevant: \"${oedema} = 'yes' or ${muac} < 125\" },\n            { label: \"end_note appears only when consent = no\", kind: \"field\", name: \"end_note\", relevant: \"${consent} = 'no'\" },\n          ],\n          solution: { survey: [\n            { type: \"select_one yes_no\", name: \"consent\", label: \"Does the caregiver agree to the screening?\", required: \"yes\" },\n            { type: \"begin_group\", name: \"child\", label: \"Child screening\", relevant: \"${consent} = 'yes'\" },\n            { type: \"integer\", name: \"age_months\", label: \"Age of the child in months\", required: \"yes\", constraint: \". >= 6 and . <= 59\", constraint_message: \"Only children aged 6 to 59 months are screened\" },\n            { type: \"select_one sex\", name: \"sex\", label: \"Sex of the child\", required: \"yes\" },\n            { type: \"integer\", name: \"muac\", label: \"MUAC in millimetres\", required: \"yes\", constraint: \". >= 80 and . <= 230\", constraint_message: \"Check the reading: MUAC must be between 80 and 230 mm\" },\n            { type: \"select_one yes_no\", name: \"oedema\", label: \"Bilateral pitting oedema on both feet?\", required: \"yes\" },\n            { type: \"calculate\", name: \"muac_class\", label: \"\", calculation: \"if(${oedema} = 'yes' or ${muac} < 115, 'sam', if(${muac} < 125, 'mam', 'normal'))\" },\n            { type: \"note\", name: \"refer_note\", label: \"Refer the child to the nearest health centre with the referral slip.\", relevant: \"${oedema} = 'yes' or ${muac} < 125\" },\n            { type: \"select_one yes_no\", name: \"referred\", label: \"Was the referral slip given?\", relevant: \"${oedema} = 'yes' or ${muac} < 125\" },\n            { type: \"end_group\", name: \"child_end\" },\n            { type: \"note\", name: \"end_note\", label: \"Thank the caregiver and end the screening.\", relevant: \"${consent} = 'no'\" },\n          ] } },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"meal-m4-quiz\",\n    title: \"Module 4 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"In an XLSForm, where do you write the answer options of a select_one question?\", options: [\"In the label column of the survey sheet\", \"In the choices sheet, under the list_name used in the question type\", \"In the settings sheet\", \"In the hint column\"], answer: 1, explain: \"The type select_one water points to all rows of the choices sheet with list_name water.\" },\n      { id: \"q2\", question: \"Which of these is a valid XLSForm name?\", options: [\"hh size\", \"2nd_visit\", \"water-source?\", \"water_source\"], answer: 3, explain: \"Names start with a letter or an underscore and use only letters, digits and underscores, without spaces.\" },\n      { id: \"q3\", question: \"An enumerator collects offline for a week. What must happen for the data to reach the server?\", options: [\"The forms must be finalized and then sent when a connection is available\", \"Nothing, the data is sent by SMS\", \"The enumerator must retype the data on a computer\", \"The form must be redeployed\"], answer: 0, explain: \"Collect apps keep finalized forms on the phone until they are sent over a connection.\" },\n      { id: \"q4\", question: \"Your KoboToolbox account is on the EU server. Which collection URL goes in KoboCollect?\", options: [\"kc.kobotoolbox.org\", \"The ODK Central URL\", \"kc-eu.kobotoolbox.org\", \"Any URL, the app finds the server itself\"], answer: 2, explain: \"The app must point to the collection URL of the server where the account and the project are.\" },\n      { id: \"q5\", question: \"Which tool is designed for case management, such as following pregnant women over several home visits?\", options: [\"CommCare\", \"SurveyCTO\", \"Excel\", \"KoboToolbox's form builder\"], answer: 0, explain: \"CommCare registers cases and updates them at each visit, and shows health workers who is due for follow-up.\" },\n      { id: \"q6\", question: \"Which constraint accepts only Cameroon mobile numbers of 9 digits starting with 6?\", options: [\"string-length(.) = 9\", \". > 600000000\", \"regex(., '6[0-9]')\", \"regex(., '^6[0-9]{8}$')\"], answer: 3, explain: \"The caret and the dollar sign anchor the pattern, 6 is the first digit and [0-9]{8} requires exactly eight more digits.\" },\n      { id: \"q7\", question: \"What does a calculate row do?\", options: [\"It asks the respondent to do a calculation\", \"It computes a value from other answers and stores it without showing it\", \"It checks that an answer is within a range\", \"It exports the data to Excel\"], answer: 1, explain: \"A calculate row derives a value, for example adults = ${hh_size} - ${children}, that other rows and the dataset can use.\" },\n      { id: \"q8\", question: \"You will analyse the data in Stata. Which export is most suitable?\", options: [\"XLS with labels, because it is easier to read\", \"A KML file\", \"CSV with XML values, because names and codes are short and stable\", \"Media attachments\"], answer: 2, explain: \"XML values give short variable names and choice codes that analysis software handles well; labels are better for sharing readable tables.\" },\n    ],\n  },\n};\n","client/src/data/courses/meal/m5.ts":"import type { Block, CourseModule } from \"../../../lms/types\";\n\n// MEAL Professional Certificate — Module 5: Data Analysis with Excel, SPSS and Stata\n// Original Analytix Engineering material. All projects, organisations, people and figures are fictional.\n\nconst STATA = \"Stata\";\nconst BE = \"BetterEvaluation\";\n\nconst CODES = [\"Distance\", \"Cost\", \"Safety\", \"Staff attitude\"];\n\nconst INTRO: Block = { type: \"p\", text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" };\n\nexport const m5: CourseModule = {\n  id: \"meal-m5\",\n  number: 5,\n  title: \"Data Analysis with Excel, SPSS and Stata\",\n  summary: \"Clean data, calculate and disaggregate indicators, and run descriptive statistics and cross-tabulations in Excel, SPSS and Stata.\",\n  hours: 24,\n  lessons: [\n    // ─────────────────────────────── LESSON 1 ───────────────────────────────\n    {\n      id: \"meal-m5-l1\",\n      title: \"Cleaning data: missing values, duplicates and outliers\",\n      minutes: 25,\n      objectives: [\n        \"Detect missing values, duplicate IDs, out-of-range values and special codes in a survey dataset\",\n        \"Apply cleaning checks in Excel, SPSS and Stata without touching the raw data\",\n        \"Record every correction in a cleaning log that another person can follow\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"A dataset straight from the server is never ready for analysis. Some households were submitted twice, some ages were typed with an extra digit, and some answers are codes such as 99 that mean \\\"don't know\\\". If you calculate indicators before cleaning, one error can move a percentage by several points. Cleaning is not about making the data look nice; it is about making every figure you report defensible.\" },\n        { type: \"h\", text: \"Golden rules before you start\" },\n        { type: \"list\", items: [\n          \"Never overwrite the raw data: keep the exported file untouched and work on a copy.\",\n          \"Write every change in a cleaning log: ID, variable, old value, new value, reason, who and when.\",\n          \"Prefer rules over case-by-case decisions: the same problem is always treated the same way.\",\n          \"Correct from a source (paper form, call-back, supervisor) when you can; otherwise set the value to missing rather than guess.\",\n          \"Keep the cleaning steps in a script or a documented sheet so that you can run them again when new data arrives.\",\n        ] },\n        { type: \"h\", text: \"The five common problems\" },\n        { type: \"table\", head: [\"Problem\", \"Example\", \"Usual treatment\"], rows: [\n          [\"Duplicate records\", \"The same household ID submitted twice after a sync failure\", \"Check that the rows are really identical, keep one, log the other\"],\n          [\"Missing values\", \"Household size left empty\", \"Leave it missing and exclude it from that indicator's denominator\"],\n          [\"Special codes\", \"98 = don't know, 99 = refused, entered in the age field\", \"Declare them as missing before any mean or median\"],\n          [\"Out-of-range values\", \"Age of household head = 132\", \"Check the paper form or call back; if impossible, set to missing\"],\n          [\"Inconsistent codes\", \"\\\"F\\\", \\\"f\\\", \\\"Female\\\" and \\\"Femme\\\" in the same column\", \"Recode to one agreed value, ideally a numeric code with a label\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Missing is not the same as \\\"don't know\\\"\", text: \"A blank means the question was not asked or not answered. A 98 means the person was asked and did not know. Both are excluded from a mean, but you may want to report the share of \\\"don't know\\\" answers, because it tells you something about the question or the respondents.\" },\n        { type: \"h\", text: \"Cleaning checks in Excel\" },\n        { type: \"steps\", title: \"Five quick checks on a copy of the data\", items: [\n          \"Turn on filters (Data › Filter) and open each column's filter list to spot odd values and blanks.\",\n          \"Count blanks per column with COUNTBLANK, for example =COUNTBLANK(D2:D501).\",\n          \"Flag duplicate IDs in a helper column: =COUNTIF($A$2:$A$501,A2)>1 returns TRUE for every repeated ID.\",\n          \"Count special codes and impossible values: =COUNTIF(C2:C501,99) and =COUNTIF(C2:C501,\\\">110\\\").\",\n          \"Record what you found and what you decided in the cleaning log sheet.\",\n        ] },\n        { type: \"path\", items: [\"Home\", \"Conditional Formatting\", \"Highlight Cells Rules\", \"Duplicate Values\"], note: \"Colours repeated IDs in Excel so you can see them at a glance.\" },\n        { type: \"sheet\", id: \"meal-m5-l1-sheet\", title: \"Run the cleaning checks\", task: \"An extract of a fictional food security survey in the Adamawa region. In **F2:F10**, write `Duplicate` when the household ID appears more than once, otherwise `OK`. Then fill **H2:H5**. In this survey, 99 means \\\"don't know\\\" and any age above 110 is impossible.\",\n          data: [[\"HH ID\", \"Sex of head\", \"Age of head\", \"HH size\", \"Meals per day\", \"ID check\", \"Check\", \"Result\"],\n            [\"H001\", \"F\", 34, 5, 2, null, \"Blank cells in C2:E10\", null],\n            [\"H002\", \"M\", 41, 7, 3, null, \"Rows with a duplicate ID\", null],\n            [\"H003\", \"F\", 99, 4, 2, null, \"Ages coded 99\", null],\n            [\"H004\", \"M\", 28, null, 3, null, \"Ages above 110\", null],\n            [\"H002\", \"M\", 41, 7, 3, null],\n            [\"H006\", \"F\", 132, 6, 1, null],\n            [\"H007\", \"M\", 55, 3, null, null],\n            [\"H008\", \"F\", 46, 8, 2, null],\n            [\"H009\", \"M\", 19, 2, 1, null]],\n          editable: [\"F2\", \"F3\", \"F4\", \"F5\", \"F6\", \"F7\", \"F8\", \"F9\", \"F10\", \"H2\", \"H3\", \"H4\", \"H5\"],\n          checks: [{ cell: \"F2\", equals: \"OK\" }, { cell: \"F3\", equals: \"Duplicate\" }, { cell: \"F4\", equals: \"OK\" }, { cell: \"F5\", equals: \"OK\" }, { cell: \"F6\", equals: \"Duplicate\" }, { cell: \"F7\", equals: \"OK\" }, { cell: \"F8\", equals: \"OK\" }, { cell: \"F9\", equals: \"OK\" }, { cell: \"F10\", equals: \"OK\" },\n            { cell: \"H2\", equals: 2 }, { cell: \"H3\", equals: 2 }, { cell: \"H4\", equals: 1 }, { cell: \"H5\", equals: 1 }],\n          hint: \"In F2: =IF(COUNTIF($A$2:$A$10,A2)>1,\\\"Duplicate\\\",\\\"OK\\\") and copy down. H2: =COUNTBLANK(C2:E10). H3: =COUNTIF(F2:F10,\\\"Duplicate\\\"). H4: =COUNTIF(C2:C10,99). H5: =COUNTIF(C2:C10,\\\">110\\\").\",\n          solution: { F2: \"=IF(COUNTIF($A$2:$A$10,A2)>1,\\\"Duplicate\\\",\\\"OK\\\")\", F3: \"=IF(COUNTIF($A$2:$A$10,A3)>1,\\\"Duplicate\\\",\\\"OK\\\")\", F4: \"=IF(COUNTIF($A$2:$A$10,A4)>1,\\\"Duplicate\\\",\\\"OK\\\")\", F5: \"=IF(COUNTIF($A$2:$A$10,A5)>1,\\\"Duplicate\\\",\\\"OK\\\")\", F6: \"=IF(COUNTIF($A$2:$A$10,A6)>1,\\\"Duplicate\\\",\\\"OK\\\")\", F7: \"=IF(COUNTIF($A$2:$A$10,A7)>1,\\\"Duplicate\\\",\\\"OK\\\")\", F8: \"=IF(COUNTIF($A$2:$A$10,A8)>1,\\\"Duplicate\\\",\\\"OK\\\")\", F9: \"=IF(COUNTIF($A$2:$A$10,A9)>1,\\\"Duplicate\\\",\\\"OK\\\")\", F10: \"=IF(COUNTIF($A$2:$A$10,A10)>1,\\\"Duplicate\\\",\\\"OK\\\")\",\n            H2: \"=COUNTBLANK(C2:E10)\", H3: \"=COUNTIF(F2:F10,\\\"Duplicate\\\")\", H4: \"=COUNTIF(C2:C10,99)\", H5: \"=COUNTIF(C2:C10,\\\">110\\\")\" } },\n        { type: \"h\", text: \"The same checks in SPSS and Stata\" },\n        { type: \"path\", items: [\"Analyze\", \"Descriptive Statistics\", \"Frequencies\"], note: \"In SPSS, a frequency table of each variable shows codes such as 98 and 99 and impossible values at the ends of the list.\" },\n        { type: \"code\", text: \"* Stata: cleaning checks on a copy of the raw file\\nuse \\\"hh_survey_raw.dta\\\", clear\\nsave \\\"hh_survey_clean.dta\\\", replace\\n\\nduplicates report hhid          // how many IDs appear more than once\\nduplicates list hhid            // which ones\\nmisstable summarize             // missing values per variable\\ncount if age > 120 & !missing(age)\\nreplace age = . if age == 98 | age == 99   // log this change\\n\\n* SPSS syntax equivalents\\nFREQUENCIES VARIABLES=age hh_size.\\nMISSING VALUES age (98, 99).\" },\n        { type: \"callout\", tone: \"warning\", title: \"A Stata trap: missing is bigger than every number\", text: \"In Stata, a missing numeric value (shown as a dot) is treated as larger than any number. The command count if age > 120 therefore also counts every missing age. Add & !missing(age) to count only the real values above 120.\" },\n        { type: \"code\", text: \". duplicates report hhid\\n\\nDuplicates in terms of hhid\\n\\n--------------------------------------\\n   Copies | Observations       Surplus\\n----------+---------------------------\\n        1 |          412             0\\n        2 |            6             3\\n--------------------------------------\\n\\n. misstable summarize\\n                                                               Obs<.\\n                                                +------------------------------\\n               |                                | Unique\\n      Variable |     Obs=.     Obs>.     Obs<.  | values        Min         Max\\n  -------------+--------------------------------+------------------------------\\n       hh_size |         5                 413  |     14          1          18\\n        income |        27                 391  |    >500       2000      850000\\n  -----------------------------------------------------------------------------\" },\n        { type: \"form\", id: \"meal-m5-l1-stata\", title: \"Type the Stata cleaning commands\", task: \"You are cleaning a fictional nutrition survey file with 418 rows. Type the commands, then read the output above and answer.\",\n          hint: \"The commands are duplicates report, misstable summarize and count if. Surplus observations are the extra copies beyond the first one.\",\n          fields: [\n            { kind: \"text\", label: \"Command to report duplicates of the ID variable hhid\", pattern: \"^duplicates\\\\s+r(e(p(o(rt?)?)?)?)?\\\\s+hhid$\", example: \"duplicates report hhid\", mono: true, placeholder: \"Stata command\", explain: \"duplicates report shows how many observations appear once, twice and so on, and how many are surplus copies.\" },\n            { kind: \"text\", label: \"Command to count the missing values of every variable\", pattern: \"^misstable\\\\s+sum(m(a(r(i(ze?)?)?)?)?)?$\", example: \"misstable summarize\", mono: true, placeholder: \"Stata command\", explain: \"misstable summarize lists each variable that has missing values, with the number missing and the range of the others.\" },\n            { kind: \"text\", label: \"Command to count ages above 120, ignoring missing ages\", pattern: \"^count\\\\s+if\\\\s+age\\\\s*>\\\\s*120\\\\s*&\\\\s*(!\\\\s*missing\\\\(\\\\s*age\\\\s*\\\\)|age\\\\s*<\\\\s*\\\\.|age\\\\s*!=\\\\s*\\\\.)$\", example: \"count if age > 120 & !missing(age)\", mono: true, placeholder: \"Stata command\", explain: \"Without the second condition, Stata would also count the missing ages, because missing is larger than any number.\" },\n            { kind: \"select\", label: \"In the duplicates output above, how many surplus rows must be investigated and possibly dropped?\", options: [\"6\", \"3\", \"412\", \"2\"], answer: 1, explain: \"Six observations share an ID in pairs: three IDs appear twice, so there are three surplus copies.\" },\n            { kind: \"select\", label: \"According to misstable, how many households have no income value?\", options: [\"391\", \"418\", \"27\", \"5\"], answer: 2, explain: \"Obs=. is the count of system missing values: 27 households have no income recorded.\" },\n          ] },\n        { type: \"check\", id: \"meal-m5-l1-c1\", question: \"An age of 132 appears for one household head and the paper form is not available. What is the best action?\", options: [\"Replace it with 32, which is probably what was meant\", \"Replace it with the average age of the sample\", \"Set it to missing and record the change in the cleaning log\", \"Delete the whole household from the dataset\"], answer: 2, explain: \"Without a source you cannot know the true value. Setting it to missing keeps the household's other answers, and the log makes the decision transparent.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"In a fictional cash transfer project in the East region, two enumerators synced the same tablet twice after a network cut in Batouri, creating 38 duplicate households. The MEAL officer found them with a duplicate report on the household ID, compared the rows, kept the first submission of each, and listed the 38 IDs in the cleaning log. The donor's data quality check later found the log and accepted the figures without questions.\" },\n        { type: \"task\", id: \"meal-m5-l1-t1\", title: \"Practice\", items: [\n          \"Save the raw export of one of your datasets in a read-only folder and create a working copy\",\n          \"Create a cleaning log sheet with the columns ID, variable, old value, new value, reason, by and date\",\n          \"Run the duplicate ID, blank count and range checks on the working copy\",\n          \"List every special code used in your questionnaire (98, 99, 999…) and how you will treat each\",\n          \"Write the cleaning steps as a short Stata or SPSS script, or as numbered steps in Excel\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"duplicates: report, tag or drop duplicate observations\", url: \"https://www.stata.com/manuals/dduplicates.pdf\", source: STATA },\n          { label: \"misstable: tabulate missing values\", url: \"https://www.stata.com/manuals/rmisstable.pdf\", source: STATA },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 2 ───────────────────────────────\n    {\n      id: \"meal-m5-l2\",\n      title: \"Calculating and disaggregating indicators\",\n      minutes: 25,\n      objectives: [\n        \"Build an indicator from a clearly defined numerator and denominator\",\n        \"Disaggregate an indicator by sex, age group, location and disability with COUNTIFS and AVERAGEIFS\",\n        \"Produce the same disaggregation in Stata and SPSS with tab, mean and Crosstabs\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Most MEAL indicators are a percentage, a count or an average. The calculation is simple; the mistakes come from the definition. Who is counted on top of the fraction, who is counted below it, and who is left out? Once the indicator is right for the whole sample, disaggregation shows who benefits and who is being left behind.\" },\n        { type: \"h\", text: \"Numerator and denominator\" },\n        { type: \"table\", head: [\"Indicator\", \"Numerator\", \"Denominator\"], rows: [\n          [\"% of households using a mosquito net\", \"Respondents who slept under a net last night\", \"All respondents with a valid answer to that question\"],\n          [\"% of trained teachers who pass the post-test\", \"Trained teachers with a score of 70 or more\", \"Trained teachers who sat the post-test\"],\n          [\"Average number of meals per day\", \"Sum of meals reported\", \"Households with a valid answer\"],\n          [\"% of complaints closed within 30 days\", \"Complaints closed within 30 days\", \"Complaints received in the period\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Take the denominator from the indicator reference sheet\", text: \"The indicator reference sheet says who belongs in the denominator. Missing answers and \\\"don't know\\\" codes are normally excluded from it. Write the denominator next to every percentage you report, for example 60% (n = 240), so the reader knows what it is based on.\" },\n        { type: \"h\", text: \"Disaggregation\" },\n        { type: \"list\", items: [\n          \"Sex: women and men, girls and boys, reported separately.\",\n          \"Age group: use the groups in the reference sheet, for example 0–5, 6–17, 18–59 and 60+.\",\n          \"Location: region, department, health district, camp or host community.\",\n          \"Disability: usually measured with the Washington Group short set of questions.\",\n          \"Check the numbers in each group: a percentage based on 8 people is fragile and should be reported with care.\",\n        ] },\n        { type: \"h\", text: \"In Excel: COUNTIFS and AVERAGEIFS\" },\n        { type: \"p\", text: \"COUNTIFS counts rows that meet several conditions at once, so it builds both the numerator and the denominator of a disaggregated percentage. AVERAGEIFS gives the mean of a column for rows that meet the conditions, and it ignores empty cells.\" },\n        { type: \"code\", text: \"% of women who slept under a net\\n=COUNTIFS(B2:B11,\\\"F\\\",E2:E11,\\\"Yes\\\") / COUNTIF(B2:B11,\\\"F\\\")\\n\\nAverage nets per household in Maroua\\n=AVERAGEIFS(F2:F11,C2:C11,\\\"Maroua\\\")\\n\\nFrench Excel: NB.SI.ENS, NB.SI, MOYENNE.SI.ENS\" },\n        { type: \"sheet\", id: \"meal-m5-l2-sheet\", title: \"Disaggregate a malaria indicator\", task: \"Post-distribution survey of a fictional malaria prevention project in the Far North. Fill **H2:H9**. Percentages are shares (0.6 = 60%).\",\n          data: [[\"ID\", \"Sex\", \"Town\", \"Disability\", \"Slept under net\", \"Nets in HH\", \"Measure\", \"Result\"],\n            [\"R01\", \"F\", \"Kousseri\", \"No\", \"Yes\", 2, \"Respondents\", null],\n            [\"R02\", \"M\", \"Kousseri\", \"No\", \"No\", 1, \"% slept under a net\", null],\n            [\"R03\", \"F\", \"Maroua\", \"Yes\", \"Yes\", 2, \"% women\", null],\n            [\"R04\", \"F\", \"Maroua\", \"No\", \"No\", 0, \"% men\", null],\n            [\"R05\", \"M\", \"Kousseri\", \"No\", \"Yes\", 3, \"% in Kousseri\", null],\n            [\"R06\", \"F\", \"Kousseri\", \"Yes\", \"No\", 1, \"% with a disability\", null],\n            [\"R07\", \"M\", \"Maroua\", \"No\", \"Yes\", 2, \"Average nets, Maroua\", null],\n            [\"R08\", \"F\", \"Maroua\", \"No\", \"Yes\", 3, \"Average nets, women in Kousseri\", null],\n            [\"R09\", \"M\", \"Maroua\", \"Yes\", \"No\", 0],\n            [\"R10\", \"F\", \"Kousseri\", \"No\", \"Yes\", 2]],\n          editable: [\"H2\", \"H3\", \"H4\", \"H5\", \"H6\", \"H7\", \"H8\", \"H9\"],\n          checks: [{ cell: \"H2\", equals: 10 }, { cell: \"H3\", equals: 0.6, tol: 0.001 }, { cell: \"H4\", equals: 0.6667, tol: 0.001 }, { cell: \"H5\", equals: 0.5, tol: 0.001 }, { cell: \"H6\", equals: 0.6, tol: 0.001 }, { cell: \"H7\", equals: 0.3333, tol: 0.001 }, { cell: \"H8\", equals: 1.4, tol: 0.001 }, { cell: \"H9\", equals: 1.6667, tol: 0.001 }],\n          hint: \"H2: =COUNTA(A2:A11). Each disaggregated percentage is a COUNTIFS for the group with Yes, divided by a COUNTIF of the whole group, e.g. =COUNTIFS(B2:B11,\\\"F\\\",E2:E11,\\\"Yes\\\")/COUNTIF(B2:B11,\\\"F\\\"). The averages use AVERAGEIFS(F2:F11, …).\",\n          solution: { H2: \"=COUNTA(A2:A11)\", H3: \"=COUNTIF(E2:E11,\\\"Yes\\\")/H2\", H4: \"=COUNTIFS(B2:B11,\\\"F\\\",E2:E11,\\\"Yes\\\")/COUNTIF(B2:B11,\\\"F\\\")\", H5: \"=COUNTIFS(B2:B11,\\\"M\\\",E2:E11,\\\"Yes\\\")/COUNTIF(B2:B11,\\\"M\\\")\", H6: \"=COUNTIFS(C2:C11,\\\"Kousseri\\\",E2:E11,\\\"Yes\\\")/COUNTIF(C2:C11,\\\"Kousseri\\\")\", H7: \"=COUNTIFS(D2:D11,\\\"Yes\\\",E2:E11,\\\"Yes\\\")/COUNTIF(D2:D11,\\\"Yes\\\")\", H8: \"=AVERAGEIFS(F2:F11,C2:C11,\\\"Maroua\\\")\", H9: \"=AVERAGEIFS(F2:F11,B2:B11,\\\"F\\\",C2:C11,\\\"Kousseri\\\")\" } },\n        { type: \"h\", text: \"In Stata and SPSS\" },\n        { type: \"table\", head: [\"What you need\", \"Stata\", \"SPSS syntax\"], rows: [\n          [\"% of each sex who slept under a net\", \"tab sex netuse, row\", \"CROSSTABS /TABLES=sex BY netuse /CELLS=COUNT ROW.\"],\n          [\"Mean nets per household by town\", \"mean nets, over(town)\", \"MEANS TABLES=nets BY town.\"],\n          [\"Same table for each town separately\", \"bysort town: tab sex netuse, row\", \"SPLIT FILE BY town, then CROSSTABS\"],\n        ] },\n        { type: \"path\", items: [\"Analyze\", \"Descriptive Statistics\", \"Crosstabs\"], note: \"Put the group (sex) in Rows and the outcome in Columns, then choose Row percentages under Cells.\" },\n        { type: \"form\", id: \"meal-m5-l2-cmd\", title: \"Type the disaggregation commands\", task: \"The fictional malaria survey now has 1 240 respondents in Stata and SPSS. Variables: sex, town, netuse (0 = No, 1 = Yes) and nets. Type each command.\",\n          hint: \"In Stata, the group goes first in tab and the row option gives percentages within each group; over() goes after a comma in mean. In SPSS, CROSSTABS uses /TABLES = rows BY columns and /CELLS for percentages.\",\n          fields: [\n            { kind: \"text\", label: \"Stata: share of each sex who slept under a net (row percentages)\", pattern: \"^tab(u(l(a(te?)?)?)?)?\\\\s+sex\\\\s+netuse\\\\s*,\\\\s*row$\", example: \"tab sex netuse, row\", mono: true, placeholder: \"Stata command\", explain: \"Each row adds up to 100%: the Yes column gives the indicator for women and for men.\" },\n            { kind: \"text\", label: \"Stata: mean number of nets per household, by town\", pattern: \"^mean\\\\s+nets\\\\s*,\\\\s*over\\\\(\\\\s*town\\\\s*\\\\)$\", example: \"mean nets, over(town)\", mono: true, placeholder: \"Stata command\", explain: \"mean with over() estimates the mean for each town, with a standard error and a 95% confidence interval.\" },\n            { kind: \"text\", label: \"SPSS syntax: cross-tab of sex by netuse with counts and row percentages\", pattern: \"^CROSSTABS\\\\s+(/\\\\s*)?TABLES\\\\s*=\\\\s*sex\\\\s+BY\\\\s+netuse\\\\s*/\\\\s*CELLS\\\\s*=\\\\s*(COUNT\\\\s+ROW|ROW\\\\s+COUNT|ROW)\\\\s*\\\\.?$\", example: \"CROSSTABS /TABLES=sex BY netuse /CELLS=COUNT ROW.\", mono: true, placeholder: \"SPSS syntax\", explain: \"The first variable after TABLES= forms the rows, the variable after BY forms the columns.\" },\n            { kind: \"text\", label: \"SPSS syntax: mean number of nets by town\", pattern: \"^MEANS\\\\s+(/\\\\s*)?TABLES\\\\s*=\\\\s*nets\\\\s+BY\\\\s+town\\\\s*\\\\.?$\", example: \"MEANS TABLES=nets BY town.\", mono: true, placeholder: \"SPSS syntax\", explain: \"MEANS gives the mean, the number of cases and the standard deviation for each town.\" },\n            { kind: \"select\", label: \"Your indicator must be reported for women with a disability in Kousseri, but only 9 respondents fit that group. What do you do?\", options: [\"Drop the disaggregation\", \"Report the result with its n and a note that the group is too small for firm conclusions\", \"Merge them with the men\", \"Report 0% to be safe\"], answer: 1, explain: \"Keep the disaggregation, but show n = 9 and warn the reader. Small groups give unstable percentages.\" },\n          ] },\n        { type: \"check\", id: \"meal-m5-l2-c1\", question: \"Out of 300 respondents, 280 answered the question on net use and 196 said yes. What value should you report?\", options: [\"65.3% (196 ÷ 300)\", \"70% (196 ÷ 280)\", \"93.3% (280 ÷ 300)\", \"196 households\"], answer: 1, explain: \"Missing answers are excluded from the denominator unless the reference sheet says otherwise: 196 ÷ 280 = 70%, reported with n = 280.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A fictional education project in the North-West region reported 82% of pupils passing the end-of-year test. When the MEAL officer disaggregated by sex and by displacement status, the pass rate was 85% for host community boys but 61% for displaced girls. The team added remedial classes for displaced girls, and the donor praised the report for showing the gap instead of hiding it in the average.\" },\n        { type: \"task\", id: \"meal-m5-l2-t1\", title: \"Practice\", items: [\n          \"Write the numerator and denominator of three indicators from your logframe\",\n          \"Check in the reference sheets which disaggregations each indicator requires\",\n          \"Build a COUNTIFS table in Excel with one row per sex and one column per location\",\n          \"Run the same disaggregation in Stata or SPSS and compare the figures with Excel\",\n          \"Add the n of each group next to every percentage in your next report\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"mean: estimate means (with the over option)\", url: \"https://www.stata.com/manuals/rmean.pdf\", source: STATA },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 3 ───────────────────────────────\n    {\n      id: \"meal-m5-l3\",\n      title: \"Descriptive statistics and cross-tabulations in Excel, SPSS and Stata\",\n      minutes: 25,\n      objectives: [\n        \"Choose between mean and median and report frequencies and percentages correctly\",\n        \"Read a cross-tabulation with row or column percentages\",\n        \"Interpret a chi-square p-value in plain words without over-claiming\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Descriptive statistics summarise a dataset in a few numbers: how many, what share, what is typical and how spread out. Cross-tabulations compare those numbers between groups. Together they answer most questions a programme manager or a donor asks, and they can be produced in Excel, SPSS or Stata with a few clicks or one line of code.\" },\n        { type: \"h\", text: \"The essential descriptive statistics\" },\n        { type: \"table\", head: [\"Statistic\", \"What it tells you\", \"Excel\", \"Stata\", \"SPSS\"], rows: [\n          [\"Frequency and percentage\", \"How many and what share fall in each category\", \"COUNTIF, then divide by the total\", \"tab var\", \"FREQUENCIES\"],\n          [\"Mean\", \"The average; pulled by extreme values\", \"AVERAGE\", \"summarize var\", \"DESCRIPTIVES\"],\n          [\"Median\", \"The middle value; resists extreme values\", \"MEDIAN\", \"summarize var, detail\", \"FREQUENCIES with /STATISTICS=MEDIAN\"],\n          [\"Minimum and maximum\", \"The range; a first check for errors\", \"MIN, MAX\", \"summarize var\", \"DESCRIPTIVES\"],\n          [\"Standard deviation\", \"How spread out the values are around the mean\", \"STDEV.S\", \"summarize var\", \"DESCRIPTIVES\"],\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Mean or median?\", text: \"For income, distance, time or expenditure, a few very large values pull the mean up. When the mean is much higher than the median, report the median as the typical value and mention the mean if the donor asks for it.\" },\n        { type: \"sheet\", id: \"meal-m5-l3-desc\", title: \"Mean, median and range\", task: \"Distance in km from nine fictional households to the nearest health centre in a health district of the Centre region. Fill **E2:E6**, then answer in **E7**: which is the better typical value, `Mean` or `Median`?\",\n          data: [[\"HH\", \"Distance (km)\", null, \"Statistic\", \"Value\"],\n            [\"D01\", 2, null, \"Number of households\", null],\n            [\"D02\", 3, null, \"Mean\", null],\n            [\"D03\", 1.5, null, \"Median\", null],\n            [\"D04\", 4, null, \"Minimum\", null],\n            [\"D05\", 2.5, null, \"Maximum\", null],\n            [\"D06\", 3, null, \"Better typical value\", null],\n            [\"D07\", 18],\n            [\"D08\", 2],\n            [\"D09\", 3.5]],\n          editable: [\"E2\", \"E3\", \"E4\", \"E5\", \"E6\", \"E7\"],\n          checks: [{ cell: \"E2\", equals: 9 }, { cell: \"E3\", equals: 4.3889, tol: 0.001 }, { cell: \"E4\", equals: 3 }, { cell: \"E5\", equals: 1.5 }, { cell: \"E6\", equals: 18 }, { cell: \"E7\", equals: \"Median\" }],\n          hint: \"Use COUNT, AVERAGE, MEDIAN, MIN and MAX on B2:B10. One household lives 18 km away, which pulls the mean well above what most households experience.\",\n          solution: { E2: \"=COUNT(B2:B10)\", E3: \"=AVERAGE(B2:B10)\", E4: \"=MEDIAN(B2:B10)\", E5: \"=MIN(B2:B10)\", E6: \"=MAX(B2:B10)\", E7: \"Median\" } },\n        { type: \"h\", text: \"Reading a cross-tabulation\" },\n        { type: \"p\", text: \"A cross-tab counts the respondents in each combination of two variables. The key choice is the direction of the percentages. Put the group you compare in the rows and ask for row percentages: each row then adds up to 100%, and you compare the rows. Column percentages answer a different question: among those with a given outcome, what share belongs to each group.\" },\n        { type: \"code\", text: \". tab residence registered, row chi2\\n\\n+----------------+\\n| Key            |\\n|----------------|\\n|   frequency    |\\n| row percentage |\\n+----------------+\\n\\n           |      registered\\n residence |        No        Yes |     Total\\n-----------+----------------------+----------\\n       IDP |        78         42 |       120 \\n           |     65.00      35.00 |    100.00 \\n-----------+----------------------+----------\\n      Host |        64         96 |       160 \\n           |     40.00      60.00 |    100.00 \\n-----------+----------------------+----------\\n     Total |       142        138 |       280 \\n           |     50.71      49.29 |    100.00 \\n\\n          Pearson chi2(1) =  17.1464   Pr = 0.000\" },\n        { type: \"p\", text: \"Read it row by row: 35% of displaced (IDP) children have a birth certificate, against 60% of host community children. The gap is 25 percentage points, not 25%.\" },\n        { type: \"sheet\", id: \"meal-m5-l3-xtab\", title: \"Row and column percentages\", task: \"Rebuild the percentages of the birth registration cross-tab above. Fill **D2:D3** with the share registered in each group (row %), **E2:E3** with the share of all registered children who are IDP or host (column %), and **D5** with the gap in percentage points between host and IDP.\",\n          data: [[\"Residence\", \"Not registered\", \"Registered\", \"Row % registered\", \"Column % of registered\"],\n            [\"IDP\", 78, 42, null, null],\n            [\"Host\", 64, 96, null, null],\n            [\"Total\", 142, 138, null, null],\n            [\"Gap host minus IDP (points)\", null, null, null]],\n          editable: [\"D2\", \"D3\", \"E2\", \"E3\", \"D5\"],\n          checks: [{ cell: \"D2\", equals: 0.35, tol: 0.001 }, { cell: \"D3\", equals: 0.6, tol: 0.001 }, { cell: \"E2\", equals: 0.3043, tol: 0.001 }, { cell: \"E3\", equals: 0.6957, tol: 0.001 }, { cell: \"D5\", equals: 25, tol: 0.01 }],\n          hint: \"Row %: registered divided by the row total, =C2/(B2+C2). Column %: registered in the group divided by all registered, =C2/C4. The gap in points is (D3-D2)*100.\",\n          solution: { D2: \"=C2/(B2+C2)\", D3: \"=C3/(B3+C3)\", E2: \"=C2/$C$4\", E3: \"=C3/$C$4\", D5: \"=(D3-D2)*100\" } },\n        { type: \"h\", text: \"What the chi-square test tells you\" },\n        { type: \"list\", items: [\n          \"The chi-square test asks: if there were no real link between the two variables in the population, how likely would a gap this large be in a sample, just by chance?\",\n          \"That likelihood is the p-value. If p < 0.05, the gap is called statistically significant: chance alone is an unlikely explanation.\",\n          \"If p ≥ 0.05, you cannot rule out chance. It does not prove that the groups are equal; the sample may be too small.\",\n          \"Significant does not mean large or important, and it never proves that one variable causes the other.\",\n          \"The test assumes a random sample and enough cases in each cell; with very small counts, ask a statistician.\",\n        ] },\n        { type: \"path\", items: [\"Analyze\", \"Descriptive Statistics\", \"Crosstabs\"], note: \"In SPSS, click Statistics and tick Chi-square, then Cells and tick Row under Percentages.\" },\n        { type: \"code\", text: \"* Stata\\nsummarize distance, detail\\ntabstat distance, statistics(n mean median min max) by(residence)\\ntab residence registered, row chi2\\n\\n* SPSS syntax\\nFREQUENCIES VARIABLES=distance /FORMAT=NOTABLE /STATISTICS=MEAN MEDIAN MINIMUM MAXIMUM.\\nCROSSTABS /TABLES=residence BY registered /CELLS=COUNT ROW /STATISTICS=CHISQ.\" },\n        { type: \"code\", text: \". tabstat distance, statistics(n mean median min max) by(residence)\\n\\nSummary for variables: distance\\nGroup variable: residence\\n\\nresidence |         N      Mean       p50       Min       Max\\n----------+--------------------------------------------------\\n      IDP |       120      6.42       4.5        .5        31\\n     Host |       160      3.18       2.8        .3        12\\n----------+--------------------------------------------------\\n    Total |       280  4.568571       3.3        .3        31\\n-------------------------------------------------------------\" },\n        { type: \"form\", id: \"meal-m5-l3-read\", title: \"Read the output\", task: \"Use the Stata cross-tab and the tabstat output above from the same fictional survey to answer.\",\n          hint: \"Row percentages compare groups. p50 is the median. Pr is the p-value of the chi-square test.\",\n          fields: [\n            { kind: \"select\", label: \"What share of IDP children are registered?\", options: [\"42%\", \"35%\", \"30.4%\", \"65%\"], answer: 1, explain: \"Row percentage in the IDP row, Yes column: 42 out of 120 = 35%.\" },\n            { kind: \"select\", label: \"What does Pr = 0.000 mean here?\", options: [\"There is no difference between the groups\", \"Being displaced causes lower registration\", \"A gap this large would be very unlikely if registration did not differ between the groups in the population\", \"Zero percent of children are registered\"], answer: 2, explain: \"A p-value below 0.05 means chance alone is an unlikely explanation. It says nothing about causes.\" },\n            { kind: \"select\", label: \"In the tabstat output, which value best describes the typical distance for IDP households?\", options: [\"6.42 km, the mean\", \"4.5 km, the median\", \"31 km, the maximum\", \"0.5 km, the minimum\"], answer: 1, explain: \"The mean (6.42) is pulled up by a few very distant households; the median (4.5) is the typical value.\" },\n            { kind: \"text\", label: \"Type the Stata command that produced the cross-tab with row percentages and the chi-square test\", pattern: \"^tab(u(l(a(te?)?)?)?)?\\\\s+residence\\\\s+registered\\\\s*,\\\\s*(row\\\\s+chi2|chi2\\\\s+row)$\", example: \"tab residence registered, row chi2\", mono: true, placeholder: \"Stata command\", explain: \"The row option adds row percentages; chi2 adds Pearson's chi-square test and its p-value.\" },\n          ] },\n        { type: \"check\", id: \"meal-m5-l3-c1\", question: \"A cross-tab shows that 48% of women and 41% of men use the health centre, with a chi-square p-value of 0.31. What is the correct conclusion?\", options: [\"Women use the health centre more than men; the difference is proven\", \"The difference could well be due to chance; the data does not show a clear difference\", \"There is no difference at all between women and men\", \"The test failed and must be repeated\"], answer: 1, explain: \"With p ≥ 0.05, chance remains a plausible explanation. That is not proof that women and men are equal, only that this sample cannot show a difference.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"In a fictional protection project in the Far North, a draft report stated that displacement \\\"causes\\\" low birth registration because the chi-square test was significant. The MEAL officer rewrote it: displaced children were much less likely to be registered (35% against 60%, p < 0.001), and the team listed possible reasons, such as lost documents and distance to civil status centres, to explore in focus groups.\" },\n        { type: \"task\", id: \"meal-m5-l3-t1\", title: \"Practice\", items: [\n          \"Produce the mean, median, minimum and maximum of one numeric variable of your survey in Excel and in Stata or SPSS\",\n          \"Decide for that variable whether the mean or the median is the better typical value, and write why\",\n          \"Build one cross-tab with the group in the rows and row percentages\",\n          \"Add the chi-square test and write one plain sentence about the p-value\",\n          \"Report the gap between two groups in percentage points\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"tabulate twoway: two-way table of frequencies\", url: \"https://www.stata.com/manuals/rtabulatetwoway.pdf\", source: STATA },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── LESSON 4 ───────────────────────────────\n    {\n      id: \"meal-m5-l4\",\n      title: \"Basic qualitative analysis: coding and themes\",\n      minutes: 25,\n      objectives: [\n        \"Build a codebook with deductive and inductive codes and apply it to transcripts\",\n        \"Count code frequency in an Excel code matrix and select representative quotes\",\n        \"Triangulate qualitative themes with quantitative results\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Focus groups and key informant interviews explain the numbers: why women do not come to the health centre, why a water point is not used, why a training did not change practice. Their answers arrive as pages of notes and transcripts. Coding turns those pages into a small number of themes you can compare, count and illustrate with quotes.\" },\n        { type: \"h\", text: \"From recordings to transcripts\" },\n        { type: \"list\", items: [\n          \"Transcribe or write detailed notes on the same day, while the discussion is fresh.\",\n          \"Translate into the analysis language, keeping key expressions in the original language (Fulfulde, Pidgin, Ewondo…) when they carry meaning.\",\n          \"Give each transcript a code (FGD1, KII2) and a header: date, place, type of group, facilitator. Never use participants' names.\",\n          \"Number the lines or paragraphs so that every quote can be traced back.\",\n        ] },\n        { type: \"h\", text: \"The codebook\" },\n        { type: \"table\", head: [\"Code\", \"Definition\", \"Type\", \"Example of text\"], rows: [\n          [\"Distance\", \"Travel time, cost of transport or lack of transport to the service\", \"Deductive\", \"\\\"The health centre is two hours on foot.\\\"\"],\n          [\"Cost\", \"Fees, drugs or other payments\", \"Deductive\", \"\\\"They ask us to buy the gloves.\\\"\"],\n          [\"Safety\", \"Fear of attack or harassment on the way or at the service\", \"Inductive\", \"\\\"Nobody walks on that road after four o'clock.\\\"\"],\n          [\"Staff attitude\", \"How staff treat and speak to users\", \"Inductive\", \"\\\"The nurse shouted at me in front of everyone.\\\"\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Deductive and inductive codes\", text: \"Deductive codes come from your questions, your theory of change or the indicator framework and are written before you read. Inductive codes emerge from the data: themes that participants raise and that you did not expect. A good codebook starts deductive and grows inductive codes as you read.\" },\n        { type: \"h\", text: \"Coding step by step\" },\n        { type: \"steps\", title: \"A simple coding process\", items: [\n          \"Read all transcripts once without coding, and note first impressions.\",\n          \"Apply the deductive codes, marking each passage with one or more codes.\",\n          \"Add an inductive code when a new idea appears in two or more transcripts, and write its definition in the codebook.\",\n          \"Have a second person code one or two transcripts and compare; clarify definitions where you disagree.\",\n          \"Build the code matrix: one row per transcript, one column per code, 1 when the code appears.\",\n          \"Group related codes into themes and write a short summary of each theme, with its best quotes.\",\n        ] },\n        { type: \"sheet\", id: \"meal-m5-l4-matrix\", title: \"Count codes in a matrix\", task: \"Code matrix from six fictional transcripts on why women do not give birth at a health centre in a health district of the North region (1 = the code appears). Fill **C8:F8** with the number of transcripts mentioning each code, **C9:F9** with the number of women's transcripts, and **C10:F10** with the share of women's transcripts.\",\n          data: [[\"Transcript\", \"Group\", \"Distance\", \"Cost\", \"Safety\", \"Staff attitude\"],\n            [\"FGD1\", \"Women\", 1, 0, 1, 1],\n            [\"FGD2\", \"Men\", 1, 1, 0, 0],\n            [\"FGD3\", \"Women\", 1, 1, 1, 0],\n            [\"KII1\", \"Men\", 0, 1, 0, 1],\n            [\"FGD4\", \"Women\", 0, 0, 1, 1],\n            [\"KII2\", \"Women\", 1, 0, 1, 0],\n            [\"All transcripts\", null, null, null, null, null],\n            [\"Women's transcripts\", null, null, null, null, null],\n            [\"Share of women's transcripts\", null, null, null, null, null]],\n          editable: [\"C8\", \"D8\", \"E8\", \"F8\", \"C9\", \"D9\", \"E9\", \"F9\", \"C10\", \"D10\", \"E10\", \"F10\"],\n          checks: [{ cell: \"C8\", equals: 4 }, { cell: \"D8\", equals: 3 }, { cell: \"E8\", equals: 4 }, { cell: \"F8\", equals: 3 },\n            { cell: \"C9\", equals: 3 }, { cell: \"D9\", equals: 1 }, { cell: \"E9\", equals: 4 }, { cell: \"F9\", equals: 2 },\n            { cell: \"C10\", equals: 0.75, tol: 0.001 }, { cell: \"D10\", equals: 0.25, tol: 0.001 }, { cell: \"E10\", equals: 1, tol: 0.001 }, { cell: \"F10\", equals: 0.5, tol: 0.001 }],\n          hint: \"Row 8: =SUM(C2:C7). Row 9: =SUMIF($B$2:$B$7,\\\"Women\\\",C2:C7). Row 10: =C9/COUNTIF($B$2:$B$7,\\\"Women\\\").\",\n          solution: { C8: \"=SUM(C2:C7)\", D8: \"=SUM(D2:D7)\", E8: \"=SUM(E2:E7)\", F8: \"=SUM(F2:F7)\",\n            C9: \"=SUMIF($B$2:$B$7,\\\"Women\\\",C2:C7)\", D9: \"=SUMIF($B$2:$B$7,\\\"Women\\\",D2:D7)\", E9: \"=SUMIF($B$2:$B$7,\\\"Women\\\",E2:E7)\", F9: \"=SUMIF($B$2:$B$7,\\\"Women\\\",F2:F7)\",\n            C10: \"=C9/COUNTIF($B$2:$B$7,\\\"Women\\\")\", D10: \"=D9/COUNTIF($B$2:$B$7,\\\"Women\\\")\", E10: \"=E9/COUNTIF($B$2:$B$7,\\\"Women\\\")\", F10: \"=F9/COUNTIF($B$2:$B$7,\\\"Women\\\")\" } },\n        { type: \"callout\", tone: \"warning\", title: \"Counts show spread, not importance\", text: \"A code that appears in four transcripts out of six is widespread, but a theme mentioned once can still be critical, for example a single report of abuse by staff. Use counts to show how common a theme is, never as a percentage of the population.\" },\n        { type: \"h\", text: \"Choosing quotes and triangulating\" },\n        { type: \"list\", items: [\n          \"Choose quotes that are typical of the theme, not only the most dramatic ones.\",\n          \"Keep quotes short, and label them with the group and place only, for example: woman, FGD, Tcholliré.\",\n          \"Remove any detail that could identify the speaker in a small village.\",\n          \"Triangulate: set each theme next to the survey figures. Do they confirm, explain or contradict each other?\",\n          \"When sources disagree, say so and explain what you did to understand why.\",\n        ] },\n        { type: \"form\", id: \"meal-m5-l4-code\", title: \"Code the quotes\", task: \"Apply the codebook above to extracts from the fictional transcripts, then answer the analysis questions.\",\n          hint: \"Use the definitions in the codebook. For triangulation, ask whether the qualitative theme explains a pattern seen in the survey.\",\n          fields: [\n            { kind: \"select\", label: \"\\\"When labour starts at night, we stay at home. The bush road is not safe.\\\"\", options: CODES, answer: 2, explain: \"Fear on the road is the Safety code. Some coders would also add Distance; one passage can carry several codes.\" },\n            { kind: \"select\", label: \"\\\"We must pay for the card, the gloves and the medicines before they touch you.\\\"\", options: CODES, answer: 1 },\n            { kind: \"select\", label: \"\\\"The motorbike to the centre costs more than a day's work, and there is often none.\\\"\", options: CODES, answer: 0, explain: \"Transport cost and availability fall under Distance as defined in the codebook, not under Cost, which covers payments at the service.\" },\n            { kind: \"select\", label: \"\\\"The midwife is young and she insults the women who scream.\\\"\", options: CODES, answer: 3 },\n            { kind: \"select\", label: \"Safety was not in the interview guide, but participants raised it in four transcripts. What kind of code is it?\", options: [\"Deductive\", \"Inductive\", \"A quantitative variable\", \"A theme to ignore because it was not asked\"], answer: 1, explain: \"A code that emerges from the data rather than from the guide is inductive.\" },\n            { kind: \"select\", label: \"The survey shows that births at the health centre are 20 points lower in villages more than 10 km away. How do the transcripts help?\", options: [\"They replace the survey figure\", \"They explain the figure: distance, night travel and safety keep women at home\", \"They prove that distance causes home births\", \"They are not useful because the samples differ\"], answer: 1, explain: \"This is triangulation: the qualitative themes explain the pattern in the numbers.\" },\n          ] },\n        { type: \"check\", id: \"meal-m5-l4-c1\", question: \"Which practice makes qualitative analysis more reliable?\", options: [\"Choosing only the most striking quotes\", \"Coding alone and never changing the codebook\", \"Writing code definitions and having a second person code some transcripts to compare\", \"Reporting that 67% of the population fear the road because four of six transcripts say so\"], answer: 2, explain: \"Clear definitions and a second coder make the coding consistent and reveal ambiguous codes. Transcript counts are not population percentages.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A fictional WASH project in the North-West region found that only 40% of households used the new water kiosks. Focus groups coded in Excel showed a theme nobody expected: the kiosks closed at 5 p.m., before women returned from the farms. The team extended opening hours, and the next monitoring round showed use rising.\" },\n        { type: \"task\", id: \"meal-m5-l4-t1\", title: \"Practice\", items: [\n          \"Write a codebook of five codes, with a definition and an example for each, for one of your FGD guides\",\n          \"Code two transcripts and add at least one inductive code\",\n          \"Ask a colleague to code one transcript and compare your codes\",\n          \"Build a code matrix in Excel and count code frequency by group\",\n          \"Write one paragraph that triangulates a theme with a survey figure\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Thematic coding\", url: \"https://www.betterevaluation.org/methods-approaches/methods/thematic-coding\", source: BE },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────────── PRACTICE ───────────────────────────────\n    {\n      id: \"meal-m5-practice\",\n      title: \"Practice lab: from raw data to disaggregated results\",\n      minutes: 40,\n      objectives: [\n        \"Calculate rates and conditional counts from a small monitoring dataset\",\n        \"Run and read a disaggregated cross-tab in Stata and SPSS\",\n        \"Build disaggregated indicators that exclude missing answers from the denominator\",\n        \"Clean a dataset with duplicates, special codes and impossible values before calculating indicators\",\n      ],\n      blocks: [\n        INTRO,\n        { type: \"h\", text: \"Exercise 1: School attendance\" },\n        { type: \"sheet\", id: \"meal-pr-m5-school\", level: \"beginner\", title: \"Monthly attendance rates\",\n          task: \"Attendance of six pupils in a fictional primary school in the Littoral region. The school was open 20 days (**G2**). Fill **D2:D7** with each pupil's attendance rate, then **G3:G5**.\",\n          data: [[\"Pupil\", \"Sex\", \"Days present\", \"Attendance rate\", null, \"Measure\", \"Result\"],\n            [\"Amina\", \"F\", 19, null, null, \"School days in the month\", 20],\n            [\"Boris\", \"M\", 14, null, null, \"Average attendance rate\", null],\n            [\"Chantal\", \"F\", 17, null, null, \"Pupils at 80% or more\", null],\n            [\"Didier\", \"M\", 20, null, null, \"Girls at 80% or more\", null],\n            [\"Esther\", \"F\", 12, null],\n            [\"Fabrice\", \"M\", 18, null]],\n          editable: [\"D2\", \"D3\", \"D4\", \"D5\", \"D6\", \"D7\", \"G3\", \"G4\", \"G5\"],\n          checks: [{ cell: \"D2\", equals: 0.95, tol: 0.001 }, { cell: \"D3\", equals: 0.7, tol: 0.001 }, { cell: \"D4\", equals: 0.85, tol: 0.001 }, { cell: \"D5\", equals: 1, tol: 0.001 }, { cell: \"D6\", equals: 0.6, tol: 0.001 }, { cell: \"D7\", equals: 0.9, tol: 0.001 },\n            { cell: \"G3\", equals: 0.8333, tol: 0.001 }, { cell: \"G4\", equals: 4 }, { cell: \"G5\", equals: 2 }],\n          hint: \"D2: =C2/$G$2, copied down (the $ keeps G2 fixed). G3: =AVERAGE(D2:D7). G4: =COUNTIF(D2:D7,\\\">=0.8\\\"). G5: =COUNTIFS(B2:B7,\\\"F\\\",D2:D7,\\\">=0.8\\\").\",\n          solution: { D2: \"=C2/$G$2\", D3: \"=C3/$G$2\", D4: \"=C4/$G$2\", D5: \"=C5/$G$2\", D6: \"=C6/$G$2\", D7: \"=C7/$G$2\", G3: \"=AVERAGE(D2:D7)\", G4: \"=COUNTIF(D2:D7,\\\">=0.8\\\")\", G5: \"=COUNTIFS(B2:B7,\\\"F\\\",D2:D7,\\\">=0.8\\\")\" } },\n        { type: \"h\", text: \"Exercise 2: Nutrition screening\" },\n        { type: \"code\", text: \". tab sex muac_cat, row chi2\\n\\n           |            muac_cat\\n       sex |     Green     Yellow        Red |     Total\\n-----------+---------------------------------+----------\\n    Female |       168         24          8 |       200 \\n           |     84.00      12.00       4.00 |    100.00 \\n-----------+---------------------------------+----------\\n      Male |       150         36         14 |       200 \\n           |     75.00      18.00       7.00 |    100.00 \\n-----------+---------------------------------+----------\\n     Total |       318         60         22 |       400 \\n           |     79.50      15.00       5.50 |    100.00 \\n\\n          Pearson chi2(2) =   5.0552   Pr = 0.080\" },\n        { type: \"form\", id: \"meal-pr-m5-muac\", level: \"intermediate\", title: \"Screening results by sex\",\n          task: \"Community health workers in a fictional nutrition project in the East region screened 400 children aged 6–59 months with a MUAC tape (green = normal, yellow = moderate, red = severe acute malnutrition). Type the commands and read the output above.\",\n          hint: \"Group first, outcome second, then the options after the comma. Row percentages are the second line of each row. Compare Pr with 0.05.\",\n          fields: [\n            { kind: \"text\", label: \"Stata: the command that produced the output above\", pattern: \"^tab(u(l(a(te?)?)?)?)?\\\\s+sex\\\\s+muac_cat\\\\s*,\\\\s*(row\\\\s+chi2|chi2\\\\s+row)$\", example: \"tab sex muac_cat, row chi2\", mono: true, placeholder: \"Stata command\", explain: \"sex in the rows, MUAC category in the columns, with row percentages and the chi-square test.\" },\n            { kind: \"text\", label: \"SPSS syntax: the same table with counts, row percentages and chi-square\", pattern: \"^CROSSTABS\\\\s+(/\\\\s*)?TABLES\\\\s*=\\\\s*sex\\\\s+BY\\\\s+muac_cat\\\\s*(/\\\\s*CELLS\\\\s*=\\\\s*(COUNT\\\\s+ROW|ROW\\\\s+COUNT|ROW)\\\\s*/\\\\s*STATISTICS\\\\s*=\\\\s*CHISQ|/\\\\s*STATISTICS\\\\s*=\\\\s*CHISQ\\\\s*/\\\\s*CELLS\\\\s*=\\\\s*(COUNT\\\\s+ROW|ROW\\\\s+COUNT|ROW))\\\\s*\\\\.?$\", example: \"CROSSTABS /TABLES=sex BY muac_cat /CELLS=COUNT ROW /STATISTICS=CHISQ.\", mono: true, placeholder: \"SPSS syntax\", explain: \"/CELLS sets the percentages shown; /STATISTICS=CHISQ adds the Chi-Square Tests table.\" },\n            { kind: \"select\", label: \"What percentage of boys screened were in the red category?\", options: [\"14%\", \"5.5%\", \"7%\", \"63.6%\"], answer: 2, explain: \"14 of 200 boys = 7%, read on the row percentage line of the Male row.\" },\n            { kind: \"select\", label: \"What is the total percentage of acute malnutrition (yellow + red) among girls?\", options: [\"16%\", \"20.5%\", \"12%\", \"25%\"], answer: 0, explain: \"12% yellow + 4% red = 16% for girls, against 25% for boys.\" },\n            { kind: \"select\", label: \"How should the team describe the difference between girls and boys?\", options: [\"Boys are significantly more malnourished (p < 0.05)\", \"Boys show more malnutrition in this sample, but with p = 0.080 the difference is not statistically significant\", \"There is no difference between girls and boys\", \"The test proves that sex causes malnutrition\"], answer: 1, explain: \"p = 0.080 is above 0.05: chance cannot be ruled out. Report the figures, note the gap, and keep monitoring rather than claiming a proven difference.\" },\n          ] },\n        { type: \"h\", text: \"Exercise 3: Water access in a displacement setting\" },\n        { type: \"sheet\", id: \"meal-pr-m5-wash\", level: \"advanced\", title: \"Disaggregated WASH indicators with a missing answer\",\n          task: \"Household survey in a fictional IDP site and host community in the South-West region. W04 did not answer the water source question and must be excluded from the denominators. Fill **H2:H7**.\",\n          data: [[\"HH\", \"Location\", \"Head has disability\", \"Improved source\", \"Minutes to collect\", null, \"Measure\", \"Result\"],\n            [\"W01\", \"Camp\", \"No\", \"Yes\", 20, null, \"Households with a source answer\", null],\n            [\"W02\", \"Camp\", \"Yes\", \"No\", 45, null, \"% using an improved source\", null],\n            [\"W03\", \"Host\", \"No\", \"Yes\", 10, null, \"% improved, camp\", null],\n            [\"W04\", \"Camp\", \"No\", null, 35, null, \"% improved, head with disability\", null],\n            [\"W05\", \"Host\", \"Yes\", \"Yes\", 15, null, \"Average minutes, camp with improved source\", null],\n            [\"W06\", \"Camp\", \"No\", \"Yes\", 25, null, \"Households over 30 minutes\", null],\n            [\"W07\", \"Host\", \"No\", \"No\", 50],\n            [\"W08\", \"Camp\", \"Yes\", \"Yes\", 40],\n            [\"W09\", \"Host\", \"No\", \"Yes\", 5],\n            [\"W10\", \"Camp\", \"No\", \"No\", 60]],\n          editable: [\"H2\", \"H3\", \"H4\", \"H5\", \"H6\", \"H7\"],\n          checks: [{ cell: \"H2\", equals: 9 }, { cell: \"H3\", equals: 0.6667, tol: 0.001 }, { cell: \"H4\", equals: 0.6, tol: 0.001 }, { cell: \"H5\", equals: 0.6667, tol: 0.001 }, { cell: \"H6\", equals: 28.3333, tol: 0.01 }, { cell: \"H7\", equals: 5 }],\n          hint: \"Valid answers are Yes plus No: =COUNTIF(D2:D11,\\\"Yes\\\")+COUNTIF(D2:D11,\\\"No\\\"). For each group, divide the COUNTIFS with Yes by the COUNTIFS with Yes plus the COUNTIFS with No, so the blank never enters the denominator. H6 needs AVERAGEIFS with two conditions.\",\n          solution: { H2: \"=COUNTIF(D2:D11,\\\"Yes\\\")+COUNTIF(D2:D11,\\\"No\\\")\", H3: \"=COUNTIF(D2:D11,\\\"Yes\\\")/H2\",\n            H4: \"=COUNTIFS(B2:B11,\\\"Camp\\\",D2:D11,\\\"Yes\\\")/(COUNTIFS(B2:B11,\\\"Camp\\\",D2:D11,\\\"Yes\\\")+COUNTIFS(B2:B11,\\\"Camp\\\",D2:D11,\\\"No\\\"))\",\n            H5: \"=COUNTIFS(C2:C11,\\\"Yes\\\",D2:D11,\\\"Yes\\\")/(COUNTIFS(C2:C11,\\\"Yes\\\",D2:D11,\\\"Yes\\\")+COUNTIFS(C2:C11,\\\"Yes\\\",D2:D11,\\\"No\\\"))\",\n            H6: \"=AVERAGEIFS(E2:E11,B2:B11,\\\"Camp\\\",D2:D11,\\\"Yes\\\")\", H7: \"=COUNTIF(E2:E11,\\\">30\\\")\" } },\n        { type: \"h\", text: \"Exercise 4: Livelihoods income survey\" },\n        { type: \"sheet\", id: \"meal-pr-m5-income\", level: \"expert\", title: \"Clean first, then calculate\",\n          task: \"Endline survey of a fictional livelihoods project in the North region. A record is valid only if it is the first occurrence of its ID, household size is not 99 (don't know), and monthly income is at most 1 000 000 FCFA. In **F2:F11** write `Yes` or `No` for valid, then fill **H2:H6** using valid records only.\",\n          data: [[\"ID\", \"Sex of head\", \"Location\", \"HH size\", \"Income (FCFA)\", \"Valid\", \"Measure\", \"Result\"],\n            [\"L01\", \"F\", \"Garoua\", 5, 60000, null, \"Valid households\", null],\n            [\"L02\", \"M\", \"Garoua\", 7, 95000, null, \"% headed by women\", null],\n            [\"L03\", \"F\", \"Guider\", 4, 45000, null, \"Average income, women-headed\", null],\n            [\"L04\", \"M\", \"Guider\", 6, 120000, null, \"Average income, men-headed\", null],\n            [\"L04\", \"M\", \"Guider\", 6, 120000, null, \"% in Garoua below 60 000 FCFA\", null],\n            [\"L06\", \"F\", \"Garoua\", 99, 70000, null],\n            [\"L07\", \"M\", \"Guider\", 8, 4500000, null],\n            [\"L08\", \"F\", \"Guider\", 3, 38000, null],\n            [\"L09\", \"M\", \"Garoua\", 5, 80000, null],\n            [\"L10\", \"F\", \"Garoua\", 6, 52000, null]],\n          editable: [\"F2\", \"F3\", \"F4\", \"F5\", \"F6\", \"F7\", \"F8\", \"F9\", \"F10\", \"F11\", \"H2\", \"H3\", \"H4\", \"H5\", \"H6\"],\n          checks: [{ cell: \"F2\", equals: \"Yes\" }, { cell: \"F3\", equals: \"Yes\" }, { cell: \"F4\", equals: \"Yes\" }, { cell: \"F5\", equals: \"Yes\" }, { cell: \"F6\", equals: \"No\" }, { cell: \"F7\", equals: \"No\" }, { cell: \"F8\", equals: \"No\" }, { cell: \"F9\", equals: \"Yes\" }, { cell: \"F10\", equals: \"Yes\" }, { cell: \"F11\", equals: \"Yes\" },\n            { cell: \"H2\", equals: 7 }, { cell: \"H3\", equals: 0.5714, tol: 0.001 }, { cell: \"H4\", equals: 48750, tol: 0.5 }, { cell: \"H5\", equals: 98333.33, tol: 0.5 }, { cell: \"H6\", equals: 0.25, tol: 0.001 }],\n          hint: \"F2: =IF(AND(COUNTIF($A$2:A2,A2)=1,D2<>99,E2<=1000000),\\\"Yes\\\",\\\"No\\\"). The growing range $A$2:A2 counts an ID only up to the current row, so the first copy is kept and the second flagged. Then add F2:F11,\\\"Yes\\\" as a condition in every COUNTIFS and AVERAGEIFS.\",\n          solution: { F2: \"=IF(AND(COUNTIF($A$2:A2,A2)=1,D2<>99,E2<=1000000),\\\"Yes\\\",\\\"No\\\")\", F3: \"=IF(AND(COUNTIF($A$2:A3,A3)=1,D3<>99,E3<=1000000),\\\"Yes\\\",\\\"No\\\")\", F4: \"=IF(AND(COUNTIF($A$2:A4,A4)=1,D4<>99,E4<=1000000),\\\"Yes\\\",\\\"No\\\")\", F5: \"=IF(AND(COUNTIF($A$2:A5,A5)=1,D5<>99,E5<=1000000),\\\"Yes\\\",\\\"No\\\")\", F6: \"=IF(AND(COUNTIF($A$2:A6,A6)=1,D6<>99,E6<=1000000),\\\"Yes\\\",\\\"No\\\")\", F7: \"=IF(AND(COUNTIF($A$2:A7,A7)=1,D7<>99,E7<=1000000),\\\"Yes\\\",\\\"No\\\")\", F8: \"=IF(AND(COUNTIF($A$2:A8,A8)=1,D8<>99,E8<=1000000),\\\"Yes\\\",\\\"No\\\")\", F9: \"=IF(AND(COUNTIF($A$2:A9,A9)=1,D9<>99,E9<=1000000),\\\"Yes\\\",\\\"No\\\")\", F10: \"=IF(AND(COUNTIF($A$2:A10,A10)=1,D10<>99,E10<=1000000),\\\"Yes\\\",\\\"No\\\")\", F11: \"=IF(AND(COUNTIF($A$2:A11,A11)=1,D11<>99,E11<=1000000),\\\"Yes\\\",\\\"No\\\")\",\n            H2: \"=COUNTIF(F2:F11,\\\"Yes\\\")\", H3: \"=COUNTIFS(B2:B11,\\\"F\\\",F2:F11,\\\"Yes\\\")/H2\", H4: \"=AVERAGEIFS(E2:E11,B2:B11,\\\"F\\\",F2:F11,\\\"Yes\\\")\", H5: \"=AVERAGEIFS(E2:E11,B2:B11,\\\"M\\\",F2:F11,\\\"Yes\\\")\",\n            H6: \"=COUNTIFS(C2:C11,\\\"Garoua\\\",E2:E11,\\\"<60000\\\",F2:F11,\\\"Yes\\\")/COUNTIFS(C2:C11,\\\"Garoua\\\",F2:F11,\\\"Yes\\\")\" } },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"meal-m5-quiz\",\n    title: \"Module 5 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"What is the first rule of data cleaning?\", options: [\"Delete every incomplete record\", \"Never overwrite the raw data; work on a copy and log every change\", \"Replace missing values with the mean\", \"Clean only the variables the donor asks for\"], answer: 1, explain: \"Keeping the raw file untouched and logging each change means every correction can be checked and undone.\" },\n      { id: \"q2\", question: \"In a survey, 99 means \\\"refused\\\" in the age variable. What must you do before calculating the mean age?\", options: [\"Nothing, 99 is a plausible age\", \"Replace 99 with 0\", \"Declare 99 as missing so it is excluded from the mean\", \"Delete the respondents who refused\"], answer: 2, explain: \"Special codes are not real values. Left in, they pull the mean up; declared as missing, they are excluded but the rest of the record is kept.\" },\n      { id: \"q3\", question: \"In Stata, why can count if age > 120 give a wrong result?\", options: [\"Because count only works with strings\", \"Because age must be written in capitals\", \"Because Stata rounds ages\", \"Because missing values are treated as larger than any number and are counted too\"], answer: 3, explain: \"Add & !missing(age) to exclude missing values from the count.\" },\n      { id: \"q4\", question: \"Out of 250 respondents, 20 did not answer and 138 said yes. What is the indicator value?\", options: [\"60% (138 ÷ 230)\", \"55.2% (138 ÷ 250)\", \"92% (230 ÷ 250)\", \"138%\"], answer: 0, explain: \"Missing answers are excluded from the denominator: 138 ÷ 230 = 60%, reported with n = 230.\" },\n      { id: \"q5\", question: \"Which Excel formula gives the percentage of women (F in column B) who answered Yes in column E?\", options: [\"=COUNTIF(E2:E101,\\\"Yes\\\")/COUNTIF(B2:B101,\\\"F\\\")\", \"=COUNTIFS(B2:B101,\\\"F\\\",E2:E101,\\\"Yes\\\")/COUNTIF(B2:B101,\\\"F\\\")\", \"=AVERAGEIFS(E2:E101,B2:B101,\\\"F\\\")\", \"=COUNTIFS(B2:B101,\\\"F\\\",E2:E101,\\\"Yes\\\")/COUNTA(B2:B101)\"], answer: 1, explain: \"The numerator counts women who said yes; the denominator counts all women. The other options mix groups or average text.\" },\n      { id: \"q6\", question: \"Household incomes have a mean of 145 000 FCFA and a median of 62 000 FCFA. What is the best typical value to report?\", options: [\"The mean, because it uses all values\", \"The maximum\", \"The median, because a few very high incomes pull the mean up\", \"The average of the mean and the median\"], answer: 2, explain: \"A mean far above the median shows a skewed distribution. The median describes the typical household better.\" },\n      { id: \"q7\", question: \"A cross-tab gives a chi-square p-value of 0.02. What does this mean?\", options: [\"A difference this large would be unlikely if the groups did not differ in the population\", \"One variable causes the other\", \"The difference between the groups is large and important\", \"2% of respondents are in the table\"], answer: 0, explain: \"p < 0.05 means chance alone is an unlikely explanation. It does not measure size or importance, and it does not show cause.\" },\n      { id: \"q8\", question: \"In qualitative analysis, what is an inductive code?\", options: [\"A code taken from the indicator framework before reading\", \"A code that counts the number of participants\", \"A code used only in Stata\", \"A code that emerges from the data, for a theme the team did not anticipate\"], answer: 3, explain: \"Deductive codes come from your questions or framework; inductive codes come from what participants actually said.\" },\n    ],\n  },\n};\n","client/src/data/courses/meal/m6.ts":"import type { CourseModule } from \"../../../lms/types\";\n\n// MEAL Professional Certificate — Module 6: Reporting, Accountability and Learning.\n// Original Analytix Engineering material. All projects, organisations, people and figures are fictional.\n\nconst KOBO = \"KoboToolbox Support\";\nconst OECD = \"OECD\";\nconst CHS = \"CHS Alliance\";\n\nconst INTRO = \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\";\n\nconst FCM = [\n  \"Non-sensitive: the programme team responds\",\n  \"Sensitive: refer to the safeguarding / PSEA focal point\",\n  \"Sensitive: refer to the fraud and compliance focal point\",\n];\nconst DAC = [\"Relevance\", \"Coherence\", \"Effectiveness\", \"Efficiency\", \"Impact\", \"Sustainability\"];\n\nexport const m6: CourseModule = {\n  id: \"meal-m6\",\n  number: 6,\n  title: \"Reporting, Accountability and Learning\",\n  summary: \"Indicator tracking, dashboards, donor reports and briefs, feedback and complaints mechanisms, evaluation and adaptive management.\",\n  hours: 20,\n  lessons: [\n    // ─────────────────────────── LESSON 1 ───────────────────────────\n    {\n      id: \"meal-m6-l1\",\n      title: \"Indicator tracking tables and dashboards\",\n      minutes: 22,\n      objectives: [\n        \"Build an indicator tracking table with cumulative actuals, % of target and a status\",\n        \"Design a simple dashboard with a few KPIs, a trend chart and a map\",\n        \"Choose between Excel, Power BI and KoboToolbox reports for a given need\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Data collected every month is only useful if someone can see, at a glance, whether the project is where it should be. The **indicator tracking table (ITT)** answers that question for every indicator in the logframe, and a dashboard shows the few numbers that managers watch most closely.\" },\n        { type: \"h\", text: \"What goes into an ITT\" },\n        { type: \"table\", head: [\"Column\", \"What it holds\", \"Common mistake\"], rows: [\n          [\"Indicator\", \"The exact wording from the logframe and the indicator reference sheet\", \"Rewording the indicator, so it no longer matches the donor's version\"],\n          [\"Baseline\", \"The value before the project started\", \"Leaving it empty, so progress cannot be judged\"],\n          [\"Target\", \"The value to reach, for the year or for the whole project\", \"Mixing annual and life-of-project targets in one column\"],\n          [\"Actuals by quarter\", \"What was achieved in each quarter (Q1, Q2, Q3, Q4)\", \"Typing a cumulative figure in a quarterly column\"],\n          [\"Cumulative\", \"Total achieved so far, or the latest value for a rate\", \"Adding up percentages from several quarters\"],\n          [\"% achieved\", \"Cumulative divided by target\", \"Dividing by the quarterly target instead of the annual one\"],\n          [\"Status\", \"On track, behind, or at risk, often shown as a traffic light\", \"Choosing the colour by feeling instead of a written rule\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Counts add up, rates do not\", text: \"Latrines built or people trained can be summed across quarters. A rate such as the percentage of functional water points cannot: report the latest measured value, or recalculate it from the underlying numbers.\" },\n        { type: \"h\", text: \"Setting the status rule\" },\n        { type: \"p\", text: \"Write the rule down before the first report, so nobody argues about colours later. A simple rule compares % achieved with the share of the year that has passed: after three quarters, an indicator at 75% of its annual target or more is on track.\" },\n        { type: \"code\", text: \"Cumulative    =SUM(C2:E2)\\n% achieved    =F2/B2\\nStatus        =IF(G2>=0.75,\\\"On track\\\",\\\"Behind\\\")\" },\n        { type: \"sheet\", id: \"meal-m6-l1-sheet\", title: \"Complete a WASH indicator tracking table\",\n          task: \"The Eau Saine Est project (East region) has reported three quarters. Fill **F2:F5** with the cumulative actuals, **G2:G5** with the % of the annual target achieved, and **H2:H5** with \\\"On track\\\" if at least 75% of the target is reached, otherwise \\\"Behind\\\".\",\n          data: [\n            [\"Indicator\", \"Annual target\", \"Q1\", \"Q2\", \"Q3\", \"Cumulative\", \"% achieved\", \"Status\"],\n            [\"Latrines built\", 400, 80, 120, 110, null, null, null],\n            [\"Households reached by hygiene sessions\", 2000, 350, 400, 380, null, null, null],\n            [\"Water points rehabilitated\", 24, 6, 8, 5, null, null, null],\n            [\"Water committee members trained\", 24, 4, 5, 3, null, null, null],\n          ],\n          editable: [\"F2\", \"F3\", \"F4\", \"F5\", \"G2\", \"G3\", \"G4\", \"G5\", \"H2\", \"H3\", \"H4\", \"H5\"],\n          checks: [\n            { cell: \"F2\", equals: 310 }, { cell: \"F3\", equals: 1130 }, { cell: \"F4\", equals: 19 }, { cell: \"F5\", equals: 12 },\n            { cell: \"G2\", equals: 0.775, tol: 0.001 }, { cell: \"G3\", equals: 0.565, tol: 0.001 }, { cell: \"G4\", equals: 0.7917, tol: 0.001 }, { cell: \"G5\", equals: 0.5, tol: 0.001 },\n            { cell: \"H2\", equals: \"On track\" }, { cell: \"H3\", equals: \"Behind\" }, { cell: \"H4\", equals: \"On track\" }, { cell: \"H5\", equals: \"Behind\" },\n          ],\n          hint: \"F2 is =SUM(C2:E2). G2 divides the cumulative by the annual target: =F2/B2. H2 is =IF(G2>=0.75,\\\"On track\\\",\\\"Behind\\\"). Copy each formula down.\",\n          solution: {\n            F2: \"=SUM(C2:E2)\", F3: \"=SUM(C3:E3)\", F4: \"=SUM(C4:E4)\", F5: \"=SUM(C5:E5)\",\n            G2: \"=F2/B2\", G3: \"=F3/B3\", G4: \"=F4/B4\", G5: \"=F5/B5\",\n            H2: \"=IF(G2>=0.75,\\\"On track\\\",\\\"Behind\\\")\", H3: \"=IF(G3>=0.75,\\\"On track\\\",\\\"Behind\\\")\", H4: \"=IF(G4>=0.75,\\\"On track\\\",\\\"Behind\\\")\", H5: \"=IF(G5>=0.75,\\\"On track\\\",\\\"Behind\\\")\",\n          } },\n        { type: \"h\", text: \"Traffic lights in Excel\" },\n        { type: \"path\", items: [\"Home\", \"Styles\", \"Conditional Formatting\", \"Icon Sets\"], note: \"Or use Highlight Cells Rules › Text that Contains to colour \\\"Behind\\\" in red.\" },\n        { type: \"steps\", title: \"Colour the status column\", items: [\n          \"Select the status cells, for example H2:H30.\",\n          \"Open Conditional Formatting and choose Highlight Cells Rules › Text that Contains.\",\n          \"Type Behind and choose a red fill; add a second rule for On track with a green fill.\",\n          \"Add a short legend under the table that states the rule, for example \\\"On track = 75% or more after Q3\\\".\",\n        ] },\n        { type: \"h\", text: \"A dashboard people actually read\" },\n        { type: \"list\", items: [\n          \"**Few KPIs**: four to six headline numbers at the top, each with its target.\",\n          \"**One trend chart**: a line showing a key indicator month by month.\",\n          \"**One map or breakdown**: results by health area, commune or site, so managers see where to act.\",\n          \"**Date and source** on every page, so readers know how fresh the data is.\",\n        ] },\n        { type: \"chart\", id: \"meal-m6-l1-chart\", title: \"Children screened for malnutrition, January to June 2026\", unit: \"children\",\n          data: [{ label: \"Jan\", value: 1240 }, { label: \"Feb\", value: 1310 }, { label: \"Mar\", value: 1180 }, { label: \"Apr\", value: 960 }, { label: \"May\", value: 1420 }, { label: \"Jun\", value: 1515 }],\n          kinds: [\"bar\", \"line\", \"pie\"], best: \"line\",\n          question: \"The nutrition dashboard must show the district team whether screening is recovering after the April drop. Which chart fits the trend panel?\",\n          explain: \"A line joins the months in order, so the April dip and the recovery in May and June are visible at once. A pie would treat the months as shares of a whole and hide the time order.\" },\n        { type: \"h\", text: \"Which tool for which job\" },\n        { type: \"table\", head: [\"Tool\", \"Good for\", \"Limits\"], rows: [\n          [\"Excel\", \"ITTs, small dashboards, work offline, easy to share\", \"Manual updates; version confusion when copies circulate by e-mail\"],\n          [\"Power BI\", \"Dashboards that refresh from several data sources, filters by region or period\", \"Needs training and a licence to publish and share online\"],\n          [\"KoboToolbox reports\", \"Quick charts of each question while data is coming in\", \"Basic analysis only; no ITT logic or targets\"],\n        ] },\n        { type: \"path\", items: [\"DATA\", \"Reports\"], note: \"In KoboToolbox, open the project first. Reports shows a chart and a frequency table for each question.\" },\n        { type: \"path\", items: [\"Home\", \"Get data\", \"Excel workbook\"], note: \"In Power BI Desktop, this connects a dashboard to your ITT workbook.\" },\n        { type: \"check\", id: \"meal-m6-l1-c1\", question: \"An indicator is \\\"% of health facilities with no stock-out of RUTF\\\". The quarterly values are 60%, 70% and 80%. What should the cumulative column show after Q3?\", options: [\"210%\", \"70%, the average\", \"80%, the latest value\", \"It must stay empty until Q4\"], answer: 2, explain: \"Rates cannot be added across quarters. Report the latest measured value (or recalculate from the facility counts), and compare it with the target rate.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"In a health district of the Far North, the MEAL officer sends one ITT file to the donor and another to the district team, each updated by hand. By the third quarter the figures no longer match. Keep one master ITT on a shared drive, lock the formula cells and export copies as PDF for readers.\" },\n        { type: \"task\", id: \"meal-m6-l1-t1\", title: \"Practice\", items: [\n          \"Take one logframe from your organisation and list its indicators in an ITT with baseline, target and four quarterly columns\",\n          \"Mark each indicator as a count (summed) or a rate (latest value)\",\n          \"Add the cumulative, % achieved and status formulas and write the status rule under the table\",\n          \"Apply red and green conditional formatting to the status column\",\n          \"Sketch a one-page dashboard with four KPIs, one trend chart and one breakdown by site\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Visualizing your data with reports\", url: \"https://support.kobotoolbox.org/creating_custom_reports.html\", source: KOBO },\n        ] },\n      ],\n    },\n    // ─────────────────────────── LESSON 2 ───────────────────────────\n    {\n      id: \"meal-m6-l2\",\n      title: \"Donor reports and one-page briefs\",\n      minutes: 22,\n      objectives: [\n        \"Structure a progress report around indicators, challenges, lessons and next steps\",\n        \"Write findings that state the result, the comparison and the reason\",\n        \"Produce a one-page brief and a results slide for decision-makers\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"A donor report is where your monitoring work becomes visible. Donors read many reports, so a clear, honest and well-structured one builds trust and makes the next funding conversation easier. Decision-makers read even less: for them, a one-page brief is often all they will see.\" },\n        { type: \"h\", text: \"The structure of a progress report\" },\n        { type: \"table\", head: [\"Section\", \"What to write\", \"Typical length\"], rows: [\n          [\"Executive summary\", \"The three to five most important results and any major issue\", \"Half a page\"],\n          [\"Progress against indicators\", \"The ITT, then a short comment on each indicator that is off track\", \"One to three pages plus the ITT\"],\n          [\"Activities implemented\", \"What was done, where and for whom, with disaggregation\", \"One to two pages\"],\n          [\"Challenges and mitigation\", \"What went wrong, its effect, and what you did about it\", \"Half a page\"],\n          [\"Lessons learned\", \"What you now know that you did not know before, and how it changes your work\", \"Half a page\"],\n          [\"Next steps\", \"Main activities of the next period, with dates\", \"A short list\"],\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Always use the donor's template\", text: \"Most donors impose their own template and word limits. Read the reporting section of the grant agreement at the start of the project, and prepare your ITT so it matches the donor's indicator list exactly.\" },\n        { type: \"h\", text: \"Writing findings clearly\" },\n        { type: \"p\", text: \"A good finding contains three things: the result, a comparison (with the target, the baseline or the last period) and, when you know it, the reason.\" },\n        { type: \"table\", head: [\"Weak\", \"Clear\"], rows: [\n          [\"Many activities were carried out in the schools.\", \"Hot meals were served in 18 of the 20 planned schools (90%) during the quarter.\"],\n          [\"Attendance improved a lot.\", \"Average attendance rose from 71% at baseline to 86%, above the 80% target.\"],\n          [\"There were some difficulties with suppliers.\", \"Two deliveries arrived three weeks late because the road to Mokolo was cut; schools used their reserve stock.\"],\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Report bad news early\", text: \"An indicator that is behind is not a failure of the report. Explain why, what you are doing about it and whether the target should be revised. Donors react far worse to a surprise at the end of the project than to an honest explanation in the second quarter.\" },\n        { type: \"h\", text: \"The one-page brief\" },\n        { type: \"steps\", title: \"Build a one-page brief\", items: [\n          \"Write a title that states the main finding, not only the topic.\",\n          \"Put the key figure near the top, in bold, with its comparison.\",\n          \"Explain in two or three sentences why it matters for the reader.\",\n          \"End with three recommendations, each starting with a verb.\",\n          \"Add one simple chart, the data source and the date.\",\n        ] },\n        { type: \"path\", items: [\"Home\", \"Styles\", \"Heading 1\"], note: \"In Word, use heading styles for the title and section names instead of making text larger by hand.\" },\n        { type: \"doc\", id: \"meal-m6-l2-doc\", title: \"Format a one-page brief\",\n          task: \"Make the title a **Heading 1**, make \\\"Key finding\\\" and \\\"Recommendations\\\" **Heading 2**, make the figure \\\"from 71% to 86%\\\" **bold**, and turn the three recommendations into a **bulleted list**.\",\n          hint: \"Click in a line and choose the style in the Styles menu. Select only the figure before clicking Bold. Select the three recommendation lines together before clicking Bullets.\",\n          html: \"<p>Brief: School feeding in Mayo-Tsanaga, second quarter 2026</p><p>Prepared by the MEAL unit for the regional delegation of basic education, July 2026.</p><p>Key finding</p><p>Average attendance in the 18 supported schools rose from 71% to 86% since hot meals started in January.</p><p>The rise is largest for girls in the last two years of primary school. Head teachers link it to the meal and to the new latrines.</p><p>Recommendations</p><p>Extend the programme to the 6 schools on the waiting list before the lean season</p><p>Buy cereals from local producer groups to cut transport costs</p><p>Keep the monthly attendance check by the school management committees</p>\",\n          checks: [\n            { kind: \"heading\", level: 1, text: \"Brief: School feeding\" },\n            { kind: \"heading\", level: 2, text: \"Key finding\" },\n            { kind: \"heading\", level: 2, text: \"Recommendations\" },\n            { kind: \"bold\", text: \"from 71% to 86%\" },\n            { kind: \"list\", ordered: false, min: 3 },\n          ] },\n        { type: \"h\", text: \"Visuals that support the message\" },\n        { type: \"list\", items: [\n          \"One message per chart, stated in the chart title.\",\n          \"Bars to compare sites or groups, a line for change over time.\",\n          \"Show the target as a line or a label so readers can judge the result.\",\n          \"Photos only with informed consent, and never of children in a way that exposes them.\",\n        ] },\n        { type: \"slide\", id: \"meal-m6-l2-slide\", title: \"Tighten a results slide\",\n          task: \"This slide will be shown at the quarterly review with the health district team in Kousseri. Rewrite it with a title that **states the result** in 10 words or fewer and **no more than 4 bullets** of 10 words or fewer.\",\n          hint: \"Put the conclusion in the title, for example \\\"Screening back on track after the April drop\\\". Keep one idea per bullet and move the details to the report.\",\n          slide: { title: \"Presentation of the results of the nutrition project in the health district for the second quarter of the year 2026\", bullets: [\n            \"A total of 4 890 children aged 6 to 59 months were screened by community health workers, which is 98% of the quarterly target\",\n            \"In April screening dropped because many community health workers were mobilised for the polio vaccination campaign\",\n            \"The number of children admitted for severe acute malnutrition was 312, of whom 58% were girls\",\n            \"The cure rate in the outpatient programme reached 81%, which is above the 75% standard\",\n            \"There were two stock-outs of therapeutic food in the Makary health area in May\",\n            \"The team recommends pre-positioning stock before the rainy season begins\",\n          ] },\n          rules: { maxBullets: 4, maxWords: 10, titleMaxWords: 10 } },\n        { type: \"check\", id: \"meal-m6-l2-c1\", question: \"Which sentence is the best finding for a donor report?\", options: [\"The project did very well this quarter.\", \"Many women took part in the savings groups.\", \"1 140 women joined savings groups, 95% of the annual target, mainly in Maroua and Mokolo.\", \"Savings groups are an important activity for women's empowerment.\"], answer: 2, explain: \"It gives the result, compares it with the target and says where. The other sentences give no figure or no comparison, so the reader cannot judge progress.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A bilingual team in Bamenda writes its report in English for the donor, but the regional delegation reads French. Prepare the one-page brief in both languages from the same figures, and have a second person check that every number is identical in the two versions.\" },\n        { type: \"task\", id: \"meal-m6-l2-t1\", title: \"Practice\", items: [\n          \"Find the reporting template and deadlines in one of your current grant agreements\",\n          \"Rewrite three weak sentences from an old report so each gives a result, a comparison and a reason\",\n          \"Write a challenge paragraph that states the problem, its effect and your mitigation\",\n          \"Draft a one-page brief with a finding title, a bold key figure and three recommendations\",\n          \"Replace one crowded results slide with a title that states the result and four short bullets\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Visualizing your data with reports\", url: \"https://support.kobotoolbox.org/creating_custom_reports.html\", source: KOBO },\n        ] },\n      ],\n    },\n    // ─────────────────────────── LESSON 3 ───────────────────────────\n    {\n      id: \"meal-m6-l3\",\n      title: \"Feedback and complaints mechanisms\",\n      minutes: 24,\n      objectives: [\n        \"Choose feedback channels that suit the community and the context\",\n        \"Separate sensitive from non-sensitive complaints and refer them correctly\",\n        \"Log, answer and analyse feedback so that the loop is closed\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Accountability to affected people means that the people a project serves can influence it, question it and complain about it safely. A **feedback and complaints mechanism** is the practical system that makes this possible: channels to speak, a team that answers, and a log that turns individual messages into lessons.\" },\n        { type: \"h\", text: \"Choosing channels\" },\n        { type: \"table\", head: [\"Channel\", \"Strengths\", \"Watch out for\"], rows: [\n          [\"Free hotline\", \"Fast, confidential, works in several languages\", \"Needs network coverage and staff to answer; many women may not own a phone\"],\n          [\"Suggestion boxes\", \"Anonymous, no phone needed\", \"Excludes people who cannot write; boxes must be opened on a fixed schedule by two people\"],\n          [\"Community committees\", \"Trusted, reach people who do not use phones\", \"Members may filter out complaints about themselves or local leaders\"],\n          [\"WhatsApp or SMS number\", \"Cheap, allows voice notes and photos\", \"Messages stay on personal phones; set rules on who reads them and how data is protected\"],\n          [\"Help desks at distributions\", \"Immediate answers on registration and entitlements\", \"Crowds make it hard to speak privately\"],\n        ] },\n        { type: \"p\", text: \"Ask the community which channels they prefer during the design phase, and offer at least two different ones so that people without a phone, who cannot read or who fear being seen can still speak.\" },\n        { type: \"h\", text: \"Sensitive and non-sensitive complaints\" },\n        { type: \"table\", head: [\"Type\", \"Examples\", \"Who handles it\"], rows: [\n          [\"Non-sensitive\", \"Requests for information, broken water point, missing name on a list, quality of items\", \"The programme team, with a standard response time\"],\n          [\"Sensitive: safeguarding and PSEA\", \"Sexual exploitation or abuse, harassment, abuse of a child by staff, volunteers or partners\", \"The safeguarding / PSEA focal point only, within 24 hours\"],\n          [\"Sensitive: fraud and misconduct\", \"Theft, bribes to be registered, diversion of aid\", \"The compliance or fraud focal point, often at country office level\"],\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Never investigate a sensitive complaint yourself\", text: \"Your role is to receive the complaint respectfully, record only the essential facts, ensure the person's safety and refer immediately and confidentially. Do not question the alleged perpetrator, do not look for witnesses and do not share names with colleagues.\" },\n        { type: \"form\", id: \"meal-m6-l3-form\", title: \"Classify the complaints\",\n          task: \"A food security project in Garoua-Boulaï received these messages this week. Choose how each one must be handled.\",\n          hint: \"Ask two questions: could the person or someone else be harmed (abuse, exploitation), and does it involve theft, bribes or diversion? If neither, the programme team responds.\",\n          fields: [\n            { kind: \"select\", label: \"\\\"The water point near the market has been broken for two weeks.\\\"\", options: FCM, answer: 0, explain: \"An operational problem: log it, pass it to the WASH team and tell the community when it will be repaired.\" },\n            { kind: \"select\", label: \"\\\"A volunteer who distributes vouchers asked my daughter to meet him at night for an extra ration.\\\"\", options: FCM, answer: 1, explain: \"A possible case of sexual exploitation of a minor. Refer it at once to the PSEA focal point and ensure the girl's safety; do not investigate.\" },\n            { kind: \"select\", label: \"\\\"My name is not on the distribution list although I was registered in March.\\\"\", options: FCM, answer: 0, explain: \"A registration issue the programme team can check against the database.\" },\n            { kind: \"select\", label: \"\\\"The warehouse keeper sells bags of rice at the market on Saturdays.\\\"\", options: FCM, answer: 2, explain: \"Possible diversion of aid. It goes to the fraud and compliance focal point, not to the warehouse manager.\" },\n            { kind: \"select\", label: \"\\\"A teacher paid by the project beats the pupils with a stick.\\\"\", options: FCM, answer: 1, explain: \"Physical abuse of children by someone linked to the project is a safeguarding case.\" },\n            { kind: \"select\", label: \"\\\"Why do the hygiene kits no longer contain soap?\\\"\", options: FCM, answer: 0, explain: \"A question about the content of kits: answer it and check whether the specification changed.\" },\n          ] },\n        { type: \"h\", text: \"Response times and closing the loop\" },\n        { type: \"steps\", title: \"From message to closed case\", items: [\n          \"Acknowledge receipt, ideally within 48 hours, and give the case number.\",\n          \"Log the case the same day: date, channel, type, location, sex and age group, sensitive or not.\",\n          \"Refer sensitive cases immediately; assign others to the responsible team.\",\n          \"Answer the person within the standard time, for example 7 days, even if the answer is \\\"not possible\\\".\",\n          \"Close the case in the log and record whether the person was satisfied with the answer.\",\n          \"Share what changed with the whole community, for example at a committee meeting.\",\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Closing the loop\", text: \"A mechanism that receives messages but never answers destroys trust faster than having no mechanism at all. Tell people what happened, including when their request could not be met.\" },\n        { type: \"h\", text: \"Analysing the feedback log\" },\n        { type: \"path\", items: [\"Insert\", \"Tables\", \"PivotTable\"], note: \"Useful for counting cases by channel, type or site when the log has hundreds of rows.\" },\n        { type: \"sheet\", id: \"meal-m6-l3-sheet\", title: \"Analyse a feedback log\",\n          task: \"The standard response time is **7 days**. Fill **H2** with the number of hotline cases, **H3** with the complaints received by hotline, **H4** with the number of closed cases and **H5** with the share of all cases closed within 7 days.\",\n          data: [\n            [\"Case\", \"Channel\", \"Type\", \"Status\", \"Days to close\", null, \"Measure\", \"Result\"],\n            [\"FB-01\", \"Hotline\", \"Information request\", \"Closed\", 2, null, \"Hotline cases\", null],\n            [\"FB-02\", \"Box\", \"Complaint\", \"Closed\", 9, null, \"Hotline complaints\", null],\n            [\"FB-03\", \"WhatsApp\", \"Information request\", \"Closed\", 1, null, \"Closed cases\", null],\n            [\"FB-04\", \"Hotline\", \"Complaint\", \"Open\", null, null, \"% closed within 7 days\", null],\n            [\"FB-05\", \"Committee\", \"Suggestion\", \"Closed\", 5],\n            [\"FB-06\", \"Hotline\", \"Complaint\", \"Closed\", 6],\n            [\"FB-07\", \"Box\", \"Suggestion\", \"Open\", null],\n            [\"FB-08\", \"WhatsApp\", \"Complaint\", \"Closed\", 12],\n            [\"FB-09\", \"Hotline\", \"Information request\", \"Closed\", 3],\n          ],\n          editable: [\"H2\", \"H3\", \"H4\", \"H5\"],\n          checks: [{ cell: \"H2\", equals: 4 }, { cell: \"H3\", equals: 2 }, { cell: \"H4\", equals: 7 }, { cell: \"H5\", equals: 0.5556, tol: 0.001 }],\n          hint: \"H2 is a COUNTIF on the channel column. H3 needs two conditions: =COUNTIFS(B2:B10,\\\"Hotline\\\",C2:C10,\\\"Complaint\\\"). For H5, count cases that are Closed and have \\\"<=7\\\" days, then divide by all cases with COUNTA(A2:A10).\",\n          solution: { H2: \"=COUNTIF(B2:B10,\\\"Hotline\\\")\", H3: \"=COUNTIFS(B2:B10,\\\"Hotline\\\",C2:C10,\\\"Complaint\\\")\", H4: \"=COUNTIF(D2:D10,\\\"Closed\\\")\", H5: \"=COUNTIFS(D2:D10,\\\"Closed\\\",E2:E10,\\\"<=7\\\")/COUNTA(A2:A10)\" } },\n        { type: \"p\", text: \"Look beyond the counts: which sites send no feedback at all, which topics come back every month, and whether women and people with disabilities use the channels. Silence from a group is a finding too.\" },\n        { type: \"check\", id: \"meal-m6-l3-c1\", question: \"During a monitoring visit, a woman tells you privately that a partner staff member asked her for money to put her on the cash transfer list. What do you do?\", options: [\"Ask the staff member for his version of the story\", \"Record the essential facts, reassure her and refer the case to the fraud and compliance focal point\", \"Wait to see if other people make the same complaint\", \"Tell her to use the suggestion box\"], answer: 1, explain: \"A bribe for registration is a sensitive complaint. Record only what is needed, protect her identity and refer it the same day. Investigating yourself could put her at risk and damage the case.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"In an IDP site near Mora, the complaints box was opened only when the project officer visited, about once a month, and people stopped using it. The team switched to a weekly opening by two people, a free hotline in Fulfulde and French, and a monthly \\\"you said, we did\\\" board at the distribution point. Feedback tripled in two months.\" },\n        { type: \"task\", id: \"meal-m6-l3-t1\", title: \"Practice\", items: [\n          \"List the feedback channels your project offers and who in the community cannot use each one\",\n          \"Write down the name and contact of your organisation's safeguarding / PSEA focal point\",\n          \"Set up a feedback log with columns for date, channel, type, sensitivity, status and days to close\",\n          \"Calculate last month's % of cases closed within the response time\",\n          \"Prepare a short \\\"you said, we did\\\" message for the next community meeting\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Core Humanitarian Standard on Quality and Accountability\", url: \"https://www.corehumanitarianstandard.org/\", source: CHS },\n        ] },\n      ],\n    },\n    // ─────────────────────────── LESSON 4 ───────────────────────────\n    {\n      id: \"meal-m6-l4\",\n      title: \"Evaluation, learning and adaptive management\",\n      minutes: 24,\n      objectives: [\n        \"Distinguish baseline, midterm, final and real-time evaluations\",\n        \"Match evaluation questions to the six OECD-DAC criteria\",\n        \"Run a pause-and-reflect session and turn learning into project adaptations\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Monitoring tells you what is happening; evaluation asks whether it is the right thing, done well, and whether it lasts. Learning closes the circle: the team uses both to change what it does. This last lesson connects the three.\" },\n        { type: \"h\", text: \"Types of evaluation\" },\n        { type: \"table\", head: [\"Type\", \"When\", \"Main purpose\"], rows: [\n          [\"Baseline study\", \"Before or at the very start of activities\", \"Measure starting values and set realistic targets\"],\n          [\"Midterm evaluation\", \"Around the middle of the project\", \"Check progress and correct the course while there is time\"],\n          [\"Final evaluation\", \"At or after the end\", \"Judge results, accountability to donors, lessons for future projects\"],\n          [\"Real-time evaluation\", \"In the first weeks or months of an emergency response\", \"Give rapid feedback to managers while decisions are still being made\"],\n        ] },\n        { type: \"p\", text: \"Evaluations can be internal (run by your own MEAL team) or external (run by an independent consultant). External evaluations are more credible to donors; internal ones are cheaper and often more useful for learning.\" },\n        { type: \"h\", text: \"The six OECD-DAC criteria\" },\n        { type: \"table\", head: [\"Criterion\", \"Core question\", \"Example question for a WASH project\"], rows: [\n          [\"Relevance\", \"Is the intervention doing the right things?\", \"Did the choice of water points match what households said they needed most?\"],\n          [\"Coherence\", \"How well does it fit with other interventions?\", \"Did the project work with the commune's water plan and other NGOs in the area?\"],\n          [\"Effectiveness\", \"Is it achieving its objectives?\", \"Did the share of households using safe water reach the 80% target?\"],\n          [\"Efficiency\", \"How well are resources used?\", \"What did each rehabilitated water point cost compared with similar projects?\"],\n          [\"Impact\", \"What difference does it make?\", \"Did diarrhoea cases among children under five fall in the served villages?\"],\n          [\"Sustainability\", \"Will the benefits last?\", \"Are water committees still collecting fees and repairing pumps a year later?\"],\n        ] },\n        { type: \"form\", id: \"meal-m6-l4-form\", title: \"Match questions to OECD-DAC criteria\",\n          task: \"An external team is preparing the final evaluation of a youth employment project in Douala and Yaoundé. Choose the criterion each question belongs to.\",\n          hint: \"Relevance is about needs, coherence about fit with others, effectiveness about objectives, efficiency about resources, impact about wider and longer-term change, sustainability about what continues after funding ends.\",\n          fields: [\n            { kind: \"select\", label: \"Were the trades taught (tailoring, phone repair, welding) those most in demand by local employers?\", options: DAC, answer: 0 },\n            { kind: \"select\", label: \"Did the project duplicate the vocational training offered by the national employment fund?\", options: DAC, answer: 1, explain: \"Fit with other programmes in the same area is coherence.\" },\n            { kind: \"select\", label: \"Did 60% of graduates find paid work within six months, as planned?\", options: DAC, answer: 2 },\n            { kind: \"select\", label: \"Was the cost per graduate reasonable compared with similar programmes?\", options: DAC, answer: 3 },\n            { kind: \"select\", label: \"Has youth income in the target neighbourhoods changed, including for young people who were not trained?\", options: DAC, answer: 4, explain: \"Wider and indirect effects, positive or negative, belong to impact.\" },\n            { kind: \"select\", label: \"Will the training centres keep running the courses after the grant ends?\", options: DAC, answer: 5 },\n            { kind: \"select\", label: \"Three weeks after floods in Douala, the director wants quick feedback on the emergency response while it is still running. Which evaluation is this?\", options: [\"Baseline study\", \"Midterm evaluation\", \"Final evaluation\", \"Real-time evaluation\"], answer: 3, explain: \"A real-time evaluation gives rapid feedback early in an emergency, when decisions can still change.\" },\n          ] },\n        { type: \"h\", text: \"Learning questions and pause-and-reflect\" },\n        { type: \"p\", text: \"Learning questions are the few things the team most needs to understand, written at the start of the project. For example: \\\"Why do some mothers stop attending the nutrition sessions after the second month?\\\" Monitoring data, visits and feedback are then used to answer them.\" },\n        { type: \"steps\", title: \"Run an after-action review in one hour\", items: [\n          \"What did we plan to happen?\",\n          \"What actually happened? Use the ITT, feedback log and field notes.\",\n          \"Why was there a difference?\",\n          \"What will we keep doing, and what will we change? Name a person and a date for each change.\",\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Keep it safe to speak\", text: \"An after-action review is not an inspection. The most senior person should speak last, and the notes should record lessons, not blame.\" },\n        { type: \"h\", text: \"Using data to adapt\" },\n        { type: \"p\", text: \"Adaptive management means changing activities, targets or methods when evidence shows the plan is not working. Record every decision in an action log with the evidence, the change, the owner and the deadline, and inform the donor when a change affects the budget or the logframe.\" },\n        { type: \"path\", items: [\"Data\", \"Sort & Filter\", \"Filter\"], note: \"In Excel, filter the action log by status to see which adaptations are still open.\" },\n        { type: \"check\", id: \"meal-m6-l4-c1\", question: \"Midterm monitoring shows that only 40% of women beneficiaries collect their cash, because the only pay point is 15 km away. What is the best adaptive response?\", options: [\"Keep the plan and explain the gap in the final report\", \"Lower the target to 40%\", \"Add a mobile pay point or mobile money option, record the decision and inform the donor\", \"Remove women from the beneficiary list\"], answer: 2, explain: \"The evidence points to a clear barrier that the project can remove. Changing the delivery method, documenting why and informing the donor is adaptive management.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A livelihoods project in the West region holds a pause-and-reflect session every quarter with field staff, two farmer group leaders and the MEAL officer. In one session, the team learned that trainings clashed with market days; moving them to Tuesdays raised attendance from 55% to 80%.\" },\n        { type: \"task\", id: \"meal-m6-l4-t1\", title: \"Practice\", items: [\n          \"Write two learning questions for a project you know\",\n          \"Draft one evaluation question for each OECD-DAC criterion for that project\",\n          \"Plan a one-hour after-action review with its four questions and a list of participants\",\n          \"Create an action log with columns for evidence, decision, owner, deadline and status\",\n          \"Identify one change in your project that should be reported to the donor\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Evaluation criteria\", url: \"https://www.oecd.org/en/topics/sub-issues/development-co-operation-evaluation-and-effectiveness/evaluation-criteria.html\", source: OECD },\n          { label: \"Applying evaluation criteria thoughtfully\", url: \"https://www.oecd.org/en/publications/applying-evaluation-criteria-thoughtfully_543e84ed-en.html\", source: OECD },\n        ] },\n      ],\n    },\n    // ─────────────────────────── PRACTICE LAB ───────────────────────────\n    {\n      id: \"meal-m6-practice\",\n      title: \"Practice lab: reporting, accountability and learning\",\n      minutes: 35,\n      objectives: [\n        \"Calculate % of target and count indicators that reach a threshold\",\n        \"Format a donor progress report section\",\n        \"Make accountability and adaptation decisions and write the formulas behind them\",\n        \"Build an indicator tracking table that handles missing data and rate indicators\",\n      ],\n      blocks: [\n        { type: \"p\", text: INTRO },\n        { type: \"h\", text: \"Exercise 1: Livelihoods results in Mokolo\" },\n        { type: \"sheet\", id: \"meal-pr-m6-livelihoods\", level: \"beginner\", title: \"Percentage of target achieved\",\n          task: \"Fill **D2:D5** with the % of target achieved for each indicator, then **D6** with the number of indicators that reached at least 90% of their target.\",\n          data: [\n            [\"Indicator\", \"Target\", \"Achieved\", \"% achieved\"],\n            [\"Households receiving seed kits\", 1200, 1140, null],\n            [\"Farmers trained in composting\", 800, 520, null],\n            [\"Village savings groups created\", 40, 44, null],\n            [\"Hectares of market garden irrigated\", 25, 18, null],\n            [null, null, \"Indicators at 90% or more\", null],\n          ],\n          editable: [\"D2\", \"D3\", \"D4\", \"D5\", \"D6\"],\n          checks: [{ cell: \"D2\", equals: 0.95, tol: 0.001 }, { cell: \"D3\", equals: 0.65, tol: 0.001 }, { cell: \"D4\", equals: 1.1, tol: 0.001 }, { cell: \"D5\", equals: 0.72, tol: 0.001 }, { cell: \"D6\", equals: 2 }],\n          hint: \"D2 is =C2/B2; copy it down. D6 counts the cells of D2:D5 that are at least 0.9: =COUNTIF(D2:D5,\\\">=0.9\\\").\",\n          solution: { D2: \"=C2/B2\", D3: \"=C3/B3\", D4: \"=C4/B4\", D5: \"=C5/B5\", D6: \"=COUNTIF(D2:D5,\\\">=0.9\\\")\" } },\n        { type: \"h\", text: \"Exercise 2: A quarterly report for the donor\" },\n        { type: \"doc\", id: \"meal-pr-m6-report\", level: \"intermediate\", title: \"Format a progress report section\",\n          task: \"Make the title a **Heading 1** and **centre** it, **right-align** the reporting period, make \\\"Executive summary\\\", \\\"Challenges\\\" and \\\"Next steps\\\" **Heading 2**, **justify** the first summary paragraph, make \\\"78% of girls surveyed\\\" **bold**, and turn the three next steps into a **numbered list**.\",\n          hint: \"Work from top to bottom. Click inside a paragraph before choosing an alignment; select the three next-step lines together before clicking Numbering.\",\n          html: \"<p>Quarterly progress report: menstrual hygiene in schools, Adamaoua</p><p>Reporting period: 1 April to 30 June 2026</p><p>Executive summary</p><p>During the quarter, the project distributed reusable pad kits to 2 450 girls in 30 secondary schools and trained 60 teachers to lead menstrual health sessions. Changing rooms with water were completed in 22 schools.</p><p>In the follow-up survey, 78% of girls surveyed said they had missed no school day because of their period in the last month, against 52% at baseline.</p><p>Challenges</p><p>Construction in 8 schools was delayed by the late delivery of cement; the contractor has agreed a new completion date of 31 August.</p><p>Next steps</p><p>Complete the changing rooms in the remaining 8 schools</p><p>Run refresher sessions for the 60 trained teachers</p><p>Share the survey results with the regional delegation of secondary education</p>\",\n          checks: [\n            { kind: \"heading\", level: 1, text: \"Quarterly progress report\" },\n            { kind: \"align\", text: \"Quarterly progress report\", value: \"center\" },\n            { kind: \"align\", text: \"Reporting period\", value: \"right\" },\n            { kind: \"heading\", level: 2, text: \"Executive summary\" },\n            { kind: \"heading\", level: 2, text: \"Challenges\" },\n            { kind: \"heading\", level: 2, text: \"Next steps\" },\n            { kind: \"align\", text: \"reusable pad kits\", value: \"justify\" },\n            { kind: \"bold\", text: \"78% of girls surveyed\" },\n            { kind: \"list\", ordered: true, min: 3 },\n          ] },\n        { type: \"h\", text: \"Exercise 3: Midterm decisions in a cash transfer project\" },\n        { type: \"form\", id: \"meal-pr-m6-cash\", level: \"advanced\", title: \"Accountability and adaptation decisions\",\n          task: \"A cash transfer project for displaced households in the South-West region is at midterm. Answer each question. Type formulas in English with commas, starting with =.\",\n          hint: \"Sensitive cases go to a focal point, never to the person's manager. For the formulas, COUNTIFS takes pairs of range and criterion; % of target divides what was achieved by the target.\",\n          fields: [\n            { kind: \"text\", label: \"The feedback log has the channel in B2:B150 and the status in D2:D150. Type the formula that counts closed cases received by WhatsApp.\", pattern: \"^=\\\\s*COUNTIFS\\\\(\\\\s*(\\\\$?B\\\\$?2:\\\\$?B\\\\$?150\\\\s*,\\\\s*\\\"WhatsApp\\\"\\\\s*,\\\\s*\\\\$?D\\\\$?2:\\\\$?D\\\\$?150\\\\s*,\\\\s*\\\"Closed\\\"|\\\\$?D\\\\$?2:\\\\$?D\\\\$?150\\\\s*,\\\\s*\\\"Closed\\\"\\\\s*,\\\\s*\\\\$?B\\\\$?2:\\\\$?B\\\\$?150\\\\s*,\\\\s*\\\"WhatsApp\\\")\\\\s*\\\\)$\", example: \"=COUNTIFS(B2:B150,\\\"WhatsApp\\\",D2:D150,\\\"Closed\\\")\", placeholder: \"=COUNTIFS(…)\", mono: true, explain: \"Each range is followed by its criterion; the order of the pairs does not matter.\" },\n            { kind: \"text\", label: \"In the ITT, the cumulative value is in F7 and the annual target in B7. Type the formula for % achieved.\", pattern: \"^=\\\\s*\\\\$?F\\\\$?7\\\\s*/\\\\s*\\\\$?B\\\\$?7$\", example: \"=F7/B7\", placeholder: \"=…\", mono: true },\n            { kind: \"select\", label: \"A woman calls the hotline: a community mobiliser demands part of her transfer every month or he will remove her from the list. Who handles this?\", options: [\"The mobiliser's supervisor\", \"The fraud and compliance focal point, with the PSEA focal point informed if there is any sexual element\", \"The community committee\", \"The MEAL officer, who investigates first\"], answer: 1, explain: \"Extortion of aid is misconduct and fraud. Refer it confidentially; the supervisor may be close to the mobiliser.\" },\n            { kind: \"select\", label: \"Monitoring shows that 35% of recipients in Kumba spend a day travelling to the only cash agent. What is the best decision?\", options: [\"Lower the target for Kumba\", \"Add a second agent or a mobile money option, record the decision in the action log and inform the donor\", \"Wait for the final evaluation\", \"Stop transfers in Kumba\"], answer: 1 },\n            { kind: \"select\", label: \"The evaluation team asks: \\\"Were the transfer amounts enough to cover the minimum expenditure basket in local markets?\\\" Which criterion is this?\", options: DAC, answer: 0, explain: \"Whether the design matches people's needs is relevance.\" },\n            { kind: \"select\", label: \"Another question: \\\"Did the project align its transfer amount with the other cash actors in the region?\\\" Which criterion?\", options: DAC, answer: 1 },\n            { kind: \"select\", label: \"The feedback log shows 40 cases but none from households headed by people with disabilities. What does this most likely mean?\", options: [\"These households are fully satisfied\", \"The channels may not be accessible to them; check and adapt the channels\", \"The log is complete\", \"Their feedback is not important for the report\"], answer: 1, explain: \"Silence from a group is a finding. Test whether the channels reach them, for example through home visits or disability organisations.\" },\n          ] },\n        { type: \"h\", text: \"Exercise 4: A nutrition ITT with traps\" },\n        { type: \"sheet\", id: \"meal-pr-m6-itt\", level: \"expert\", title: \"Indicator tracking table with missing data\",\n          task: \"Three quarters have been reported in the Logone nutrition project. Fill **F2:F5** with the value to date: the sum of the quarters, except for the rate indicator in row 4, where you report the **latest** quarter. Fill **G2:G5** with the % of the annual target. In **H2:H5**, write \\\"Data missing\\\" if any quarter is empty, otherwise \\\"On track\\\" when % of target is at least 75% and \\\"Behind\\\" when it is not. In **H6**, count the indicators on track.\",\n          data: [\n            [\"Indicator\", \"Annual target\", \"Q1\", \"Q2\", \"Q3\", \"To date\", \"% of target\", \"Status\"],\n            [\"Children screened for malnutrition\", 6000, 1500, 1650, 1720, null, null, null],\n            [\"Mothers attending counselling sessions\", 2400, 500, 610, null, null, null, null],\n            [\"% of nutrition sites without stock-out (latest value)\", 90, 70, 80, 85, null, null, null],\n            [\"Community health workers trained\", 120, 40, 0, 35, null, null, null],\n            [null, null, null, null, null, null, \"Indicators on track\", null],\n          ],\n          editable: [\"F2\", \"F3\", \"F4\", \"F5\", \"G2\", \"G3\", \"G4\", \"G5\", \"H2\", \"H3\", \"H4\", \"H5\", \"H6\"],\n          checks: [\n            { cell: \"F2\", equals: 4870 }, { cell: \"F3\", equals: 1110 }, { cell: \"F4\", equals: 85 }, { cell: \"F5\", equals: 75 },\n            { cell: \"G2\", equals: 0.8117, tol: 0.001 }, { cell: \"G3\", equals: 0.4625, tol: 0.001 }, { cell: \"G4\", equals: 0.9444, tol: 0.001 }, { cell: \"G5\", equals: 0.625, tol: 0.001 },\n            { cell: \"H2\", equals: \"On track\" }, { cell: \"H3\", equals: \"Data missing\" }, { cell: \"H4\", equals: \"On track\" }, { cell: \"H5\", equals: \"Behind\" },\n            { cell: \"H6\", equals: 2 },\n          ],\n          hint: \"Row 4 is a rate: F4 is simply =E4, never a sum. The 0 in row 5 is a real result, not missing data, while the empty Q3 in row 3 is missing. Test for missing quarters with COUNTBLANK: =IF(COUNTBLANK(C2:E2)>0,\\\"Data missing\\\",IF(G2>=0.75,\\\"On track\\\",\\\"Behind\\\")). H6 is a COUNTIF on H2:H5.\",\n          solution: {\n            F2: \"=SUM(C2:E2)\", F3: \"=SUM(C3:E3)\", F4: \"=E4\", F5: \"=SUM(C5:E5)\",\n            G2: \"=F2/B2\", G3: \"=F3/B3\", G4: \"=F4/B4\", G5: \"=F5/B5\",\n            H2: \"=IF(COUNTBLANK(C2:E2)>0,\\\"Data missing\\\",IF(G2>=0.75,\\\"On track\\\",\\\"Behind\\\"))\",\n            H3: \"=IF(COUNTBLANK(C3:E3)>0,\\\"Data missing\\\",IF(G3>=0.75,\\\"On track\\\",\\\"Behind\\\"))\",\n            H4: \"=IF(COUNTBLANK(C4:E4)>0,\\\"Data missing\\\",IF(G4>=0.75,\\\"On track\\\",\\\"Behind\\\"))\",\n            H5: \"=IF(COUNTBLANK(C5:E5)>0,\\\"Data missing\\\",IF(G5>=0.75,\\\"On track\\\",\\\"Behind\\\"))\",\n            H6: \"=COUNTIF(H2:H5,\\\"On track\\\")\",\n          } },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"meal-m6-quiz\",\n    title: \"Module 6 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"In an ITT, a quarterly indicator shows 110 latrines built against an annual target of 400 after Q1 to Q3 totals of 80, 120 and 110. What is the % achieved?\", options: [\"27.5%\", \"77.5%\", \"103%\", \"310%\"], answer: 1, explain: \"The cumulative is 80 + 120 + 110 = 310, and 310 ÷ 400 = 77.5%. Dividing only the last quarter by the target gives 27.5%, which is wrong.\" },\n      { id: \"q2\", question: \"Which indicator should NOT be summed across quarters?\", options: [\"Number of people trained\", \"Number of latrines built\", \"% of schools with a functional water point\", \"Number of hygiene kits distributed\"], answer: 2, explain: \"A percentage is a rate: report the latest value or recalculate it from the underlying counts.\" },\n      { id: \"q3\", question: \"What does a good finding in a donor report contain?\", options: [\"The result, a comparison and, when known, the reason\", \"Only the activities carried out\", \"Positive news only\", \"A description of the team\"], answer: 0, explain: \"A result compared with a target, baseline or earlier period, plus the reason, lets the reader judge progress.\" },\n      { id: \"q4\", question: \"What is the main purpose of a one-page brief?\", options: [\"To replace the financial report\", \"To give decision-makers the key finding and recommendations quickly\", \"To list every activity of the quarter\", \"To store raw data\"], answer: 1, explain: \"A brief is short and action-oriented: a finding title, a key figure and a few recommendations.\" },\n      { id: \"q5\", question: \"A community member reports that a volunteer asked for sex in exchange for food. What is the correct first step?\", options: [\"Ask the volunteer to explain\", \"Discuss it at the next committee meeting\", \"Wait for more complaints\", \"Record the essential facts and refer it immediately to the PSEA focal point\"], answer: 3, explain: \"Sexual exploitation is a sensitive complaint: ensure safety, record only essentials and refer confidentially, without investigating.\" },\n      { id: \"q6\", question: \"What does \\\"closing the loop\\\" mean in a feedback mechanism?\", options: [\"Locking the complaints box\", \"Deleting old cases from the log\", \"Telling the person, and the community, what was done in response\", \"Sending the log to the donor\"], answer: 2, explain: \"People need to hear the answer, even when their request cannot be met, or they stop using the mechanism.\" },\n      { id: \"q7\", question: \"\\\"Will the water committees keep repairing the pumps after the project ends?\\\" belongs to which OECD-DAC criterion?\", options: [\"Effectiveness\", \"Efficiency\", \"Coherence\", \"Sustainability\"], answer: 3, explain: \"Whether benefits continue after funding ends is sustainability.\" },\n      { id: \"q8\", question: \"Which is an example of adaptive management?\", options: [\"Moving trainings away from market days after attendance data showed a clash, and recording the decision\", \"Keeping the original plan whatever the data shows\", \"Changing indicators without telling the donor\", \"Collecting more data without looking at it\"], answer: 0, explain: \"Adaptive management uses evidence to change activities, documents the decision and informs the donor when needed.\" },\n    ],\n  },\n};\n"};
const BIN = {"client/public/media/meal-intro-en.mp4":"","client/public/media/meal-intro-en.jpg":"","client/public/media/meal-intro-fr.mp4":"","client/public/media/meal-intro-fr.jpg":""};
