const PATCHES = [["client/src/lms/types.ts","\"figure\", \"keys\", \"form\"] as const;","\"figure\", \"keys\", \"form\", \"xlsform\"] as const;"],["client/src/lms/types.ts","/** Block types that are hands-on labs; completing one earns XP. */","/** XLSForm lab (KoboToolbox / ODK / SurveyCTO form builder). */\nexport type XlsColumn = \"type\" | \"name\" | \"label\" | \"required\" | \"relevant\" | \"constraint\" | \"constraint_message\" | \"calculation\" | \"hint\";\nexport type XlsRow = Partial<Record<XlsColumn, string>>;\nexport interface XlsChoice { list_name: string; name: string; label: string }\nexport type XlsCheck = { label: string } & (\n  | { kind: \"field\"; name: string; type?: string; required?: boolean; relevant?: string; constraint?: string; calculation?: string; labelHas?: string }\n  | { kind: \"choices\"; list: string; names: string[] }\n);\n\n/** Block types that are hands-on labs; completing one earns XP. */"],["client/src/lms/types.ts","  | { type: \"links\";","  | { type: \"xlsform\"; id: string; level?: LabLevel; title: string; task: string; hint?: string; columns?: XlsColumn[]; survey: XlsRow[]; choices?: XlsChoice[]; checks: XlsCheck[]; solution: { survey: XlsRow[]; choices?: XlsChoice[] } }\n  | { type: \"links\";"],["client/src/lms/blocks.tsx","import { FormLab } from \"./labs/FormLab\";","import { FormLab } from \"./labs/FormLab\";\nimport { XlsFormLab } from \"./labs/XlsFormLab\";"],["client/src/lms/blocks.tsx","    case \"form\": return <FormLab block={block} api={api} />;","    case \"form\": return <FormLab block={block} api={api} />;\n    case \"xlsform\": return <XlsFormLab block={block} api={api} />;"],["client/src/lms/registry.ts","import { MOSP_PRACTICE } from \"../data/courses/mosp-practice\";","import { MOSP_PRACTICE } from \"../data/courses/mosp-practice\";\nimport { MEAL_COURSE } from \"../data/courses/meal\";"],["client/src/lms/registry.ts","  mosp: withPractice(MOSP_COURSE, MOSP_PRACTICE),","  mosp: withPractice(MOSP_COURSE, MOSP_PRACTICE),\n  meal: MEAL_COURSE,\n  \"meal-cert\": MEAL_COURSE,"]];
const FR = {"MEAL Foundations":"Fondamentaux du MEAL","What MEAL is, how it fits the project cycle, who it serves, and the ethics of working with data about people.":"Ce qu'est le MEAL, sa place dans le cycle de projet, les personnes qu'il sert et l'éthique du travail avec des données sur les personnes.","What MEAL is and how the four pillars work together":"Ce qu'est le MEAL et comment ses quatre piliers fonctionnent ensemble","Define monitoring, evaluation, accountability and learning and explain how they differ":"Définir le suivi, l'évaluation, la redevabilité et l'apprentissage, et expliquer ce qui les distingue","Trace how data flows from monitoring into evaluation, accountability and learning":"Retracer le cheminement des données du suivi vers l'évaluation, la redevabilité et l'apprentissage","Explain what MEAL adds to classic M&E and to results-based management":"Expliquer ce que le MEAL apporte au S&E classique et à la gestion axée sur les résultats","Every project promises change: more children vaccinated, cleaner water, better harvests. MEAL is the system a team uses to know whether that change is really happening, to answer to the people it serves, and to improve while there is still time. It is not a report written at the end; it is a way of working from the first day to the last.":"Tout projet promet un changement : plus d'enfants vaccinés, une eau plus propre, de meilleures récoltes. Le MEAL est le système qu'une équipe utilise pour savoir si ce changement se produit vraiment, pour rendre compte aux personnes qu'elle sert et pour s'améliorer tant qu'il est encore temps. Ce n'est pas un rapport rédigé à la fin ; c'est une manière de travailler, du premier au dernier jour.","Four pillars, one system":"Quatre piliers, un seul système","Pillar":"Pilier","Main question":"Question principale","Typical products":"Produits types","Monitoring":"Suivi","Are we doing what we planned, on time and on budget?":"Faisons-nous ce qui était prévu, dans les délais et dans le budget ?","Continuously: weekly, monthly, quarterly":"En continu : chaque semaine, chaque mois, chaque trimestre","Activity registers, monthly reports, indicator tracking table":"Registres d'activités, rapports mensuels, tableau de suivi des indicateurs (ITT)","Evaluation":"Évaluation","Did it work, for whom, and why?":"Cela a-t-il marché, pour qui et pourquoi ?","At set moments: midterm, end, sometimes after":"À des moments fixés : mi-parcours, fin, parfois après","Baseline and endline studies, evaluation reports":"Études de situation de référence et de fin de projet, rapports d'évaluation","Accountability":"Redevabilité","Do affected people know, influence and trust what we do?":"Les personnes affectées connaissent-elles ce que nous faisons, l'influencent-elles et y font-elles confiance ?","Throughout the project":"Tout au long du projet","Information sessions, complaints and feedback mechanism, feedback logs":"Séances d'information, mécanisme de gestion des plaintes et des retours (MGP), registres des retours","Learning":"Apprentissage","What should we keep, change or stop?":"Que devons-nous garder, modifier ou arrêter ?","Regularly, and at key decision points":"Régulièrement, et aux moments clés de décision","Review meetings, lessons-learned notes, adapted plans":"Réunions de revue, notes de leçons apprises, plans ajustés","Monitoring and evaluation in one sentence each":"Le suivi et l'évaluation, en une phrase chacun","Monitoring counts and follows what the project does, all the time. Evaluation steps back at chosen moments to judge whether the project achieved its results and why. Monitoring tells you that attendance dropped; evaluation tells you whether the project changed anything that matters.":"Le suivi compte et suit en permanence ce que fait le projet. L'évaluation prend du recul à des moments choisis pour juger si le projet a atteint ses résultats, et pourquoi. Le suivi vous dit que la fréquentation a baissé ; l'évaluation vous dit si le projet a changé quelque chose d'important.","How data flows between the pillars":"Comment les données circulent entre les piliers","One cycle of MEAL data":"Un cycle de données MEAL","Field teams record activities and results in registers or mobile forms (monitoring).":"Les équipes de terrain enregistrent les activités et les résultats dans des registres ou des formulaires mobiles (suivi).","The MEAL officer compiles the data, checks its quality and updates the indicator tracking table.":"Le chargé MEAL compile les données, vérifie leur qualité et met à jour le tableau de suivi des indicateurs.","Results and feedback are shared back with communities, who can question them or complain (accountability).":"Les résultats et les retours sont restitués aux communautés, qui peuvent les questionner ou porter plainte (redevabilité).","The team meets to review the figures and the feedback, and decides what to adjust (learning).":"L'équipe se réunit pour examiner les chiffres et les retours, et décide de ce qu'il faut ajuster (apprentissage).","At midterm and at the end, evaluators use all this monitoring data, plus their own collection, to judge the results (evaluation).":"À mi-parcours et à la fin, les évaluateurs utilisent toutes ces données de suivi, en plus de leur propre collecte, pour juger les résultats (évaluation).","From M&E to MEAL":"Du S&E au MEAL","Classic M&E focused on collecting data for managers and donors. MEAL adds two pillars that change the direction of the flow. Accountability sends information and power back to affected people: they are told what the project plans, they can complain safely, and their feedback changes decisions. Learning makes sure the data is actually used to improve the work, not only filed in reports.":"Le S&E classique se concentrait sur la collecte de données pour les gestionnaires et les bailleurs. Le MEAL ajoute deux piliers qui changent le sens du flux. La redevabilité renvoie l'information et le pouvoir vers les personnes affectées : elles sont informées de ce que le projet prévoit, elles peuvent se plaindre en toute sécurité et leurs retours modifient les décisions. L'apprentissage garantit que les données servent réellement à améliorer le travail, et ne sont pas seulement classées dans des rapports.","Results-based management in one paragraph":"La gestion axée sur les résultats en un paragraphe","Results-based management (RBM) means steering a project by the results it achieves rather than by the activities it completes. You define the change you want at each level (outputs, outcomes, impact), set indicators and targets for each, measure progress regularly, and use the evidence to decide. MEAL is the engine that feeds RBM with reliable evidence.":"La gestion axée sur les résultats (GAR) consiste à piloter un projet en fonction des résultats qu'il obtient plutôt que des activités qu'il réalise. Vous définissez le changement visé à chaque niveau (extrants, effets, impact), fixez des indicateurs et des cibles pour chacun, mesurez régulièrement les progrès et vous appuyez sur les données probantes pour décider. Le MEAL est le moteur qui alimente la GAR en données fiables.","Classify the activities":"Classez les activités","A nutrition project in the Far North region runs the activities below. Choose the MEAL pillar each one mainly belongs to.":"Un projet de nutrition dans la région de l'Extrême-Nord mène les activités ci-dessous. Choisissez le pilier MEAL auquel chacune appartient principalement.","Monitoring follows activities continuously, evaluation judges results at set moments, accountability is about affected people's voice and information, learning is about using evidence to change the work.":"Le suivi accompagne les activités en continu, l'évaluation juge les résultats à des moments fixés, la redevabilité concerne la voix et l'information des personnes affectées, l'apprentissage consiste à utiliser les données probantes pour changer le travail.","Community health workers fill a monthly register of children screened for malnutrition":"Les agents de santé communautaire remplissent chaque mois un registre des enfants dépistés pour la malnutrition","Routine, continuous counting of an activity is monitoring.":"Le décompte courant et continu d'une activité relève du suivi.","An external consultant compares malnutrition rates before and after the project":"Un consultant externe compare les taux de malnutrition avant et après le projet","Judging whether the project changed outcomes, at a set moment, is evaluation.":"Juger, à un moment fixé, si le projet a changé les effets relève de l'évaluation.","A free hotline number is painted on the wall of each nutrition centre":"Un numéro vert gratuit est peint sur le mur de chaque centre nutritionnel","A channel for complaints and feedback gives affected people a voice: accountability.":"Un canal de plaintes et de retours donne une voix aux personnes affectées : c'est la redevabilité.","The team meets each quarter to discuss why screening fell in two health areas and changes the outreach schedule":"L'équipe se réunit chaque trimestre pour comprendre pourquoi le dépistage a baissé dans deux aires de santé et modifie le calendrier des activités de proximité","Using evidence to adjust the plan is learning, also called adaptive management.":"Utiliser les données probantes pour ajuster le plan relève de l'apprentissage, aussi appelé gestion adaptative.","The MEAL officer updates the indicator tracking table every month":"Le chargé MEAL met à jour le tableau de suivi des indicateurs chaque mois","Village leaders are told which households were selected and why":"On explique aux chefs de village quels ménages ont été sélectionnés et pourquoi","Sharing selection criteria openly is part of being accountable to communities.":"Partager ouvertement les critères de sélection fait partie de la redevabilité envers les communautés.","A midterm review asks mothers whether the cooking demonstrations changed what they feed their children":"Une revue à mi-parcours demande aux mères si les démonstrations culinaires ont changé ce qu'elles donnent à manger à leurs enfants","A two-page note on what worked in the pilot is shared with the team starting a similar project in the East region":"Une note de deux pages sur ce qui a fonctionné pendant la phase pilote est partagée avec l'équipe qui démarre un projet similaire dans la région de l'Est","Which statement best describes what MEAL adds to classic M&E?":"Quelle affirmation décrit le mieux ce que le MEAL ajoute au S&E classique ?","More indicators and longer reports for the donor":"Plus d'indicateurs et des rapports plus longs pour le bailleur","Accountability to affected people and the use of evidence to improve the work":"La redevabilité envers les personnes affectées et l'utilisation des données probantes pour améliorer le travail","An external evaluation at the end of every project":"Une évaluation externe à la fin de chaque projet","Replacing monitoring with evaluation":"Le remplacement du suivi par l'évaluation","MEAL keeps monitoring and evaluation, and adds accountability (information and voice for affected people) and learning (acting on evidence).":"Le MEAL conserve le suivi et l'évaluation, et y ajoute la redevabilité (information et voix pour les personnes affectées) et l'apprentissage (agir à partir des données probantes).","In a fictional WASH project in the Mayo-Tsanaga department, monitoring showed that 12 new water points were built on time. Feedback from the complaints box revealed that women avoided three of them because they were far from the villages and unsafe after dark. The team moved two planned water points. Monitoring alone would have reported success.":"Dans un projet WASH fictif du département du Mayo-Tsanaga, le suivi a montré que 12 nouveaux points d'eau avaient été construits dans les délais. Les retours de la boîte à plaintes ont révélé que les femmes évitaient trois d'entre eux, car ils étaient éloignés des villages et dangereux à la tombée de la nuit. L'équipe a déplacé deux points d'eau prévus. Le suivi seul aurait conclu à un succès.","Write one sentence that defines each of the four pillars in your own words":"Rédigez, avec vos propres mots, une phrase qui définit chacun des quatre piliers","List three monitoring activities and one evaluation activity in a project you know":"Citez trois activités de suivi et une activité d'évaluation dans un projet que vous connaissez","Identify how affected people can give feedback in that project, or note that they cannot":"Identifiez comment les personnes affectées peuvent donner leur avis dans ce projet, ou notez qu'elles ne le peuvent pas","Describe one decision in that project that was, or could have been, changed by evidence":"Décrivez une décision de ce projet qui a été, ou aurait pu être, modifiée par des données probantes","Rainbow Framework: tasks in monitoring and evaluation":"Rainbow Framework : les tâches du suivi et de l'évaluation","MEAL across the project cycle":"Le MEAL tout au long du cycle de projet","Place the main MEAL activities on the stages of the project cycle":"Situer les principales activités MEAL sur les étapes du cycle de projet","Name the MEAL product expected at each stage, from assessment to closure":"Nommer le produit MEAL attendu à chaque étape, de l'évaluation des besoins à la clôture","Calculate a first indicator as a percentage of its target":"Calculer un premier indicateur en pourcentage de sa cible","MEAL is not an activity you add in the last month. Each stage of the project cycle needs something specific from MEAL, and what you skip early cannot be repaired later: without a baseline, no evaluation can show how much changed.":"Le MEAL n'est pas une activité que l'on ajoute le dernier mois. Chaque étape du cycle de projet attend quelque chose de précis du MEAL, et ce que vous négligez au début ne pourra pas être rattrapé plus tard : sans situation de référence, aucune évaluation ne peut montrer l'ampleur du changement.","The project cycle and its MEAL moments":"Le cycle de projet et ses moments MEAL","Stage":"Étape","Key MEAL question":"Question MEAL clé","What MEAL produces":"Ce que produit le MEAL","Assessment and design":"Évaluation des besoins et conception","What are the needs, and what change do we aim for?":"Quels sont les besoins, et quel changement visons-nous ?","Needs assessment, theory of change, logframe, draft indicators, MEAL plan":"Évaluation des besoins, théorie du changement, cadre logique, projet d'indicateurs, plan MEAL","Baseline":"Situation de référence","What is the situation before we start?":"Quelle est la situation avant de commencer ?","Baseline report with starting values; confirmed targets":"Rapport de situation de référence avec les valeurs de départ ; cibles confirmées","Implementation monitoring":"Suivi de la mise en œuvre","Are activities and outputs on track?":"Les activités et les extrants avancent-ils comme prévu ?","Registers, monthly data, indicator tracking table, feedback log, quarterly reports":"Registres, données mensuelles, tableau de suivi des indicateurs, registre des retours, rapports trimestriels","Midline or midterm review":"Enquête ou revue à mi-parcours","Are we on the way to the outcomes? What must change?":"Sommes-nous en voie d'atteindre les effets ? Que faut-il changer ?","Midterm review report, adjusted work plan":"Rapport de revue à mi-parcours, plan de travail ajusté","Endline or final evaluation":"Enquête de fin de projet ou évaluation finale","What changed, for whom, and was it worth it?":"Qu'est-ce qui a changé, pour qui, et cela en valait-il la peine ?","Endline survey, final evaluation report, management response":"Enquête de fin de projet, rapport d'évaluation finale, réponse de la direction","Closure and learning":"Clôture et apprentissage","What do we keep, hand over and share?":"Que gardons-nous, que transmettons-nous et que partageons-nous ?","Lessons-learned note, final report, archived and anonymised datasets":"Note de leçons apprises, rapport final, jeux de données archivés et anonymisés","The baseline comes before the activities":"La situation de référence vient avant les activités","Collect baseline data before the project starts working with the population. If distributions or trainings have already begun, your starting values are already affected and the change you report later will look smaller than it really is.":"Collectez les données de référence avant que le projet ne commence à travailler avec la population. Si des distributions ou des formations ont déjà commencé, vos valeurs de départ sont déjà influencées et le changement que vous rapporterez plus tard paraîtra plus faible qu'il ne l'est réellement.","Baseline, midline and endline":"Situation de référence, mi-parcours et fin de projet","Baseline: the starting value of each outcome indicator, measured with a method you can repeat.":"Situation de référence : la valeur de départ de chaque indicateur d'effet, mesurée avec une méthode que l'on peut répéter.","Midline: the same measurement halfway through, used to correct course while there is time.":"Mi-parcours : la même mesure à mi-chemin, utilisée pour corriger le tir tant qu'il est encore temps.","Endline: the same measurement at the end, compared with the baseline and the target.":"Fin de projet : la même mesure à la fin, comparée à la situation de référence et à la cible.","Use the same questions, the same indicator definitions and a comparable sample each time, otherwise the figures cannot be compared.":"Utilisez à chaque fois les mêmes questions, les mêmes définitions d'indicateurs et un échantillon comparable ; sinon, les chiffres ne peuvent pas être comparés.","Implementation monitoring: the monthly rhythm":"Suivi de la mise en œuvre : le rythme mensuel","A typical monthly cycle":"Un cycle mensuel type","Field staff submit activity data and registers by a fixed date, for example the 5th of each month.":"Le personnel de terrain soumet les données d'activités et les registres à une date fixe, par exemple le 5 de chaque mois.","The MEAL officer checks completeness and consistency and follows up on gaps.":"Le chargé MEAL vérifie l'exhaustivité et la cohérence des données et assure le suivi des lacunes.","The indicator tracking table is updated with the month's figures and the cumulative total.":"Le tableau de suivi des indicateurs est mis à jour avec les chiffres du mois et le total cumulé.","Feedback and complaints received during the month are summarised.":"Les retours et les plaintes reçus au cours du mois sont résumés.","The team reviews the figures in a short meeting and records decisions.":"L'équipe examine les chiffres lors d'une courte réunion et consigne les décisions.","A first taste of indicators: percentage of target":"Un premier aperçu des indicateurs : le pourcentage de la cible","The simplest progress measure divides what was achieved by what was planned. A result of 0.875 means 87.5% of the target is reached. Many teams use a simple rule to flag indicators that need attention, for example below 80% of the target at the time of reporting.":"La mesure de progrès la plus simple divise ce qui a été réalisé par ce qui était prévu. Un résultat de 0,875 signifie que 87,5 % de la cible est atteinte. Beaucoup d'équipes utilisent une règle simple pour signaler les indicateurs qui demandent de l'attention, par exemple en dessous de 80 % de la cible au moment du rapport.","Number":"Nombre","Percent Style":"Style de pourcentage","In Excel, shows a share such as 0.875 as 88%.":"Dans Excel, affiche une part comme 0,875 sous la forme 88 %.","Percentage of target achieved":"Pourcentage de la cible atteint","Six-month figures from a fictional WASH project in the East region. Fill":"Chiffres sur six mois d'un projet WASH fictif dans la région de l'Est. Remplissez","with the share of the target achieved, then":"avec la part de la cible atteinte, puis","when it is at least 80%, otherwise":"lorsqu'elle est d'au moins 80 %, sinon","The share is Achieved divided by Target: =C2/B2. For the status, test the share: =IF(D2>=0.8,\"On track\",\"Behind\").":"La part est Achieved divisé par Target : =C2/B2. Pour le statut, testez la part : =IF(D2>=0.8,\"On track\",\"Behind\") (en français : SI).","Match products to stages":"Associez les produits aux étapes","For each MEAL product of a fictional food security project in the Adamawa region, choose the stage of the project cycle where it is mainly produced.":"Pour chaque produit MEAL d'un projet fictif de sécurité alimentaire dans la région de l'Adamaoua, choisissez l'étape du cycle de projet où il est principalement produit.","Ask yourself when the product is needed: before activities start, during them, halfway, at the end, or after the project closes.":"Demandez-vous quand le produit est nécessaire : avant le début des activités, pendant, à mi-parcours, à la fin ou après la clôture du projet.","A household survey measuring food consumption before the first seed distribution":"Une enquête auprès des ménages mesurant la consommation alimentaire avant la première distribution de semences","Starting values measured before activities are the baseline.":"Des valeurs de départ mesurées avant les activités constituent la situation de référence.","Midterm review":"Revue à mi-parcours","Final evaluation":"Évaluation finale","A logframe with draft indicators and a MEAL plan":"Un cadre logique avec un projet d'indicateurs et un plan MEAL","A monthly table of seed kits distributed per village":"Un tableau mensuel des kits de semences distribués par village","A report after 18 months of a 36-month project recommending changes to the training approach":"Un rapport, après 18 mois d'un projet de 36 mois, recommandant de modifier l'approche de formation","A review halfway through, used to correct course, is the midterm review.":"Une revue à mi-chemin, utilisée pour corriger le tir, est la revue à mi-parcours.","An independent report judging the relevance, effectiveness and sustainability of the project":"Un rapport indépendant jugeant la pertinence, l'efficacité et la durabilité du projet","An anonymised dataset archived with a note on what to repeat in the next project":"Un jeu de données anonymisé archivé avec une note sur ce qu'il faut reproduire dans le prochain projet","A project starts distributing hygiene kits in January, and the baseline survey is carried out in March. What is the main problem?":"Un projet commence à distribuer des kits d'hygiène en janvier, et l'enquête de référence est réalisée en mars. Quel est le principal problème ?","The survey will cost more":"L'enquête coûtera plus cher","The starting values are already influenced by the project, so the change will be underestimated":"Les valeurs de départ sont déjà influencées par le projet, donc le changement sera sous-estimé","The donor does not accept surveys in March":"Le bailleur n'accepte pas les enquêtes en mars","There is no problem as long as the same questionnaire is used at endline":"Il n'y a aucun problème tant que le même questionnaire est utilisé en fin de projet","A baseline must describe the situation before the project acts. After two months of distributions, some change has already happened and will not be counted.":"Une situation de référence doit décrire la situation avant que le projet n'agisse. Après deux mois de distributions, une partie du changement a déjà eu lieu et ne sera pas comptée.","In a fictional education project in the South-West region, school closures delayed the baseline. Instead of skipping it, the MEAL officer used enrolment registers from the previous school year held by the sub-divisional delegation as starting values, and documented this choice in the baseline report so that evaluators could interpret the figures correctly.":"Dans un projet d'éducation fictif de la région du Sud-Ouest, la fermeture des écoles a retardé l'enquête de référence. Au lieu d'y renoncer, le chargé MEAL a utilisé comme valeurs de départ les registres d'inscription de l'année scolaire précédente détenus par la délégation d'arrondissement, et a documenté ce choix dans le rapport de référence pour que les évaluateurs puissent interpréter correctement les chiffres.","Draw the project cycle of a project you know and write one MEAL product under each stage":"Dessinez le cycle d'un projet que vous connaissez et inscrivez un produit MEAL sous chaque étape","Find out whether that project had a baseline, and when it was collected compared with the first activities":"Vérifiez si ce projet avait une situation de référence, et quand elle a été collectée par rapport aux premières activités","Build the percentage-of-target table from the lab for three indicators of your own project":"Reproduisez le tableau de pourcentage de la cible de l'atelier pour trois indicateurs de votre propre projet","Agree with your team on the threshold that flags an indicator as behind":"Convenez avec votre équipe du seuil à partir duquel un indicateur est signalé en retard","Evaluation criteria":"Critères d'évaluation","Roles, stakeholders and donor expectations":"Rôles, parties prenantes et attentes des bailleurs","Distinguish the MEAL responsibilities of MEAL officers, programme staff and enumerators":"Distinguer les responsabilités MEAL des chargés MEAL, du personnel de programme et des enquêteurs","Identify what communities, government, donors and partners each need from MEAL":"Identifier ce dont les communautés, le gouvernement, les bailleurs et les partenaires ont chacun besoin du MEAL","Check a project against typical donor requirements on indicators, reporting, data quality and safeguarding":"Vérifier un projet au regard des exigences habituelles des bailleurs en matière d'indicateurs, de rapports, de qualité des données et de protection (safeguarding)","MEAL works only when everyone knows their part. The MEAL officer designs the system and keeps it honest, but most data is collected by programme staff and enumerators, and it is used by many people outside the team, each with different needs.":"Le MEAL ne fonctionne que si chacun connaît son rôle. Le chargé MEAL conçoit le système et veille à son intégrité, mais la plupart des données sont collectées par le personnel de programme et les enquêteurs, et elles sont utilisées par de nombreuses personnes extérieures à l'équipe, chacune avec des besoins différents.","Who does what inside the team":"Qui fait quoi au sein de l'équipe","Role":"Rôle","Main MEAL tasks":"Principales tâches MEAL","Common mistake to avoid":"Erreur fréquente à éviter","MEAL officer or manager":"Chargé ou responsable MEAL","Designs the MEAL plan and tools, trains staff, checks data quality, analyses, reports, organises learning":"Conçoit le plan et les outils MEAL, forme le personnel, contrôle la qualité des données, analyse, rédige les rapports, organise l'apprentissage","Doing all the data collection alone and becoming a bottleneck":"Faire toute la collecte de données seul et devenir un goulot d'étranglement","Programme or project staff":"Personnel de programme ou de projet","Fill registers and forms correctly, use the data in planning, share feedback from the field":"Remplit correctement les registres et les formulaires, utilise les données dans la planification, fait remonter les retours du terrain","Seeing MEAL as the MEAL officer's job only":"Considérer le MEAL comme le travail du seul chargé MEAL","Enumerators and data collectors":"Enquêteurs et agents de collecte","Collect data following the protocol, obtain consent, respect confidentiality, report problems":"Collectent les données selon le protocole, obtiennent le consentement, respectent la confidentialité, signalent les problèmes","Filling in missing answers from memory or guessing":"Compléter les réponses manquantes de mémoire ou au hasard","Project manager":"Chef de projet","Makes decisions based on the evidence and makes time for review meetings":"Prend les décisions sur la base des données probantes et réserve du temps pour les réunions de revue","Reading the figures only when the donor report is due":"Ne regarder les chiffres qu'à l'approche du rapport au bailleur","MEAL is everyone's job":"Le MEAL, c'est l'affaire de tous","Write MEAL tasks into every job description and work plan: who fills which register, by which date, and who reviews it. A clear responsibility list prevents most data gaps.":"Inscrivez les tâches MEAL dans chaque description de poste et chaque plan de travail : qui remplit quel registre, avant quelle date, et qui le vérifie. Une liste claire des responsabilités évite la plupart des lacunes dans les données.","Stakeholders outside the team":"Les parties prenantes extérieures à l'équipe","Stakeholder":"Partie prenante","What they need from MEAL":"Ce dont elles ont besoin du MEAL","How MEAL serves them":"Comment le MEAL les sert","Communities and affected people":"Communautés et personnes affectées","Information on the project, a safe way to complain, results that concern them":"Des informations sur le projet, un moyen sûr de se plaindre, les résultats qui les concernent","Information sessions, feedback mechanism, sharing results back in local languages":"Séances d'information, mécanisme de retours, restitution des résultats dans les langues locales","Government (ministries, regional delegations, health districts)":"Gouvernement (ministères, délégations régionales, districts de santé)","Data aligned with national indicators and systems, coordination":"Des données alignées sur les indicateurs et les systèmes nationaux, de la coordination","Using national indicator definitions, sharing reports, reporting in national systems":"Utilisation des définitions nationales des indicateurs, partage des rapports, saisie dans les systèmes nationaux","Donors":"Bailleurs","Evidence that funds produce the agreed results, compliance with the grant":"La preuve que les fonds produisent les résultats convenus, le respect de la convention de subvention","Indicator tracking, periodic reports, evaluations, data quality checks":"Suivi des indicateurs, rapports périodiques, évaluations, contrôles de la qualité des données","Implementing partners":"Partenaires de mise en œuvre","Clear tools and deadlines, feedback on their data, support":"Des outils et des échéances clairs, des retours sur leurs données, un appui","Joint training, common forms, regular data reviews":"Formations conjointes, formulaires communs, revues régulières des données","What donors typically expect":"Ce que les bailleurs attendent généralement","Indicators: a logframe with defined indicators, often a mix of the donor's standard indicators and project-specific ones, with baselines and targets.":"Indicateurs : un cadre logique avec des indicateurs définis, souvent un mélange d'indicateurs standard du bailleur et d'indicateurs propres au projet, avec leurs situations de référence et leurs cibles.","Reporting frequency: usually quarterly or half-yearly progress reports and an annual or final report, with deadlines written in the grant agreement.":"Fréquence des rapports : généralement des rapports d'avancement trimestriels ou semestriels et un rapport annuel ou final, avec des échéances inscrites dans la convention de subvention.","Data quality: data that is valid, reliable, timely, precise and has integrity; some donors run data quality assessments on site.":"Qualité des données : des données valides, fiables, à jour, précises et intègres ; certains bailleurs réalisent des évaluations de la qualité des données sur le terrain.","Disaggregation: results broken down at least by sex and age, and often by disability or location.":"Désagrégation : des résultats ventilés au moins par sexe et par âge, et souvent par handicap ou par localité.","Safeguarding: a code of conduct, protection from sexual exploitation and abuse, and rapid reporting of incidents through confidential channels.":"Protection (safeguarding) : un code de conduite, la protection contre l'exploitation et les abus sexuels, et le signalement rapide des incidents par des canaux confidentiels.","Accountability: evidence that affected people were informed and consulted and that complaints were handled.":"Redevabilité : la preuve que les personnes affectées ont été informées et consultées, et que les plaintes ont été traitées.","Read the grant agreement first":"Lisez d'abord la convention de subvention","Reporting templates, indicator definitions and deadlines differ from one donor to another. List every MEAL requirement of the agreement in the MEAL plan in the first month; discovering one at the final report is too late.":"Les modèles de rapport, les définitions des indicateurs et les échéances varient d'un bailleur à l'autre. Inscrivez dès le premier mois toutes les exigences MEAL de la convention dans le plan MEAL ; en découvrir une au moment du rapport final, c'est trop tard.","Map your stakeholders":"Cartographiez vos parties prenantes","A quick stakeholder mapping":"Une cartographie rapide des parties prenantes","List everyone who produces, uses or is affected by the project's data.":"Listez toutes les personnes qui produisent, utilisent ou sont concernées par les données du projet.","For each one, write the information they need and how often.":"Pour chacune, notez l'information dont elle a besoin et à quelle fréquence.","Note the format that suits them: dashboard, report, meeting, radio message, community meeting.":"Notez le format qui lui convient : tableau de bord, rapport, réunion, message radio, assemblée communautaire.","Assign a person in the team responsible for each flow of information.":"Désignez dans l'équipe une personne responsable de chaque flux d'information.","Add these flows to the MEAL plan and review them every six months.":"Ajoutez ces flux au plan MEAL et révisez-les tous les six mois.","Who needs this information?":"Qui a besoin de cette information ?","A fictional maternal health project works with a health district in the Centre region. Choose the stakeholder who mainly needs each piece of information.":"Un projet fictif de santé maternelle travaille avec un district de santé de la région du Centre. Choisissez la partie prenante qui a principalement besoin de chaque information.","Think about who acts on the information: communities need what concerns their access and their rights, the district needs data for its own system, the donor needs evidence on the agreed results, the partner needs operational feedback.":"Pensez à qui agit à partir de l'information : les communautés ont besoin de ce qui concerne leur accès et leurs droits, le district a besoin de données pour son propre système, le bailleur a besoin de preuves sur les résultats convenus, le partenaire a besoin de retours opérationnels.","The opening days of the mobile clinic and how to complain about the service":"Les jours d'ouverture de la clinique mobile et la manière de se plaindre du service","Practical information and a complaints channel serve the people using the service.":"Les informations pratiques et un canal de plaintes servent les personnes qui utilisent le service.","Community members":"Membres de la communauté","Government health district":"District de santé (gouvernement)","Donor":"Bailleur","Implementing partner":"Partenaire de mise en œuvre","Monthly antenatal visits using the national indicator definitions, for the health information system":"Les consultations prénatales mensuelles selon les définitions nationales des indicateurs, pour le système d'information sanitaire","Progress against the logframe targets and the quarterly financial burn rate":"L'avancement par rapport aux cibles du cadre logique et le taux trimestriel de consommation budgétaire","Feedback on errors found in the registers of the three health centres the partner supervises":"Des retours sur les erreurs trouvées dans les registres des trois centres de santé que supervise le partenaire","The results of the midterm review presented in a village meeting in the local language":"Les résultats de la revue à mi-parcours présentés lors d'une réunion villageoise dans la langue locale","Sharing results back with communities closes the loop and is a core part of accountability.":"Restituer les résultats aux communautés boucle la boucle et constitue un élément central de la redevabilité.","Confirmation that a safeguarding incident was reported within the agreed deadline":"La confirmation qu'un incident de protection a été signalé dans le délai convenu","An enumerator cannot find a respondent and fills in the questionnaire from what the neighbour says, without noting it. What is the main issue?":"Un enquêteur ne trouve pas un répondant et remplit le questionnaire à partir de ce que dit le voisin, sans le noter. Quel est le principal problème ?","The questionnaire takes longer to complete":"Le questionnaire prend plus de temps à remplir","The data is no longer valid for that household and the protocol was broken":"Les données ne sont plus valides pour ce ménage et le protocole n'a pas été respecté","The donor will ask for more indicators":"Le bailleur demandera davantage d'indicateurs","Nothing, as long as the answers look plausible":"Rien, tant que les réponses semblent plausibles","Answers must come from the intended respondent. Replacing them without recording it damages validity and integrity; the enumerator should record the household as not reached and inform the supervisor.":"Les réponses doivent venir du répondant prévu. Les remplacer sans le consigner nuit à la validité et à l'intégrité des données ; l'enquêteur devrait enregistrer le ménage comme non atteint et en informer le superviseur.","Health districts in Cameroon report routine data to the Ministry of Public Health through the national health information system. A fictional NGO supporting a health district agreed to use the same indicator definitions and to enter its data in the district's system before its own report. The district trusted the figures, and the NGO avoided two conflicting sets of numbers.":"Au Cameroun, les districts de santé transmettent leurs données de routine au ministère de la Santé publique par le système national d'information sanitaire. Une ONG fictive qui appuie un district de santé a accepté d'utiliser les mêmes définitions d'indicateurs et de saisir ses données dans le système du district avant de rédiger son propre rapport. Le district a fait confiance aux chiffres, et l'ONG a évité d'avoir deux séries de chiffres contradictoires.","Write the MEAL tasks of each role in your team in a simple table":"Présentez dans un tableau simple les tâches MEAL de chaque rôle de votre équipe","List the external stakeholders of your project and what each needs from MEAL":"Listez les parties prenantes externes de votre projet et ce dont chacune a besoin du MEAL","Find the reporting deadlines and indicator requirements in one grant agreement you work with":"Repérez les échéances de rapport et les exigences sur les indicateurs dans une convention de subvention avec laquelle vous travaillez","Check whether your project's results are disaggregated by sex and age":"Vérifiez si les résultats de votre projet sont désagrégés par sexe et par âge","Identify the confidential channel for reporting a safeguarding incident in your organisation":"Identifiez le canal confidentiel de signalement d'un incident de protection dans votre organisation","Core Humanitarian Standard on Quality and Accountability":"Norme humanitaire fondamentale de qualité et de redevabilité (CHS)","Ethics: do no harm, informed consent and data protection":"Éthique : ne pas nuire, consentement éclairé et protection des données","Apply the do-no-harm principle when planning data collection":"Appliquer le principe « ne pas nuire » lors de la planification de la collecte de données","Build an informed consent step that ends the interview when consent is refused":"Construire une étape de consentement éclairé qui met fin à l'entretien en cas de refus","Protect personal data through minimisation, anonymisation, secure storage and controlled sharing":"Protéger les données personnelles par la minimisation, l'anonymisation, le stockage sécurisé et le partage contrôlé","Data about people can hurt them. A list of displaced households, a survivor's story or a photo of a child can expose people to stigma, violence or exclusion if it is collected carelessly or ends up in the wrong hands. Ethics is not paperwork added to MEAL; it decides what you may collect, how and from whom.":"Les données sur les personnes peuvent leur nuire. Une liste de ménages déplacés, le récit d'une survivante ou la photo d'un enfant peuvent exposer des personnes à la stigmatisation, à la violence ou à l'exclusion s'ils sont collectés sans précaution ou tombent entre de mauvaises mains. L'éthique n'est pas une formalité administrative ajoutée au MEAL ; elle détermine ce que vous pouvez collecter, comment et auprès de qui.","Do no harm in data collection":"Ne pas nuire lors de la collecte de données","Ask only what you will use, and do not ask sensitive questions just because they might be interesting.":"Ne demandez que ce que vous utiliserez, et ne posez pas de questions sensibles simplement parce qu'elles pourraient être intéressantes.","Think about who could see the interview: neighbours, family members, armed actors.":"Pensez à qui pourrait voir l'entretien : voisins, membres de la famille, acteurs armés.","Do not raise expectations: say clearly that taking part does not guarantee assistance.":"Ne suscitez pas d'attentes : dites clairement que participer ne garantit aucune assistance.","Keep interviews short; people's time has a cost, especially during a crisis.":"Faites des entretiens courts ; le temps des gens a un coût, surtout en période de crise.","Know the referral pathway: if someone needs help, you must know where to refer them.":"Connaissez le circuit de référencement : si quelqu'un a besoin d'aide, vous devez savoir vers qui l'orienter.","Informed consent":"Consentement éclairé","Consent is informed when the person understands who you are, why you ask, what happens to the answers, and that they can refuse or stop at any time without losing any assistance. It must be given freely, before any question, in a language the person understands.":"Le consentement est éclairé lorsque la personne comprend qui vous êtes, pourquoi vous posez des questions, ce que deviendront ses réponses, et qu'elle peut refuser ou s'arrêter à tout moment sans perdre aucune assistance. Il doit être donné librement, avant toute question, dans une langue que la personne comprend.","A short consent script":"Un court script de consentement","Introduce yourself and your organisation, and show your badge.":"Présentez-vous ainsi que votre organisation, et montrez votre badge.","Explain the purpose of the survey and how long it takes.":"Expliquez l'objectif de l'enquête et sa durée.","Say that taking part is voluntary and that refusing will not affect any assistance.":"Dites que la participation est volontaire et qu'un refus n'aura aucun effet sur l'assistance.","Explain that answers are confidential and that names will not appear in reports.":"Expliquez que les réponses sont confidentielles et que les noms n'apparaîtront pas dans les rapports.","Say that the person can skip any question or stop at any time.":"Dites que la personne peut sauter n'importe quelle question ou s'arrêter à tout moment.","Ask whether they have questions, then ask clearly: do you agree to take part?":"Demandez si elle a des questions, puis demandez clairement : acceptez-vous de participer ?","Minors and sensitive topics":"Mineurs et sujets sensibles","For children under 18, obtain the consent of a parent or guardian and the child's own agreement, and interview them in a visible but private place. Never ask about individual experiences of gender-based violence in a general survey: such questions need specially trained staff, a private setting and a working referral pathway.":"Pour les enfants de moins de 18 ans, obtenez le consentement d'un parent ou tuteur ainsi que l'accord de l'enfant lui-même, et interrogez-le dans un lieu visible mais à l'abri des oreilles. Ne posez jamais de questions sur les expériences individuelles de violences basées sur le genre dans une enquête générale : ces questions exigent un personnel spécialement formé, un cadre privé et un circuit de référencement fonctionnel.","Build consent into the form":"Intégrez le consentement au formulaire","In a mobile form, make consent a required question at the start and make the rest of the form relevant only when the answer is yes. The enumerator then cannot continue by mistake after a refusal.":"Dans un formulaire mobile, faites du consentement une question obligatoire au début et rendez le reste du formulaire pertinent (relevant) uniquement lorsque la réponse est oui. L'enquêteur ne peut alors pas continuer par erreur après un refus.","Projects":"Projets","Build from scratch":"Créer à partir de zéro","Creates a new form in KoboToolbox; you can also upload an XLSForm file.":"Crée un nouveau formulaire dans KoboToolbox ; vous pouvez aussi importer un fichier XLSForm.","Add a consent question":"Ajoutez une question de consentement","Replace the placeholder in row 3 with a":"Remplacez l'espace réservé de la ligne 3 par une question","required":"obligatoire","consent question named":"de consentement nommée","(type":"(type","). Make the":"). Rendez le groupe","interview":"interview","group relevant only when consent is yes, then add a row at the end: a note named":"pertinent (relevant) uniquement lorsque le consentement est « yes », puis ajoutez une ligne à la fin : une note nommée","that appears only when consent is no.":"qui ne s'affiche que lorsque le consentement est « no ».","Row 3: type select_one yes_no, name consent, required yes. Group relevant: ${consent} = 'yes'. Last row: type note, name refused, relevant ${consent} = 'no'.":"Ligne 3 : type select_one yes_no, name consent, required yes. Relevant du groupe : ${consent} = 'yes'. Dernière ligne : type note, name refused, relevant ${consent} = 'no'.","consent is a select_one yes_no question":"consent est une question select_one yes_no","consent is required":"consent est obligatoire","the interview group appears only when consent = yes":"le groupe interview ne s'affiche que lorsque consent = yes","a note named refused appears only when consent = no":"une note nommée refused ne s'affiche que lorsque consent = no","Protect the data":"Protégez les données","Principle":"Principe","In practice":"En pratique","Data minimisation":"Minimisation des données","Collect only the variables the indicators need. If you do not need names or phone numbers for analysis, do not collect them.":"Ne collectez que les variables dont les indicateurs ont besoin. Si vous n'avez pas besoin des noms ou des numéros de téléphone pour l'analyse, ne les collectez pas.","Anonymisation":"Anonymisation","Replace names with codes, keep the list linking codes to names separately, and remove GPS points or exact villages before sharing datasets.":"Remplacez les noms par des codes, conservez à part la liste qui relie les codes aux noms, et supprimez les points GPS ou les villages exacts avant de partager des jeux de données.","Secure storage":"Stockage sécurisé","Use password-protected phones and accounts, send data to the server as soon as there is a connection, and delete it from the phones afterwards.":"Utilisez des téléphones et des comptes protégés par mot de passe, envoyez les données au serveur dès qu'il y a une connexion, puis supprimez-les des téléphones.","Controlled sharing":"Partage contrôlé","Share only aggregated or anonymised data, only with people who need it, through agreed channels. Never send beneficiary lists in open messaging groups.":"Ne partagez que des données agrégées ou anonymisées, uniquement avec les personnes qui en ont besoin, par des canaux convenus. N'envoyez jamais de listes de bénéficiaires dans des groupes de messagerie ouverts.","Retention":"Conservation","Decide in advance how long personal data is kept and who deletes it at the end of the project.":"Décidez à l'avance combien de temps les données personnelles sont conservées et qui les supprime à la fin du projet.","What would you do?":"Que feriez-vous ?","Choose the most ethical response to each situation.":"Choisissez la réponse la plus éthique à chaque situation.","Protect the person first, then the data. When in doubt, collect less, share less and refer to trained staff.":"Protégez d'abord la personne, puis les données. En cas de doute, collectez moins, partagez moins et orientez vers un personnel formé.","During a household survey, a woman starts describing violence by her husband.":"Pendant une enquête auprès des ménages, une femme commence à décrire les violences que lui fait subir son mari.","Enumerators are not trained to handle disclosures. Listen, do not probe, give referral information and keep her identity confidential.":"Les enquêteurs ne sont pas formés pour gérer ce type de révélation. Écoutez, ne cherchez pas à en savoir plus, donnez les informations de référencement et gardez son identité confidentielle.","Record every detail in the form":"Consigner chaque détail dans le formulaire","Listen calmly, do not probe, offer the referral information and inform your supervisor without writing her name":"Écouter calmement, ne pas chercher à en savoir plus, proposer les informations de référencement et informer votre superviseur sans écrire son nom","Ask the husband for his version":"Demander sa version au mari","Tell her the survey is not about that and move on":"Lui dire que l'enquête ne porte pas sur ce sujet et passer à la suite","A local authority asks for the full list of displaced households with their phone numbers.":"Une autorité locale demande la liste complète des ménages déplacés avec leurs numéros de téléphone.","Personal data is shared only for a clear purpose, with consent, and through an agreed procedure. Aggregated figures usually meet the need.":"Les données personnelles ne sont partagées que dans un but clair, avec le consentement des personnes et selon une procédure convenue. Des chiffres agrégés répondent généralement au besoin.","Send it by WhatsApp to be helpful":"L'envoyer par WhatsApp pour rendre service","Send it only if the request is written":"L'envoyer uniquement si la demande est écrite","Explain the data protection rules and offer aggregated figures; refer the request to your manager":"Expliquer les règles de protection des données et proposer des chiffres agrégés ; transmettre la demande à votre responsable","Refuse any contact with the authority":"Refuser tout contact avec l'autorité","You want to interview 15-year-old students about school attendance.":"Vous voulez interroger des élèves de 15 ans sur la fréquentation scolaire.","Their own agreement is enough":"Leur propre accord suffit","Obtain parental consent and the student's assent, and interview in a visible, private place":"Obtenir le consentement des parents et l'assentiment de l'élève, et mener l'entretien dans un lieu visible mais à l'abri des oreilles","Ask the teacher to answer for them":"Demander à l'enseignant de répondre à leur place","Interview them only in groups so consent is not needed":"Les interroger uniquement en groupe pour ne pas avoir besoin de consentement","An enumerator's tablet with unsent interviews is stolen.":"La tablette d'un enquêteur contenant des entretiens non envoyés est volée.","A data breach must be reported quickly so the team can limit harm, for example by revoking access to the server account.":"Une violation de données doit être signalée rapidement pour que l'équipe puisse limiter les dommages, par exemple en révoquant l'accès au compte du serveur.","Wait to see if it is found":"Attendre de voir si elle est retrouvée","Report the incident at once, change the account password and assess who could be affected":"Signaler immédiatement l'incident, changer le mot de passe du compte et évaluer qui pourrait être affecté","Re-interview the households without telling anyone":"Réinterroger les ménages sans prévenir personne","Buy a new tablet and continue":"Acheter une nouvelle tablette et continuer","The draft form asks for the respondent's name, ethnic group and exact GPS location, but no indicator uses them.":"Le projet de formulaire demande le nom du répondant, son groupe ethnique et sa position GPS exacte, mais aucun indicateur ne les utilise.","Data minimisation: every sensitive variable you do not collect is one that cannot leak.":"Minimisation des données : chaque variable sensible que vous ne collectez pas est une variable qui ne peut pas fuiter.","Keep them, they may be useful later":"Les garder, elles pourraient servir plus tard","Remove them: collect only what the indicators need":"Les supprimer : ne collecter que ce dont les indicateurs ont besoin","Keep them but make them optional":"Les garder mais les rendre facultatives","Keep only the ethnic group":"Ne garder que le groupe ethnique","Which practice best protects respondents when you share a survey dataset with a partner?":"Quelle pratique protège le mieux les répondants lorsque vous partagez un jeu de données d'enquête avec un partenaire ?","Sending the full dataset in a password-protected Excel file":"Envoyer le jeu de données complet dans un fichier Excel protégé par mot de passe","Removing names, phone numbers and GPS points and sharing only the variables the partner needs":"Supprimer les noms, les numéros de téléphone et les points GPS, et ne partager que les variables dont le partenaire a besoin","Asking the partner to promise not to share it":"Demander au partenaire de promettre de ne pas le partager","Sharing it only on paper":"Le partager uniquement sur papier","Anonymisation and minimisation remove the risk at its source. A password or a promise protects the file, not the people in it.":"L'anonymisation et la minimisation suppriment le risque à la source. Un mot de passe ou une promesse protège le fichier, pas les personnes qu'il contient.","In a fictional shelter project in the North-West region, beneficiary lists with names and neighbourhoods were circulating in a large WhatsApp group of volunteers. The MEAL officer replaced them with coded lists, kept the key file on a password-protected laptop, and trained volunteers to call the office to confirm a household instead of forwarding lists.":"Dans un projet d'abris fictif de la région du Nord-Ouest, des listes de bénéficiaires avec noms et quartiers circulaient dans un grand groupe WhatsApp de volontaires. Le chargé MEAL les a remplacées par des listes codées, a conservé le fichier de correspondance sur un ordinateur portable protégé par mot de passe, et a formé les volontaires à appeler le bureau pour vérifier un ménage au lieu de transférer des listes.","Write a consent script of six sentences for a survey in your project, in English and French":"Rédigez un script de consentement de six phrases pour une enquête de votre projet, en anglais et en français","Add a required consent question and a relevant condition to one of your XLSForms":"Ajoutez une question de consentement obligatoire et une condition relevant à l'un de vos XLSForms","List every personal variable in that form and remove the ones no indicator uses":"Listez toutes les variables personnelles de ce formulaire et supprimez celles qu'aucun indicateur n'utilise","Find out where your project's data is stored and who has access to it":"Découvrez où sont stockées les données de votre projet et qui y a accès","Write down the referral contacts enumerators should give in case of a disclosure":"Notez les contacts de référencement que les enquêteurs doivent donner en cas de révélation","Handbook on data protection in humanitarian action":"Manuel sur la protection des données dans l'action humanitaire","Adding skip logic in the Formbuilder":"Ajouter une logique de saut dans le Formbuilder","Practice lab: MEAL foundations in the field":"Atelier pratique : les fondamentaux du MEAL sur le terrain","Classify project activities by MEAL pillar and project stage":"Classer des activités de projet par pilier MEAL et par étape du projet","Calculate achievement against targets for a set of sites":"Calculer le niveau de réalisation par rapport aux cibles pour un ensemble de sites","Build consent and eligibility logic into a mobile form":"Intégrer une logique de consentement et d'éligibilité dans un formulaire mobile","Calculate indicators correctly from data with refusals and missing answers":"Calculer correctement des indicateurs à partir de données comportant des refus et des réponses manquantes","Exercise 1: An immunisation project in a health district":"Exercice 1 : un projet de vaccination dans un district de santé","Pillars and stages":"Piliers et étapes","A fictional project supports routine immunisation in a health district of the Littoral region. Answer each question.":"Un projet fictif appuie la vaccination de routine dans un district de santé de la région du Littoral. Répondez à chaque question.","Monitoring is continuous, evaluation judges results at set moments, accountability gives people information and voice, learning turns evidence into decisions. The baseline comes before the activities.":"Le suivi est continu, l'évaluation juge les résultats à des moments fixés, la redevabilité donne aux personnes information et voix, l'apprentissage transforme les données probantes en décisions. La situation de référence vient avant les activités.","Nurses record every vaccination in the health centre register":"Les infirmiers enregistrent chaque vaccination dans le registre du centre de santé","A suggestion box and a phone number are placed in each vaccination post":"Une boîte à suggestions et un numéro de téléphone sont installés dans chaque poste de vaccination","Supervisors adjust the outreach calendar after seeing low coverage in two health areas":"Les superviseurs ajustent le calendrier des activités de proximité après avoir constaté une faible couverture dans deux aires de santé","A coverage survey after three years compares results with the starting values":"Une enquête de couverture menée au bout de trois ans compare les résultats aux valeurs de départ","The survey that measured immunisation coverage before the project began is the…":"L'enquête qui a mesuré la couverture vaccinale avant le début du projet correspond à l'étape…","Starting values measured before activities form the baseline.":"Des valeurs de départ mesurées avant les activités constituent la situation de référence.","The monthly table of children vaccinated per health area belongs to…":"Le tableau mensuel des enfants vaccinés par aire de santé relève de l'étape…","Exercise 2: A school feeding programme":"Exercice 2 : un programme de cantines scolaires","Meals served against plan":"Repas servis par rapport au plan","Term figures from five schools of a fictional school feeding programme in the Far North. Fill":"Chiffres trimestriels de cinq écoles d'un programme fictif de cantines scolaires dans l'Extrême-Nord. Remplissez","with the share of planned meals served,":"avec la part des repas prévus effectivement servis,","with the totals,":"avec les totaux,","with the overall share, and":"avec la part globale, et","with the number of schools below 80%.":"avec le nombre d'écoles en dessous de 80 %.","Each share is served divided by planned. The overall share is total served divided by total planned (=C7/B7), not the average of the five shares, because schools have different sizes. Count low schools with COUNTIF(D2:D6,\"<0.8\").":"Chaque part est égale aux repas servis divisés par les repas prévus. La part globale est le total servi divisé par le total prévu (=C7/B7), et non la moyenne des cinq parts, car les écoles n'ont pas la même taille. Comptez les écoles en dessous du seuil avec COUNTIF(D2:D6,\"<0.8\") (NB.SI en français).","Exercise 3: A WASH household survey":"Exercice 3 : une enquête WASH auprès des ménages","Consent and eligibility logic":"Logique de consentement et d'éligibilité","A fictional WASH NGO interviews adults only. Make":"Une ONG WASH fictive n'interroge que des adultes. Rendez","consent":"consent","required. Show":"obligatoire. Affichez","age":"age","only when consent is yes, make it required and accept 10 to 110. Show the":"uniquement lorsque consent vaut « yes », rendez ce champ obligatoire et acceptez les valeurs de 10 à 110. Affichez le groupe","household":"household","group only when consent is yes and age is at least 18. Then add a note named":"uniquement lorsque consent vaut « yes » et que age est d'au moins 18. Ajoutez ensuite une note nommée","at the end that appears when consent is no or the person is under 18.":"à la fin, qui s'affiche lorsque consent vaut « no » ou que la personne a moins de 18 ans.","Group relevant: ${consent} = 'yes' and ${age} >= 18. Age constraint: . >= 10 and . <= 110. End note relevant: ${consent} = 'no' or ${age} < 18.":"Relevant du groupe : ${consent} = 'yes' and ${age} >= 18. Constraint de age : . >= 10 and . <= 110. Relevant de la note de fin : ${consent} = 'no' or ${age} < 18.","age appears only when consent = yes":"age ne s'affiche que lorsque consent = yes","age is required":"age est obligatoire","age accepts 10 to 110 only":"age n'accepte que les valeurs de 10 à 110","household group only for consenting adults":"le groupe household uniquement pour les adultes consentants","end_note appears when consent = no or age < 18":"end_note s'affiche lorsque consent = no ou age < 18","Exercise 4: Post-distribution monitoring in a refugee response":"Exercice 4 : suivi post-distribution dans une réponse aux réfugiés","Indicators from messy survey data":"Des indicateurs à partir de données d'enquête désordonnées","Post-distribution monitoring at a fictional refugee-hosting site in the East region. Interviews without consent must be excluded, even if data was entered by mistake. Fill":"Suivi post-distribution sur un site fictif accueillant des réfugiés dans la région de l'Est. Les entretiens sans consentement doivent être exclus, même si des données ont été saisies par erreur. Remplissez","Every measure must include the condition Consent = Yes. Count Yes and No kit answers separately with COUNTIFS and add them. The percentage divides the Yes answers by H3, not by H2. Use AVERAGEIFS with two conditions for the days. H7 is the difference between H2 and H3.":"Chaque mesure doit inclure la condition Consent = Yes. Comptez séparément les réponses Yes et No sur le kit avec COUNTIFS (NB.SI.ENS) et additionnez-les. Le pourcentage divise les réponses Yes par H3, et non par H2. Utilisez AVERAGEIFS (MOYENNE.SI.ENS) avec deux conditions pour les jours. H7 est la différence entre H2 et H3.","Which activity is monitoring rather than evaluation?":"Quelle activité relève du suivi plutôt que de l'évaluation ?","An endline survey comparing results with the baseline":"Une enquête de fin de projet comparant les résultats à la situation de référence","Counting the hygiene kits distributed each month":"Le décompte des kits d'hygiène distribués chaque mois","A midterm review judging whether outcomes are likely":"Une revue à mi-parcours jugeant si les effets sont susceptibles d'être atteints","An independent study of the project's sustainability":"Une étude indépendante de la durabilité du projet","Monitoring follows activities and outputs continuously. The other three judge results at set moments, which is evaluation.":"Le suivi accompagne en continu les activités et les extrants. Les trois autres jugent les résultats à des moments fixés, ce qui relève de l'évaluation.","What does the accountability pillar mainly add to M&E?":"Qu'apporte principalement le pilier redevabilité au S&E ?","More frequent donor reports":"Des rapports plus fréquents au bailleur","External auditors":"Des auditeurs externes","Information, voice and a safe way to complain for affected people":"L'information, la voix et un moyen sûr de se plaindre pour les personnes affectées","A larger MEAL budget":"Un budget MEAL plus important","Accountability is about the people the project serves: they are informed, consulted, and can complain safely, and their feedback changes decisions.":"La redevabilité concerne les personnes que le projet sert : elles sont informées, consultées, peuvent se plaindre en toute sécurité, et leurs retours modifient les décisions.","When should the baseline be collected?":"Quand faut-il collecter la situation de référence ?","Before the project starts working with the population":"Avant que le projet ne commence à travailler avec la population","After the first distribution, when people know the project":"Après la première distribution, quand les gens connaissent le projet","At the midterm review":"Lors de la revue à mi-parcours","Only if the donor asks for it":"Seulement si le bailleur le demande","The baseline describes the situation before the project acts. Collected later, it already includes some of the project's effect.":"La situation de référence décrit la situation avant que le projet n'agisse. Collectée plus tard, elle inclut déjà une partie de l'effet du projet.","A project planned 400 trainees and trained 290. What is the percentage of target achieved?":"Un projet prévoyait 400 personnes à former et en a formé 290. Quel est le pourcentage de la cible atteint ?","290 ÷ 400 = 0.725, that is 72.5% of the target.":"290 ÷ 400 = 0,725, soit 72,5 % de la cible.","Who should fill in activity registers correctly and use the data in planning?":"Qui doit remplir correctement les registres d'activités et utiliser les données dans la planification ?","Only the MEAL officer":"Uniquement le chargé MEAL","Only the donor":"Uniquement le bailleur","Programme staff, with support from the MEAL officer":"Le personnel de programme, avec l'appui du chargé MEAL","Only external evaluators":"Uniquement les évaluateurs externes","Programme staff produce most routine data. The MEAL officer designs tools, trains and checks quality, but cannot collect everything alone.":"Le personnel de programme produit la plupart des données de routine. Le chargé MEAL conçoit les outils, forme et contrôle la qualité, mais ne peut pas tout collecter seul.","Which requirement is typical of donors regarding results?":"Quelle exigence est typique des bailleurs en matière de résultats ?","Results reported only as a total, without breakdown":"Des résultats présentés uniquement en total, sans ventilation","Results disaggregated at least by sex and age":"Des résultats désagrégés au moins par sexe et par âge","No indicators, only stories":"Pas d'indicateurs, seulement des témoignages","Monthly external evaluations":"Des évaluations externes mensuelles","Most donors ask for disaggregation by sex and age, and often by disability or location, to see who benefits.":"La plupart des bailleurs demandent une désagrégation par sexe et par âge, et souvent par handicap ou par localité, pour voir qui en bénéficie.","What is data minimisation?":"Qu'est-ce que la minimisation des données ?","Compressing data files before sending them":"Compresser les fichiers de données avant de les envoyer","Deleting all data at the end of each month":"Supprimer toutes les données à la fin de chaque mois","Reducing the sample size":"Réduire la taille de l'échantillon","Collecting only the personal data the indicators actually need":"Ne collecter que les données personnelles dont les indicateurs ont réellement besoin","Every sensitive variable you do not collect is one that cannot be lost, leaked or misused.":"Chaque variable sensible que vous ne collectez pas est une variable qui ne peut être ni perdue, ni divulguée, ni détournée.","In an XLSForm, how do you stop the interview when consent is refused?":"Dans un XLSForm, comment arrêter l'entretien lorsque le consentement est refusé ?","Make consent required and set the rest of the form relevant only when ${consent} = 'yes'":"Rendre consent obligatoire et rendre le reste du formulaire pertinent (relevant) uniquement lorsque ${consent} = 'yes'","Put the consent question at the end of the form":"Placer la question de consentement à la fin du formulaire","Add a constraint on every question":"Ajouter une contrainte sur chaque question","Ask the enumerator to close the form manually":"Demander à l'enquêteur de fermer le formulaire manuellement","A required consent question with the rest of the form in a group relevant on consent = yes makes it impossible to continue after a refusal.":"Une question de consentement obligatoire, avec le reste du formulaire dans un groupe dont le relevant porte sur consent = yes, rend impossible de continuer après un refus.","MEAL Planning":"Planification MEAL","Theory of Change, logframes, SMART indicators, indicator reference sheets and the MEAL plan.":"Théorie du changement, cadres logiques, indicateurs SMART, fiches de référence des indicateurs et plan MEAL.","Theory of Change and the results chain":"La théorie du changement et la chaîne des résultats","Explain the five levels of the results chain and how they connect":"Expliquer les cinq niveaux de la chaîne des résultats et leurs liens","Write the if-then logic of a project with its assumptions and risks":"Rédiger la logique « si… alors » d'un projet avec ses hypothèses et ses risques","Place project statements at the right results level":"Placer les énoncés d'un projet au bon niveau de résultat","Every project is a bet: if we do these things, then these changes will follow. A Theory of Change makes that bet explicit, so the team, the donor and the communities can see how the work is supposed to lead to results, and so the MEAL team knows what to measure at each step.":"Tout projet est un pari : si nous menons ces actions, alors ces changements suivront. Une théorie du changement rend ce pari explicite, afin que l'équipe, le bailleur et les communautés voient comment le travail est censé produire des résultats, et que l'équipe MEAL sache quoi mesurer à chaque étape.","What a Theory of Change is":"Qu'est-ce qu'une théorie du changement ?","A Theory of Change is a short narrative and a diagram that explain how and why a set of activities should lead to a long-term change. It starts from the problem, names the change you want, and traces the pathway backwards to what the project will actually do. It also states the assumptions: the conditions that must hold for each step to lead to the next. The logframe in the next lesson is a more compact, table version of the same logic.":"Une théorie du changement est un court récit accompagné d'un schéma qui expliquent comment et pourquoi un ensemble d'activités doit mener à un changement à long terme. Elle part du problème, nomme le changement souhaité, puis remonte le chemin jusqu'à ce que le projet fera concrètement. Elle énonce aussi les hypothèses : les conditions qui doivent être réunies pour que chaque étape mène à la suivante. Le cadre logique, vu dans la leçon suivante, est une version plus compacte, sous forme de tableau, de la même logique.","The results chain":"La chaîne des résultats","Question it answers":"Question à laquelle il répond","Example: girls' education in the Far North":"Exemple : l'éducation des filles dans l'Extrême-Nord","Who controls it":"Qui le maîtrise","Inputs":"Intrants","What resources do we use?":"Quelles ressources utilisons-nous ?","Budget of 95 000 000 FCFA, 6 staff, school kits, a vehicle":"Budget de 95 000 000 FCFA, 6 employés, kits scolaires, un véhicule","The project":"Le projet","Activities":"Activités","What do we do?":"Que faisons-nous ?","Train teachers, run parent sessions, distribute kits, pay fees for the poorest girls":"Former les enseignants, animer des séances avec les parents, distribuer des kits, payer les frais de scolarité des filles les plus pauvres","Outputs":"Extrants","What do we deliver directly?":"Que livrons-nous directement ?","120 teachers trained, 2 400 girls receive kits, 40 parent sessions held":"120 enseignants formés, 2 400 filles reçoivent des kits, 40 séances avec les parents tenues","The project, mostly":"Le projet, pour l'essentiel","Outcomes":"Effets","What changes for people?":"Qu'est-ce qui change pour les personnes ?","More girls enrol and stay in school; parents support girls' schooling":"Davantage de filles s'inscrivent et restent à l'école ; les parents soutiennent la scolarisation des filles","Shared with communities and partners":"Partagé avec les communautés et les partenaires","Impact":"Impact","What long-term change do we contribute to?":"À quel changement à long terme contribuons-nous ?","Girls complete primary school and have better life chances":"Les filles achèvent l'école primaire et ont de meilleures chances dans la vie","Many actors over many years":"De nombreux acteurs sur de nombreuses années","Control goes down as you go up":"Plus on monte, moins on maîtrise","A project controls its inputs, activities and outputs. Outcomes depend on people choosing to change, and impact depends on many actors. That is why you are accountable for outputs, you manage towards outcomes, and you contribute to impact.":"Un projet maîtrise ses intrants, ses activités et ses extrants. Les effets dépendent de la volonté des personnes de changer, et l'impact dépend de nombreux acteurs. C'est pourquoi vous rendez compte des extrants, vous pilotez vers les effets et vous contribuez à l'impact.","If-then logic, assumptions and risks":"Logique « si… alors », hypothèses et risques","Read the chain from the bottom up as a series of if-then statements. Each arrow hides an assumption. For the girls' education example:":"Lisez la chaîne de bas en haut comme une série d'énoncés « si… alors ». Chaque flèche cache une hypothèse. Pour l'exemple de l'éducation des filles :","If teachers are trained in gender-sensitive teaching and girls receive kits, then girls feel welcome and equipped in class (assumption: trained teachers stay in their posts).":"Si les enseignants sont formés à une pédagogie sensible au genre et si les filles reçoivent des kits, alors les filles se sentent bien accueillies et équipées en classe (hypothèse : les enseignants formés restent à leur poste).","If girls feel welcome and parents see the value of school, then more girls enrol and fewer drop out (assumption: schools stay open and the security situation allows travel to school).":"Si les filles se sentent bien accueillies et si les parents voient l'intérêt de l'école, alors davantage de filles s'inscrivent et moins abandonnent (hypothèse : les écoles restent ouvertes et la situation sécuritaire permet de se rendre à l'école).","If more girls stay in school, then more girls complete primary school (assumption: families do not face a new food crisis that pushes girls into work or early marriage).":"Si davantage de filles restent à l'école, alors davantage de filles achèvent l'école primaire (hypothèse : les familles ne subissent pas une nouvelle crise alimentaire qui pousse les filles vers le travail ou le mariage précoce).","Assumption":"Hypothèse","A condition outside the project's control that must hold for the next level to follow":"Une condition hors du contrôle du projet qui doit être réunie pour que le niveau suivant se réalise","Schools remain open during the school year":"Les écoles restent ouvertes pendant l'année scolaire","Something that could happen and stop the chain; the opposite of an assumption":"Un événement qui pourrait survenir et interrompre la chaîne ; l'inverse d'une hypothèse","Armed attacks close schools in two communes":"Des attaques armées ferment les écoles dans deux communes","Mitigation":"Mesure d'atténuation","What the project does to reduce a risk it cannot control":"Ce que fait le projet pour réduire un risque qu'il ne maîtrise pas","Agree temporary learning spaces with the inspectorate":"Convenir d'espaces d'apprentissage temporaires avec l'inspection","Build a Theory of Change with your team":"Construire une théorie du changement avec votre équipe","Agree on the problem and its main causes, using needs assessment data and community consultations.":"Mettez-vous d'accord sur le problème et ses principales causes, à partir des données de l'évaluation des besoins et des consultations communautaires.","Write the long-term change you want to contribute to (impact) in one sentence.":"Formulez en une phrase le changement à long terme auquel vous voulez contribuer (impact).","Work backwards: which changes in behaviour or practice (outcomes) must happen first, and which products and services (outputs) will cause them?":"Remontez le chemin : quels changements de comportement ou de pratique (effets) doivent se produire d'abord, et quels produits et services (extrants) les provoqueront ?","List the activities and inputs needed to deliver each output.":"Listez les activités et les intrants nécessaires pour livrer chaque extrant.","Under each arrow, write the assumption that must hold, and check it with people who know the context.":"Sous chaque flèche, écrivez l'hypothèse qui doit se vérifier, et validez-la avec des personnes qui connaissent le contexte.","Draw the diagram on one page and review it at least once a year as you learn.":"Dessinez le schéma sur une page et révisez-le au moins une fois par an, au fil de vos apprentissages.","SmartArt":"SmartArt","In Word or PowerPoint, a Process layout gives a quick first diagram of the results chain.":"Dans Word ou PowerPoint, une disposition de type Processus donne rapidement un premier schéma de la chaîne des résultats.","A health NGO in Maroua reports each quarter that it trained 60 community health workers and held 300 awareness sessions. The donor asks: did more women give birth in a health facility? The team had only planned output indicators. With a Theory of Change drawn at the start, the outcome would have been clear and measured from the baseline.":"Une ONG de santé à Maroua rapporte chaque trimestre qu'elle a formé 60 agents de santé communautaires et tenu 300 séances de sensibilisation. Le bailleur demande : davantage de femmes ont-elles accouché dans une formation sanitaire ? L'équipe n'avait prévu que des indicateurs d'extrant. Avec une théorie du changement dessinée dès le départ, l'effet attendu aurait été clair et mesuré depuis la situation de référence.","Place each statement at the right level":"Placez chaque énoncé au bon niveau","A fictional maternal health project works in one health district of the Far North. Choose the results level of each statement.":"Un projet fictif de santé maternelle intervient dans un district de santé de l'Extrême-Nord. Choisissez le niveau de résultat de chaque énoncé.","Ask: is it a resource (input), something the team does (activity), something delivered and counted (output), a change in what people do (outcome), or a long-term change in health (impact)?":"Demandez-vous : est-ce une ressource (intrant), une action de l'équipe (activité), un élément livré et compté (extrant), un changement dans ce que font les personnes (effet) ou un changement durable de la santé (impact) ?","A budget of 18 000 000 FCFA for delivery kits and training":"Un budget de 18 000 000 FCFA pour des kits d'accouchement et des formations","Money, staff and materials are inputs.":"L'argent, le personnel et le matériel sont des intrants.","Activity":"Activité","Outcome":"Effet","Train community health workers on danger signs in pregnancy":"Former les agents de santé communautaires aux signes de danger pendant la grossesse","A verb describing what the team does is an activity.":"Un verbe qui décrit ce que fait l'équipe correspond à une activité.","45 community health workers trained on danger signs in pregnancy":"45 agents de santé communautaires formés aux signes de danger pendant la grossesse","The direct, countable product of the training is an output.":"Le produit direct et dénombrable de la formation est un extrant.","2 400 home visits made to pregnant women":"2 400 visites à domicile effectuées auprès de femmes enceintes","Visits delivered by the project are outputs, even when the number is large.":"Les visites réalisées par le projet sont des extrants, même quand leur nombre est élevé.","More pregnant women attend at least four antenatal visits":"Davantage de femmes enceintes effectuent au moins quatre consultations prénatales","A change in what women do is an outcome.":"Un changement dans ce que font les femmes est un effet.","Fewer mothers die from pregnancy-related causes in the district":"Moins de mères meurent de causes liées à la grossesse dans le district","A long-term change in health status is impact, to which many actors contribute.":"Un changement durable de l'état de santé relève de l'impact, auquel de nombreux acteurs contribuent.","Which statement is an assumption between the outputs and the outcomes?":"Quel énoncé est une hypothèse entre les extrants et les effets ?","Women will only keep using the facility if staff are there. The project does not control staffing, so it is an assumption to monitor.":"Les femmes ne continueront à fréquenter la formation sanitaire que si le personnel est présent. Le projet ne maîtrise pas la dotation en personnel : c'est donc une hypothèse à suivre.","45 health workers are trained":"45 agents de santé sont formés","Health facilities have midwives on duty when women arrive":"Les formations sanitaires ont des sages-femmes de garde à l'arrivée des femmes","The project buys delivery kits":"Le projet achète des kits d'accouchement","Maternal deaths fall":"Les décès maternels diminuent","A water project reports: \"20 boreholes drilled and handed over to water committees\". At which level is this result?":"Un projet d'eau rapporte : « 20 forages réalisés et remis aux comités de gestion de l'eau ». À quel niveau se situe ce résultat ?","Boreholes built and handed over are delivered by the project, so they are outputs. The outcome would be households using safe water from them.":"Les forages construits et remis sont livrés par le projet : ce sont donc des extrants. L'effet serait que les ménages utilisent l'eau potable qu'ils fournissent.","Pick a project you know and write its impact in one sentence":"Choisissez un projet que vous connaissez et formulez son impact en une phrase","List two outcomes and three outputs that lead to that impact":"Listez deux effets et trois extrants qui mènent à cet impact","Write the chain as three if-then sentences":"Écrivez la chaîne sous forme de trois phrases « si… alors »","Add one assumption under each arrow and one risk with its mitigation":"Ajoutez une hypothèse sous chaque flèche et un risque avec sa mesure d'atténuation","Draw the chain on one page with SmartArt or on paper":"Dessinez la chaîne sur une page avec SmartArt ou sur papier","Develop programme theory / theory of change":"Développer la théorie du programme / théorie du changement","Logframes and SMART indicators":"Cadres logiques et indicateurs SMART","Read and complete the four columns of a logframe":"Lire et compléter les quatre colonnes d'un cadre logique","Distinguish output, outcome and impact indicators":"Distinguer les indicateurs d'extrant, d'effet et d'impact","Rewrite weak indicators so that they are SMART and disaggregated":"Reformuler des indicateurs faibles pour les rendre SMART et désagrégés","Most donors ask for a logical framework, or logframe: a one- or two-page table that summarises the project. It turns the Theory of Change into rows (the results levels) and columns (how you will know each result was achieved, and what must hold for it).":"La plupart des bailleurs demandent un cadre logique : un tableau d'une ou deux pages qui résume le projet. Il transforme la théorie du changement en lignes (les niveaux de résultat) et en colonnes (comment vous saurez que chaque résultat est atteint, et ce qui doit se vérifier pour qu'il le soit).","The 4×4 logframe":"Le cadre logique 4×4","Narrative summary":"Logique d'intervention","Indicators":"Indicateurs","Means of verification":"Sources de vérification","Assumptions":"Hypothèses","Impact (goal)":"Impact (objectif global)","Girls in 3 communes complete primary school":"Les filles de 3 communes achèvent l'école primaire","Primary completion rate of girls":"Taux d'achèvement du primaire des filles","School statistics from the sub-divisional inspectorate":"Statistiques scolaires de l'inspection d'arrondissement","Outcome (purpose)":"Effet (objectif spécifique)","More girls enrol and stay in school":"Davantage de filles s'inscrivent et restent à l'école","% of enrolled girls who finish the school year":"% des filles inscrites qui terminent l'année scolaire","School registers, checked by term":"Registres scolaires, vérifiés chaque trimestre","Schools stay open; families do not face a new food crisis":"Les écoles restent ouvertes ; les familles ne subissent pas de nouvelle crise alimentaire","Teachers trained; girls equipped; parents engaged":"Enseignants formés ; filles équipées ; parents mobilisés","Number of teachers trained (by sex); number of girls receiving kits":"Nombre d'enseignants formés (par sexe) ; nombre de filles recevant des kits","Training attendance sheets; distribution lists":"Feuilles de présence aux formations ; listes de distribution","Trained teachers stay in their posts":"Les enseignants formés restent à leur poste","Train teachers; distribute kits; run parent sessions":"Former les enseignants ; distribuer les kits ; animer les séances avec les parents","Budget and schedule (often shown instead of indicators)":"Budget et calendrier (souvent indiqués à la place des indicateurs)","Financial reports; activity reports":"Rapports financiers ; rapports d'activité","Kits arrive before the school year starts":"Les kits arrivent avant la rentrée scolaire","Read it in two directions. Vertically, each level plus its assumptions leads to the level above: if activities are done and the assumptions hold, then outputs are delivered, and so on. Horizontally, each result has an indicator that shows it was achieved and a means of verification that says where the evidence will come from.":"Lisez-le dans deux directions. Verticalement, chaque niveau, avec ses hypothèses, mène au niveau supérieur : si les activités sont réalisées et que les hypothèses se vérifient, alors les extrants sont livrés, et ainsi de suite. Horizontalement, chaque résultat a un indicateur qui montre qu'il est atteint et une source de vérification qui indique d'où viendront les preuves.","Output, outcome and impact indicators":"Indicateurs d'extrant, d'effet et d'impact","What it measures":"Ce qu'il mesure","Usual frequency":"Fréquence habituelle","What the project delivered":"Ce que le projet a livré","Number of hygiene kits distributed":"Nombre de kits d'hygiène distribués","Monthly, from project records":"Mensuelle, à partir des dossiers du projet","Changes in knowledge, practice, access or use":"Changements de connaissances, de pratiques, d'accès ou d'utilisation","% of households washing hands with soap at key times":"% des ménages qui se lavent les mains au savon aux moments clés","Baseline, midline, endline surveys":"Enquêtes de référence, de mi-parcours et finale","Long-term changes in well-being":"Changements durables du bien-être","Prevalence of diarrhoea among children under 5":"Prévalence de la diarrhée chez les enfants de moins de 5 ans","Start and end, often from national surveys":"Au début et à la fin, souvent à partir d'enquêtes nationales","SMART criteria":"Critères SMART","Letter":"Lettre","Question to ask":"Question à poser","Specific":"Spécifique","Does it say exactly what is measured and among whom?":"Dit-il exactement ce qui est mesuré, et auprès de qui ?","Measurable":"Mesurable","Can two people count it and get the same value?":"Deux personnes peuvent-elles le compter et obtenir la même valeur ?","Achievable":"Atteignable","Is the target realistic with this budget and time?":"La cible est-elle réaliste avec ce budget et ce délai ?","Relevant":"Pertinent","Does it really show the result it sits next to?":"Montre-t-il vraiment le résultat auquel il est associé ?","Time-bound":"Temporellement défini","Does it say by when, or over what period?":"Précise-t-il pour quand, ou sur quelle période ?","Weak indicator":"Indicateur faible","SMART version":"Version SMART","Improved hygiene in the camp":"Amélioration de l'hygiène dans le camp","% of refugee households in the camp with soap and water at the handwashing station, observed during the endline survey (target 70% by June 2027)":"% des ménages réfugiés du camp disposant de savon et d'eau au dispositif de lavage des mains, observé lors de l'enquête finale (cible : 70 % d'ici juin 2027)","Farmers trained":"Agriculteurs formés","Number of farmers (by sex and age group) who completed at least 3 of the 4 training sessions on improved maize practices by December 2026":"Nombre d'agriculteurs (par sexe et tranche d'âge) ayant suivi au moins 3 des 4 séances de formation sur les pratiques améliorées de culture du maïs d'ici décembre 2026","Better access to health care":"Meilleur accès aux soins de santé","% of pregnant women in the target health areas who attended at least 4 antenatal visits during the reporting year":"% des femmes enceintes des aires de santé ciblées ayant effectué au moins 4 consultations prénatales pendant l'année de rapportage","Disaggregation and proxy indicators":"Désagrégation et indicateurs indirects","Disaggregate people-level indicators at least by sex and age group. Add disability status, location and displacement status (host community, IDP, refugee) when they matter for your project.":"Désagrégez les indicateurs portant sur des personnes au moins par sexe et par tranche d'âge. Ajoutez la situation de handicap, la localisation et le statut de déplacement (communauté hôte, PDI, réfugié) lorsqu'ils comptent pour votre projet.","Plan disaggregation at design time: the questionnaire and registers must collect sex, age and location, or you cannot split the data later.":"Planifiez la désagrégation dès la conception : le questionnaire et les registres doivent recueillir le sexe, l'âge et la localisation, sinon vous ne pourrez pas ventiler les données plus tard.","Use a proxy indicator when the real result is too costly or sensitive to measure directly, for example the number of meals eaten per day as a proxy for food security, or household assets as a proxy for income.":"Utilisez un indicateur indirect (proxy) lorsque le résultat réel est trop coûteux ou trop sensible à mesurer directement, par exemple le nombre de repas par jour comme indicateur indirect de la sécurité alimentaire, ou les biens du ménage comme indicateur indirect du revenu.","Keep indicators few: two or three per result are usually enough. Each indicator costs time and money to collect.":"Limitez le nombre d'indicateurs : deux ou trois par résultat suffisent généralement. Chaque indicateur coûte du temps et de l'argent à collecter.","Do not mix levels":"Ne mélangez pas les niveaux","\"Number of people trained\" is an output indicator even if it sits in the outcome row of a draft logframe. An outcome indicator needs evidence that people changed what they know, do or use.":"« Nombre de personnes formées » est un indicateur d'extrant, même s'il figure dans la ligne des effets d'une version provisoire du cadre logique. Un indicateur d'effet exige la preuve que les personnes ont changé ce qu'elles savent, font ou utilisent.","In Word, a table with 5 columns and 5 rows gives a header row plus the four logframe levels.":"Dans Word, un tableau de 5 colonnes et 5 lignes donne une ligne d'en-tête plus les quatre niveaux du cadre logique.","An INGO in Bertoua prepares a proposal for a refugee livelihoods project in the East. The donor's template asks for sex- and age-disaggregated indicators and adds displacement status. The MEAL officer adds a \"refugee / host\" question to every registration form from the first day, so each report can show whether both communities benefit.":"Une ONG internationale basée à Bertoua prépare une proposition pour un projet de moyens de subsistance en faveur des réfugiés dans l'Est. Le modèle du bailleur demande des indicateurs désagrégés par sexe et par âge, et ajoute le statut de déplacement. Le chargé MEAL ajoute une question « réfugié / hôte » à chaque formulaire d'enregistrement dès le premier jour, afin que chaque rapport puisse montrer si les deux communautés en bénéficient.","Choose the SMART indicator":"Choisissez l'indicateur SMART","For each result, choose the indicator that is the most SMART. All projects are fictional.":"Pour chaque résultat, choisissez l'indicateur le plus SMART. Tous les projets sont fictifs.","Look for what is counted, among whom, where, and by when. Vague verbs such as \"improve\" or \"strengthen\" are not measurable on their own.":"Cherchez ce qui est compté, auprès de qui, où et pour quand. Des verbes vagues comme « améliorer » ou « renforcer » ne sont pas mesurables en eux-mêmes.","Result: mothers practise exclusive breastfeeding":"Résultat : les mères pratiquent l'allaitement maternel exclusif","It names the group, the measurement, the place, the time and the target.":"Il précise le groupe, la mesure, le lieu, la période et la cible.","Improved infant feeding practices":"Amélioration des pratiques d'alimentation du nourrisson","% of mothers of infants aged 0–5 months in the target health areas who report exclusive breastfeeding in the previous 24 hours, at endline (target 60%)":"% des mères de nourrissons de 0 à 5 mois des aires de santé ciblées qui déclarent un allaitement maternel exclusif au cours des 24 dernières heures, à l'enquête finale (cible : 60 %)","Number of breastfeeding sessions held":"Nombre de séances sur l'allaitement tenues","Mothers are aware of breastfeeding":"Les mères sont sensibilisées à l'allaitement","Result: youth start small businesses":"Résultat : des jeunes créent de petites entreprises","Training is an output. The SMART outcome counts active businesses after a defined period.":"La formation est un extrant. L'effet SMART compte les entreprises actives après une période définie.","Youth empowered economically":"Jeunes autonomisés économiquement","Number of youth trained in entrepreneurship":"Nombre de jeunes formés à l'entrepreneuriat","Number of youth aged 18–30 (by sex) running a business that is still active 6 months after receiving a start-up grant, by March 2027":"Nombre de jeunes de 18 à 30 ans (par sexe) dirigeant une entreprise toujours active 6 mois après avoir reçu une subvention de démarrage, d'ici mars 2027","Youth businesses are successful":"Les entreprises des jeunes réussissent","Result: water committees manage boreholes":"Résultat : les comités de gestion de l'eau gèrent les forages","Functionality after 12 months is an observable sign of good management and has a clear time frame.":"Le fonctionnement après 12 mois est un signe observable d'une bonne gestion et comporte un délai clair.","Committees are strong":"Les comités sont solides","% of project boreholes still functional 12 months after handover, checked in a field visit (target 90%)":"% des forages du projet toujours fonctionnels 12 mois après leur remise, vérifié lors d'une visite de terrain (cible : 90 %)","Number of committees":"Nombre de comités","Good management of water points":"Bonne gestion des points d'eau","Which SMART letter is missing in \"Number of teachers trained in the Adamawa region\"?":"Quelle lettre SMART manque dans « Nombre d'enseignants formés dans la région de l'Adamaoua » ?","There is no period or deadline. Add \"by the end of the 2026–2027 school year\".":"Il n'y a ni période ni échéance. Ajoutez « d'ici la fin de l'année scolaire 2026–2027 ».","\"Number of households receiving seed kits\" is an indicator of which type?":"« Nombre de ménages recevant des kits de semences » est un indicateur de quel type ?","Kits received are delivered by the project, so this is an output indicator.":"Les kits reçus sont livrés par le projet : c'est donc un indicateur d'extrant.","Which is a sensible proxy for household income in a rural survey?":"Quel indicateur indirect du revenu du ménage est judicieux dans une enquête en milieu rural ?","Income is hard to measure accurately, so surveys often use asset ownership as a proxy.":"Le revenu est difficile à mesurer avec précision : les enquêtes utilisent donc souvent la possession de biens comme indicateur indirect.","The number of assets the household owns, such as a radio, bicycle or livestock":"Le nombre de biens que possède le ménage, comme une radio, une bicyclette ou du bétail","The number of project visits":"Le nombre de visites du projet","The household head's age":"L'âge du chef de ménage","The village name":"Le nom du village","Complete the logframe cells":"Complétez les cellules du cadre logique","A fictional malaria project distributes insecticide-treated nets in a health district of the South region. Choose the right content for each empty logframe cell.":"Un projet fictif de lutte contre le paludisme distribue des moustiquaires imprégnées d'insecticide dans un district de santé de la région du Sud. Choisissez le bon contenu pour chaque cellule vide du cadre logique.","Means of verification say where the evidence comes from. Assumptions are outside the project's control. Outcome indicators measure use, not delivery.":"Les sources de vérification indiquent d'où viennent les preuves. Les hypothèses échappent au contrôle du projet. Les indicateurs d'effet mesurent l'utilisation, pas la livraison.","Output \"Households receive nets\": best means of verification":"Extrant « Les ménages reçoivent des moustiquaires » : meilleure source de vérification","Signed distribution lists record every net handed out.":"Les listes de distribution signées enregistrent chaque moustiquaire remise.","Distribution lists signed by each household":"Listes de distribution signées par chaque ménage","The national malaria strategy":"La stratégie nationale de lutte contre le paludisme","An endline focus group":"Un groupe de discussion en fin de projet","The project budget":"Le budget du projet","Outcome \"Children sleep under a net\": best indicator":"Effet « Les enfants dorment sous une moustiquaire » : meilleur indicateur","The outcome is net use, measured by asking about the previous night in a survey.":"L'effet est l'utilisation des moustiquaires, mesurée en posant une question sur la nuit précédente lors d'une enquête.","Number of nets distributed":"Nombre de moustiquaires distribuées","% of children under 5 who slept under a treated net the previous night, from a household survey":"% des enfants de moins de 5 ans ayant dormi sous une moustiquaire imprégnée la nuit précédente, d'après une enquête auprès des ménages","Number of malaria awareness sessions":"Nombre de séances de sensibilisation sur le paludisme","Cost per net":"Coût par moustiquaire","Outcome \"Children sleep under a net\": best means of verification":"Effet « Les enfants dorment sous une moustiquaire » : meilleure source de vérification","Surveys that also observe whether a net is hanging give credible evidence of use.":"Des enquêtes qui observent aussi si une moustiquaire est installée fournissent des preuves crédibles d'utilisation.","Warehouse stock cards":"Fiches de stock de l'entrepôt","Baseline and endline household surveys with observation of nets":"Enquêtes de référence et finale auprès des ménages, avec observation des moustiquaires","The donor's website":"Le site web du bailleur","Staff timesheets":"Feuilles de temps du personnel","Assumption between the output and the outcome":"Hypothèse entre l'extrant et l'effet","Whether people use the nets depends on them, not on the project. It must be written and monitored.":"L'utilisation des moustiquaires dépend des personnes, pas du projet. Cette hypothèse doit être écrite et suivie.","The project buys 30 000 nets":"Le projet achète 30 000 moustiquaires","Households are willing to hang and use the nets rather than sell them":"Les ménages acceptent d'installer et d'utiliser les moustiquaires plutôt que de les vendre","Staff are trained":"Le personnel est formé","The project has a vehicle":"Le projet dispose d'un véhicule","Impact \"Fewer children fall ill with malaria\": best indicator":"Impact « Moins d'enfants tombent malades du paludisme » : meilleur indicateur","Illness rates show the long-term change. Health facility data is the usual source.":"Les taux de morbidité montrent le changement à long terme. Les données des formations sanitaires en sont la source habituelle.","Number of nets per household":"Nombre de moustiquaires par ménage","Malaria cases among children under 5 per 1 000, from health facility data":"Cas de paludisme chez les enfants de moins de 5 ans pour 1 000, d'après les données des formations sanitaires","% of nets distributed on time":"% des moustiquaires distribuées à temps","Number of posters printed":"Nombre d'affiches imprimées","In a logframe, what does the \"means of verification\" column contain?":"Dans un cadre logique, que contient la colonne « sources de vérification » ?","The activities of the project":"Les activités du projet","The source of the data that shows the indicator's value":"La source des données qui montrent la valeur de l'indicateur","The risks that could stop the project":"Les risques qui pourraient arrêter le projet","The budget of each result":"Le budget de chaque résultat","Means of verification say where the evidence comes from: registers, survey reports, attendance sheets, health data and so on.":"Les sources de vérification indiquent d'où viennent les preuves : registres, rapports d'enquête, feuilles de présence, données sanitaires, etc.","Draw an empty 4×4 logframe in Word for the project you used in Lesson 1":"Dessinez dans Word un cadre logique 4×4 vide pour le projet utilisé dans la leçon 1","Fill the narrative summary column from your Theory of Change":"Remplissez la colonne de la logique d'intervention à partir de votre théorie du changement","Write one indicator per level and check each one against the five SMART questions":"Rédigez un indicateur par niveau et vérifiez chacun à l'aide des cinq questions SMART","Add the disaggregation you need for every people-level indicator":"Ajoutez la désagrégation nécessaire pour chaque indicateur portant sur des personnes","Write one assumption per level and one means of verification per indicator":"Rédigez une hypothèse par niveau et une source de vérification par indicateur","Logframe":"Cadre logique","Indicator reference sheets":"Fiches de référence des indicateurs","List the fields of an indicator reference sheet and explain why each one matters":"Énumérer les champs d'une fiche de référence de l'indicateur et expliquer l'utilité de chacun","Define an indicator precisely with its numerator, denominator and unit":"Définir précisément un indicateur avec son numérateur, son dénominateur et son unité","Calculate an indicator value and compare it with its target":"Calculer la valeur d'un indicateur et la comparer à sa cible","An indicator name in a logframe is only a label. Two officers can read \"ANC coverage\" and calculate it in two different ways. The indicator reference sheet (IRS), also called a performance indicator reference sheet (PIRS), is a one-page definition that makes sure everyone measures the same thing, in the same way, every time.":"Le nom d'un indicateur dans un cadre logique n'est qu'une étiquette. Deux chargés peuvent lire « couverture CPN » et la calculer de deux façons différentes. La fiche de référence de l'indicateur (IRS), aussi appelée fiche de référence des indicateurs de performance (PIRS), est une définition d'une page qui garantit que chacun mesure la même chose, de la même manière, à chaque fois.","Why each indicator needs a reference sheet":"Pourquoi chaque indicateur a besoin d'une fiche de référence","Staff change, partners collect data, and projects last several years. Without a written definition, the value reported in year 3 may not be comparable with the baseline. The IRS also forces the team to check early that the data can actually be collected, by whom and at what cost.":"Le personnel change, les partenaires collectent des données et les projets durent plusieurs années. Sans définition écrite, la valeur rapportée en année 3 risque de ne pas être comparable à la situation de référence. L'IRS oblige aussi l'équipe à vérifier tôt que les données peuvent réellement être collectées, par qui et à quel coût.","What to write":"Ce qu'il faut écrire","Definition":"Définition","What exactly is counted, with any terms explained (for example what \"skilled\" or \"functional\" means)":"Ce qui est exactement compté, avec l'explication des termes utilisés (par exemple ce que signifie « qualifié » ou « fonctionnel »)","Numerator / denominator":"Numérateur / dénominateur","For a percentage: who is counted on top, and the total population it is divided by":"Pour un pourcentage : qui est compté au numérateur, et la population totale par laquelle on divise","Number, percentage, ratio, score or FCFA":"Nombre, pourcentage, ratio, score ou FCFA","Data source and method":"Source des données et méthode","Register, survey, observation, health data; how the data is collected":"Registre, enquête, observation, données sanitaires ; manière dont les données sont collectées","Frequency":"Fréquence","How often the value is calculated and reported":"À quelle fréquence la valeur est calculée et rapportée","Responsible":"Responsable","The role that collects, checks and reports the data":"Le rôle qui collecte, vérifie et rapporte les données","Disaggregation":"Désagrégation","Sex, age group, location, displacement status, disability":"Sexe, tranche d'âge, localisation, statut de déplacement, handicap","The value at the start, with its date and source":"La valeur au départ, avec sa date et sa source","Target":"Cible","The value to reach, and by when, with intermediate targets if needed":"La valeur à atteindre, et l'échéance, avec des cibles intermédiaires si nécessaire","Worked example: antenatal care coverage":"Exemple détaillé : la couverture en consultations prénatales","Indicator":"Indicateur","% of pregnant women registered at a first antenatal visit who completed at least 4 antenatal visits":"% des femmes enceintes enregistrées à une première consultation prénatale qui ont effectué au moins 4 consultations prénatales","A woman counts when her antenatal card or the facility register shows 4 or more visits for the same pregnancy":"Une femme est comptée lorsque sa carte de CPN ou le registre de la formation sanitaire indique 4 consultations ou plus pour la même grossesse","Numerator":"Numérateur","Number of women with 4 or more antenatal visits during the period":"Nombre de femmes ayant effectué 4 consultations prénatales ou plus pendant la période","Denominator":"Dénominateur","Number of women registered at a first antenatal visit during the same period":"Nombre de femmes enregistrées à une première consultation prénatale pendant la même période","Antenatal registers of the 4 supported health facilities, compiled monthly":"Registres de CPN des 4 formations sanitaires appuyées, compilés chaque mois","Collected monthly, reported quarterly":"Collecte mensuelle, rapportage trimestriel","Facility midwives collect; the project MEAL officer checks and compiles":"Les sages-femmes des formations sanitaires collectent ; le chargé MEAL du projet vérifie et compile","Health area; age group of the woman (under 20, 20 and over)":"Aire de santé ; tranche d'âge de la femme (moins de 20 ans, 20 ans et plus)","38% (fictional value, January to December 2025 registers)":"38 % (valeur fictive, registres de janvier à décembre 2025)","60% by December 2027":"60 % d'ici décembre 2027","Same people, same period":"Mêmes personnes, même période","The numerator must be a subset of the denominator, taken over the same period and area. Dividing women with 4 visits in one district by first visits in another, or mixing years, gives a number that means nothing.":"Le numérateur doit être un sous-ensemble du dénominateur, pris sur la même période et la même zone. Diviser les femmes ayant 4 consultations dans un district par les premières consultations d'un autre, ou mélanger les années, donne un chiffre qui ne veut rien dire.","Common errors":"Erreurs courantes","A denominator that changes from report to report (all women one quarter, registered women the next).":"Un dénominateur qui change d'un rapport à l'autre (toutes les femmes un trimestre, les femmes enregistrées le suivant).","Averaging percentages of facilities of very different sizes instead of dividing the total numerator by the total denominator.":"Faire la moyenne des pourcentages de formations sanitaires de tailles très différentes au lieu de diviser le numérateur total par le dénominateur total.","A target written in a different unit from the indicator, such as a number of women when the indicator is a percentage.":"Une cible exprimée dans une autre unité que l'indicateur, par exemple un nombre de femmes alors que l'indicateur est un pourcentage.","No baseline, so progress cannot be shown.":"Pas de situation de référence : impossible de montrer les progrès.","Calculate the indicator in Excel":"Calculer l'indicateur dans Excel","Enter the numerator and denominator of each facility or area in two columns.":"Saisissez le numérateur et le dénominateur de chaque formation sanitaire ou zone dans deux colonnes.","Divide the numerator by the denominator on each row, for example =C2/B2.":"Divisez le numérateur par le dénominateur sur chaque ligne, par exemple =C2/B2.","Add the totals with SUM, then divide the total numerator by the total denominator.":"Additionnez les totaux avec SUM (SOMME), puis divisez le numérateur total par le dénominateur total.","Divide the result by the target to get the % of target achieved.":"Divisez le résultat par la cible pour obtenir le % de la cible atteint.","Format the result cells as percentages.":"Mettez les cellules de résultat au format pourcentage.","Shows 0.55 as 55%. The cell still holds 0.55, which is what your formulas use.":"Affiche 0,55 sous la forme 55 %. La cellule contient toujours 0,55, et c'est cette valeur que vos formules utilisent.","Antenatal care coverage by health area":"Couverture en consultations prénatales par aire de santé","Fictional data for the ANC indicator above. Fill":"Données fictives pour l'indicateur CPN ci-dessus. Remplissez","with the coverage of each health area,":"avec la couverture de chaque aire de santé,","with the totals and the overall coverage, and":"avec les totaux et la couverture globale, et","with the % of target achieved.":"avec le % de la cible atteint.","Coverage is numerator divided by denominator: =C2/B2. The overall coverage is =C6/B6, not the average of D2:D5. The % of target achieved is =D6/D7.":"La couverture est le numérateur divisé par le dénominateur : =C2/B2. La couverture globale est =C6/B6, et non la moyenne de D2:D5. Le % de la cible atteint est =D6/D7.","Complete an indicator reference sheet":"Complétez une fiche de référence de l'indicateur","A fictional food assistance project for displaced households in the North-West uses the indicator \"% of targeted households with an acceptable Food Consumption Score (FCS)\". Choose the right content for each field of its reference sheet.":"Un projet fictif d'assistance alimentaire aux ménages déplacés du Nord-Ouest utilise l'indicateur « % des ménages ciblés ayant un score de consommation alimentaire (SCA / FCS) acceptable ». Choisissez le bon contenu pour chaque champ de sa fiche de référence.","The FCS is calculated for each surveyed household. The indicator counts households in the acceptable range, divided by all surveyed households.":"Le FCS est calculé pour chaque ménage enquêté. L'indicateur compte les ménages situés dans la tranche acceptable, divisés par l'ensemble des ménages enquêtés.","Only households in the acceptable range are counted on top.":"Seuls les ménages situés dans la tranche acceptable sont comptés au numérateur.","Number of households that received food vouchers":"Nombre de ménages ayant reçu des bons alimentaires","Number of surveyed targeted households whose FCS is in the acceptable range":"Nombre de ménages ciblés enquêtés dont le FCS est dans la tranche acceptable","Average FCS of surveyed households":"FCS moyen des ménages enquêtés","Total number of households in the commune":"Nombre total de ménages de la commune","The denominator is all surveyed targeted households, including those with poor or borderline scores.":"Le dénominateur comprend tous les ménages ciblés enquêtés, y compris ceux dont le score est pauvre ou limite.","Number of targeted households surveyed in the same round":"Nombre de ménages ciblés enquêtés lors du même passage","Number of vouchers printed":"Nombre de bons imprimés","Number of enumerators":"Nombre d'enquêteurs","Population of the region":"Population de la région","FCFA":"FCFA","Number of meals":"Nombre de repas","Kilograms":"Kilogrammes","The FCS is built from a 7-day food recall asked in a household survey.":"Le FCS est construit à partir d'un rappel alimentaire sur 7 jours posé lors d'une enquête auprès des ménages.","Distribution lists":"Listes de distribution","Household survey on a random sample of targeted households, asking about foods eaten in the last 7 days":"Enquête auprès des ménages sur un échantillon aléatoire de ménages ciblés, portant sur les aliments consommés au cours des 7 derniers jours","The warehouse stock report":"Le rapport de stock de l'entrepôt","Staff interviews":"Entretiens avec le personnel","Post-distribution monitoring after each cycle lets the team react during the project, not only at the end.":"Le suivi post-distribution après chaque cycle permet à l'équipe de réagir pendant le projet, et pas seulement à la fin.","Every day":"Tous les jours","Baseline, then after each distribution cycle and at endline":"Situation de référence, puis après chaque cycle de distribution et à l'enquête finale","Once, at the end only":"Une seule fois, à la fin uniquement","Whenever a staff member has time":"Quand un membre du personnel a le temps","Most useful disaggregation for this project":"Désagrégation la plus utile pour ce projet","Comparing female- and male-headed households, and IDPs and hosts, shows who is being left behind.":"Comparer les ménages dirigés par une femme et par un homme, ainsi que les PDI et les hôtes, montre qui est laissé pour compte.","Colour of the voucher":"Couleur du bon","Sex of the household head and displacement status (IDP / host)":"Sexe du chef de ménage et statut de déplacement (PDI / hôte)","Enumerator's name":"Nom de l'enquêteur","Day of the week":"Jour de la semaine","In a health district of the Far North, a project and the district team both report ANC coverage. The project divides by women registered at ANC1; the district divides by the estimated number of pregnancies in the population. Neither is wrong, but the figures differ by 20 points. Writing the definition in the IRS, and noting the difference in reports, avoids a painful meeting with the donor.":"Dans un district de santé de l'Extrême-Nord, un projet et l'équipe du district rapportent tous deux la couverture CPN. Le projet divise par les femmes enregistrées en CPN1 ; le district divise par le nombre estimé de grossesses dans la population. Aucun n'a tort, mais les chiffres diffèrent de 20 points. Écrire la définition dans l'IRS, et signaler la différence dans les rapports, évite une réunion pénible avec le bailleur.","Facility A has 90 of 100 children vaccinated and facility B has 10 of 50. What is the overall vaccination coverage?":"La formation sanitaire A compte 90 enfants vaccinés sur 100 et la formation sanitaire B 10 sur 50. Quelle est la couverture vaccinale globale ?","55%, the average of 90% and 20%":"55 %, la moyenne de 90 % et 20 %","66.7%, 100 vaccinated out of 150":"66,7 %, soit 100 vaccinés sur 150","Add the numerators and the denominators, then divide: 100 ÷ 150 = 66.7%. Averaging the two percentages ignores that facility A serves twice as many children.":"Additionnez les numérateurs et les dénominateurs, puis divisez : 100 ÷ 150 = 66,7 %. Faire la moyenne des deux pourcentages ignore que la formation sanitaire A dessert deux fois plus d'enfants.","Choose one outcome indicator from your logframe":"Choisissez un indicateur d'effet dans votre cadre logique","Write its full reference sheet using the nine fields in this lesson":"Rédigez sa fiche de référence complète à l'aide des neuf champs de cette leçon","Check that the numerator is a subset of the denominator":"Vérifiez que le numérateur est un sous-ensemble du dénominateur","Ask a colleague to calculate the indicator from your sheet alone and compare results":"Demandez à un collègue de calculer l'indicateur à partir de votre seule fiche et comparez les résultats","Recommended performance indicator reference sheet":"Fiche de référence des indicateurs de performance recommandée","The MEAL plan: methods, calendar, roles and budget":"Le plan MEAL : méthodes, calendrier, rôles et budget","Build a MEAL plan table that links each indicator to a method, frequency and owner":"Construire un tableau du plan MEAL qui relie chaque indicateur à une méthode, une fréquence et un responsable","Draw up a data collection and reporting calendar":"Établir un calendrier de collecte des données et de rapportage","Estimate a MEAL budget and check it against the 5–10% rule of thumb":"Estimer un budget MEAL et le comparer à la règle empirique des 5–10 %","The logframe says what you will measure; the MEAL plan says how, when, by whom and at what cost. It is the working document the MEAL team uses every week, and the first thing an auditor or donor monitor asks to see.":"Le cadre logique dit ce que vous allez mesurer ; le plan MEAL dit comment, quand, par qui et à quel coût. C'est le document de travail que l'équipe MEAL utilise chaque semaine, et la première chose que demande à voir un auditeur ou un chargé de suivi du bailleur.","The MEAL plan table":"Le tableau du plan MEAL","Method and tool":"Méthode et outil","Used for":"Utilisé pour","Number of teachers trained (by sex)":"Nombre d'enseignants formés (par sexe)","Attendance sheets entered in Excel":"Feuilles de présence saisies dans Excel","After each training":"Après chaque formation","Education officer":"Chargé de l'éducation","Monthly report":"Rapport mensuel","School register review in KoboToolbox":"Revue des registres scolaires dans KoboToolbox","Each term":"Chaque trimestre","MEAL assistant with head teachers":"Assistant MEAL avec les directeurs d'école","Quarterly review, donor report":"Revue trimestrielle, rapport au bailleur","Parents' attitudes to girls' schooling":"Attitudes des parents envers la scolarisation des filles","Focus group discussions and key informant interviews":"Groupes de discussion (FGD) et entretiens avec des informateurs clés (KII)","Baseline and endline":"Situation de référence et enquête finale","MEAL officer":"Chargé MEAL","Evaluation, learning workshop":"Évaluation, atelier d'apprentissage","Complaints received and resolved":"Plaintes reçues et traitées","Hotline and suggestion boxes, complaints log":"Ligne verte et boîtes à suggestions, registre des plaintes","Continuous, reviewed monthly":"En continu, revu chaque mois","Accountability officer":"Chargé de la redevabilité","Management meeting":"Réunion de direction","Choosing methods":"Choisir les méthodes","Routine monitoring from project records (registers, distribution lists, attendance sheets) for output indicators.":"Suivi de routine à partir des dossiers du projet (registres, listes de distribution, feuilles de présence) pour les indicateurs d'extrant.","Household or individual surveys on a sample for outcome indicators at baseline, midline and endline.":"Enquêtes auprès des ménages ou des individus sur un échantillon pour les indicateurs d'effet, en situation de référence, à mi-parcours et en fin de projet.","Focus group discussions and key informant interviews to understand why things change or do not.":"Groupes de discussion et entretiens avec des informateurs clés pour comprendre pourquoi les choses changent ou non.","Post-distribution monitoring after cash, voucher or in-kind distributions.":"Suivi post-distribution après les distributions d'espèces, de bons ou en nature.","A complaints and feedback mechanism that runs all the time, not only during surveys.":"Un mécanisme de gestion des plaintes et des retours (MGP) qui fonctionne en permanence, pas seulement pendant les enquêtes.","In KoboToolbox, start a new form for a survey or a monitoring checklist. Forms work offline once downloaded to the phone.":"Dans KoboToolbox, créez un nouveau formulaire pour une enquête ou une liste de contrôle de suivi. Une fois téléchargés sur le téléphone, les formulaires fonctionnent hors ligne.","The data collection calendar":"Le calendrier de collecte des données","Baseline survey":"Enquête de référence","Monthly monitoring of outputs":"Suivi mensuel des extrants","Post-distribution monitoring":"Suivi post-distribution","Quarterly review meeting":"Réunion de revue trimestrielle","Annual learning workshop":"Atelier annuel d'apprentissage","Plan around the context":"Planifiez en fonction du contexte","Avoid field surveys during the peak rainy season when roads are cut, during exams for school surveys, and during major religious holidays. Plan enough time for data entry and cleaning before each report deadline.":"Évitez les enquêtes de terrain au plus fort de la saison des pluies, quand les routes sont coupées, pendant les examens pour les enquêtes en milieu scolaire, et pendant les grandes fêtes religieuses. Prévoyez assez de temps pour la saisie et le nettoyage des données avant chaque échéance de rapport.","Roles and responsibilities":"Rôles et responsabilités","Main MEAL responsibilities":"Principales responsabilités MEAL","Uses the data for decisions; approves the MEAL plan and reports":"Utilise les données pour décider ; approuve le plan MEAL et les rapports","Writes the MEAL plan and IRS, designs tools, trains enumerators, checks data quality, analyses and reports":"Rédige le plan MEAL et les IRS, conçoit les outils, forme les enquêteurs, contrôle la qualité des données, analyse et rédige les rapports","Field staff and partners":"Personnel de terrain et partenaires","Fill registers and monitoring forms correctly and on time":"Remplissent correctement et à temps les registres et les formulaires de suivi","Enumerators":"Enquêteurs","Collect survey data following the protocol and consent rules":"Collectent les données d'enquête en respectant le protocole et les règles de consentement","Communities":"Communautés","Give feedback, take part in reviews and hear the results":"Donnent leur avis, participent aux revues et sont informées des résultats","Budgeting MEAL":"Budgétiser le MEAL","A common rule of thumb is to plan about 5–10% of the total project budget for MEAL. Small projects with a large external evaluation may need more; large delivery projects with simple outputs may need less. What matters is that each activity in the MEAL plan has a line in the budget.":"Une règle empirique courante consiste à prévoir environ 5–10 % du budget total du projet pour le MEAL. Les petits projets avec une grande évaluation externe peuvent avoir besoin de plus ; les grands projets de mise en œuvre aux extrants simples peuvent avoir besoin de moins. L'essentiel est que chaque activité du plan MEAL ait une ligne dans le budget.","Staff: MEAL officer and assistants, or the share of their time charged to the project.":"Personnel : chargé MEAL et assistants, ou la part de leur temps imputée au projet.","Surveys: enumerator allowances, transport, training, printing, phones or tablets and power banks.":"Enquêtes : indemnités des enquêteurs, transport, formation, impression, téléphones ou tablettes et batteries externes.","Evaluation: external consultant fees for a midterm or final evaluation.":"Évaluation : honoraires de consultants externes pour une évaluation à mi-parcours ou finale.","Accountability and learning: hotline, suggestion boxes, review meetings and learning workshops.":"Redevabilité et apprentissage : ligne verte, boîtes à suggestions, réunions de revue et ateliers d'apprentissage.","Check a MEAL budget":"Vérifiez un budget MEAL","A fictional 3-year education project has a total budget of 320 000 000 FCFA. Fill":"Un projet fictif d'éducation sur 3 ans a un budget total de 320 000 000 FCFA. Remplissez","with the total MEAL budget,":"avec le budget MEAL total,","with its share of the project budget,":"avec sa part dans le budget du projet,","with \"OK\" if the share is between 5% and 10% (inclusive) and \"Review\" otherwise, and":"avec \"OK\" si cette part est comprise entre 5 % et 10 % (inclus) et \"Review\" (à revoir) sinon, et","with the share of the MEAL budget spent on the final evaluation.":"avec la part du budget MEAL consacrée à l'évaluation finale.","B8 is a SUM of B2:B7. B10 divides B8 by B9. B11 needs IF with AND: =IF(AND(B10>=5%,B10<=10%),\"OK\",\"Review\"). B12 is the evaluation line divided by the MEAL total.":"B8 est une somme (SUM) de B2:B7. B10 divise B8 par B9. B11 nécessite IF (SI) avec AND (ET) : =IF(AND(B10>=5%,B10<=10%),\"OK\",\"Review\"). B12 est la ligne de l'évaluation divisée par le total MEAL.","The reporting cycle":"Le cycle de rapportage","Monthly: field teams submit activity data; the MEAL officer checks and updates the indicator tracking table.":"Chaque mois : les équipes de terrain transmettent les données d'activité ; le chargé MEAL les vérifie et met à jour le tableau de suivi des indicateurs (ITT).","Quarterly: the team reviews progress against targets and agrees corrective actions; a short report goes to the donor if required.":"Chaque trimestre : l'équipe examine les progrès par rapport aux cibles et convient d'actions correctives ; un court rapport est envoyé au bailleur si nécessaire.","Annually: an annual report, a learning workshop with partners and communities, and an update of the Theory of Change if needed.":"Chaque année : un rapport annuel, un atelier d'apprentissage avec les partenaires et les communautés, et une mise à jour de la théorie du changement si nécessaire.","End of project: final evaluation, final report and sharing of results with communities.":"Fin du projet : évaluation finale, rapport final et partage des résultats avec les communautés.","A local NGO in Bamenda submits a proposal with no MEAL lines apart from a final evaluation. The donor asks for 7% of the budget for MEAL and a MEAL plan. The MEAL officer adds a baseline survey, a half-time assistant, phones for offline KoboToolbox collection and a feedback hotline, and links each line to an indicator in the plan.":"Une ONG locale de Bamenda soumet une proposition sans aucune ligne MEAL en dehors d'une évaluation finale. Le bailleur demande 7 % du budget pour le MEAL et un plan MEAL. Le chargé MEAL ajoute une enquête de référence, un assistant à mi-temps, des téléphones pour la collecte hors ligne avec KoboToolbox et une ligne verte de feedback, et relie chaque ligne à un indicateur du plan.","A project has a total budget of 150 000 000 FCFA. The MEAL lines add up to 4 500 000 FCFA. What does the rule of thumb suggest?":"Un projet a un budget total de 150 000 000 FCFA. Les lignes MEAL totalisent 4 500 000 FCFA. Que suggère la règle empirique ?","The MEAL budget is 3%, below the usual 5–10%: check whether key MEAL activities are missing":"Le budget MEAL représente 3 %, en dessous des 5–10 % habituels : vérifiez s'il manque des activités MEAL essentielles","The MEAL budget is 30%, far too high":"Le budget MEAL représente 30 %, beaucoup trop","The MEAL budget is exactly right at 10%":"Le budget MEAL est exactement correct, à 10 %","MEAL should not have its own budget":"Le MEAL ne devrait pas avoir son propre budget","4 500 000 ÷ 150 000 000 = 3%. That is below the usual range, so check that surveys, staff time and accountability costs are all budgeted.":"4 500 000 ÷ 150 000 000 = 3 %. C'est en dessous de la fourchette habituelle : vérifiez que les enquêtes, le temps du personnel et les coûts de redevabilité sont tous budgétisés.","Turn your logframe indicators into a MEAL plan table with method, frequency, responsible and use":"Transformez les indicateurs de votre cadre logique en un tableau du plan MEAL avec méthode, fréquence, responsable et utilisation","Draw a 12-month data collection calendar that avoids the rainy season peak in your area":"Dessinez un calendrier de collecte des données sur 12 mois qui évite le pic de la saison des pluies dans votre zone","List every MEAL cost and total it in Excel":"Listez tous les coûts MEAL et faites-en le total dans Excel","Calculate the MEAL share of your project budget and compare it with 5–10%":"Calculez la part du MEAL dans le budget de votre projet et comparez-la à 5–10 %","Write who receives each report and when":"Indiquez qui reçoit chaque rapport et quand","Manage an evaluation or evaluation system":"Gérer une évaluation ou un système d'évaluation","Practice lab: planning MEAL for real projects":"Atelier pratique : planifier le MEAL de projets réels","Place results of a livelihoods project on the results chain":"Placer les résultats d'un projet de moyens de subsistance sur la chaîne des résultats","Track output indicators against targets for a nutrition project":"Suivre les indicateurs d'extrant par rapport aux cibles pour un projet de nutrition","Judge indicators, means of verification and assumptions in an education logframe":"Évaluer les indicateurs, les sources de vérification et les hypothèses d'un cadre logique en éducation","Calculate a WASH outcome indicator and analyse progress towards its target":"Calculer un indicateur d'effet WASH et analyser les progrès vers sa cible","Exercise 1: A livelihoods project in the West":"Exercice 1 : un projet de moyens de subsistance dans l'Ouest","Where does each result belong?":"À quel niveau se situe chaque résultat ?","A fictional project supports women's savings groups and poultry farming in the West region. Choose the results level of each statement.":"Un projet fictif appuie des groupes d'épargne de femmes et l'aviculture dans la région de l'Ouest. Choisissez le niveau de résultat de chaque énoncé.","Resources are inputs, verbs are activities, things delivered are outputs, changes in practice or income are outcomes, and long-term well-being is impact.":"Les ressources sont des intrants, les verbes des activités, ce qui est livré des extrants, les changements de pratiques ou de revenus des effets, et le bien-être à long terme relève de l'impact.","Two livelihoods officers and a motorbike":"Deux chargés des moyens de subsistance et une moto","Staff and equipment are inputs.":"Le personnel et l'équipement sont des intrants.","Set up village savings and loan associations":"Mettre en place des associations villageoises d'épargne et de crédit (AVEC)","30 savings groups formed with 750 members":"30 groupes d'épargne constitués avec 750 membres","Groups formed are delivered by the project: an output.":"Les groupes constitués sont livrés par le projet : c'est un extrant.","Group members use loans to start or expand a poultry business":"Les membres des groupes utilisent des prêts pour lancer ou développer un élevage de volailles","A change in what members do is an outcome.":"Un changement dans ce que font les membres est un effet.","Members' households have a higher and more stable income":"Les ménages des membres ont un revenu plus élevé et plus stable","Income change within the project period is usually an outcome. Impact is broader and longer term.":"Un changement de revenu pendant la durée du projet est généralement un effet. L'impact est plus large et à plus long terme.","Poverty falls in the participating communities":"La pauvreté recule dans les communautés participantes","Distribute 5 000 day-old chicks":"Distribuer 5 000 poussins d'un jour","The verb \"distribute\" describes an activity. \"5 000 chicks distributed\" would be an output.":"Le verbe « distribuer » décrit une activité. « 5 000 poussins distribués » serait un extrant.","Exercise 2: Nutrition outputs in the East":"Exercice 2 : extrants de nutrition dans l'Est","Output indicators against targets":"Indicateurs d'extrant par rapport aux cibles","Fictional quarterly data from a nutrition project for refugee and host communities. Fill":"Données trimestrielles fictives d'un projet de nutrition en faveur des communautés réfugiées et hôtes. Remplissez","with the % of target achieved,":"avec le % de la cible atteint,","with \"On track\" when it is at least 90% and \"Behind\" otherwise, and":"avec \"On track\" (en bonne voie) lorsqu'il atteint au moins 90 % et \"Behind\" (en retard) sinon, et","with the number of indicators on track.":"avec le nombre d'indicateurs en bonne voie.","% of target is =C2/B2. The status is =IF(D2>=0.9,\"On track\",\"Behind\"). Count the statuses with COUNTIF(E2:E5,\"On track\"). Values above 100% are possible.":"Le % de la cible est =C2/B2. Le statut est =IF(D2>=0.9,\"On track\",\"Behind\"). Comptez les statuts avec COUNTIF(E2:E5,\"On track\") (NB.SI). Des valeurs supérieures à 100 % sont possibles.","Exercise 3: An education logframe in the North-West":"Exercice 3 : un cadre logique en éducation dans le Nord-Ouest","Review an accelerated learning logframe":"Examinez le cadre logique d'un programme d'apprentissage accéléré","A fictional accelerated learning programme helps out-of-school IDP children aged 9–14 catch up on literacy and numeracy. Review its logframe and answer each question.":"Un programme fictif d'apprentissage accéléré aide des enfants PDI non scolarisés de 9 à 14 ans à rattraper leur retard en lecture-écriture et en calcul. Examinez son cadre logique et répondez à chaque question.","Think about what each column is for, which level an indicator measures, and whether it is SMART. For the calculations, divide first, then compare with the target.":"Réfléchissez au rôle de chaque colonne, au niveau que mesure un indicateur et à son caractère SMART. Pour les calculs, divisez d'abord, puis comparez à la cible.","The outcome \"Children gain basic literacy\" has the indicator \"Number of learners enrolled\". What is wrong?":"L'effet « Les enfants acquièrent des compétences de base en lecture-écriture » a pour indicateur « Nombre d'apprenants inscrits ». Qu'est-ce qui ne va pas ?","Enrolment shows the service reached children. The outcome needs evidence of learning, for example the % of learners passing a literacy test.":"L'inscription montre que le service a atteint les enfants. L'effet exige des preuves d'apprentissage, par exemple le % d'apprenants qui réussissent un test de lecture-écriture.","Nothing, it is a good outcome indicator":"Rien, c'est un bon indicateur d'effet","It measures an output (enrolment), not the change in literacy":"Il mesure un extrant (l'inscription), et non le changement en lecture-écriture","It is not disaggregated by region":"Il n'est pas désagrégé par région","It is an impact indicator":"C'est un indicateur d'impact","Best indicator for \"Children gain basic literacy\"":"Meilleur indicateur pour « Les enfants acquièrent des compétences de base en lecture-écriture »","% of learners (by sex and age) who pass the end-of-cycle reading test, at the end of each 9-month cycle":"% des apprenants (par sexe et par âge) qui réussissent le test de lecture de fin de cycle, à la fin de chaque cycle de 9 mois","Number of reading books distributed":"Nombre de livres de lecture distribués","Learners are happier":"Les apprenants sont plus heureux","Number of teachers recruited":"Nombre d'enseignants recrutés","Best means of verification for that indicator":"Meilleure source de vérification pour cet indicateur","Test results given in the same way to every learner are credible, comparable evidence.":"Des résultats de test administrés de la même façon à chaque apprenant sont des preuves crédibles et comparables.","Enrolment forms":"Fiches d'inscription","Results of a standard reading test given by trained assessors, entered in a database":"Résultats d'un test de lecture standardisé administré par des évaluateurs formés, saisis dans une base de données","Photos of classes":"Photos des classes","The donor contract":"Le contrat avec le bailleur","Which is an assumption, not a result?":"Lequel est une hypothèse, et non un résultat ?","Further displacement is outside the project's control and would break the chain.":"Un nouveau déplacement échappe au contrôle du projet et romprait la chaîne.","Facilitators trained":"Facilitateurs formés","Learning centres equipped":"Centres d'apprentissage équipés","Families do not have to move again during the cycle":"Les familles n'ont pas à se déplacer de nouveau pendant le cycle","Learners pass the reading test":"Les apprenants réussissent le test de lecture","Which disaggregation matters most for this indicator?":"Quelle désagrégation compte le plus pour cet indicateur ?","Girls, older learners and children with disabilities often drop out or struggle more. Without disaggregation you cannot see it.":"Les filles, les apprenants plus âgés et les enfants en situation de handicap abandonnent souvent davantage ou rencontrent plus de difficultés. Sans désagrégation, vous ne pouvez pas le voir.","Sex, age group and disability status":"Sexe, tranche d'âge et situation de handicap","Colour of the classroom":"Couleur de la salle de classe","Name of the facilitator only":"Nom du facilitateur uniquement","None, the total is enough":"Aucune, le total suffit","At the end of the cycle, 208 of 320 learners passed the reading test. Type the pass rate as a whole-number percentage.":"À la fin du cycle, 208 apprenants sur 320 ont réussi le test de lecture. Saisissez le taux de réussite sous forme de pourcentage entier.","208 ÷ 320 = 0.65, so 65% of learners passed.":"208 ÷ 320 = 0,65 : 65 % des apprenants ont donc réussi.","The target is 70%. Type the % of target achieved, rounded to a whole number.":"La cible est de 70 %. Saisissez le % de la cible atteint, arrondi à un nombre entier.","65% ÷ 70% = 0.929, so about 93% of the target is achieved.":"65 % ÷ 70 % = 0,929 : environ 93 % de la cible est donc atteint.","Exercise 4: WASH outcome in the Far North":"Exercice 4 : un effet WASH dans l'Extrême-Nord","From the reference sheet to the target analysis":"De la fiche de référence à l'analyse de la cible","The IRS defines the indicator as surveyed households that treat their drinking water, divided by all surveyed households. Fictional endline data by village is below; one village could not be surveyed. Fill":"L'IRS définit l'indicateur comme les ménages enquêtés qui traitent leur eau de boisson, divisés par l'ensemble des ménages enquêtés. Les données fictives de l'enquête finale par village figurent ci-dessous ; un village n'a pas pu être enquêté. Remplissez","with the overall value,":"avec la valeur globale,","with the value for Mora commune only,":"avec la valeur pour la seule commune de Mora,","with the progress from baseline to target,":"avec la progression de la situation de référence vers la cible,","with the status, and":"avec le statut, et","with the number of villages without data.":"avec le nombre de villages sans données.","Pool the data: =SUM(D2:D8)/SUM(C2:C8), not the average of village percentages. For Mora use SUMIF on column B for both the numerator and the denominator. Progress is (current − baseline) ÷ (target − baseline). Status: \"On track\" from 80% progress, \"Monitor\" from 50%, otherwise \"Off track\" (IFS or nested IF). COUNTBLANK finds the village without data.":"Regroupez les données : =SUM(D2:D8)/SUM(C2:C8), et non la moyenne des pourcentages des villages. Pour Mora, utilisez SUMIF (SOMME.SI) sur la colonne B pour le numérateur comme pour le dénominateur. La progression est (valeur actuelle − référence) ÷ (cible − référence). Statut : \"On track\" (en bonne voie) à partir de 80 % de progression, \"Monitor\" (à surveiller) à partir de 50 %, sinon \"Off track\" (hors trajectoire) (IFS ou IF imbriqués). COUNTBLANK (NB.VIDE) trouve le village sans données.","\"500 hygiene kits distributed\" is a result at which level?":"« 500 kits d'hygiène distribués » est un résultat de quel niveau ?","Kits distributed are delivered directly by the project, so this is an output.":"Les kits distribués sont livrés directement par le projet : c'est donc un extrant.","What is an assumption in a Theory of Change?":"Qu'est-ce qu'une hypothèse dans une théorie du changement ?","An activity the project will carry out":"Une activité que le projet va mener","A target value for an indicator":"Une valeur cible pour un indicateur","The budget of the project":"Le budget du projet","Assumptions link the levels. If they fail, the chain breaks even when the project does everything it planned.":"Les hypothèses relient les niveaux. Si elles ne se vérifient pas, la chaîne se rompt même lorsque le projet fait tout ce qu'il avait prévu.","Which indicator is SMART?":"Quel indicateur est SMART ?","% of targeted farmers (by sex) using improved seed in the 2027 main season, from the endline survey":"% des agriculteurs ciblés (par sexe) utilisant des semences améliorées pendant la grande saison 2027, d'après l'enquête finale","Improved agriculture":"Agriculture améliorée","Farmers are trained well":"Les agriculteurs sont bien formés","More food in the region":"Plus de nourriture dans la région","It is specific about who and what, measurable, relevant and time-bound.":"Il est spécifique quant au qui et au quoi, mesurable, pertinent et temporellement défini.","In a logframe, where do you write \"Distribution lists signed by beneficiaries\"?":"Dans un cadre logique, où écrivez-vous « Listes de distribution signées par les bénéficiaires » ?","It is the source of evidence for an output indicator, so it belongs in the means of verification column.":"C'est la source de preuve d'un indicateur d'extrant : elle va donc dans la colonne des sources de vérification.","Which field of an indicator reference sheet states the value at the start of the project?":"Quel champ d'une fiche de référence de l'indicateur indique la valeur au début du projet ?","The baseline is the starting value, with its date and source. Progress is measured against it.":"La situation de référence est la valeur de départ, avec sa date et sa source. Les progrès sont mesurés par rapport à elle.","What share of the total budget is commonly suggested for MEAL?":"Quelle part du budget total est couramment recommandée pour le MEAL ?","Less than 1%":"Moins de 1 %","About 25–30%":"Environ 25–30 %","Nothing: MEAL is covered by overheads":"Rien : le MEAL est couvert par les frais généraux","About 5–10%":"Environ 5–10 %","About 5–10% is a common rule of thumb. Adjust it to the size of the project and the evaluation needs.":"Environ 5–10 % est une règle empirique courante. Adaptez-la à la taille du projet et aux besoins d'évaluation.","Why must disaggregation be planned at design time?":"Pourquoi la désagrégation doit-elle être planifiée dès la conception ?","Because donors forbid adding it later":"Parce que les bailleurs interdisent de l'ajouter plus tard","Because data collection tools must record sex, age, location or status, or the data cannot be split later":"Parce que les outils de collecte doivent enregistrer le sexe, l'âge, la localisation ou le statut, sinon les données ne pourront pas être ventilées plus tard","Because it reduces the sample size":"Parce qu'elle réduit la taille de l'échantillon","Because it replaces the baseline":"Parce qu'elle remplace la situation de référence","If a register or questionnaire does not record sex or age, nobody can disaggregate the results afterwards.":"Si un registre ou un questionnaire n'enregistre pas le sexe ou l'âge, personne ne peut désagréger les résultats par la suite.","Three health facilities report 30/50, 40/100 and 90/200 children vaccinated. What is the overall coverage?":"Trois formations sanitaires signalent 30/50, 40/100 et 90/200 enfants vaccinés. Quelle est la couverture globale ?","48.3%, the average of the three rates":"48,3 %, la moyenne des trois taux","Pool the data: 160 ÷ 350 = 45.7%. Averaging the three rates (60%, 40% and 45%) gives 48.3%, which overweights the small facility. Always divide the totals.":"Regroupez les données : 160 ÷ 350 = 45,7 %. La moyenne des trois taux (60 %, 40 % et 45 %) donne 48,3 %, ce qui surpondère la petite formation. Divisez toujours les totaux.","Data Collection Methods":"Méthodes de collecte de données","Surveys, interviews and focus groups, sampling, questionnaire design and data quality in the field.":"Enquêtes, entretiens et groupes de discussion, échantillonnage, conception du questionnaire et qualité des données sur le terrain.","Quantitative and qualitative methods":"Méthodes quantitatives et qualitatives","Describe the main data collection methods used in MEAL and what each one can tell you":"Décrire les principales méthodes de collecte de données utilisées en MEAL et ce que chacune peut vous apprendre","Choose the method that fits an information need, a budget and a context":"Choisir la méthode adaptée à un besoin d'information, à un budget et à un contexte","Combine methods and triangulate sources to strengthen your findings":"Combiner les méthodes et trianguler les sources pour renforcer vos constats","Every indicator in your MEAL plan needs a way of getting its data. Some questions ask how many or how much, and need numbers from many people. Others ask why or how, and need the words and experiences of a few well-chosen people. Choosing the right method is the first quality decision you make, long before the first interview.":"Chaque indicateur de votre plan MEAL a besoin d'un moyen d'obtenir ses données. Certaines questions demandent combien, et exigent des chiffres venant de nombreuses personnes. D'autres demandent pourquoi ou comment, et exigent les mots et l'expérience de quelques personnes bien choisies. Choisir la bonne méthode est la première décision de qualité que vous prenez, bien avant le premier entretien.","Quantitative and qualitative in one sentence each":"Quantitatif et qualitatif en une phrase chacun","Numbers and meaning":"Des chiffres et du sens","Quantitative methods measure how many, how much and how often, using standard questions asked to a sample large enough to represent the population. Qualitative methods explore why and how, using open conversations with a small number of people chosen for what they know or have lived.":"Les méthodes quantitatives mesurent combien et à quelle fréquence, avec des questions standardisées posées à un échantillon assez grand pour représenter la population. Les méthodes qualitatives explorent le pourquoi et le comment, par des conversations ouvertes avec un petit nombre de personnes choisies pour ce qu'elles savent ou ont vécu.","The five methods you will use most":"Les cinq méthodes que vous utiliserez le plus","What it tells you":"Ce qu'elle vous apprend","Watch out for":"Points de vigilance","Household survey":"Enquête auprès des ménages","Quantitative":"Quantitative","Prevalence, coverage and practices across a population, for example the share of households treating drinking water":"Prévalence, couverture et pratiques dans une population, par exemple la proportion de ménages qui traitent l'eau de boisson","Costly and slow; needs a good sample and a tested questionnaire":"Coûteuse et lente ; exige un bon échantillon et un questionnaire testé","Registers and routine data":"Registres et données de routine","Activities and services delivered over time: children vaccinated, kits distributed, pupils enrolled":"Activités et services fournis dans le temps : enfants vaccinés, kits distribués, élèves inscrits","Only counts people who reached the service; quality depends on how registers are filled":"Ne compte que les personnes qui ont atteint le service ; la qualité dépend de la tenue des registres","Key informant interviews (KII)":"Entretiens avec des informateurs clés (KII)","Qualitative":"Qualitative","Expert or insider views: a head of health district, a teacher, a traditional chief, a camp manager":"Points de vue d'experts ou d'initiés : un chef de district de santé, un enseignant, un chef traditionnel, un gestionnaire de camp","One person's view; choose informants from different positions":"Le point de vue d'une seule personne ; choisissez des informateurs occupant des positions différentes","Focus group discussions (FGD)":"Groupes de discussion (FGD)","Shared norms, perceptions and reasons within a group of 6 to 10 similar people":"Normes, perceptions et raisons partagées au sein d'un groupe de 6 à 10 personnes semblables","Dominant voices; not for personal or sensitive topics":"Voix dominantes ; ne convient pas aux sujets personnels ou sensibles","Direct observation":"Observation directe","Quantitative or qualitative":"Quantitative ou qualitative","What really happens: whether a latrine is used, whether soap is present, how a distribution is organised":"Ce qui se passe réellement : si une latrine est utilisée, si du savon est présent, comment une distribution est organisée","People behave differently when watched; needs a clear checklist":"Les gens se comportent autrement quand on les observe ; exige une grille d'observation claire","When to use which":"Quelle méthode, pour quel besoin","You need a percentage for the whole target population, comparable at baseline and endline: household survey.":"Vous avez besoin d'un pourcentage pour toute la population cible, comparable entre la situation de référence et la fin du projet : enquête auprès des ménages.","You need to follow outputs every month: registers and routine data, often from the health or education system.":"Vous devez suivre les extrants chaque mois : registres et données de routine, souvent issus du système de santé ou d'éducation.","You need to understand how a service or a decision works from people who know it well: key informant interviews.":"Vous devez comprendre comment fonctionne un service ou une décision auprès de personnes qui le connaissent bien : entretiens avec des informateurs clés.","You need to know how a community sees a problem or why people behave as they do: focus group discussions.":"Vous devez savoir comment une communauté perçoit un problème ou pourquoi les gens agissent ainsi : groupes de discussion.","You need to check a physical condition or a practice without relying on what people say: direct observation.":"Vous devez vérifier un état physique ou une pratique sans dépendre de ce que disent les gens : observation directe.","Organise focus groups by similarity":"Constituez les groupes de discussion par similarité","Hold separate groups for women and men, for younger and older people, and for displaced and host households. People speak more freely among peers. Aim for 6 to 10 participants, one facilitator and one note-taker, and about 60 to 90 minutes.":"Organisez des groupes séparés pour les femmes et les hommes, pour les jeunes et les aînés, et pour les ménages déplacés et hôtes. On parle plus librement entre pairs. Visez 6 à 10 participants, un animateur et un preneur de notes, et environ 60 à 90 minutes.","Choose the method":"Choisissez la méthode","A fictional WASH and health project in the East region needs the information below. Choose the method that fits each need best.":"Un projet fictif WASH et santé dans la région de l'Est a besoin des informations ci-dessous. Choisissez la méthode la mieux adaptée à chaque besoin.","Ask: do I need a number for the population, a trend of services delivered, an expert view, a group's perceptions, or proof of a physical condition?":"Demandez-vous : ai-je besoin d'un chiffre pour la population, d'une tendance des services fournis, d'un avis d'expert, des perceptions d'un groupe ou de la preuve d'un état physique ?","The share of households in the project area that treat their drinking water, for the baseline":"La proportion de ménages de la zone du projet qui traitent leur eau de boisson, pour la situation de référence","A population percentage that must be compared later calls for a household survey with a representative sample.":"Un pourcentage de population qui doit être comparé plus tard exige une enquête auprès des ménages avec un échantillon représentatif.","Key informant interviews":"Entretiens avec des informateurs clés","Focus group discussions":"Groupes de discussion","The number of children under 5 treated for diarrhoea each month in the four supported health centres":"Le nombre d'enfants de moins de 5 ans traités pour diarrhée chaque mois dans les quatre centres de santé appuyés","Monthly service data already exists in health centre registers; use it rather than a new survey.":"Les données mensuelles de service existent déjà dans les registres des centres de santé ; utilisez-les plutôt qu'une nouvelle enquête.","How the health district plans its supervision visits and what blocks them":"Comment le district de santé planifie ses visites de supervision et ce qui les bloque","A few people inside the district team know this well: interview them as key informants.":"Quelques personnes de l'équipe du district le savent bien : interrogez-les comme informateurs clés.","Why many young women prefer the river to the new borehole":"Pourquoi de nombreuses jeunes femmes préfèrent la rivière au nouveau forage","Shared perceptions and social reasons are best explored in a focus group of young women.":"Les perceptions partagées et les raisons sociales s'explorent le mieux dans un groupe de discussion de jeunes femmes.","Whether handwashing stations in 20 schools have water and soap on the day of the visit":"Si les dispositifs de lavage des mains de 20 écoles ont de l'eau et du savon le jour de la visite","A physical condition is checked most reliably by looking, with a short observation checklist.":"Un état physique se vérifie le plus sûrement en regardant, avec une courte grille d'observation.","The views of the chief of a refugee-hosting village on how water committees are chosen":"L'avis du chef d'un village hôte de réfugiés sur la manière dont les comités de l'eau sont choisis","Mixed methods":"Méthodes mixtes","Most evaluations combine methods, because numbers without explanations and stories without scale both leave questions open. The order in which you combine them depends on what you need to know first.":"La plupart des évaluations combinent les méthodes, car des chiffres sans explications et des récits sans ampleur laissent tous deux des questions ouvertes. L'ordre dans lequel vous les combinez dépend de ce que vous devez savoir en premier.","How it works":"Fonctionnement","Explanatory (numbers first)":"Explicatif (les chiffres d'abord)","A survey finds a pattern, then interviews or FGDs explain it":"Une enquête révèle une tendance, puis des entretiens ou des FGD l'expliquent","The survey shows low bed net use in one subdivision; FGDs reveal that nets are used for fishing":"L'enquête montre une faible utilisation des moustiquaires dans un arrondissement ; les FGD révèlent qu'elles servent à la pêche","Exploratory (words first)":"Exploratoire (les mots d'abord)","FGDs or KIIs identify issues, then a survey measures how common they are":"Des FGD ou des KII identifient les problèmes, puis une enquête mesure leur fréquence","FGDs list reasons for school dropout; the survey measures how many households cite each reason":"Les FGD listent les raisons de l'abandon scolaire ; l'enquête mesure combien de ménages citent chaque raison","Convergent (at the same time)":"Convergent (en même temps)","Survey and qualitative work run in parallel and are compared at analysis":"L'enquête et le travail qualitatif se déroulent en parallèle et sont comparés à l'analyse","A food security survey and KIIs with market traders are analysed together":"Une enquête de sécurité alimentaire et des KII avec des commerçants du marché sont analysés ensemble","Triangulation":"Triangulation","Triangulation means checking a finding from more than one angle before you trust it. If the survey, the health centre registers and the focus groups all point the same way, you can report the finding with confidence. If they disagree, the disagreement itself is a finding to investigate.":"Trianguler, c'est vérifier un constat sous plusieurs angles avant de s'y fier. Si l'enquête, les registres du centre de santé et les groupes de discussion vont tous dans le même sens, vous pouvez rapporter le constat avec confiance. S'ils divergent, la divergence elle-même est un constat à approfondir.","Triangulate methods: compare survey results with observation or FGDs.":"Triangulez les méthodes : comparez les résultats de l'enquête avec l'observation ou les FGD.","Triangulate sources: compare what women, men, staff and local authorities say.":"Triangulez les sources : comparez ce que disent les femmes, les hommes, le personnel et les autorités locales.","Triangulate data collectors: check whether results differ between enumerators or teams.":"Triangulez les collecteurs : vérifiez si les résultats diffèrent entre enquêteurs ou entre équipes.","A survey shows that 85% of households say they use a latrine, but observation finds that many latrines have no path and no signs of use. What should the MEAL officer do?":"Une enquête montre que 85 % des ménages déclarent utiliser une latrine, mais l'observation constate que beaucoup de latrines n'ont ni sentier ni trace d'utilisation. Que doit faire le chargé MEAL ?","Report 85% because the survey is larger":"Rapporter 85 %, car l'enquête est plus large","Report the observation only and drop the survey":"Rapporter uniquement l'observation et abandonner l'enquête","Treat the gap as a finding, explore it in FGDs, and report both sources with their limits":"Traiter l'écart comme un constat, l'explorer en FGD, et rapporter les deux sources avec leurs limites","Repeat the survey with more households":"Refaire l'enquête avec plus de ménages","When methods disagree, triangulation has done its job: it has revealed a possible reporting bias. Investigate the reason and report transparently.":"Quand les méthodes divergent, la triangulation a joué son rôle : elle a révélé un possible biais de déclaration. Cherchez la raison et rapportez en toute transparence.","A fictional livelihoods project in the Far North measured household income with a survey and found no change. Focus groups with women's savings groups explained why: income had risen, but women were reluctant to declare it in front of other household members. The team moved the income questions to a private moment and added observation of assets.":"Un projet fictif de moyens de subsistance dans l'Extrême-Nord a mesuré le revenu des ménages par enquête et n'a constaté aucun changement. Des groupes de discussion avec des groupes d'épargne de femmes ont expliqué pourquoi : le revenu avait augmenté, mais les femmes hésitaient à le déclarer devant les autres membres du ménage. L'équipe a déplacé les questions sur le revenu vers un moment en privé et a ajouté l'observation des biens.","List the outcome indicators of a project you know and write the method used for each":"Listez les indicateurs d'effet d'un projet que vous connaissez et notez la méthode utilisée pour chacun","Identify one indicator that relies only on self-reported data and suggest a second source to triangulate it":"Repérez un indicateur qui repose uniquement sur des données déclaratives et proposez une deuxième source pour le trianguler","Draft five guiding questions for a focus group on why people do or do not use a service":"Rédigez cinq questions guides pour un groupe de discussion sur les raisons pour lesquelles les gens utilisent ou non un service","List three key informants for that project and the position of each":"Listez trois informateurs clés pour ce projet et la fonction de chacun","Sampling basics and sample size":"Bases de l'échantillonnage et taille de l'échantillon","Explain the key sampling terms and choose between probability and purposive sampling":"Expliquer les termes clés de l'échantillonnage et choisir entre échantillonnage probabiliste et raisonné","Select a sampling design that fits the frame, the terrain and the reporting needs":"Choisir un plan d'échantillonnage adapté à la base de sondage, au terrain et aux besoins de rapportage","Calculate a survey sample size with the design effect and a non-response adjustment":"Calculer la taille de l'échantillon d'une enquête avec l'effet de plan et un ajustement pour la non-réponse","You rarely interview everyone. Sampling lets you talk to a few hundred households and still say something reliable about thousands, as long as the sample is drawn properly and is large enough. Get the sample wrong and even a perfect questionnaire will give misleading results.":"On interroge rarement tout le monde. L'échantillonnage permet de parler à quelques centaines de ménages et de dire quand même quelque chose de fiable sur des milliers, à condition que l'échantillon soit bien tiré et assez grand. Si l'échantillon est mauvais, même un questionnaire parfait donnera des résultats trompeurs.","The vocabulary of sampling":"Le vocabulaire de l'échantillonnage","Population":"Population","Everyone the result should describe":"Tous ceux que le résultat doit décrire","All households in the 12 villages of the project":"Tous les ménages des 12 villages du projet","Sampling frame":"Base de sondage","The list or map from which you draw the sample":"La liste ou la carte à partir de laquelle vous tirez l'échantillon","The beneficiary list, a village census, a list of schools":"La liste des bénéficiaires, un recensement du village, une liste d'écoles","Sampling unit":"Unité d'échantillonnage","What you select":"Ce que vous sélectionnez","A household, a pupil, a health centre, a village":"Un ménage, un élève, un centre de santé, un village","Sample":"Échantillon","The units actually selected":"Les unités effectivement sélectionnées","420 households drawn from the beneficiary list":"420 ménages tirés de la liste des bénéficiaires","Respondent":"Répondant","The person who answers for the unit":"La personne qui répond pour l'unité","The adult in charge of meals in the household":"L'adulte chargé des repas dans le ménage","Probability sampling designs":"Plans d'échantillonnage probabilistes","Simple random":"Aléatoire simple","Draw units at random from a complete list":"Tirer les unités au hasard dans une liste complète","You have a good, complete list and units are easy to reach":"Vous disposez d'une bonne liste complète et les unités sont faciles à atteindre","Systematic":"Systématique","Pick a random start, then every k-th unit (k = population ÷ sample)":"Choisir un point de départ au hasard, puis chaque k-ième unité (k = population ÷ échantillon)","Units are in a list or pass by one after another, such as patients leaving a clinic":"Les unités figurent dans une liste ou se présentent l'une après l'autre, comme des patients qui quittent une clinique","Stratified":"Stratifié","Split the population into groups (strata) and sample within each":"Diviser la population en groupes (strates) et échantillonner dans chacun","You must report results separately for groups, such as refugees and hosts, or three health districts":"Vous devez rapporter les résultats séparément par groupe, par exemple réfugiés et hôtes, ou trois districts de santé","Cluster":"En grappes","Select groups first (villages, blocks), then households inside them":"Sélectionner d'abord des groupes (villages, quartiers), puis des ménages à l'intérieur","There is no list of households and the area is large; saves travel time":"Il n'existe pas de liste de ménages et la zone est vaste ; économise du temps de déplacement","Purposive sampling for qualitative work":"L'échantillonnage raisonné pour le travail qualitatif","In probability sampling every unit has a known chance of being selected, which allows you to generalise and calculate a margin of error. Focus groups and key informant interviews do not aim to represent the population statistically. You choose participants on purpose for what they know or have lived: women who stopped attending antenatal care, chiefs of villages with and without a water point, the most and least successful savings groups. Keep going until new interviews stop bringing new ideas.":"Dans l'échantillonnage probabiliste, chaque unité a une chance connue d'être sélectionnée, ce qui permet de généraliser et de calculer une marge d'erreur. Les groupes de discussion et les entretiens avec des informateurs clés ne visent pas à représenter statistiquement la population. Vous choisissez les participants délibérément pour ce qu'ils savent ou ont vécu : des femmes qui ont cessé les consultations prénatales, des chefs de villages avec et sans point d'eau, les groupes d'épargne les plus et les moins performants. Continuez jusqu'à ce que les nouveaux entretiens n'apportent plus d'idées nouvelles.","Choose the sampling design":"Choisissez le plan d'échantillonnage","For each situation from fictional projects in Cameroon, choose the most suitable sampling design.":"Pour chaque situation tirée de projets fictifs au Cameroun, choisissez le plan d'échantillonnage le plus adapté.","A complete list and easy access suggests simple random; a flow of people suggests systematic; separate results per group suggests stratified; no list and a large area suggests cluster; qualitative work suggests purposive.":"Une liste complète et un accès facile orientent vers l'aléatoire simple ; un flux de personnes vers le systématique ; des résultats séparés par groupe vers le stratifié ; l'absence de liste et une grande zone vers les grappes ; un travail qualitatif vers le raisonné.","A phone survey of 150 people drawn from a complete list of 1 200 cash transfer recipients":"Une enquête téléphonique auprès de 150 personnes tirées d'une liste complète de 1 200 bénéficiaires de transferts monétaires","With a complete list and phone access, a simple random draw is easy and gives every recipient the same chance.":"Avec une liste complète et un accès par téléphone, un tirage aléatoire simple est facile et donne à chaque bénéficiaire la même chance.","Simple random sampling":"Échantillonnage aléatoire simple","Systematic sampling":"Échantillonnage systématique","Stratified sampling":"Échantillonnage stratifié","Cluster sampling":"Échantillonnage en grappes","Purposive sampling":"Échantillonnage raisonné","Exit interviews with every 6th woman leaving an antenatal clinic, after a random start":"Entretiens de sortie avec une femme sur six quittant une consultation prénatale, après un départ tiré au hasard","A survey that must give separate results for refugee households and host households in the East region":"Une enquête qui doit donner des résultats séparés pour les ménages réfugiés et les ménages hôtes dans la région de l'Est","Stratify by population group and draw a sufficient sample in each stratum.":"Stratifiez par groupe de population et tirez un échantillon suffisant dans chaque strate.","A nutrition survey across 60 villages of the Far North with no household list":"Une enquête nutritionnelle dans 60 villages de l'Extrême-Nord sans liste de ménages","Select villages first, then list and draw households inside the selected villages.":"Sélectionnez d'abord les villages, puis dénombrez et tirez les ménages dans les villages sélectionnés.","Six focus groups with women leaders from villages with high and low school attendance":"Six groupes de discussion avec des femmes leaders de villages à forte et à faible fréquentation scolaire","Qualitative participants are chosen on purpose to cover contrasting situations.":"Les participants qualitatifs sont choisis délibérément pour couvrir des situations contrastées.","A survey of pupils where each of the four subdivisions must have its own reliable estimate":"Une enquête auprès des élèves où chacun des quatre arrondissements doit avoir sa propre estimation fiable","The sample size formula for a proportion":"La formule de la taille de l'échantillon pour une proportion","Most MEAL surveys estimate a proportion, such as the share of children sleeping under a net. The basic sample size depends on three choices: how confident you want to be (z), what proportion you expect (p) and how precise the result must be (the margin of error e).":"La plupart des enquêtes MEAL estiment une proportion, comme la part des enfants qui dorment sous une moustiquaire. La taille de base de l'échantillon dépend de trois choix : le niveau de confiance voulu (z), la proportion attendue (p) et la précision exigée du résultat (la marge d'erreur e).","Design effect (deff): cluster samples are less precise than simple random ones, because neighbours tend to be alike. Multiply n by the design effect, often 1.5 to 2 for household surveys.":"Effet de plan (deff) : les échantillons en grappes sont moins précis que les échantillons aléatoires simples, car les voisins se ressemblent. Multipliez n par l'effet de plan, souvent 1,5 à 2 pour les enquêtes auprès des ménages.","Non-response: some households will be absent or refuse. Divide by (1 − expected non-response rate), for example by 0.9 for 10%.":"Non-réponse : certains ménages seront absents ou refuseront. Divisez par (1 − taux de non-réponse attendu), par exemple par 0,9 pour 10 %.","Round up at the end, never down: a sample of 853.7 means 854 households.":"Arrondissez au supérieur à la fin, jamais à l'inférieur : un échantillon de 853,7 signifie 854 ménages.","Several strata: if each stratum needs its own estimate, calculate the sample size for each stratum separately.":"Plusieurs strates : si chaque strate a besoin de sa propre estimation, calculez la taille de l'échantillon séparément pour chacune.","Worked example":"Exemple résolu","Expected proportion unknown, so p = 0.5; confidence 95%, so z = 1.96; margin of error e = 0.05.":"Proportion attendue inconnue, donc p = 0,5 ; confiance de 95 %, donc z = 1,96 ; marge d'erreur e = 0,05.","Basic sample: 1.96² × 0.5 × 0.5 ÷ 0.05² = 384.16.":"Échantillon de base : 1,96² × 0,5 × 0,5 ÷ 0,05² = 384,16.","Cluster design with deff = 2: 384.16 × 2 = 768.32.":"Plan en grappes avec deff = 2 : 384,16 × 2 = 768,32.","Expected non-response of 10%: 768.32 ÷ 0.9 = 853.69, rounded up to 854 households.":"Non-réponse attendue de 10 % : 768,32 ÷ 0,9 = 853,69, arrondi au supérieur à 854 ménages.","With 12 households per cluster: 854 ÷ 12 = 71.2, rounded up to 72 clusters.":"Avec 12 ménages par grappe : 854 ÷ 12 = 71,2, arrondi au supérieur à 72 grappes.","Math & Trig":"Maths et trigonométrie","ROUNDUP":"ARRONDI.SUP","In Excel, ROUNDUP(value, 0) rounds up to the next whole number. Use ^ for powers, for example 1.96^2.":"Dans Excel, ROUNDUP(valeur, 0) (ARRONDI.SUP) arrondit au nombre entier supérieur. Utilisez ^ pour les puissances, par exemple 1,96^2.","Calculate the sample size":"Calculez la taille de l'échantillon","A fictional food security baseline in the Adamawa region expects 40% of households to have a poor food consumption score. Fill":"Une étude de référence fictive sur la sécurité alimentaire dans la région de l'Adamaoua s'attend à ce que 40 % des ménages aient un score de consommation alimentaire pauvre. Remplissez","with the basic sample size (not rounded),":"avec la taille d'échantillon de base (non arrondie),","after the design effect,":"après l'effet de plan,","after non-response, rounded up, and":"après la non-réponse, arrondie au supérieur, et","with the number of clusters needed, rounded up.":"avec le nombre de grappes nécessaires, arrondi au supérieur.","B9: =B3^2*B4*(1-B4)/B5^2. B10: =B9*B6. B11: =ROUNDUP(B10/(1-B7),0). B12: =ROUNDUP(B11/B8,0).":"B9 : =B3^2*B4*(1-B4)/B5^2. B10 : =B9*B6. B11 : =ROUNDUP(B10/(1-B7),0). B12 : =ROUNDUP(B11/B8,0).","Small populations":"Petites populations","When the population is small, for example 600 households, the formula gives a sample close to the whole population. A finite population correction reduces it: n divided by (1 + (n − 1) ÷ N), where N is the population size. Apply it before the design effect and non-response.":"Quand la population est petite, par exemple 600 ménages, la formule donne un échantillon proche de la population entière. Une correction pour population finie le réduit : n divisé par (1 + (n − 1) ÷ N), où N est la taille de la population. Appliquez-la avant l'effet de plan et la non-réponse.","Why do you multiply the sample size by a design effect in a cluster survey?":"Pourquoi multiplie-t-on la taille de l'échantillon par un effet de plan dans une enquête en grappes ?","To compensate for households that refuse":"Pour compenser les ménages qui refusent","Because households in the same cluster tend to be similar, so each one adds less new information":"Parce que les ménages d'une même grappe se ressemblent, si bien que chacun apporte moins d'information nouvelle","To make the survey cheaper":"Pour rendre l'enquête moins chère","Because the donor requires a larger sample":"Parce que le bailleur exige un échantillon plus grand","Neighbours share the same water point, market and customs. The design effect restores the precision lost by sampling in clusters. Refusals are handled by the separate non-response adjustment.":"Les voisins partagent le même point d'eau, le même marché et les mêmes coutumes. L'effet de plan rétablit la précision perdue en échantillonnant en grappes. Les refus sont traités par l'ajustement distinct pour la non-réponse.","A fictional NGO planned a single sample of 400 households for a survey covering both refugees and host communities in the East region. When the donor asked for separate results for each group, the MEAL officer recalculated a sample for each stratum, which almost doubled the fieldwork. Deciding the reporting groups before calculating the sample would have avoided the surprise.":"Une ONG fictive avait prévu un échantillon unique de 400 ménages pour une enquête couvrant à la fois les réfugiés et les communautés hôtes dans la région de l'Est. Quand le bailleur a demandé des résultats séparés pour chaque groupe, le chargé MEAL a recalculé un échantillon pour chaque strate, ce qui a presque doublé le travail de terrain. Décider des groupes de rapportage avant de calculer l'échantillon aurait évité la surprise.","Write the population, sampling frame, sampling unit and respondent of a survey you know":"Notez la population, la base de sondage, l'unité d'échantillonnage et le répondant d'une enquête que vous connaissez","Rebuild the sample size sheet from the lab in your own Excel file":"Reconstruisez la feuille de taille d'échantillon de l'exercice dans votre propre fichier Excel","Recalculate it with a margin of error of 7% and compare the fieldwork days needed":"Recalculez-la avec une marge d'erreur de 7 % et comparez les jours de terrain nécessaires","List the groups your donor wants results for and decide whether you need strata":"Listez les groupes pour lesquels votre bailleur veut des résultats et décidez si vous avez besoin de strates","Describe how you would choose participants for three focus groups in the same project":"Décrivez comment vous choisiriez les participants de trois groupes de discussion dans le même projet","Sample: Rainbow Framework":"Échantillonner : Rainbow Framework","Questionnaire design, skip logic and pre-testing":"Conception du questionnaire, logique de saut et pré-test","Write clear questions with complete, non-overlapping response options":"Rédiger des questions claires avec des options de réponse complètes et sans chevauchement","Add skip logic and constraints to a mobile questionnaire in XLSForm":"Ajouter une logique de saut et des contraintes à un questionnaire mobile en XLSForm","Organise translation, back-translation and a pilot test before data collection":"Organiser la traduction, la rétro-traduction et un test pilote avant la collecte des données","A questionnaire is a measuring instrument. If a question is unclear, leading or missing an option, every enumerator will measure something slightly different, and no analysis can repair it afterwards. Good questionnaires are short, follow the indicators, and are tested with real respondents before the survey starts.":"Un questionnaire est un instrument de mesure. Si une question est floue, orientée ou incomplète, chaque enquêteur mesurera quelque chose de légèrement différent, et aucune analyse ne pourra le réparer ensuite. Un bon questionnaire est court, suit les indicateurs et est testé avec de vrais répondants avant le début de l'enquête.","List every indicator the survey must calculate, then write only the questions needed for them, plus the few variables needed for disaggregation, such as sex, age group and location. A question that feeds no indicator and no decision should go.":"Listez chaque indicateur que l'enquête doit calculer, puis rédigez uniquement les questions nécessaires, plus les quelques variables utiles à la désagrégation, comme le sexe, la tranche d'âge et la localité. Une question qui n'alimente aucun indicateur ni aucune décision doit disparaître.","Question types":"Types de questions","Single choice":"Choix unique","One answer from a list":"Une réponse dans une liste","What is the main source of drinking water?":"Quelle est la principale source d'eau de boisson ?","Multiple choice":"Choix multiple","Several answers allowed":"Plusieurs réponses possibles","Which of these foods did the child eat yesterday?":"Lesquels de ces aliments l'enfant a-t-il mangés hier ?","Numeric":"Numérique","Counts and amounts":"Effectifs et montants","How many people live in this household?":"Combien de personnes vivent dans ce ménage ?","Scale":"Échelle","Satisfaction or agreement, on 3 to 5 points":"Satisfaction ou accord, sur 3 à 5 niveaux","How satisfied are you with the distribution? Very, somewhat, not at all":"Êtes-vous satisfait de la distribution ? Très, assez, pas du tout","Explanations and unexpected answers; use sparingly":"Explications et réponses inattendues ; à utiliser avec modération","What would you change in the service?":"Que changeriez-vous dans le service ?","Wording and response options":"Formulation et options de réponse","Use simple words that respondents use themselves, and define terms such as household or last week.":"Employez des mots simples que les répondants utilisent eux-mêmes, et définissez des termes comme ménage ou semaine dernière.","Avoid leading questions that suggest the expected answer.":"Évitez les questions orientées qui suggèrent la réponse attendue.","Avoid double-barrelled questions that ask two things at once; split them.":"Évitez les questions doubles qui demandent deux choses à la fois ; séparez-les.","Set a clear recall period: yesterday, the last 7 days, the last 30 days.":"Fixez une période de rappel claire : hier, les 7 derniers jours, les 30 derniers jours.","Make response options mutually exclusive and complete; add Other (specify), Don't know and Refused where needed.":"Rendez les options de réponse mutuellement exclusives et complètes ; ajoutez Autre (préciser), Ne sait pas et Refus si nécessaire.","Put easy questions first and sensitive ones later, once trust is built.":"Placez les questions faciles en premier et les questions sensibles plus tard, une fois la confiance établie.","Spot the problem":"Repérez le problème","A draft questionnaire for a fictional water and hygiene project in the Littoral region contains the questions below. Choose the main problem of each one.":"Un projet de questionnaire pour un projet fictif d'eau et d'hygiène dans la région du Littoral contient les questions ci-dessous. Choisissez le principal problème de chacune.","Does the question suggest an answer, ask two things, have gaps or overlaps in the options, use a word people will understand differently, or ask something too sensitive for a doorstep survey?":"La question suggère-t-elle une réponse, demande-t-elle deux choses, a-t-elle des trous ou des chevauchements dans les options, emploie-t-elle un mot que chacun comprendra différemment, ou demande-t-elle quelque chose de trop sensible pour une enquête sur le pas de la porte ?","Don't you agree that the new borehole has improved your family's health?":"N'êtes-vous pas d'accord que le nouveau forage a amélioré la santé de votre famille ?","The wording pushes the respondent to agree. Ask neutrally: has your family's health changed since the borehole opened?":"La formulation pousse le répondant à approuver. Demandez de façon neutre : la santé de votre famille a-t-elle changé depuis l'ouverture du forage ?","Leading question":"Question orientée","Double-barrelled question":"Question double","Overlapping or missing response options":"Options de réponse qui se chevauchent ou manquantes","Vague or undefined term":"Terme vague ou non défini","Too sensitive for this setting":"Trop sensible dans ce contexte","Is the water point clean and is the water committee helpful?":"Le point d'eau est-il propre et le comité de l'eau est-il serviable ?","A respondent may find the point clean but the committee unhelpful. Ask two separate questions.":"Un répondant peut trouver le point propre mais le comité peu serviable. Posez deux questions séparées.","Age of respondent: 18–25, 25–35, 35–50":"Âge du répondant : 18–25, 25–35, 35–50","25 and 35 appear in two groups, and people over 50 have no option. Use 18–24, 25–34, 35–49, 50 and over.":"25 et 35 figurent dans deux tranches, et les plus de 50 ans n'ont pas d'option. Utilisez 18–24, 25–34, 35–49, 50 et plus.","Do you wash your hands regularly?":"Vous lavez-vous les mains régulièrement ?","Regularly means different things to different people. Ask about specific moments, such as before eating or after using the latrine.":"« Régulièrement » ne signifie pas la même chose pour tout le monde. Interrogez sur des moments précis, comme avant de manger ou après être allé aux latrines.","In a doorstep survey with neighbours listening: has anyone in your household suffered sexual violence this year?":"Dans une enquête sur le pas de la porte, devant les voisins : quelqu'un de votre ménage a-t-il subi des violences sexuelles cette année ?","Such questions need trained staff, privacy and a referral pathway. They do not belong in a general household survey.":"De telles questions exigent un personnel formé, de l'intimité et un circuit de référencement. Elles n'ont pas leur place dans une enquête générale auprès des ménages.","Monthly household income: less than 25 000 FCFA, 25 000 to 50 000 FCFA, more than 75 000 FCFA":"Revenu mensuel du ménage : moins de 25 000 FCFA, de 25 000 à 50 000 FCFA, plus de 75 000 FCFA","Households earning between 50 000 and 75 000 FCFA have no option.":"Les ménages qui gagnent entre 50 000 et 75 000 FCFA n'ont pas d'option.","Skip logic and constraints":"Logique de saut et contraintes","In a mobile form, skip logic shows a question only when it applies, and constraints refuse impossible answers at the moment of entry. In XLSForm, skip logic goes in the relevant column and validation in the constraint column, where a dot stands for the current answer.":"Dans un formulaire mobile, la logique de saut n'affiche une question que lorsqu'elle s'applique, et les contraintes refusent les réponses impossibles au moment de la saisie. En XLSForm, la logique de saut se place dans la colonne relevant et la validation dans la colonne constraint, où un point représente la réponse en cours.","Need":"Besoin","Ask about care only if a child had fever":"Interroger sur les soins seulement si un enfant a eu de la fièvre","relevant":"relevant","${child_fever} = 'yes'":"${child_fever} = 'yes'","Ask the other source only if Other was chosen":"Demander l'autre source seulement si « Autre » a été choisi","${water_source} = 'other'":"${water_source} = 'other'","Household size between 1 and 30":"Taille du ménage entre 1 et 30","constraint":"constraint",". >= 1 and . <= 30":". >= 1 and . <= 30","Children under 5 cannot exceed household size":"Les enfants de moins de 5 ans ne peuvent pas dépasser la taille du ménage",". <= ${hh_size}":". <= ${hh_size}","Question settings":"Paramètres de la question","Skip Logic":"Logique de saut","In the KoboToolbox Formbuilder, open a question's settings (gear icon); the Validation Criteria tab holds constraints.":"Dans le Formbuilder de KoboToolbox, ouvrez les paramètres d'une question (icône d'engrenage) ; l'onglet des critères de validation contient les contraintes.","Add skip logic and constraints":"Ajoutez une logique de saut et des contraintes","Complete this short household questionnaire for a fictional health project in the Centre region. Make":"Complétez ce court questionnaire ménage d'un projet de santé fictif dans la région du Centre. Faites en sorte que","hh_size":"hh_size","accept 1 to 30 only, make":"n'accepte que 1 à 30, que","children_u5":"children_u5","accept no more than hh_size, show":"n'accepte pas plus que hh_size ; affichez","child_fever":"child_fever","only when there is at least one child under 5, show":"seulement s'il y a au moins un enfant de moins de 5 ans, affichez","care_sought":"care_sought","only when a child had fever, and show":"seulement si un enfant a eu de la fièvre, et affichez","water_other":"water_other","only when the water source is other.":"seulement si la source d'eau est « autre ».","hh_size constraint: . >= 1 and . <= 30. children_u5 constraint: . <= ${hh_size}. Relevant: ${children_u5} > 0, then ${child_fever} = 'yes', then ${water_source} = 'other'.":"Contrainte de hh_size : . >= 1 and . <= 30. Contrainte de children_u5 : . <= ${hh_size}. Relevant : ${children_u5} > 0, puis ${child_fever} = 'yes', puis ${water_source} = 'other'.","hh_size accepts 1 to 30 only":"hh_size n'accepte que 1 à 30","children_u5 cannot exceed hh_size":"children_u5 ne peut pas dépasser hh_size","child_fever appears only when children_u5 > 0":"child_fever n'apparaît que si children_u5 > 0","care_sought appears only when child_fever = yes":"care_sought n'apparaît que si child_fever = yes","water_other appears only when water_source = other":"water_other n'apparaît que si water_source = other","Translation and back-translation":"Traduction et rétro-traduction","Getting the same question in every language":"Obtenir la même question dans chaque langue","Finalise the English or French master version first.":"Finalisez d'abord la version de référence en anglais ou en français.","A translator who knows the local language and the topic translates it, for example into Fulfulde, Ewondo or Pidgin.":"Un traducteur qui connaît la langue locale et le sujet la traduit, par exemple en fulfulde, en ewondo ou en pidgin.","A second translator, who has not seen the original, translates it back into the master language.":"Un second traducteur, qui n'a pas vu l'original, la retraduit dans la langue de référence.","Compare the back-translation with the original and discuss every difference in meaning.":"Comparez la rétro-traduction avec l'original et discutez chaque différence de sens.","Agree the wording of key terms, such as household or diarrhoea, and add them to the training manual.":"Convenez de la formulation des termes clés, comme ménage ou diarrhée, et ajoutez-les au manuel de formation.","Pilot the questionnaire":"Testez le questionnaire","Test the form with 10 to 20 respondents similar to the sample, but outside the sample villages.":"Testez le formulaire avec 10 à 20 répondants semblables à l'échantillon, mais hors des villages de l'échantillon.","Time each interview and note questions that cause hesitation, confusion or refusals.":"Chronométrez chaque entretien et notez les questions qui provoquent hésitation, confusion ou refus.","Check that the skip logic works and that no respondent is stuck without a suitable option.":"Vérifiez que la logique de saut fonctionne et qu'aucun répondant ne reste bloqué sans option adaptée.","Export the pilot data and try to calculate every indicator from it.":"Exportez les données du pilote et essayez d'en calculer chaque indicateur.","Correct the form, record the version number, and retrain enumerators on the changes.":"Corrigez le formulaire, notez le numéro de version, et reformez les enquêteurs sur les changements.","What is the purpose of back-translation?":"À quoi sert la rétro-traduction ?","To check that the translated questionnaire keeps the same meaning as the original":"À vérifier que le questionnaire traduit garde le même sens que l'original","To make the questionnaire shorter":"À raccourcir le questionnaire","To translate the answers into English for analysis":"À traduire les réponses en anglais pour l'analyse","To let respondents choose their language":"À laisser les répondants choisir leur langue","An independent translator converts the translation back into the original language, so differences in meaning become visible and can be corrected before fieldwork.":"Un traducteur indépendant retraduit la traduction dans la langue d'origine : les différences de sens deviennent visibles et peuvent être corrigées avant le terrain.","During the pilot of a fictional nutrition survey in the Far North, enumerators found that the Fulfulde word chosen for diarrhoea was also used for ordinary stomach pain. Reported diarrhoea was twice as high as expected. The team agreed a more precise description with health workers and retrained enumerators before the main survey.":"Lors du pilote d'une enquête nutritionnelle fictive dans l'Extrême-Nord, les enquêteurs ont constaté que le mot fulfulde choisi pour diarrhée désignait aussi un simple mal de ventre. La diarrhée déclarée était deux fois plus élevée que prévu. L'équipe a convenu d'une description plus précise avec les agents de santé et a reformé les enquêteurs avant l'enquête principale.","Take a questionnaire from your project and link each question to the indicator it feeds":"Prenez un questionnaire de votre projet et reliez chaque question à l'indicateur qu'elle alimente","Find and rewrite one leading and one double-barrelled question":"Trouvez et réécrivez une question orientée et une question double","Check every set of response options for gaps and overlaps":"Vérifiez chaque ensemble d'options de réponse pour détecter trous et chevauchements","Add at least two relevant conditions and one constraint to your XLSForm":"Ajoutez au moins deux conditions relevant et une contrainte à votre XLSForm","Plan a pilot: where, with how many respondents, and who records the problems":"Planifiez un pilote : où, avec combien de répondants, et qui note les problèmes","XLSForm documentation: relevant and constraint":"Documentation XLSForm : relevant et constraint","Form logic":"Logique des formulaires","Enumerator training, supervision and data quality":"Formation des enquêteurs, supervision et qualité des données","Plan an enumerator training that combines theory, role plays and a field practice":"Planifier une formation des enquêteurs qui combine théorie, jeux de rôle et pratique sur le terrain","Organise spot checks, back-checks and daily data review during fieldwork":"Organiser des contrôles inopinés, des contre-visites et une revue quotidienne des données pendant le terrain","Detect common enumerator errors in the data and decide on follow-up":"Détecter dans les données les erreurs courantes des enquêteurs et décider du suivi","The best questionnaire and sample are wasted if enumerators ask questions differently, skip households or invent answers. Data quality is built in three places: in training before fieldwork, in supervision during fieldwork, and in the daily review of data as it arrives on the server.":"Le meilleur questionnaire et le meilleur échantillon sont gâchés si les enquêteurs posent les questions différemment, sautent des ménages ou inventent des réponses. La qualité des données se construit à trois endroits : dans la formation avant le terrain, dans la supervision pendant le terrain, et dans la revue quotidienne des données à leur arrivée sur le serveur.","A typical training agenda":"Un programme de formation type","Day":"Jour","Day 1":"Jour 1","Project and survey objectives, ethics, consent, safeguarding, code of conduct, sampling and household selection rules":"Objectifs du projet et de l'enquête, éthique, consentement, protection (safeguarding), code de conduite, échantillonnage et règles de sélection des ménages","Day 2":"Jour 2","Question by question review in all languages, definitions of key terms, practice with the mobile form":"Revue question par question dans toutes les langues, définition des termes clés, pratique avec le formulaire mobile","Day 3":"Jour 3","Role plays in pairs, difficult situations, device care, sending data, the daily routine":"Jeux de rôle en binômes, situations difficiles, entretien des appareils, envoi des données, routine quotidienne","Day 4":"Jour 4","Field practice in a village outside the sample, debriefing and final corrections to the form":"Pratique de terrain dans un village hors échantillon, débriefing et dernières corrections du formulaire","Recruit more than you need":"Recrutez plus que nécessaire","Train about 10 to 20% more enumerators than required and select the final team from their test results and role plays. You then have replacements ready if someone falls ill or leaves.":"Formez environ 10 à 20 % d'enquêteurs de plus que nécessaire et sélectionnez l'équipe finale d'après leurs résultats aux tests et aux jeux de rôle. Vous aurez ainsi des remplaçants prêts si quelqu'un tombe malade ou part.","Supervision in the field":"La supervision sur le terrain","Spot checks: the supervisor attends part of an interview unannounced and checks how questions are asked.":"Contrôles inopinés : le superviseur assiste sans prévenir à une partie d'un entretien et vérifie comment les questions sont posées.","Back-checks: a different person revisits a random 5 to 10% of households and re-asks a few stable questions, such as household size or water source.":"Contre-visites : une autre personne revisite 5 à 10 % des ménages tirés au hasard et repose quelques questions stables, comme la taille du ménage ou la source d'eau.","Daily debriefing: the team meets each evening to share problems and agree solutions.":"Débriefing quotidien : l'équipe se réunit chaque soir pour partager les problèmes et convenir de solutions.","Consistent rules: any change in instructions is written down and shared with all teams the same day.":"Règles cohérentes : tout changement de consigne est écrit et partagé avec toutes les équipes le jour même.","Daily data review":"La revue quotidienne des données","Every evening, on the server":"Chaque soir, sur le serveur","Count interviews per enumerator and per cluster against the plan.":"Comptez les entretiens par enquêteur et par grappe par rapport au plan.","Look at interview duration: very short interviews suggest skipped questions or invented data.":"Regardez la durée des entretiens : des entretiens très courts suggèrent des questions sautées ou des données inventées.","Check the share of Don't know answers, refusals and missing values per enumerator.":"Vérifiez la part de réponses Ne sait pas, de refus et de valeurs manquantes par enquêteur.","Compare back-check answers with the original interviews and calculate the mismatch rate.":"Comparez les réponses des contre-visites avec les entretiens d'origine et calculez le taux de discordance.","Send clear feedback to each team the next morning and record decisions.":"Envoyez un retour clair à chaque équipe le lendemain matin et consignez les décisions.","DATA":"DONNÉES","In a KoboToolbox project, the table view lets you review submissions and set a validation status such as Approved, Not approved or On hold.":"Dans un projet KoboToolbox, la vue en tableau permet de revoir les soumissions et de leur attribuer un statut de validation, comme approuvé, non approuvé ou en attente.","Common errors and what they look like":"Les erreurs courantes et leurs signes","Sign in the data":"Signe dans les données","Response":"Réponse","Skipping questions to go faster":"Sauter des questions pour aller plus vite","Very short interviews; many No answers that avoid follow-up questions":"Entretiens très courts ; beaucoup de réponses Non qui évitent les questions de suivi","Spot checks, retraining, back-checks on that enumerator":"Contrôles inopinés, recyclage, contre-visites sur cet enquêteur","Invented or copied interviews":"Entretiens inventés ou copiés","Identical answer patterns, interviews one or two minutes apart, GPS points in one place":"Réponses identiques, entretiens espacés d'une ou deux minutes, points GPS au même endroit","Back-checks; discard the data if confirmed":"Contre-visites ; écarter les données si c'est confirmé","Wrong household selected":"Mauvais ménage sélectionné","Clusters with too many or too few interviews":"Grappes avec trop ou trop peu d'entretiens","Review selection rules with the team":"Revoir les règles de sélection avec l'équipe","Misunderstood question":"Question mal comprise","One enumerator's answers very different from the others":"Les réponses d'un enquêteur très différentes de celles des autres","Clarify the question with the whole team":"Clarifier la question avec toute l'équipe","Flag enumerators for follow-up":"Signalez les enquêteurs à suivre","Day 3 of a fictional household survey in the South region. Fill":"Jour 3 d'une enquête ménage fictive dans la région du Sud. Remplissez","with each enumerator's back-check mismatch rate,":"avec le taux de discordance des contre-visites de chaque enquêteur,","when the average interview lasts less than 20 minutes or the mismatch rate is above 15%, otherwise":"lorsque l'entretien moyen dure moins de 20 minutes ou que le taux de discordance dépasse 15 %, sinon","with the team's overall mismatch rate.":"avec le taux de discordance global de l'équipe.","Mismatch rate: =E2/D2. Flag: =IF(OR(C2<20,F2>0.15),\"Follow up\",\"OK\"). The team rate divides total mismatches by total back-checks: =SUM(E2:E6)/SUM(D2:D6).":"Taux de discordance : =E2/D2. Signal : =IF(OR(C2<20,F2>0.15),\"Follow up\",\"OK\") (SI, OU). Le taux de l'équipe divise le total des discordances par le total des contre-visites : =SUM(E2:E6)/SUM(D2:D6).","Enumerator safety":"La sécurité des enquêteurs","Check the security situation each morning with local authorities and the security focal point, especially in the North-West, South-West and Far North.":"Vérifiez la situation sécuritaire chaque matin avec les autorités locales et le point focal sécurité, surtout dans le Nord-Ouest, le Sud-Ouest et l'Extrême-Nord.","Work in pairs or teams, never alone, and share the daily route with the supervisor.":"Travaillez en binômes ou en équipes, jamais seul, et communiquez l'itinéraire du jour au superviseur.","Carry identification and an authorisation letter, and introduce the team to the village chief first.":"Portez une pièce d'identité et une lettre d'autorisation, et présentez d'abord l'équipe au chef du village.","Agree a check-in time and a procedure if a team does not report back.":"Convenez d'une heure de pointage et d'une procédure si une équipe ne donne pas de nouvelles.","Stop an interview at once if the respondent or the enumerator is at risk.":"Arrêtez immédiatement un entretien si le répondant ou l'enquêteur est en danger.","What is a back-check?":"Qu'est-ce qu'une contre-visite ?","The supervisor reads each form before it is sent":"Le superviseur lit chaque formulaire avant son envoi","The enumerator re-reads the answers to the respondent at the end":"L'enquêteur relit les réponses au répondant à la fin","The server checks that all required questions are answered":"Le serveur vérifie que toutes les questions obligatoires ont une réponse","A different person revisits a random sample of households and re-asks a few questions to compare with the original answers":"Une autre personne revisite un échantillon aléatoire de ménages et repose quelques questions pour les comparer aux réponses d'origine","Back-checks confirm that interviews really took place and that answers were recorded correctly. They work best when enumerators know they happen but not which households are chosen.":"Les contre-visites confirment que les entretiens ont bien eu lieu et que les réponses ont été correctement enregistrées. Elles fonctionnent le mieux quand les enquêteurs savent qu'elles existent, mais pas quels ménages sont choisis.","In a fictional education survey in the Adamawa region, the daily review showed that one enumerator completed twelve interviews in a morning, each in under ten minutes, with GPS points a few metres apart. Back-checks found that most of the listed households had never been visited. The data was discarded, the households were re-interviewed, and the team introduced a minimum duration flag on the dashboard.":"Dans une enquête fictive sur l'éducation dans la région de l'Adamaoua, la revue quotidienne a montré qu'un enquêteur avait réalisé douze entretiens en une matinée, chacun en moins de dix minutes, avec des points GPS distants de quelques mètres. Les contre-visites ont révélé que la plupart des ménages listés n'avaient jamais été visités. Les données ont été écartées, les ménages ont été réinterrogés, et l'équipe a ajouté au tableau de bord un signal de durée minimale.","Draft a four-day training agenda for your next survey":"Rédigez un programme de formation de quatre jours pour votre prochaine enquête","Choose five stable questions to re-ask in back-checks":"Choisissez cinq questions stables à reposer lors des contre-visites","Build the enumerator follow-up sheet from the lab for your own team":"Construisez la feuille de suivi des enquêteurs de l'exercice pour votre propre équipe","Write a one-page daily review checklist for the supervisor":"Rédigez une liste de contrôle quotidienne d'une page pour le superviseur","List the security contacts and check-in procedure for your field area":"Listez les contacts de sécurité et la procédure de pointage pour votre zone de terrain","Collecting high-quality data":"Collecter des données de qualité","Practice lab: planning and running data collection":"Atelier pratique : planifier et conduire la collecte de données","Choose methods and sampling designs for a new project":"Choisir les méthodes et les plans d'échantillonnage pour un nouveau projet","Diagnose and correct badly worded survey questions":"Diagnostiquer et corriger des questions d'enquête mal formulées","Calculate a stratified sample size with design effect and non-response":"Calculer la taille d'un échantillon stratifié avec effet de plan et non-réponse","Build several skip-logic rules and constraints into a screening form":"Intégrer plusieurs règles de logique de saut et contraintes dans un formulaire de dépistage","Exercise 1: An education project in the North-West region":"Exercice 1 : un projet d'éducation dans la région du Nord-Ouest","Methods and sampling":"Méthodes et échantillonnage","A fictional NGO supports displaced pupils returning to school in the North-West region. Answer each question.":"Une ONG fictive accompagne des élèves déplacés qui retournent à l'école dans la région du Nord-Ouest. Répondez à chaque question.","Numbers for a population need a survey or routine data; reasons and views need interviews or focus groups. Separate results per group call for strata; no list and scattered villages call for clusters.":"Des chiffres pour une population exigent une enquête ou des données de routine ; des raisons et des avis exigent des entretiens ou des groupes de discussion. Des résultats séparés par groupe demandent des strates ; l'absence de liste et des villages dispersés demandent des grappes.","Monthly attendance of pupils in the 25 supported schools":"La fréquentation mensuelle des élèves dans les 25 écoles appuyées","Schools already keep attendance registers; collect them monthly.":"Les écoles tiennent déjà des registres d'appel ; collectez-les chaque mois.","Why some parents keep girls at home after the age of 12":"Pourquoi certains parents gardent les filles à la maison après 12 ans","How the divisional delegation allocates new teachers":"Comment la délégation départementale affecte les nouveaux enseignants","Whether classrooms have enough benches and a working blackboard":"Si les salles de classe ont assez de bancs et un tableau noir utilisable","A survey must give separate results for displaced and host pupils":"Une enquête doit donner des résultats séparés pour les élèves déplacés et les élèves hôtes","Participants for focus groups with teachers from high- and low-performing schools":"Les participants de groupes de discussion avec des enseignants d'écoles très et peu performantes","Exercise 2: A nutrition survey questionnaire":"Exercice 2 : le questionnaire d'une enquête nutritionnelle","Diagnose and fix the questions":"Diagnostiquez et corrigez les questions","A draft questionnaire for a fictional infant feeding survey in the North region has several weak questions. For each one, identify the problem, then choose the best replacement.":"Un projet de questionnaire pour une enquête fictive sur l'alimentation du nourrisson dans la région du Nord contient plusieurs questions faibles. Pour chacune, identifiez le problème, puis choisissez la meilleure formulation de remplacement.","A good replacement asks one thing, neutrally, with a clear recall period and complete options.":"Une bonne formulation demande une seule chose, de façon neutre, avec une période de rappel claire et des options complètes.","\"You breastfeed your baby, don't you?\" What is the problem?":"« Vous allaitez votre bébé, n'est-ce pas ? » Quel est le problème ?","Best replacement for that question":"Meilleure formulation de remplacement pour cette question","It is neutral, asks one thing and uses a clear recall period: yesterday, day or night.":"Elle est neutre, demande une seule chose et utilise une période de rappel claire : hier, de jour ou de nuit.","\"You surely breastfeed, like all good mothers?\"":"« Vous allaitez sûrement, comme toutes les bonnes mères ? »","\"Was the baby breastfed yesterday, during the day or at night?\"":"« Le bébé a-t-il été allaité hier, pendant la journée ou la nuit ? »","\"Do you breastfeed and give porridge?\"":"« Allaitez-vous et donnez-vous de la bouillie ? »","\"Breastfeeding is important, isn't it?\"":"« L'allaitement est important, n'est-ce pas ? »","\"Did the child eat meat and eggs yesterday?\" What is the problem?":"« L'enfant a-t-il mangé de la viande et des œufs hier ? » Quel est le problème ?","Two separate questions let you count each food group correctly.":"Deux questions séparées permettent de compter correctement chaque groupe d'aliments.","Keep it and accept yes or no":"La garder et accepter oui ou non","Ask about meat, then ask about eggs, as two separate questions":"Demander pour la viande, puis pour les œufs, en deux questions séparées","Ask whether the child ate well yesterday":"Demander si l'enfant a bien mangé hier","Ask only about eggs":"Demander uniquement pour les œufs","\"Child's age in months: 0–6, 6–12, 12–24\" What is the problem?":"« Âge de l'enfant en mois : 0–6, 6–12, 12–24 » Quel est le problème ?","Best replacement for those options":"Meilleur remplacement pour ces options","Recording the exact age removes overlaps and gaps, and lets you build any age group during analysis, such as 0–5, 6–11 and 12–23 months.":"Enregistrer l'âge exact supprime chevauchements et trous, et permet de construire n'importe quelle tranche d'âge à l'analyse, comme 0–5, 6–11 et 12–23 mois.","0–6, 6–12, 12–24, 24 and over":"0–6, 6–12, 12–24, 24 et plus","Less than 1 year, 1 year or more":"Moins de 1 an, 1 an ou plus","Record the exact age in months as a number":"Enregistrer l'âge exact en mois sous forme de nombre","Young, medium, old":"Petit, moyen, grand","Exercise 3: A malaria survey across three health districts":"Exercice 3 : une enquête paludisme dans trois districts de santé","Stratified sample size":"Taille d'un échantillon stratifié","A fictional malaria project in the East region needs a reliable estimate of bed net use in each of three health districts. Fill":"Un projet fictif de lutte contre le paludisme dans la région de l'Est a besoin d'une estimation fiable de l'utilisation des moustiquaires dans chacun de trois districts de santé. Remplissez","with the final sample for each district, rounded up, including its design effect and non-response. When a district's design effect is blank, use the default in":"avec l'échantillon final de chaque district, arrondi au supérieur, en incluant son effet de plan et sa non-réponse. Quand l'effet de plan d'un district est vide, utilisez la valeur par défaut en",". Then fill":". Remplissez ensuite","with the total and":"avec le total et","with the enumerator-days needed if one enumerator completes 8 interviews a day, rounded up.":"avec le nombre de jours-enquêteur nécessaires si un enquêteur réalise 8 entretiens par jour, arrondi au supérieur.","For each district: =ROUNDUP($B$7^2*B2*(1-B2)/C2^2*IF(D2=\"\",$B$8,D2)/(1-E2),0). The IF picks the default design effect when D is blank. Total with SUM, then =ROUNDUP(F5/8,0).":"Pour chaque district : =ROUNDUP($B$7^2*B2*(1-B2)/C2^2*IF(D2=\"\",$B$8,D2)/(1-E2),0). Le IF (SI) prend l'effet de plan par défaut quand D est vide. Total avec SUM (SOMME), puis =ROUNDUP(F5/8,0).","Exercise 4: A nutrition screening form in the Far North":"Exercice 4 : un formulaire de dépistage nutritionnel dans l'Extrême-Nord","Screening logic and validation":"Logique de dépistage et validation","Community health workers of a fictional nutrition project screen children with this form. Make":"Les agents de santé communautaires d'un projet de nutrition fictif dépistent les enfants avec ce formulaire. Rendez","required and show the":"obligatoire et affichez le groupe","child":"child","group only when consent is yes. Make":"seulement si le consentement est oui. Rendez","age_months":"age_months","required and limited to 0–59. Show":"obligatoire et limité à 0–59. Affichez","muac_mm":"muac_mm","oedema":"oedema","only from 6 months, and limit MUAC to 70–250 mm. Show":"seulement à partir de 6 mois, et limitez le PB (MUAC) à 70–250 mm. Affichez","measles":"measles","only from 9 months. Show":"seulement à partir de 9 mois. Affichez","refer_note":"refer_note","when MUAC is below 115 mm or oedema is yes, and show":"lorsque le PB est inférieur à 115 mm ou que l'œdème est oui, et affichez","caregiver_phone":"caregiver_phone","in the same case, accepting only 9 digits starting with 6.":"dans le même cas, en n'acceptant que 9 chiffres commençant par 6.","Group: ${consent} = 'yes'. Age: . >= 0 and . <= 59. MUAC and oedema: ${age_months} >= 6. MUAC constraint: . >= 70 and . <= 250. Measles: ${age_months} >= 9. Referral: ${muac_mm} < 115 or ${oedema} = 'yes'. Phone constraint: regex(., '^6[0-9]{8}$').":"Groupe : ${consent} = 'yes'. Âge : . >= 0 and . <= 59. PB et œdème : ${age_months} >= 6. Contrainte du PB : . >= 70 and . <= 250. Rougeole : ${age_months} >= 9. Référence : ${muac_mm} < 115 or ${oedema} = 'yes'. Contrainte du téléphone : regex(., '^6[0-9]{8}$').","the child group appears only when consent = yes":"le groupe child n'apparaît que si consent = yes","age_months is required":"age_months est obligatoire","age_months accepts 0 to 59 only":"age_months n'accepte que 0 à 59","muac_mm appears only from 6 months":"muac_mm n'apparaît qu'à partir de 6 mois","muac_mm accepts 70 to 250 only":"muac_mm n'accepte que 70 à 250","oedema appears only from 6 months":"oedema n'apparaît qu'à partir de 6 mois","measles appears only from 9 months":"measles n'apparaît qu'à partir de 9 mois","refer_note appears when MUAC < 115 or oedema = yes":"refer_note apparaît si PB < 115 ou oedema = yes","caregiver_phone appears in the same case":"caregiver_phone apparaît dans le même cas","caregiver_phone accepts 9 digits starting with 6":"caregiver_phone n'accepte que 9 chiffres commençant par 6","You want to understand why many mothers stopped attending a community nutrition session. Which method fits best?":"Vous voulez comprendre pourquoi de nombreuses mères ont cessé de participer à une séance communautaire de nutrition. Quelle méthode convient le mieux ?","A household survey of 800 households":"Une enquête auprès de 800 ménages","Monthly attendance registers":"Les registres mensuels de présence","Focus group discussions with mothers who stopped attending":"Des groupes de discussion avec des mères qui ont cessé de venir","Observation of the sessions":"L'observation des séances","Reasons and perceptions are best explored in open discussion with the people concerned. Registers show that attendance fell, not why.":"Les raisons et les perceptions s'explorent le mieux en discussion ouverte avec les personnes concernées. Les registres montrent que la participation a baissé, pas pourquoi.","What does triangulation mean?":"Que signifie trianguler ?","Checking a finding with several methods, sources or data collectors":"Vérifier un constat avec plusieurs méthodes, sources ou collecteurs de données","Using three enumerators per household":"Envoyer trois enquêteurs par ménage","Sampling in three stages":"Échantillonner en trois degrés","Reporting results for three groups":"Rapporter les résultats pour trois groupes","When different methods and sources point the same way, the finding is stronger; when they disagree, the gap needs investigating.":"Quand différentes méthodes et sources vont dans le même sens, le constat est plus solide ; quand elles divergent, l'écart doit être approfondi.","With z = 1.96, p = 0.5 and a margin of error of 0.1, what is the basic sample size, rounded up?":"Avec z = 1,96, p = 0,5 et une marge d'erreur de 0,1, quelle est la taille d'échantillon de base, arrondie au supérieur ?","1.96² × 0.5 × 0.5 ÷ 0.1² = 96.04, rounded up to 97. Halving the margin of error to 0.05 would multiply it by four.":"1,96² × 0,5 × 0,5 ÷ 0,1² = 96,04, arrondi au supérieur à 97. Diviser la marge d'erreur par deux (0,05) la multiplierait par quatre.","Which adjustment compensates for households that will be absent or refuse?":"Quel ajustement compense les ménages qui seront absents ou refuseront ?","Multiplying by the design effect":"Multiplier par l'effet de plan","Dividing by (1 − expected non-response rate)":"Diviser par (1 − taux de non-réponse attendu)","Using p = 0.5":"Utiliser p = 0,5","Reducing the margin of error":"Réduire la marge d'erreur","Dividing by 0.9 for 10% non-response ensures that enough completed interviews remain. The design effect addresses clustering, not refusals.":"Diviser par 0,9 pour 10 % de non-réponse garantit qu'il reste assez d'entretiens complets. L'effet de plan traite le regroupement en grappes, pas les refus.","\"Are the teachers present and well trained?\" is an example of…":"« Les enseignants sont-ils présents et bien formés ? » est un exemple de…","A leading question":"Question orientée","An open question":"Question ouverte","A double-barrelled question":"Question double","A scale question":"Question à échelle","It asks two things at once. A respondent may say teachers are present but not well trained; split it into two questions.":"Elle demande deux choses à la fois. Un répondant peut dire que les enseignants sont présents mais mal formés ; séparez-la en deux questions.","Which sampling design fits a survey of 50 villages with no household list?":"Quel plan d'échantillonnage convient à une enquête dans 50 villages sans liste de ménages ?","Cluster sampling: select villages, then households within them":"L'échantillonnage en grappes : sélectionner des villages, puis des ménages à l'intérieur","Simple random sampling of households":"L'échantillonnage aléatoire simple des ménages","Purposive sampling of households":"L'échantillonnage raisonné des ménages","Systematic sampling from the beneficiary list":"L'échantillonnage systématique à partir de la liste des bénéficiaires","Without a household list, you first select clusters such as villages, then list and draw households inside them. Remember the design effect.":"Sans liste de ménages, vous sélectionnez d'abord des grappes comme les villages, puis vous dénombrez et tirez les ménages à l'intérieur. N'oubliez pas l'effet de plan.","During daily data review, one enumerator's interviews last 8 minutes on average while the others take 35. What should you do first?":"Lors de la revue quotidienne des données, les entretiens d'un enquêteur durent 8 minutes en moyenne alors que ceux des autres en durent 35. Que faites-vous en premier ?","Delete all of that enumerator's data":"Supprimer toutes les données de cet enquêteur","Ignore it: some enumerators are faster":"L'ignorer : certains enquêteurs sont plus rapides","Increase the sample size":"Augmenter la taille de l'échantillon","Run spot checks and back-checks on that enumerator's households and discuss the findings with them":"Faire des contrôles inopinés et des contre-visites sur les ménages de cet enquêteur et discuter des résultats avec lui","A very short duration is a warning sign, not proof. Verify with back-checks and spot checks before deciding whether to discard data or retrain.":"Une durée très courte est un signal d'alerte, pas une preuve. Vérifiez par des contre-visites et des contrôles inopinés avant de décider d'écarter les données ou de reformer.","In XLSForm, which entry shows the question care_sought only when a child had fever?":"En XLSForm, quelle entrée n'affiche la question care_sought que si un enfant a eu de la fièvre ?","constraint: ${child_fever} = 'yes'":"constraint: ${child_fever} = 'yes'","relevant: ${child_fever} = 'yes'":"relevant: ${child_fever} = 'yes'","required: ${child_fever}":"required: ${child_fever}","calculation: ${child_fever} = 'yes'":"calculation: ${child_fever} = 'yes'","The relevant column controls whether a question is shown. Constraints validate the answer to the question itself.":"La colonne relevant détermine si une question est affichée. Les contraintes valident la réponse à la question elle-même.","Digital Data Collection Tools":"Outils de collecte de données numériques","Build XLSForms and run digital surveys with KoboToolbox, ODK, SurveyCTO and CommCare.":"Créer des XLSForms et mener des enquêtes numériques avec KoboToolbox, ODK, SurveyCTO et CommCare.","Building forms in XLSForm":"Créer des formulaires avec XLSForm","Describe the role of the survey, choices and settings sheets of an XLSForm":"Décrire le rôle des feuilles survey, choices et settings d'un XLSForm","Choose the right question type and write valid names and choice lists":"Choisir le bon type de question et écrire des noms et des listes de choix valides","Build and extend a household form with required questions and a group":"Créer et compléter un formulaire ménage avec des questions obligatoires et un groupe","Most digital survey tools used in humanitarian and development work read the same kind of file: an XLSForm. It is an ordinary Excel workbook in which each row describes a question. Once you can write an XLSForm, you can run the same questionnaire in KoboToolbox, ODK or SurveyCTO with little or no change.":"La plupart des outils d'enquête numérique utilisés dans l'humanitaire et le développement lisent le même type de fichier : un XLSForm. C'est un classeur Excel ordinaire dans lequel chaque ligne décrit une question. Une fois que vous savez écrire un XLSForm, vous pouvez utiliser le même questionnaire dans KoboToolbox, ODK ou SurveyCTO avec peu ou pas de modifications.","Three sheets make a form":"Trois feuilles forment un formulaire","Sheet":"Feuille","What it holds":"Ce qu'elle contient","Key columns":"Colonnes clés","survey":"survey","One row per question, note, calculation or group, in the order the enumerator sees them":"Une ligne par question, note, calcul ou groupe, dans l'ordre où l'enquêteur les voit","type, name, label, required, hint, relevant, constraint, calculation":"type, name, label, required, hint, relevant, constraint, calculation","choices":"choices","The answer options of every select_one and select_multiple question":"Les options de réponse de chaque question select_one et select_multiple","list_name, name, label":"list_name, name, label","settings (optional)":"settings (facultative)","Information about the form itself":"Des informations sur le formulaire lui-même","form_title, form_id, version, default_language":"form_title, form_id, version, default_language","The survey sheet: one row per question":"La feuille survey : une ligne par question","What you write":"Ce que vous écrivez","type":"type","The question type, and for select questions the list name":"Le type de question et, pour les questions à choix, le nom de la liste","select_one yes_no":"select_one yes_no","name":"name","A short unique variable name: it becomes the column header of your dataset":"Un nom de variable court et unique : il devient l'en-tête de colonne de votre base de données","label":"label","The question text the enumerator reads":"Le texte de la question que lit l'enquêteur","yes when the question cannot be skipped":"yes lorsque la question ne peut pas être sautée","yes":"yes","hint":"hint","A short instruction shown under the label":"Une courte consigne affichée sous le libellé","Include babies and elderly people":"Comptez les bébés et les personnes âgées","A condition: the question appears only when it is true":"Une condition : la question n'apparaît que lorsqu'elle est vraie","${consent} = 'yes'":"${consent} = 'yes'","Question types you will use most":"Les types de questions les plus utilisés","What it collects":"Ce qu'il collecte","text":"text","Free text":"Du texte libre","Name of the village, other answer to specify":"Nom du village, autre réponse à préciser","integer":"integer","A whole number":"Un nombre entier","Household size, age in years, number of meals":"Taille du ménage, âge en années, nombre de repas","decimal":"decimal","A number with decimals":"Un nombre avec décimales","Weight in kg, area of a field in hectares":"Poids en kg, superficie d'un champ en hectares","select_one list":"select_one liste","Sex, main water source, yes/no":"Sexe, principale source d'eau, oui/non","select_multiple list":"select_multiple liste","Several answers from a list":"Plusieurs réponses dans une liste","Crops grown, types of assistance received":"Cultures pratiquées, types d'assistance reçue","date":"date","A calendar date":"Une date du calendrier","Date of birth, date of the last distribution":"Date de naissance, date de la dernière distribution","geopoint":"geopoint","GPS coordinates from the phone":"Les coordonnées GPS du téléphone","Location of a water point or a household":"Emplacement d'un point d'eau ou d'un ménage","image":"image","A photo taken with the phone":"Une photo prise avec le téléphone","Photo of a completed latrine":"Photo d'une latrine achevée","note":"note","Text displayed, no answer":"Un texte affiché, sans réponse","Instructions, consent script, section titles":"Consignes, texte du consentement, titres de sections","calculate":"calculate","A value computed from other answers, not shown":"Une valeur calculée à partir d'autres réponses, non affichée","Number of adults = household size minus children":"Nombre d'adultes = taille du ménage moins les enfants","Naming rules":"Règles de nommage","A name starts with a letter or an underscore and contains only letters, digits and underscores: no spaces, no accents, no hyphens at the start. Every name in the survey sheet must be unique. Keep names short and in English or French consistently, for example hh_size, water_source, muac_mm.":"Un nom commence par une lettre ou un tiret bas et ne contient que des lettres, des chiffres et des tirets bas : pas d'espaces, pas d'accents, pas de trait d'union au début. Chaque nom de la feuille survey doit être unique. Gardez des noms courts, en anglais ou en français de façon cohérente, par exemple hh_size, water_source, muac_mm.","Choice lists and list_name":"Listes de choix et list_name","A select question points to a list by its list_name: the type select_one water means the answers come from all rows of the choices sheet with list_name water. The choice name is what is stored in the data, the label is what the enumerator sees. One list can serve several questions, which is why a yes_no list is written only once.":"Une question à choix renvoie à une liste par son list_name : le type select_one water signifie que les réponses proviennent de toutes les lignes de la feuille choices dont le list_name est water. Le name du choix est ce qui est enregistré dans les données, le label est ce que voit l'enquêteur. Une même liste peut servir à plusieurs questions ; c'est pourquoi une liste yes_no n'est écrite qu'une fois.","Pick the type and check the names":"Choisir le type et vérifier les noms","A fictional nutrition project in the North region is drafting its household form. Choose the question type for each item, then say whether each proposed name is valid.":"Un projet de nutrition fictif dans la région du Nord prépare son formulaire ménage. Choisissez le type de question de chaque élément, puis indiquez si chaque nom proposé est valide.","Whole numbers are integer, numbers with a comma are decimal, one answer from a list is select_one, several answers is select_multiple. A valid name has no spaces and does not start with a digit.":"Les nombres entiers sont integer, les nombres à virgule sont decimal, une réponse dans une liste est select_one, plusieurs réponses est select_multiple. Un nom valide n'a pas d'espace et ne commence pas par un chiffre.","Number of children under five in the household":"Nombre d'enfants de moins de cinq ans dans le ménage","select_one":"select_one","select_multiple":"select_multiple","Weight of the child in kilograms, for example 11.4":"Poids de l'enfant en kilogrammes, par exemple 11,4","A value with decimals needs the decimal type; integer would refuse 11.4.":"Une valeur avec décimales exige le type decimal ; integer refuserait 11,4.","Main source of drinking water (one answer)":"Principale source d'eau de boisson (une seule réponse)","All the crops grown by the household this season":"Toutes les cultures pratiquées par le ménage cette saison","Several answers from the same list call for select_multiple.":"Plusieurs réponses dans la même liste demandent un select_multiple.","Location of the health post":"Emplacement du poste de santé","Photo of the ration card":"Photo de la carte de ration","An instruction to the enumerator with no answer":"Une consigne à l'enquêteur, sans réponse","Number of adults, computed from household size minus children":"Nombre d'adultes, calculé comme la taille du ménage moins les enfants","A calculate row computes a value from other answers without asking anything.":"Une ligne calculate calcule une valeur à partir d'autres réponses sans rien demander.","Proposed name: hh size":"Nom proposé : hh size","Names cannot contain spaces. Use hh_size.":"Les noms ne peuvent pas contenir d'espaces. Utilisez hh_size.","Valid name":"Nom valide","Invalid name":"Nom invalide","Proposed name: 2nd_visit":"Nom proposé : 2nd_visit","Names must start with a letter or an underscore. Use visit_2 instead.":"Les noms doivent commencer par une lettre ou un tiret bas. Utilisez plutôt visit_2.","Proposed name: water_source":"Nom proposé : water_source","Groups":"Les groupes","A group is opened by a begin_group row and closed by an end_group row. Everything between them forms a section, for example Household, Water or Health. Groups keep long forms readable, and a relevant condition written on the begin_group row applies to every question inside it.":"Un groupe s'ouvre par une ligne begin_group et se ferme par une ligne end_group. Tout ce qui se trouve entre les deux forme une section, par exemple Ménage, Eau ou Santé. Les groupes rendent les longs formulaires lisibles, et une condition relevant écrite sur la ligne begin_group s'applique à toutes les questions du groupe.","Upload an XLSForm":"Upload an XLSForm","Imports your XLSForm file into a new KoboToolbox project.":"Importe votre fichier XLSForm dans un nouveau projet KoboToolbox.","Extend a household form":"Compléter un formulaire ménage","A fictional food security survey in the Adamawa region. Make hh_size required. Replace the placeholder row with a select_one question named main_food using a new list food_source with the choices own_production, market and food_assistance. Add a date question named visit_date at the top, and put hh_size, main_food and meals inside a group named food.":"Une enquête fictive de sécurité alimentaire dans la région de l'Adamaoua. Rendez hh_size obligatoire. Remplacez la ligne provisoire par une question select_one nommée main_food utilisant une nouvelle liste food_source avec les choix own_production, market et food_assistance. Ajoutez en haut une question date nommée visit_date, et placez hh_size, main_food et meals dans un groupe nommé food.","hh_size: required yes. Placeholder row: type select_one food_source, name main_food. In the choices sheet add three rows with list_name food_source. First row: type date, name visit_date. Add a begin_group row named food before hh_size and an end_group row after meals.":"hh_size : required yes. Ligne provisoire : type select_one food_source, name main_food. Dans la feuille choices, ajoutez trois lignes avec le list_name food_source. Première ligne : type date, name visit_date. Ajoutez une ligne begin_group nommée food avant hh_size et une ligne end_group après meals.","visit_date is a date question":"visit_date est une question date","hh_size is required":"hh_size est obligatoire","main_food is a select_one food_source question":"main_food est une question select_one food_source","the food_source list has own_production, market and food_assistance":"la liste food_source contient own_production, market et food_assistance","a group named food is opened":"un groupe nommé food est ouvert","A question has the type select_one crops, but the phone shows no answer options. What is the most likely cause?":"Une question a le type select_one crops, mais le téléphone n'affiche aucune option de réponse. Quelle est la cause la plus probable ?","The question is not required":"La question n'est pas obligatoire","The choices sheet has no rows with list_name crops, or the list name is spelled differently":"La feuille choices n'a aucune ligne avec le list_name crops, ou le nom de la liste est écrit différemment","select_one cannot be used for crops":"select_one ne peut pas être utilisé pour les cultures","The label is too long":"Le libellé est trop long","The word after select_one must match a list_name in the choices sheet exactly. A typo such as crop instead of crops leaves the question without options, and most tools refuse to deploy the form.":"Le mot qui suit select_one doit correspondre exactement à un list_name de la feuille choices. Une faute de frappe, par exemple crop au lieu de crops, laisse la question sans options, et la plupart des outils refusent de déployer le formulaire.","A fictional NGO in Ngaoundéré keeps one master XLSForm per survey in a shared folder, with a change log in the settings sheet and English names for every variable, while labels are in French and English. When the Yaoundé office asks for the dataset, every column name is already clear and stable from one round to the next.":"Une ONG fictive de Ngaoundéré conserve un XLSForm de référence par enquête dans un dossier partagé, avec un journal des modifications dans la feuille settings et des noms anglais pour chaque variable, tandis que les libellés sont en français et en anglais. Quand le bureau de Yaoundé demande la base de données, chaque nom de colonne est déjà clair et stable d'une vague à l'autre.","Rewrite five questions of a paper questionnaire you use as rows of an XLSForm survey sheet":"Réécrivez cinq questions d'un questionnaire papier que vous utilisez sous forme de lignes de la feuille survey d'un XLSForm","Create a yes_no list and one list with at least four choices in the choices sheet":"Créez une liste yes_no et une liste d'au moins quatre choix dans la feuille choices","Check that every name is unique, short and without spaces":"Vérifiez que chaque nom est unique, court et sans espace","Organise the form into at least two groups and add a hint to one question":"Organisez le formulaire en au moins deux groupes et ajoutez un hint à une question","Upload the file to a KoboToolbox project and open the preview":"Téléversez le fichier dans un projet KoboToolbox et ouvrez l'aperçu","XLSForm documentation":"Documentation XLSForm","KoboToolbox and ODK: deploy, collect offline and sync":"KoboToolbox et ODK : déployer, collecter hors ligne et synchroniser","Deploy an XLSForm on a KoboToolbox or ODK Central server":"Déployer un XLSForm sur un serveur KoboToolbox ou ODK Central","Set up KoboCollect or ODK Collect to collect offline and send finalized forms":"Configurer KoboCollect ou ODK Collect pour collecter hors ligne et envoyer les formulaires finalisés","Manage form versions and solve the most common deployment problems":"Gérer les versions de formulaire et résoudre les problèmes de déploiement les plus courants","A digital survey has two halves: a server where forms are published and data is stored, and a mobile app that enumerators use in the field. The app works without a network; it needs a connection only to download the blank form and to send completed interviews. This is what makes digital collection possible in villages with weak or no coverage.":"Une enquête numérique a deux moitiés : un serveur où les formulaires sont publiés et les données stockées, et une application mobile que les enquêteurs utilisent sur le terrain. L'application fonctionne sans réseau ; elle n'a besoin d'une connexion que pour télécharger le formulaire vierge et envoyer les entretiens terminés. C'est ce qui rend la collecte numérique possible dans des villages où la couverture est faible ou absente.","The pieces of the system":"Les éléments du système","Component":"Composant","KoboToolbox":"KoboToolbox","ODK":"ODK","Server and web platform":"Serveur et plateforme web","KoboToolbox, on the Global or the European Union server":"KoboToolbox, sur le serveur Global ou le serveur Union européenne","ODK Central, self-hosted or on paid ODK Cloud hosting":"ODK Central, auto-hébergé ou sur l'hébergement payant ODK Cloud","Android app for enumerators":"Application Android pour les enquêteurs","KoboCollect":"KoboCollect","ODK Collect":"ODK Collect","Form design":"Conception des formulaires","XLSForm upload or the online form builder":"Téléversement d'un XLSForm ou éditeur de formulaires en ligne","XLSForm upload":"Téléversement d'un XLSForm","Cost":"Coût","Free Community plan with monthly limits, paid plans above":"Plan Community gratuit avec des limites mensuelles, plans payants au-delà","Free and open source; you pay for your own server or for ODK Cloud":"Gratuit et open source ; vous payez votre propre serveur ou ODK Cloud","Which KoboToolbox server?":"Quel serveur KoboToolbox ?","KoboToolbox runs two public servers with separate accounts: the Global server (kf.kobotoolbox.org) and the European Union server (eu.kobotoolbox.org). The EU server replaced the former humanitarian server that was hosted with OCHA, and many humanitarian organisations use it. Create your account on the server your organisation uses, because a project on one server is invisible from the other.":"KoboToolbox gère deux serveurs publics aux comptes séparés : le serveur Global (kf.kobotoolbox.org) et le serveur Union européenne (eu.kobotoolbox.org). Le serveur UE a remplacé l'ancien serveur humanitaire hébergé avec OCHA, et de nombreuses organisations humanitaires l'utilisent. Créez votre compte sur le serveur qu'utilise votre organisation, car un projet sur un serveur est invisible depuis l'autre.","Match the app to the server":"Faire correspondre l'application et le serveur","KoboCollect must point to the collection URL of the same server as your account: kc.kobotoolbox.org for the Global server, kc-eu.kobotoolbox.org for the EU server. A phone set to the wrong server cannot log in or find your forms.":"KoboCollect doit pointer vers l'URL de collecte du même serveur que votre compte : kc.kobotoolbox.org pour le serveur Global, kc-eu.kobotoolbox.org pour le serveur UE. Un téléphone réglé sur le mauvais serveur ne peut ni se connecter ni trouver vos formulaires.","From XLSForm to deployed form":"Du XLSForm au formulaire déployé","Creates the project from your file; enter a project name and description, then create it.":"Crée le projet à partir de votre fichier ; saisissez un nom et une description, puis créez-le.","Deploy in KoboToolbox":"Déployer dans KoboToolbox","Upload the XLSForm to a new project and fix any error message about types, names or lists.":"Téléversez le XLSForm dans un nouveau projet et corrigez tout message d'erreur sur les types, les noms ou les listes.","Open the preview and test every skip rule and constraint in the browser.":"Ouvrez l'aperçu et testez chaque saut et chaque contrainte dans le navigateur.","Click Deploy on the project page: the form becomes available for collection.":"Cliquez sur Deploy dans la page du projet : le formulaire devient disponible pour la collecte.","Share the project with the enumerators' accounts, or use one collection account per team.":"Partagez le projet avec les comptes des enquêteurs, ou utilisez un compte de collecte par équipe.","After any change, replace the form and redeploy it: a new version is created.":"Après toute modification, remplacez le formulaire et redéployez-le : une nouvelle version est créée.","ODK Central follows the same logic: create a project, upload the XLSForm as a draft, test the draft, then publish it. Enumerators use App Users, and each phone is configured by scanning a QR code generated by Central.":"ODK Central suit la même logique : créez un projet, téléversez le XLSForm comme brouillon, testez le brouillon, puis publiez-le. Les enquêteurs utilisent des App Users, et chaque téléphone est configuré en scannant un code QR généré par Central.","Collecting offline with KoboCollect or ODK Collect":"Collecter hors ligne avec KoboCollect ou ODK Collect","On the enumerator's phone":"Sur le téléphone de l'enquêteur","Install KoboCollect or ODK Collect from the Google Play Store.":"Installez KoboCollect ou ODK Collect depuis le Google Play Store.","Configure the project: enter the server URL, username and password, or scan the QR code.":"Configurez le projet : saisissez l'URL du serveur, le nom d'utilisateur et le mot de passe, ou scannez le code QR.","With a connection, open Download form and select the blank forms of the survey.":"Avec une connexion, ouvrez Download form et sélectionnez les formulaires vierges de l'enquête.","In the field, start a new form for each interview; no network is needed.":"Sur le terrain, commencez un nouveau formulaire pour chaque entretien ; aucun réseau n'est nécessaire.","At the end of the interview, finalize the form; save it as a draft only if it is incomplete.":"À la fin de l'entretien, finalisez le formulaire ; ne l'enregistrez comme brouillon que s'il est incomplet.","When back in coverage, send the finalized forms and check that the list of forms ready to send is empty.":"De retour dans une zone couverte, envoyez les formulaires finalisés et vérifiez que la liste des formulaires prêts à envoyer est vide.","Data lives on the phone until it is sent":"Les données restent sur le téléphone jusqu'à leur envoi","Finalized interviews stay on the device until they reach the server. Send at least once a day when you can, never uninstall the app or clear its data before sending, and check on the server that the number of submissions matches the enumerators' daily counts.":"Les entretiens finalisés restent sur l'appareil jusqu'à ce qu'ils atteignent le serveur. Envoyez au moins une fois par jour quand c'est possible, ne désinstallez jamais l'application et n'effacez jamais ses données avant l'envoi, et vérifiez sur le serveur que le nombre de soumissions correspond aux décomptes quotidiens des enquêteurs.","Form versions":"Versions de formulaire","Each time you change and redeploy a form, the server creates a new version. KoboToolbox sets the version automatically; in ODK you can control it in the version column of the settings sheet. Enumerators must download the new version before starting new interviews. Interviews already collected with the old version are still accepted, but avoid renaming or deleting questions during collection, because their data will be split across columns.":"Chaque fois que vous modifiez et redéployez un formulaire, le serveur crée une nouvelle version. KoboToolbox fixe la version automatiquement ; dans ODK, vous pouvez la contrôler dans la colonne version de la feuille settings. Les enquêteurs doivent télécharger la nouvelle version avant de commencer de nouveaux entretiens. Les entretiens déjà collectés avec l'ancienne version restent acceptés, mais évitez de renommer ou de supprimer des questions en cours de collecte, car leurs données seraient réparties sur plusieurs colonnes.","Deploy, collect and troubleshoot":"Déployer, collecter et dépanner","A fictional WASH survey in the Far North region is about to start. First put the seven steps in the right order, then choose the best fix for each problem reported by the team.":"Une enquête EHA fictive dans la région de l'Extrême-Nord va commencer. Mettez d'abord les sept étapes dans le bon ordre, puis choisissez la meilleure solution à chaque problème signalé par l'équipe.","Work from the office to the field: file, test, deploy, then phones, then offline collection, then sending. For problems, ask whether the issue is on the server, in the app settings, or in what the enumerator did.":"Allez du bureau vers le terrain : fichier, test, déploiement, puis téléphones, puis collecte hors ligne, puis envoi. Pour les problèmes, demandez-vous si la cause est sur le serveur, dans les paramètres de l'application ou dans ce qu'a fait l'enquêteur.","Step 1":"Étape 1","Deploy the form":"Déployer le formulaire","Send the finalized forms when a connection is available":"Envoyer les formulaires finalisés quand une connexion est disponible","Upload the XLSForm to a new project":"Téléverser le XLSForm dans un nouveau projet","Configure the collection app with the server URL and account":"Configurer l'application de collecte avec l'URL du serveur et le compte","Fill and finalize interviews offline":"Remplir et finaliser les entretiens hors ligne","Preview and test the form in the browser":"Prévisualiser et tester le formulaire dans le navigateur","Download the blank form to the phone":"Télécharger le formulaire vierge sur le téléphone","Step 2":"Étape 2","Step 3":"Étape 3","Step 4":"Étape 4","Step 5":"Étape 5","Step 6":"Étape 6","Step 7":"Étape 7","Enumerators collect offline and send when they find a connection, for example at the base in the evening.":"Les enquêteurs collectent hors ligne et envoient quand ils trouvent une connexion, par exemple à la base le soir.","An enumerator cannot see the survey in the list of forms to download.":"Un enquêteur ne voit pas l'enquête dans la liste des formulaires à télécharger.","Only deployed forms that the account can access appear in the download list.":"Seuls les formulaires déployés auxquels le compte a accès apparaissent dans la liste de téléchargement.","Turn on the phone's GPS":"Activer le GPS du téléphone","Check that the form is deployed and that the account on the phone has access to the project":"Vérifier que le formulaire est déployé et que le compte du téléphone a accès au projet","Delete the choices sheet":"Supprimer la feuille choices","Reinstall the app and clear its data":"Réinstaller l'application et effacer ses données","After one week, the server shows 12 submissions, but the enumerators say they did 140 interviews.":"Au bout d'une semaine, le serveur affiche 12 soumissions, mais les enquêteurs disent avoir fait 140 entretiens.","Data stays on the phone until it is finalized and sent. Check drafts and unsent forms before anything else.":"Les données restent sur le téléphone jusqu'à ce qu'elles soient finalisées et envoyées. Vérifiez les brouillons et les formulaires non envoyés avant toute autre chose.","The server deletes old submissions":"Le serveur supprime les anciennes soumissions","The form has too many questions":"Le formulaire a trop de questions","The interviews are probably saved as drafts or were never sent; check the forms ready to send on each phone":"Les entretiens sont probablement enregistrés comme brouillons ou n'ont jamais été envoyés ; vérifiez les formulaires prêts à envoyer sur chaque téléphone","The enumerators must fill the forms again":"Les enquêteurs doivent remplir à nouveau les formulaires","You corrected a question and redeployed, but enumerators still see the old wording.":"Vous avez corrigé une question et redéployé, mais les enquêteurs voient toujours l'ancienne formulation.","They must download the new version of the form before starting new interviews":"Ils doivent télécharger la nouvelle version du formulaire avant de commencer de nouveaux entretiens","The server needs a day to update":"Le serveur a besoin d'une journée pour se mettre à jour","You must create a new project":"Vous devez créer un nouveau projet","The change only appears in the export":"La modification n'apparaît que dans l'export","A new enumerator cannot log in. Your team's account is on the EU server.":"Un nouvel enquêteur ne parvient pas à se connecter. Le compte de votre équipe est sur le serveur UE.","The collection app must point to the same server as the account.":"L'application de collecte doit pointer vers le même serveur que le compte.","Create a new account on the Global server":"Créer un nouveau compte sur le serveur Global","Use the form builder instead":"Utiliser plutôt l'éditeur de formulaires","Send the XLSForm by WhatsApp":"Envoyer le XLSForm par WhatsApp","Set the server URL in the app to kc-eu.kobotoolbox.org":"Régler l'URL du serveur dans l'application sur kc-eu.kobotoolbox.org","An enumerator works three days in a village without network. What happens to the interviews?":"Un enquêteur travaille trois jours dans un village sans réseau. Que deviennent les entretiens ?","They are lost unless the phone has a connection":"Ils sont perdus si le téléphone n'a pas de connexion","They are stored on the phone and sent when the enumerator reaches a connection":"Ils sont stockés sur le téléphone et envoyés lorsque l'enquêteur trouve une connexion","They are sent automatically by SMS":"Ils sont envoyés automatiquement par SMS","They must be copied on paper":"Ils doivent être recopiés sur papier","KoboCollect and ODK Collect are built for offline work: finalized forms wait on the phone until they are sent.":"KoboCollect et ODK Collect sont conçus pour le travail hors ligne : les formulaires finalisés attendent sur le téléphone jusqu'à leur envoi.","During a fictional baseline in Mayo-Sava, enumerators slept in villages without coverage for four days. The supervisor set a rule: finalize each interview immediately, send everything from the market town every fourth day, and report the daily number of interviews by SMS. The MEAL officer compared those counts with the server and spotted one phone whose forms had stayed in draft.":"Lors d'une situation de référence fictive dans le Mayo-Sava, les enquêteurs ont dormi quatre jours dans des villages sans couverture. Le superviseur a fixé une règle : finaliser chaque entretien immédiatement, tout envoyer depuis la ville du marché tous les quatre jours et communiquer chaque jour le nombre d'entretiens par SMS. Le chargé MEAL a comparé ces décomptes avec le serveur et repéré un téléphone dont les formulaires étaient restés en brouillon.","Create a free KoboToolbox account on the server your organisation uses":"Créez un compte KoboToolbox gratuit sur le serveur qu'utilise votre organisation","Upload the XLSForm from Lesson 1, test it in the preview and deploy it":"Téléversez le XLSForm de la leçon 1, testez-le dans l'aperçu et déployez-le","Install KoboCollect on an Android phone and connect it to your account":"Installez KoboCollect sur un téléphone Android et connectez-le à votre compte","Fill three test interviews in airplane mode, then send them and find them on the server":"Remplissez trois entretiens de test en mode avion, puis envoyez-les et retrouvez-les sur le serveur","Change one label, redeploy, and check that the phone gets the new version":"Modifiez un libellé, redéployez et vérifiez que le téléphone reçoit la nouvelle version","Setting up KoboCollect on Android":"Configurer KoboCollect sur Android","ODK Central":"ODK Central","SurveyCTO and CommCare: when to choose them":"SurveyCTO et CommCare : quand les choisir","Describe the main strengths of SurveyCTO and CommCare compared with KoboToolbox and ODK":"Décrire les principaux atouts de SurveyCTO et de CommCare par rapport à KoboToolbox et ODK","Compare the licensing models of the four tools at a high level":"Comparer dans les grandes lignes les modèles de licence des quatre outils","Choose the right tool for a project using clear decision criteria":"Choisir le bon outil pour un projet à l'aide de critères de décision clairs","KoboToolbox and ODK cover most surveys. Two other tools are common in Central Africa for specific needs: SurveyCTO when security and quality control come first, and CommCare when frontline workers must follow the same people over many visits. Choosing well at the start saves months of workarounds.":"KoboToolbox et ODK couvrent la plupart des enquêtes. Deux autres outils sont courants en Afrique centrale pour des besoins particuliers : SurveyCTO quand la sécurité et le contrôle qualité passent en premier, et CommCare quand des agents de première ligne doivent suivre les mêmes personnes au fil de nombreuses visites. Bien choisir au départ évite des mois de solutions de contournement.","One family, different strengths":"Une même famille, des atouts différents","KoboToolbox, ODK and SurveyCTO all use spreadsheet form definitions based on XLSForm, so your skills carry over; SurveyCTO adds some field types and functions of its own. CommCare is different: forms are built in its own web application builder and packaged into mobile apps with several modules.":"KoboToolbox, ODK et SurveyCTO utilisent tous des définitions de formulaires en tableur basées sur XLSForm, vos compétences restent donc valables ; SurveyCTO ajoute quelques types de champs et fonctions qui lui sont propres. CommCare est différent : les formulaires sont créés dans son propre générateur d'applications web et regroupés dans des applications mobiles à plusieurs modules.","SurveyCTO: security and quality control":"SurveyCTO : sécurité et contrôle qualité","Form encryption is built in and easy to switch on: data is encrypted on the phone and can only be read with the organisation's private key.":"Le chiffrement des formulaires est intégré et facile à activer : les données sont chiffrées sur le téléphone et ne peuvent être lues qu'avec la clé privée de l'organisation.","Quality control features such as automated quality checks, review and approval of submissions, and audio or text audits of interviews.":"Des fonctions de contrôle qualité comme les vérifications automatiques, la revue et l'approbation des soumissions, et les audits audio ou texte des entretiens.","Support for phone surveys, web forms and advanced workflows used by research teams.":"La prise en charge des enquêtes téléphoniques, des formulaires web et de flux de travail avancés utilisés par les équipes de recherche.","A paid subscription, with a free trial; hosting is provided by the vendor.":"Un abonnement payant, avec un essai gratuit ; l'hébergement est assuré par l'éditeur.","CommCare: follow people over time":"CommCare : suivre les personnes dans le temps","Case management: a case, such as a pregnant woman or a child in a nutrition programme, is registered once and updated at each follow-up visit.":"La gestion de cas : un cas, par exemple une femme enceinte ou un enfant dans un programme de nutrition, est enregistré une fois puis mis à jour à chaque visite de suivi.","Apps guide community health workers through visits, show who is due for a follow-up and can include counselling content.":"Les applications guident les agents de santé communautaires pendant les visites, indiquent qui doit être revu et peuvent inclure des contenus de conseil.","Works offline by default and synchronises when a connection is available.":"Fonctionne hors ligne par défaut et se synchronise lorsqu'une connexion est disponible.","Developed by Dimagi, open source, with a free plan and paid plans for larger deployments.":"Développé par Dimagi, open source, avec un plan gratuit et des plans payants pour les déploiements plus importants.","Longitudinal data in other tools":"Les données longitudinales dans les autres outils","ODK Central now offers Entities, and SurveyCTO has case management features, so simple follow-up is possible outside CommCare. For large programmes with many visits per person, reminders and referrals, CommCare remains the specialised choice.":"ODK Central propose désormais les Entities et SurveyCTO dispose de fonctions de gestion de cas, un suivi simple est donc possible en dehors de CommCare. Pour de grands programmes avec de nombreuses visites par personne, des rappels et des références, CommCare reste le choix spécialisé.","Licensing at a glance":"Les licences en un coup d'œil","Tool":"Outil","Cost model":"Modèle de coût","Hosting":"Hébergement","Free Community plan with limits; paid plans for higher volume":"Plan Community gratuit avec des limites ; plans payants pour les volumes plus élevés","Hosted by Kobo (Global or EU server), or your own server":"Hébergé par Kobo (serveur Global ou UE), ou sur votre propre serveur","Free, open-source software":"Logiciel gratuit et open source","Your own server, or paid ODK Cloud":"Votre propre serveur, ou ODK Cloud payant","SurveyCTO":"SurveyCTO","Paid subscription, free trial":"Abonnement payant, essai gratuit","Hosted by the vendor":"Hébergé par l'éditeur","CommCare":"CommCare","Free plan, paid plans by features and users":"Plan gratuit, plans payants selon les fonctions et le nombre d'utilisateurs","Hosted by Dimagi, or self-hosted":"Hébergé par Dimagi, ou auto-hébergé","Decision criteria":"Critères de décision","Criterion":"Critère","Points towards":"Oriente vers","No budget, one-off survey, staff new to digital tools":"Pas de budget, enquête ponctuelle, personnel novice en outils numériques","Data must stay on a server the organisation or ministry controls":"Les données doivent rester sur un serveur contrôlé par l'organisation ou le ministère","ODK Central, self-hosted":"ODK Central, auto-hébergé","Highly sensitive data, strict encryption and quality control, research budget":"Données très sensibles, chiffrement et contrôle qualité stricts, budget de recherche","The same people are visited many times, with reminders and referrals":"Les mêmes personnes sont visitées de nombreuses fois, avec rappels et références","Rapid assessment to deploy in two or three days":"Évaluation rapide à déployer en deux ou trois jours","KoboToolbox or ODK":"KoboToolbox ou ODK","Existing team skills and the donor's or cluster's standard tool":"Compétences existantes de l'équipe et outil standard du bailleur ou du cluster","The tool the team already masters":"L'outil que l'équipe maîtrise déjà","Choose the right tool":"Choisir le bon outil","For each fictional situation in Cameroon, choose the tool that fits best.":"Pour chaque situation fictive au Cameroun, choisissez l'outil le plus adapté.","Look for the deciding need: no budget and speed, control of the server, strong security and quality control, or follow-up of the same people over time.":"Cherchez le besoin décisif : absence de budget et rapidité, contrôle du serveur, sécurité et contrôle qualité renforcés, ou suivi des mêmes personnes dans le temps.","A small local NGO in Adamawa with no budget for software runs a one-off baseline of 400 households.":"Une petite ONG locale de l'Adamaoua, sans budget pour les logiciels, réalise une situation de référence ponctuelle auprès de 400 ménages.","The free Community plan and the online builder make KoboToolbox the easiest start.":"Le plan Community gratuit et l'éditeur en ligne font de KoboToolbox le point de départ le plus simple.","ODK (Central and Collect)":"ODK (Central et Collect)","Community health workers in a health district visit pregnant women several times and must know who is due for the next visit.":"Des agents de santé communautaires d'un district de santé rendent plusieurs visites à des femmes enceintes et doivent savoir qui attend la prochaine visite.","Registering each woman as a case and updating it at every visit is what CommCare is built for.":"Enregistrer chaque femme comme un cas et le mettre à jour à chaque visite, c'est exactement ce pour quoi CommCare est conçu.","A university research team runs a survey on sensitive attitudes, needs strong encryption and audio audits, and has a research budget.":"Une équipe de recherche universitaire mène une enquête sur des attitudes sensibles, a besoin d'un chiffrement fort et d'audits audio, et dispose d'un budget de recherche.","A ministry wants all survey data on its own server in Yaoundé, managed by its IT unit.":"Un ministère veut que toutes les données d'enquête soient sur son propre serveur à Yaoundé, géré par sa cellule informatique.","ODK Central is free, open source and can be installed on a server the ministry controls.":"ODK Central est gratuit, open source et peut être installé sur un serveur contrôlé par le ministère.","A humanitarian organisation must launch a rapid needs assessment after floods within three days.":"Une organisation humanitaire doit lancer une évaluation rapide des besoins après des inondations en moins de trois jours.","A nutrition programme follows each child admitted for treatment every week until discharge, with referral if the child does not improve.":"Un programme de nutrition suit chaque semaine chaque enfant admis en traitement jusqu'à sa sortie, avec référence si l'enfant ne s'améliore pas.","What is the main reason to choose CommCare over a simple survey tool?":"Quelle est la principale raison de choisir CommCare plutôt qu'un simple outil d'enquête ?","It is the only tool that works offline":"C'est le seul outil qui fonctionne hors ligne","It uses the same XLSForm files as KoboToolbox":"Il utilise les mêmes fichiers XLSForm que KoboToolbox","It manages cases that are followed and updated over many visits":"Il gère des cas suivis et mis à jour au fil de nombreuses visites","It is always free":"Il est toujours gratuit","All four tools work offline. CommCare's strength is case management for longitudinal follow-up by frontline workers.":"Les quatre outils fonctionnent hors ligne. La force de CommCare est la gestion de cas pour le suivi longitudinal par les agents de première ligne.","A fictional consortium in the East region used KoboToolbox for its quarterly household surveys and CommCare for its community health workers' home visits. The MEAL officer linked the two only through shared village codes, which kept each tool doing what it does best without a costly integration.":"Un consortium fictif de la région de l'Est utilisait KoboToolbox pour ses enquêtes ménages trimestrielles et CommCare pour les visites à domicile de ses agents de santé communautaires. Le chargé MEAL reliait les deux uniquement par des codes de village communs, ce qui permettait à chaque outil de faire ce qu'il fait le mieux sans intégration coûteuse.","List the data collection needs of your project for the next twelve months":"Listez les besoins de collecte de données de votre projet pour les douze prochains mois","Mark which needs are one-off surveys and which involve following the same people":"Indiquez quels besoins sont des enquêtes ponctuelles et lesquels impliquent de suivre les mêmes personnes","Check your data protection requirements and where the data may be hosted":"Vérifiez vos exigences de protection des données et les lieux où les données peuvent être hébergées","Estimate your budget for software licences, phones and hosting":"Estimez votre budget pour les licences, les téléphones et l'hébergement","Write a one-paragraph recommendation of the tool to use, with two reasons":"Rédigez en un paragraphe une recommandation de l'outil à utiliser, avec deux raisons","SurveyCTO documentation":"Documentation SurveyCTO","GPS, photos, validation and exporting data":"GPS, photos, validation et export des données","Add GPS points and photos to a form and protect the privacy they put at risk":"Ajouter des points GPS et des photos à un formulaire et protéger la vie privée qu'ils mettent en jeu","Write constraints with clear messages, including a regex for phone numbers, and calculate fields":"Écrire des contraintes avec des messages clairs, dont une regex pour les numéros de téléphone, et des champs calculés","Export data in the right format with labels or XML values":"Exporter les données dans le bon format, avec les libellés ou les valeurs XML","The best time to catch an error is while the enumerator is still in front of the respondent. Constraints refuse impossible answers on the spot, calculations do the arithmetic for the enumerator, and GPS points and photos provide evidence that is hard to fake. This lesson also covers how to get the data out in a format your analysis software understands.":"Le meilleur moment pour détecter une erreur, c'est quand l'enquêteur est encore face au répondant. Les contraintes refusent sur-le-champ les réponses impossibles, les calculs font l'arithmétique à la place de l'enquêteur, et les points GPS et les photos apportent des preuves difficiles à falsifier. Cette leçon montre aussi comment sortir les données dans un format que comprend votre logiciel d'analyse.","Location and photos":"Localisation et photos","What it records":"Ce qu'il enregistre","Good practice":"Bonne pratique","Latitude, longitude, altitude and accuracy of one point":"Latitude, longitude, altitude et précision d'un point","Capture outdoors, wait until the accuracy is below about 10 metres, make it required when the location is essential":"Capturer à l'extérieur, attendre que la précision soit inférieure à environ 10 mètres, rendre la question obligatoire quand la localisation est indispensable","A photo from the camera":"Une photo prise avec l'appareil photo","Limit the photo size with max-pixels in the parameters column to save data and storage":"Limiter la taille des photos avec max-pixels dans la colonne parameters pour économiser les données et le stockage","GPS points and photos are personal data":"Les points GPS et les photos sont des données personnelles","A GPS point on a household or a face in a photo can identify a person as surely as a name. Collect them only when an indicator needs them, never photograph people without consent, avoid faces and documents, and remove or blur them before sharing any dataset.":"Un point GPS sur un ménage ou un visage sur une photo peut identifier une personne aussi sûrement qu'un nom. Ne les collectez que lorsqu'un indicateur en a besoin, ne photographiez jamais des personnes sans leur consentement, évitez les visages et les documents, et supprimez-les ou floutez-les avant de partager une base de données.","Constraints and messages":"Contraintes et messages","A constraint is a condition the answer must meet. In the formula, a dot stands for the current answer. When the condition is false, the phone refuses the answer and shows the text of the constraint_message column. Constraints are not checked on empty answers; use required for that.":"Une contrainte est une condition que la réponse doit respecter. Dans la formule, un point représente la réponse en cours. Lorsque la condition est fausse, le téléphone refuse la réponse et affiche le texte de la colonne constraint_message. Les contraintes ne sont pas vérifiées sur les réponses vides ; utilisez required pour cela.","Rule":"Règle","constraint_message":"constraint_message","Age of an adult respondent":"Âge d'un répondant adulte",". >= 18 and . <= 100":". >= 18 and . <= 100","Age must be between 18 and 100":"L'âge doit être compris entre 18 et 100","Children cannot outnumber the household":"Les enfants ne peuvent pas être plus nombreux que le ménage","Cannot be more than the household size":"Ne peut pas dépasser la taille du ménage","At most three answers ticked":"Trois réponses cochées au maximum","count-selected(.) <= 3":"count-selected(.) <= 3","Choose three answers at most":"Choisissez trois réponses au maximum","A 9-digit Cameroon mobile number":"Un numéro mobile camerounais à 9 chiffres","regex(., '^6[0-9]{8}$')":"regex(., '^6[0-9]{8}$')","9 digits starting with 6, no spaces":"9 chiffres commençant par 6, sans espaces","Regex for phone numbers":"Regex pour les numéros de téléphone","Cameroon mobile numbers have nine digits and start with 6. Store them in a text question, not an integer, so that the number is kept exactly as typed. The regex function then checks the pattern: the caret marks the start, 6 is the first digit, [0-9]{8} means eight more digits, and the dollar sign marks the end, so spaces, the +237 prefix or a missing digit are refused.":"Les numéros mobiles camerounais ont neuf chiffres et commencent par 6. Enregistrez-les dans une question text et non integer, afin que le numéro soit conservé exactement tel qu'il est saisi. La fonction regex vérifie ensuite le motif : l'accent circonflexe marque le début, 6 est le premier chiffre, [0-9]{8} signifie huit chiffres de plus, et le signe dollar marque la fin ; les espaces, le préfixe +237 ou un chiffre manquant sont donc refusés.","Calculate fields":"Les champs calculés","A calculate row computes a value from earlier answers and stores it in the dataset without showing it. Use it to derive a figure, for example adults = household size minus children, or to classify a measurement. Other rows can then refer to it like any question, in a relevant condition or a note.":"Une ligne calculate calcule une valeur à partir des réponses précédentes et l'enregistre dans la base de données sans l'afficher. Utilisez-la pour dériver un chiffre, par exemple adultes = taille du ménage moins les enfants, ou pour classer une mesure. D'autres lignes peuvent ensuite y faire référence comme à n'importe quelle question, dans une condition relevant ou une note.","Validate a registration form":"Valider un formulaire d'enregistrement","A fictional cash transfer project registers displaced households in the East region. Add constraints with messages: resp_age from 18 to 100, phone a 9-digit number starting with 6, and children no more than hh_size. Add a calculate row named adults equal to hh_size minus children, and make gps required.":"Un projet fictif de transferts monétaires enregistre des ménages déplacés dans la région de l'Est. Ajoutez des contraintes avec messages : resp_age de 18 à 100, phone un numéro à 9 chiffres commençant par 6, et children pas plus que hh_size. Ajoutez une ligne calculate nommée adults égale à hh_size moins children, et rendez gps obligatoire.","resp_age: . >= 18 and . <= 100. phone: regex(., '^6[0-9]{8}$'). children: . <= ${hh_size}. New row: type calculate, name adults, calculation ${hh_size} - ${children}. gps: required yes.":"resp_age : . >= 18 and . <= 100. phone : regex(., '^6[0-9]{8}$'). children : . <= ${hh_size}. Nouvelle ligne : type calculate, name adults, calculation ${hh_size} - ${children}. gps : required yes.","resp_age accepts 18 to 100 only":"resp_age n'accepte que 18 à 100","phone accepts 9 digits starting with 6":"phone accepte 9 chiffres commençant par 6","children cannot exceed hh_size":"children ne peut pas dépasser hh_size","adults is a calculate row: hh_size minus children":"adults est une ligne calculate : hh_size moins children","gps is required":"gps est obligatoire","Exporting your data":"Exporter vos données","Downloads":"Downloads","In a KoboToolbox project, choose the export type and format, then create and download the export.":"Dans un projet KoboToolbox, choisissez le type et le format d'export, puis créez et téléchargez l'export.","XLS":"XLS","Opening in Excel, especially with repeat groups":"Ouverture dans Excel, en particulier avec des groupes répétés","CSV":"CSV","Importing into Stata, R, Power BI or a database":"Import dans Stata, R, Power BI ou une base de données","SPSS Labels":"SPSS Labels","A syntax file that adds question and value labels to your data in SPSS":"Un fichier de syntaxe qui ajoute les libellés des questions et des valeurs à vos données dans SPSS","GPS coordinates (KML)":"Coordonnées GPS (KML)","Viewing locations in Google Earth or a GIS tool":"Visualiser les emplacements dans Google Earth ou un outil SIG","Media attachments (ZIP)":"Pièces jointes médias (ZIP)","Downloading all photos at once":"Télécharger toutes les photos en une fois","Labels or XML values?":"Libellés ou valeurs XML ?","An export with labels shows question texts as headers and choice labels as answers: easy to read, but long and language-dependent. An export with XML values uses the names, such as hh_size and borehole: short, stable and best for analysis software. Most MEAL officers analyse with XML values and use labels for sharing tables with colleagues.":"Un export avec libellés affiche les textes des questions en en-têtes et les libellés des choix comme réponses : facile à lire, mais long et dépendant de la langue. Un export avec valeurs XML utilise les noms, comme hh_size et borehole : courts, stables et mieux adaptés aux logiciels d'analyse. La plupart des chargés MEAL analysent avec les valeurs XML et utilisent les libellés pour partager des tableaux avec leurs collègues.","Why store a phone number in a text question with a regex constraint rather than in an integer question?":"Pourquoi enregistrer un numéro de téléphone dans une question text avec une contrainte regex plutôt que dans une question integer ?","Integer questions cannot be required":"Les questions integer ne peuvent pas être obligatoires","Text is kept exactly as typed and the regex controls the number of digits and the first digit":"Le texte est conservé exactement tel qu'il est saisi et la regex contrôle le nombre de chiffres et le premier chiffre","Regex only works on integer questions":"La regex ne fonctionne que sur les questions integer","Text questions are encrypted automatically":"Les questions text sont chiffrées automatiquement","A phone number is a code, not a quantity. As text it keeps its exact digits, and regex(., '^6[0-9]{8}$') enforces the Cameroon mobile format.":"Un numéro de téléphone est un code, pas une quantité. En texte, il garde ses chiffres exacts, et regex(., '^6[0-9]{8}$') impose le format mobile camerounais.","In a fictional cash transfer project in Bertoua, 14% of Mobile Money numbers in the first registration round were wrong, and payments bounced. After adding the regex constraint and a second question asking the enumerator to retype the number, errors fell to almost zero in the next round.":"Dans un projet fictif de transferts monétaires à Bertoua, 14 % des numéros Mobile Money de la première vague d'enregistrement étaient erronés, et des paiements ont été rejetés. Après l'ajout de la contrainte regex et d'une seconde question demandant à l'enquêteur de ressaisir le numéro, les erreurs sont tombées presque à zéro lors de la vague suivante.","Add a constraint and a clear constraint_message to every numeric question of one of your forms":"Ajoutez une contrainte et un constraint_message clair à chaque question numérique de l'un de vos formulaires","Add a phone question with the Cameroon regex and test it with five correct and wrong numbers":"Ajoutez une question de téléphone avec la regex camerounaise et testez-la avec cinq numéros corrects et erronés","Add one calculate field and display it in a note to check it":"Ajoutez un champ calculate et affichez-le dans une note pour le vérifier","Export the same data with labels and with XML values and compare the two files":"Exportez les mêmes données avec les libellés et avec les valeurs XML, et comparez les deux fichiers","Decide which GPS and photo fields must be removed before sharing the dataset":"Décidez quels champs GPS et photo doivent être retirés avant de partager la base de données","Form logic: constraints, relevance and calculations":"Logique des formulaires : contraintes, pertinence et calculs","Exporting and downloading your data":"Exporter et télécharger vos données","Practice lab: building digital forms":"Atelier pratique : créer des formulaires numériques","Build a short XLSForm with basic question types and a choice list":"Créer un court XLSForm avec des types de questions de base et une liste de choix","Write skip logic based on a select_multiple question":"Écrire des sauts basés sur une question select_multiple","Write constraints, a phone regex and calculations":"Écrire des contraintes, une regex de téléphone et des calculs","Build a complete screening module with groups, relevant rules, constraints and a calculation":"Créer un module de dépistage complet avec des groupes, des conditions relevant, des contraintes et un calcul","Exercise 1: Weekly market price monitoring":"Exercice 1 : Suivi hebdomadaire des prix sur les marchés","Four basic questions and a choice list":"Quatre questions de base et une liste de choix","A fictional food security project monitors prices in markets of the North region. Below the note, add four questions: a required text question named market, a date question named visit_date, a select_one question named commodity using a new list commodity with the choices maize, sorghum and rice, and a required integer question named price for the price of one kilogram in FCFA.":"Un projet fictif de sécurité alimentaire suit les prix sur des marchés de la région du Nord. Sous la note, ajoutez quatre questions : une question text obligatoire nommée market, une question date nommée visit_date, une question select_one nommée commodity utilisant une nouvelle liste commodity avec les choix maize, sorghum et rice, et une question integer obligatoire nommée price pour le prix d'un kilogramme en FCFA.","Types: text, date, select_one commodity, integer. Set required to yes for market and price. In the choices sheet, add three rows with list_name commodity and the names maize, sorghum, rice.":"Types : text, date, select_one commodity, integer. Mettez required à yes pour market et price. Dans la feuille choices, ajoutez trois lignes avec le list_name commodity et les names maize, sorghum, rice.","market is a required text question":"market est une question text obligatoire","commodity is a select_one commodity question":"commodity est une question select_one commodity","the commodity list has maize, sorghum and rice":"la liste commodity contient maize, sorghum et rice","price is a required integer question":"price est une question integer obligatoire","Exercise 2: Post-distribution monitoring of livelihood support":"Exercice 2 : Suivi post-distribution d'un appui aux moyens d'existence","Skip logic with select_multiple":"Sauts avec select_multiple","A fictional livelihoods project supports refugee and host households near Garoua-Boulaï. Make support required and add the choice other to its list. Show cash_amount only when cash was received, tools_used only when tools were received and other_support only when other was ticked. Finally add a calculate row named n_support that counts the types of support ticked.":"Un projet fictif de moyens d'existence appuie des ménages réfugiés et hôtes près de Garoua-Boulaï. Rendez support obligatoire et ajoutez le choix other à sa liste. Affichez cash_amount seulement si de l'argent a été reçu, tools_used seulement si des outils ont été reçus et other_support seulement si other a été coché. Enfin, ajoutez une ligne calculate nommée n_support qui compte les types d'appui cochés.","Use selected(): cash_amount relevant selected(${support}, 'cash'); tools_used relevant selected(${support}, 'tools'); other_support relevant selected(${support}, 'other'). The count is count-selected(${support}).":"Utilisez selected() : cash_amount relevant selected(${support}, 'cash') ; tools_used relevant selected(${support}, 'tools') ; other_support relevant selected(${support}, 'other'). Le décompte est count-selected(${support}).","support is required":"support est obligatoire","the support list includes other":"la liste support contient other","cash_amount appears only when cash is ticked":"cash_amount n'apparaît que si cash est coché","tools_used appears only when tools is ticked":"tools_used n'apparaît que si tools est coché","other_support appears only when other is ticked":"other_support n'apparaît que si other est coché","n_support counts the ticked answers":"n_support compte les réponses cochées","Exercise 3: Validation rules for a school census":"Exercice 3 : Règles de validation pour un recensement scolaire","Write the constraints and calculations":"Écrire les contraintes et les calculs","A fictional education project runs a school census in the South region. The form has the integer questions boys, girls and total_pupils, a text question head_phone and an integer question teacher_age. Type each formula exactly as you would write it in the XLSForm.":"Un projet d'éducation fictif réalise un recensement scolaire dans la région du Sud. Le formulaire comprend les questions integer boys, girls et total_pupils, une question text head_phone et une question integer teacher_age. Saisissez chaque formule exactement comme vous l'écririez dans le XLSForm.","In a constraint, the dot is the current answer. Other questions are written ${name}. Division in XLSForm is div, not a slash. The phone regex is regex(., '^6[0-9]{8}$').":"Dans une contrainte, le point est la réponse en cours. Les autres questions s'écrivent ${name}. Dans XLSForm, la division s'écrit div, pas avec une barre oblique. La regex du téléphone est regex(., '^6[0-9]{8}$').","constraint on girls: cannot be more than total_pupils":"constraint sur girls : ne peut pas dépasser total_pupils","The dot is the number of girls being typed; it must not exceed the total already entered.":"Le point est le nombre de filles en cours de saisie ; il ne doit pas dépasser le total déjà saisi.","constraint on teacher_age: from 18 to 65":"constraint sur teacher_age : de 18 à 65","Both limits are joined with and; the phone refuses 17 or 70.":"Les deux limites sont reliées par and ; le téléphone refuse 17 ou 70.","constraint on head_phone: 9 digits starting with 6":"constraint sur head_phone : 9 chiffres commençant par 6","The caret and the dollar sign force the whole answer to match, so 237677123456 or 67712345 are refused.":"L'accent circonflexe et le signe dollar obligent toute la réponse à correspondre ; 237677123456 ou 67712345 sont donc refusés.","calculation of a field pupils_check: boys plus girls":"calculation d'un champ pupils_check : garçons plus filles","calculation of girls_share: girls divided by total_pupils":"calculation de girls_share : filles divisées par total_pupils","XLSForm divides with div. You can wrap it in round(..., 2) to keep two decimals.":"XLSForm divise avec div. Vous pouvez l'entourer de round(..., 2) pour garder deux décimales.","Where should the rule that boys plus girls equals total_pupils be written?":"Où écrire la règle selon laquelle garçons plus filles égale total_pupils ?","Placing it on the last of the three questions lets the enumerator correct the figures while still at the school.":"La placer sur la dernière des trois questions permet à l'enquêteur de corriger les chiffres tant qu'il est encore à l'école.","As a constraint on total_pupils: . = ${boys} + ${girls}":"Comme contrainte sur total_pupils : . = ${boys} + ${girls}","In the label of total_pupils":"Dans le libellé de total_pupils","As a relevant condition on boys":"Comme condition relevant sur boys","It cannot be checked in the form":"Cela ne peut pas être vérifié dans le formulaire","The head teacher has no phone and the question is left empty. What does the regex constraint do?":"Le directeur d'école n'a pas de téléphone et la question reste vide. Que fait la contrainte regex ?","Constraints apply only to answers that exist. If the number is compulsory, also set required to yes.":"Les contraintes ne s'appliquent qu'aux réponses existantes. Si le numéro est indispensable, mettez aussi required à yes.","It refuses the empty answer":"Elle refuse la réponse vide","It replaces it with 0":"Elle la remplace par 0","Nothing: constraints are not checked on empty answers":"Rien : les contraintes ne sont pas vérifiées sur les réponses vides","It deletes the question":"Elle supprime la question","Exercise 4: Nutrition screening of children under five":"Exercice 4 : Dépistage nutritionnel des enfants de moins de cinq ans","A complete screening module":"Un module de dépistage complet","A fictional nutrition project screens children aged 6 to 59 months in the Far North with a MUAC tape (in mm). Make consent required. Wrap the child questions (from age_months to referred) in a group named child shown only when consent is yes. Add constraints with messages: age_months from 6 to 59 and muac from 80 to 230. Add a calculate row muac_class giving 'sam' when there is oedema or MUAC is below 115, 'mam' when MUAC is below 125, otherwise 'normal'. Show refer_note and referred only when there is oedema or MUAC is below 125, and end_note only when consent is no.":"Un projet de nutrition fictif dépiste les enfants de 6 à 59 mois dans l'Extrême-Nord avec un bracelet MUAC (en mm). Rendez consent obligatoire. Placez les questions sur l'enfant (de age_months à referred) dans un groupe nommé child affiché seulement si consent est yes. Ajoutez des contraintes avec messages : age_months de 6 à 59 et muac de 80 à 230. Ajoutez une ligne calculate muac_class donnant 'sam' en cas d'œdèmes ou si le MUAC est inférieur à 115, 'mam' si le MUAC est inférieur à 125, sinon 'normal'. Affichez refer_note et referred seulement en cas d'œdèmes ou si le MUAC est inférieur à 125, et end_note seulement si consent est no.","Group relevant: ${consent} = 'yes'. Constraints: . >= 6 and . <= 59; . >= 80 and . <= 230. Calculation: if(${oedema} = 'yes' or ${muac} < 115, 'sam', if(${muac} < 125, 'mam', 'normal')). Referral relevant: ${oedema} = 'yes' or ${muac} < 125. End note relevant: ${consent} = 'no'.":"Relevant du groupe : ${consent} = 'yes'. Contraintes : . >= 6 and . <= 59 ; . >= 80 and . <= 230. Calcul : if(${oedema} = 'yes' or ${muac} < 115, 'sam', if(${muac} < 125, 'mam', 'normal')). Relevant de la référence : ${oedema} = 'yes' or ${muac} < 125. Relevant de la note de fin : ${consent} = 'no'.","age_months accepts 6 to 59 only":"age_months n'accepte que 6 à 59","muac accepts 80 to 230 only":"muac n'accepte que 80 à 230","muac_class gives sam, mam or normal":"muac_class donne sam, mam ou normal","refer_note appears when oedema = yes or MUAC < 125":"refer_note apparaît si oedema = yes ou MUAC < 125","referred appears when oedema = yes or MUAC < 125":"referred apparaît si oedema = yes ou MUAC < 125","end_note appears only when consent = no":"end_note n'apparaît que si consent = no","In an XLSForm, where do you write the answer options of a select_one question?":"Dans un XLSForm, où écrit-on les options de réponse d'une question select_one ?","In the label column of the survey sheet":"Dans la colonne label de la feuille survey","In the choices sheet, under the list_name used in the question type":"Dans la feuille choices, sous le list_name utilisé dans le type de la question","In the settings sheet":"Dans la feuille settings","In the hint column":"Dans la colonne hint","The type select_one water points to all rows of the choices sheet with list_name water.":"Le type select_one water renvoie à toutes les lignes de la feuille choices dont le list_name est water.","Which of these is a valid XLSForm name?":"Lequel de ces noms XLSForm est valide ?","hh size":"hh size","2nd_visit":"2nd_visit","water-source?":"water-source?","water_source":"water_source","Names start with a letter or an underscore and use only letters, digits and underscores, without spaces.":"Les noms commencent par une lettre ou un tiret bas et n'utilisent que des lettres, des chiffres et des tirets bas, sans espaces.","An enumerator collects offline for a week. What must happen for the data to reach the server?":"Un enquêteur collecte hors ligne pendant une semaine. Que faut-il pour que les données atteignent le serveur ?","The forms must be finalized and then sent when a connection is available":"Les formulaires doivent être finalisés puis envoyés lorsqu'une connexion est disponible","Nothing, the data is sent by SMS":"Rien, les données sont envoyées par SMS","The enumerator must retype the data on a computer":"L'enquêteur doit ressaisir les données sur un ordinateur","The form must be redeployed":"Le formulaire doit être redéployé","Collect apps keep finalized forms on the phone until they are sent over a connection.":"Les applications de collecte gardent les formulaires finalisés sur le téléphone jusqu'à leur envoi via une connexion.","Your KoboToolbox account is on the EU server. Which collection URL goes in KoboCollect?":"Votre compte KoboToolbox est sur le serveur UE. Quelle URL de collecte faut-il saisir dans KoboCollect ?","kc.kobotoolbox.org":"kc.kobotoolbox.org","The ODK Central URL":"L'URL d'ODK Central","kc-eu.kobotoolbox.org":"kc-eu.kobotoolbox.org","Any URL, the app finds the server itself":"N'importe quelle URL, l'application trouve le serveur toute seule","The app must point to the collection URL of the server where the account and the project are.":"L'application doit pointer vers l'URL de collecte du serveur où se trouvent le compte et le projet.","Which tool is designed for case management, such as following pregnant women over several home visits?":"Quel outil est conçu pour la gestion de cas, par exemple le suivi de femmes enceintes lors de plusieurs visites à domicile ?","Excel":"Excel","KoboToolbox's form builder":"L'éditeur de formulaires de KoboToolbox","CommCare registers cases and updates them at each visit, and shows health workers who is due for follow-up.":"CommCare enregistre des cas, les met à jour à chaque visite et indique aux agents de santé qui doit être revu.","Which constraint accepts only Cameroon mobile numbers of 9 digits starting with 6?":"Quelle contrainte n'accepte que les numéros mobiles camerounais de 9 chiffres commençant par 6 ?","string-length(.) = 9":"string-length(.) = 9","regex(., '6[0-9]')":"regex(., '6[0-9]')","The caret and the dollar sign anchor the pattern, 6 is the first digit and [0-9]{8} requires exactly eight more digits.":"L'accent circonflexe et le signe dollar ancrent le motif, 6 est le premier chiffre et [0-9]{8} exige exactement huit chiffres de plus.","What does a calculate row do?":"Que fait une ligne calculate ?","It asks the respondent to do a calculation":"Elle demande au répondant de faire un calcul","It computes a value from other answers and stores it without showing it":"Elle calcule une valeur à partir d'autres réponses et l'enregistre sans l'afficher","It checks that an answer is within a range":"Elle vérifie qu'une réponse se situe dans une plage","It exports the data to Excel":"Elle exporte les données vers Excel","A calculate row derives a value, for example adults = ${hh_size} - ${children}, that other rows and the dataset can use.":"Une ligne calculate dérive une valeur, par exemple adults = ${hh_size} - ${children}, que les autres lignes et la base de données peuvent utiliser.","You will analyse the data in Stata. Which export is most suitable?":"Vous analyserez les données dans Stata. Quel export convient le mieux ?","XLS with labels, because it is easier to read":"XLS avec libellés, parce qu'il est plus facile à lire","A KML file":"Un fichier KML","CSV with XML values, because names and codes are short and stable":"CSV avec valeurs XML, parce que les noms et les codes sont courts et stables","Media attachments":"Pièces jointes médias","XML values give short variable names and choice codes that analysis software handles well; labels are better for sharing readable tables.":"Les valeurs XML donnent des noms de variables et des codes de choix courts que les logiciels d'analyse gèrent bien ; les libellés conviennent mieux pour partager des tableaux lisibles.","Data Analysis with Excel, SPSS and Stata":"Analyse des données avec Excel, SPSS et Stata","Clean data, calculate and disaggregate indicators, and run descriptive statistics and cross-tabulations in Excel, SPSS and Stata.":"Nettoyer les données, calculer et désagréger les indicateurs, et produire des statistiques descriptives et des tableaux croisés dans Excel, SPSS et Stata.","Cleaning data: missing values, duplicates and outliers":"Nettoyer les données : valeurs manquantes, doublons et valeurs aberrantes","Detect missing values, duplicate IDs, out-of-range values and special codes in a survey dataset":"Détecter les valeurs manquantes, les identifiants en double, les valeurs hors plage et les codes spéciaux dans une base d'enquête","Apply cleaning checks in Excel, SPSS and Stata without touching the raw data":"Appliquer des contrôles de nettoyage dans Excel, SPSS et Stata sans toucher aux données brutes","Record every correction in a cleaning log that another person can follow":"Consigner chaque correction dans un journal de nettoyage qu'une autre personne peut suivre","A dataset straight from the server is never ready for analysis. Some households were submitted twice, some ages were typed with an extra digit, and some answers are codes such as 99 that mean \"don't know\". If you calculate indicators before cleaning, one error can move a percentage by several points. Cleaning is not about making the data look nice; it is about making every figure you report defensible.":"Une base de données qui sort tout juste du serveur n'est jamais prête pour l'analyse. Certains ménages ont été envoyés deux fois, certains âges ont été saisis avec un chiffre de trop, et certaines réponses sont des codes comme 99 qui signifient « ne sait pas ». Si vous calculez les indicateurs avant de nettoyer, une seule erreur peut déplacer un pourcentage de plusieurs points. Nettoyer ne sert pas à rendre les données jolies ; cela sert à rendre chaque chiffre que vous publiez défendable.","Golden rules before you start":"Règles d'or avant de commencer","Never overwrite the raw data: keep the exported file untouched and work on a copy.":"N'écrasez jamais les données brutes : gardez le fichier exporté intact et travaillez sur une copie.","Write every change in a cleaning log: ID, variable, old value, new value, reason, who and when.":"Notez chaque modification dans un journal de nettoyage : identifiant, variable, ancienne valeur, nouvelle valeur, motif, qui et quand.","Prefer rules over case-by-case decisions: the same problem is always treated the same way.":"Préférez des règles aux décisions au cas par cas : un même problème est toujours traité de la même façon.","Correct from a source (paper form, call-back, supervisor) when you can; otherwise set the value to missing rather than guess.":"Corrigez à partir d'une source (fiche papier, rappel téléphonique, superviseur) quand c'est possible ; sinon, mettez la valeur en manquante plutôt que de deviner.","Keep the cleaning steps in a script or a documented sheet so that you can run them again when new data arrives.":"Conservez les étapes de nettoyage dans un script ou une feuille documentée, afin de pouvoir les relancer à l'arrivée de nouvelles données.","The five common problems":"Les cinq problèmes courants","Problem":"Problème","Usual treatment":"Traitement habituel","Duplicate records":"Enregistrements en double","The same household ID submitted twice after a sync failure":"Le même identifiant de ménage envoyé deux fois après un échec de synchronisation","Check that the rows are really identical, keep one, log the other":"Vérifier que les lignes sont vraiment identiques, en garder une, consigner l'autre","Missing values":"Valeurs manquantes","Household size left empty":"Taille du ménage laissée vide","Leave it missing and exclude it from that indicator's denominator":"La laisser manquante et l'exclure du dénominateur de l'indicateur concerné","Special codes":"Codes spéciaux","98 = don't know, 99 = refused, entered in the age field":"98 = ne sait pas, 99 = refus, saisis dans le champ de l'âge","Declare them as missing before any mean or median":"Les déclarer comme manquants avant tout calcul de moyenne ou de médiane","Out-of-range values":"Valeurs hors plage","Age of household head = 132":"Âge du chef de ménage = 132","Check the paper form or call back; if impossible, set to missing":"Vérifier la fiche papier ou rappeler ; si c'est impossible, mettre en manquant","Inconsistent codes":"Codes incohérents","\"F\", \"f\", \"Female\" and \"Femme\" in the same column":"« F », « f », « Female » et « Femme » dans la même colonne","Recode to one agreed value, ideally a numeric code with a label":"Recoder vers une seule valeur convenue, idéalement un code numérique avec une étiquette","Missing is not the same as \"don't know\"":"Manquant n'est pas la même chose que « ne sait pas »","A blank means the question was not asked or not answered. A 98 means the person was asked and did not know. Both are excluded from a mean, but you may want to report the share of \"don't know\" answers, because it tells you something about the question or the respondents.":"Une case vide signifie que la question n'a pas été posée ou n'a pas reçu de réponse. Un 98 signifie que la personne a été interrogée et ne savait pas. Les deux sont exclus d'une moyenne, mais vous pouvez vouloir publier la part de réponses « ne sait pas », car elle vous apprend quelque chose sur la question ou sur les répondants.","Cleaning checks in Excel":"Contrôles de nettoyage dans Excel","Five quick checks on a copy of the data":"Cinq contrôles rapides sur une copie des données","Turn on filters (Data › Filter) and open each column's filter list to spot odd values and blanks.":"Activez les filtres (Données › Filtrer) et ouvrez la liste de filtre de chaque colonne pour repérer les valeurs étranges et les cases vides.","Count blanks per column with COUNTBLANK, for example =COUNTBLANK(D2:D501).":"Comptez les cases vides par colonne avec COUNTBLANK (NB.VIDE), par exemple =COUNTBLANK(D2:D501).","Flag duplicate IDs in a helper column: =COUNTIF($A$2:$A$501,A2)>1 returns TRUE for every repeated ID.":"Signalez les identifiants en double dans une colonne d'aide : =COUNTIF($A$2:$A$501,A2)>1 renvoie TRUE (VRAI) pour chaque identifiant répété.","Count special codes and impossible values: =COUNTIF(C2:C501,99) and =COUNTIF(C2:C501,\">110\").":"Comptez les codes spéciaux et les valeurs impossibles : =COUNTIF(C2:C501,99) et =COUNTIF(C2:C501,\">110\").","Record what you found and what you decided in the cleaning log sheet.":"Notez ce que vous avez trouvé et ce que vous avez décidé dans la feuille du journal de nettoyage.","Duplicate Values":"Valeurs en double","Colours repeated IDs in Excel so you can see them at a glance.":"Colore les identifiants répétés dans Excel pour les voir d'un coup d'œil.","Run the cleaning checks":"Lancer les contrôles de nettoyage","An extract of a fictional food security survey in the Adamawa region. In":"Extrait d'une enquête fictive sur la sécurité alimentaire dans la région de l'Adamaoua. Dans",", write":", écrivez","when the household ID appears more than once, otherwise":"lorsque l'identifiant du ménage apparaît plus d'une fois, sinon",". In this survey, 99 means \"don't know\" and any age above 110 is impossible.":". Dans cette enquête, 99 signifie « ne sait pas » et tout âge supérieur à 110 est impossible.","In F2: =IF(COUNTIF($A$2:$A$10,A2)>1,\"Duplicate\",\"OK\") and copy down. H2: =COUNTBLANK(C2:E10). H3: =COUNTIF(F2:F10,\"Duplicate\"). H4: =COUNTIF(C2:C10,99). H5: =COUNTIF(C2:C10,\">110\").":"En F2 : =IF(COUNTIF($A$2:$A$10,A2)>1,\"Duplicate\",\"OK\") puis recopiez vers le bas. H2 : =COUNTBLANK(C2:E10). H3 : =COUNTIF(F2:F10,\"Duplicate\"). H4 : =COUNTIF(C2:C10,99). H5 : =COUNTIF(C2:C10,\">110\").","The same checks in SPSS and Stata":"Les mêmes contrôles dans SPSS et Stata","Analyze":"Analyse","Descriptive Statistics":"Statistiques descriptives","Frequencies":"Effectifs","In SPSS, a frequency table of each variable shows codes such as 98 and 99 and impossible values at the ends of the list.":"Dans SPSS, le tableau des effectifs de chaque variable fait apparaître les codes comme 98 et 99 et les valeurs impossibles aux extrémités de la liste.","A Stata trap: missing is bigger than every number":"Un piège de Stata : le manquant est plus grand que tous les nombres","In Stata, a missing numeric value (shown as a dot) is treated as larger than any number. The command count if age > 120 therefore also counts every missing age. Add & !missing(age) to count only the real values above 120.":"Dans Stata, une valeur numérique manquante (affichée par un point) est traitée comme plus grande que n'importe quel nombre. La commande count if age > 120 compte donc aussi tous les âges manquants. Ajoutez & !missing(age) pour ne compter que les vraies valeurs supérieures à 120.","Type the Stata cleaning commands":"Saisir les commandes de nettoyage Stata","You are cleaning a fictional nutrition survey file with 418 rows. Type the commands, then read the output above and answer.":"Vous nettoyez le fichier fictif d'une enquête nutritionnelle de 418 lignes. Saisissez les commandes, puis lisez les résultats ci-dessus et répondez.","The commands are duplicates report, misstable summarize and count if. Surplus observations are the extra copies beyond the first one.":"Les commandes sont duplicates report, misstable summarize et count if. Les observations en surplus sont les copies supplémentaires au-delà de la première.","Command to report duplicates of the ID variable hhid":"Commande pour signaler les doublons de la variable d'identifiant hhid","duplicates report shows how many observations appear once, twice and so on, and how many are surplus copies.":"duplicates report indique combien d'observations apparaissent une fois, deux fois, etc., et combien sont des copies en surplus.","Command to count the missing values of every variable":"Commande pour compter les valeurs manquantes de chaque variable","misstable summarize lists each variable that has missing values, with the number missing and the range of the others.":"misstable summarize liste chaque variable qui a des valeurs manquantes, avec le nombre de manquants et l'étendue des autres valeurs.","Command to count ages above 120, ignoring missing ages":"Commande pour compter les âges supérieurs à 120, en ignorant les âges manquants","Without the second condition, Stata would also count the missing ages, because missing is larger than any number.":"Sans la seconde condition, Stata compterait aussi les âges manquants, car le manquant est plus grand que n'importe quel nombre.","In the duplicates output above, how many surplus rows must be investigated and possibly dropped?":"Dans le résultat de duplicates ci-dessus, combien de lignes en surplus faut-il examiner et éventuellement supprimer ?","Six observations share an ID in pairs: three IDs appear twice, so there are three surplus copies.":"Six observations partagent un identifiant par paires : trois identifiants apparaissent deux fois, il y a donc trois copies en surplus.","According to misstable, how many households have no income value?":"D'après misstable, combien de ménages n'ont aucune valeur de revenu ?","Obs=. is the count of system missing values: 27 households have no income recorded.":"Obs=. est le nombre de valeurs manquantes système : 27 ménages n'ont pas de revenu enregistré.","An age of 132 appears for one household head and the paper form is not available. What is the best action?":"Un âge de 132 ans apparaît pour un chef de ménage et la fiche papier n'est pas disponible. Quelle est la meilleure action ?","Replace it with 32, which is probably what was meant":"Le remplacer par 32, qui est probablement ce qui était voulu","Replace it with the average age of the sample":"Le remplacer par l'âge moyen de l'échantillon","Set it to missing and record the change in the cleaning log":"Le mettre en manquant et consigner la modification dans le journal de nettoyage","Delete the whole household from the dataset":"Supprimer tout le ménage de la base","Without a source you cannot know the true value. Setting it to missing keeps the household's other answers, and the log makes the decision transparent.":"Sans source, vous ne pouvez pas connaître la vraie valeur. Le mettre en manquant conserve les autres réponses du ménage, et le journal rend la décision transparente.","In a fictional cash transfer project in the East region, two enumerators synced the same tablet twice after a network cut in Batouri, creating 38 duplicate households. The MEAL officer found them with a duplicate report on the household ID, compared the rows, kept the first submission of each, and listed the 38 IDs in the cleaning log. The donor's data quality check later found the log and accepted the figures without questions.":"Dans un projet fictif de transferts monétaires dans la région de l'Est, deux enquêteurs ont synchronisé deux fois la même tablette après une coupure de réseau à Batouri, créant 38 ménages en double. Le chargé MEAL les a trouvés avec un rapport de doublons sur l'identifiant du ménage, a comparé les lignes, a gardé le premier envoi de chacun et a listé les 38 identifiants dans le journal de nettoyage. Le contrôle de qualité des données du bailleur a ensuite trouvé le journal et accepté les chiffres sans poser de questions.","Save the raw export of one of your datasets in a read-only folder and create a working copy":"Enregistrez l'export brut de l'une de vos bases dans un dossier en lecture seule et créez une copie de travail","Create a cleaning log sheet with the columns ID, variable, old value, new value, reason, by and date":"Créez une feuille de journal de nettoyage avec les colonnes identifiant, variable, ancienne valeur, nouvelle valeur, motif, auteur et date","Run the duplicate ID, blank count and range checks on the working copy":"Lancez les contrôles d'identifiants en double, de cases vides et de plages sur la copie de travail","List every special code used in your questionnaire (98, 99, 999…) and how you will treat each":"Listez chaque code spécial utilisé dans votre questionnaire (98, 99, 999…) et la façon dont vous traiterez chacun","Write the cleaning steps as a short Stata or SPSS script, or as numbered steps in Excel":"Écrivez les étapes de nettoyage sous forme d'un court script Stata ou SPSS, ou d'étapes numérotées dans Excel","duplicates: report, tag or drop duplicate observations":"duplicates : signaler, marquer ou supprimer les observations en double","misstable: tabulate missing values":"misstable : tabuler les valeurs manquantes","Calculating and disaggregating indicators":"Calculer et désagréger les indicateurs","Build an indicator from a clearly defined numerator and denominator":"Construire un indicateur à partir d'un numérateur et d'un dénominateur clairement définis","Disaggregate an indicator by sex, age group, location and disability with COUNTIFS and AVERAGEIFS":"Désagréger un indicateur par sexe, tranche d'âge, localité et handicap avec COUNTIFS (NB.SI.ENS) et AVERAGEIFS (MOYENNE.SI.ENS)","Produce the same disaggregation in Stata and SPSS with tab, mean and Crosstabs":"Produire la même désagrégation dans Stata et SPSS avec tab, mean et Crosstabs","Most MEAL indicators are a percentage, a count or an average. The calculation is simple; the mistakes come from the definition. Who is counted on top of the fraction, who is counted below it, and who is left out? Once the indicator is right for the whole sample, disaggregation shows who benefits and who is being left behind.":"La plupart des indicateurs MEAL sont un pourcentage, un nombre ou une moyenne. Le calcul est simple ; les erreurs viennent de la définition. Qui est compté au-dessus de la fraction, qui est compté en dessous, et qui est laissé de côté ? Une fois l'indicateur juste pour l'ensemble de l'échantillon, la désagrégation montre qui en bénéficie et qui est laissé pour compte.","Numerator and denominator":"Numérateur et dénominateur","% of households using a mosquito net":"% de ménages utilisant une moustiquaire","Respondents who slept under a net last night":"Répondants ayant dormi sous une moustiquaire la nuit dernière","All respondents with a valid answer to that question":"Tous les répondants ayant une réponse valide à cette question","% of trained teachers who pass the post-test":"% d'enseignants formés qui réussissent le post-test","Trained teachers with a score of 70 or more":"Enseignants formés ayant une note de 70 ou plus","Trained teachers who sat the post-test":"Enseignants formés ayant passé le post-test","Average number of meals per day":"Nombre moyen de repas par jour","Sum of meals reported":"Somme des repas déclarés","Households with a valid answer":"Ménages ayant une réponse valide","% of complaints closed within 30 days":"% de plaintes clôturées en 30 jours","Complaints closed within 30 days":"Plaintes clôturées en 30 jours","Complaints received in the period":"Plaintes reçues au cours de la période","Take the denominator from the indicator reference sheet":"Prenez le dénominateur dans la fiche de référence de l'indicateur","The indicator reference sheet says who belongs in the denominator. Missing answers and \"don't know\" codes are normally excluded from it. Write the denominator next to every percentage you report, for example 60% (n = 240), so the reader knows what it is based on.":"La fiche de référence de l'indicateur précise qui appartient au dénominateur. Les réponses manquantes et les codes « ne sait pas » en sont normalement exclus. Écrivez le dénominateur à côté de chaque pourcentage publié, par exemple 60 % (n = 240), pour que le lecteur sache sur quoi il repose.","Sex: women and men, girls and boys, reported separately.":"Sexe : femmes et hommes, filles et garçons, présentés séparément.","Age group: use the groups in the reference sheet, for example 0–5, 6–17, 18–59 and 60+.":"Tranche d'âge : utilisez les tranches de la fiche de référence, par exemple 0–5, 6–17, 18–59 et 60+.","Location: region, department, health district, camp or host community.":"Localité : région, département, district de santé, camp ou communauté hôte.","Disability: usually measured with the Washington Group short set of questions.":"Handicap : généralement mesuré avec la série courte de questions du Groupe de Washington.","Check the numbers in each group: a percentage based on 8 people is fragile and should be reported with care.":"Vérifiez les effectifs de chaque groupe : un pourcentage fondé sur 8 personnes est fragile et doit être présenté avec prudence.","In Excel: COUNTIFS and AVERAGEIFS":"Dans Excel : COUNTIFS et AVERAGEIFS","COUNTIFS counts rows that meet several conditions at once, so it builds both the numerator and the denominator of a disaggregated percentage. AVERAGEIFS gives the mean of a column for rows that meet the conditions, and it ignores empty cells.":"COUNTIFS (NB.SI.ENS) compte les lignes qui remplissent plusieurs conditions à la fois ; il construit donc à la fois le numérateur et le dénominateur d'un pourcentage désagrégé. AVERAGEIFS (MOYENNE.SI.ENS) donne la moyenne d'une colonne pour les lignes qui remplissent les conditions, et ignore les cellules vides.","Disaggregate a malaria indicator":"Désagréger un indicateur paludisme","Post-distribution survey of a fictional malaria prevention project in the Far North. Fill":"Enquête post-distribution d'un projet fictif de prévention du paludisme dans l'Extrême-Nord. Remplissez",". Percentages are shares (0.6 = 60%).":". Les pourcentages sont des proportions (0,6 = 60 %).","H2: =COUNTA(A2:A11). Each disaggregated percentage is a COUNTIFS for the group with Yes, divided by a COUNTIF of the whole group, e.g. =COUNTIFS(B2:B11,\"F\",E2:E11,\"Yes\")/COUNTIF(B2:B11,\"F\"). The averages use AVERAGEIFS(F2:F11, …).":"H2 : =COUNTA(A2:A11). Chaque pourcentage désagrégé est un COUNTIFS pour le groupe avec Yes, divisé par un COUNTIF de tout le groupe, par ex. =COUNTIFS(B2:B11,\"F\",E2:E11,\"Yes\")/COUNTIF(B2:B11,\"F\"). Les moyennes utilisent AVERAGEIFS(F2:F11, …).","In Stata and SPSS":"Dans Stata et SPSS","What you need":"Ce dont vous avez besoin","Stata":"Stata","SPSS syntax":"Syntaxe SPSS","% of each sex who slept under a net":"% de chaque sexe ayant dormi sous une moustiquaire","tab sex netuse, row":"tab sex netuse, row","CROSSTABS /TABLES=sex BY netuse /CELLS=COUNT ROW.":"CROSSTABS /TABLES=sex BY netuse /CELLS=COUNT ROW.","Mean nets per household by town":"Nombre moyen de moustiquaires par ménage, par ville","mean nets, over(town)":"mean nets, over(town)","MEANS TABLES=nets BY town.":"MEANS TABLES=nets BY town.","Same table for each town separately":"Même tableau pour chaque ville séparément","bysort town: tab sex netuse, row":"bysort town: tab sex netuse, row","SPLIT FILE BY town, then CROSSTABS":"SPLIT FILE BY town, puis CROSSTABS","Crosstabs":"Tableaux croisés","Put the group (sex) in Rows and the outcome in Columns, then choose Row percentages under Cells.":"Placez le groupe (sexe) en Lignes et le résultat en Colonnes, puis choisissez les pourcentages en Ligne sous Cellules.","Type the disaggregation commands":"Saisir les commandes de désagrégation","The fictional malaria survey now has 1 240 respondents in Stata and SPSS. Variables: sex, town, netuse (0 = No, 1 = Yes) and nets. Type each command.":"L'enquête fictive sur le paludisme compte maintenant 1 240 répondants dans Stata et SPSS. Variables : sex, town, netuse (0 = Non, 1 = Oui) et nets. Saisissez chaque commande.","In Stata, the group goes first in tab and the row option gives percentages within each group; over() goes after a comma in mean. In SPSS, CROSSTABS uses /TABLES = rows BY columns and /CELLS for percentages.":"Dans Stata, le groupe vient en premier dans tab et l'option row donne les pourcentages à l'intérieur de chaque groupe ; over() se place après une virgule dans mean. Dans SPSS, CROSSTABS utilise /TABLES = lignes BY colonnes et /CELLS pour les pourcentages.","Stata: share of each sex who slept under a net (row percentages)":"Stata : part de chaque sexe ayant dormi sous une moustiquaire (pourcentages en ligne)","Each row adds up to 100%: the Yes column gives the indicator for women and for men.":"Chaque ligne totalise 100 % : la colonne Yes donne l'indicateur pour les femmes et pour les hommes.","Stata: mean number of nets per household, by town":"Stata : nombre moyen de moustiquaires par ménage, par ville","mean with over() estimates the mean for each town, with a standard error and a 95% confidence interval.":"mean avec over() estime la moyenne pour chaque ville, avec une erreur type et un intervalle de confiance à 95 %.","SPSS syntax: cross-tab of sex by netuse with counts and row percentages":"Syntaxe SPSS : tableau croisé de sex par netuse avec effectifs et pourcentages en ligne","The first variable after TABLES= forms the rows, the variable after BY forms the columns.":"La première variable après TABLES= forme les lignes, la variable après BY forme les colonnes.","SPSS syntax: mean number of nets by town":"Syntaxe SPSS : nombre moyen de moustiquaires par ville","MEANS gives the mean, the number of cases and the standard deviation for each town.":"MEANS donne la moyenne, le nombre d'observations et l'écart type pour chaque ville.","Your indicator must be reported for women with a disability in Kousseri, but only 9 respondents fit that group. What do you do?":"Votre indicateur doit être présenté pour les femmes en situation de handicap à Kousseri, mais seuls 9 répondants entrent dans ce groupe. Que faites-vous ?","Keep the disaggregation, but show n = 9 and warn the reader. Small groups give unstable percentages.":"Gardez la désagrégation, mais indiquez n = 9 et prévenez le lecteur. Les petits groupes donnent des pourcentages instables.","Drop the disaggregation":"Supprimer la désagrégation","Report the result with its n and a note that the group is too small for firm conclusions":"Présenter le résultat avec son n et une note indiquant que le groupe est trop petit pour des conclusions solides","Merge them with the men":"Les fusionner avec les hommes","Report 0% to be safe":"Indiquer 0 % par prudence","Out of 300 respondents, 280 answered the question on net use and 196 said yes. What value should you report?":"Sur 300 répondants, 280 ont répondu à la question sur l'utilisation de la moustiquaire et 196 ont dit oui. Quelle valeur devez-vous publier ?","196 households":"196 ménages","Missing answers are excluded from the denominator unless the reference sheet says otherwise: 196 ÷ 280 = 70%, reported with n = 280.":"Les réponses manquantes sont exclues du dénominateur, sauf si la fiche de référence dit autre chose : 196 ÷ 280 = 70 %, présenté avec n = 280.","A fictional education project in the North-West region reported 82% of pupils passing the end-of-year test. When the MEAL officer disaggregated by sex and by displacement status, the pass rate was 85% for host community boys but 61% for displaced girls. The team added remedial classes for displaced girls, and the donor praised the report for showing the gap instead of hiding it in the average.":"Un projet fictif d'éducation dans la région du Nord-Ouest annonçait 82 % d'élèves admis à l'examen de fin d'année. Quand le chargé MEAL a désagrégé par sexe et par statut de déplacement, le taux de réussite était de 85 % pour les garçons de la communauté hôte mais de 61 % pour les filles déplacées. L'équipe a ajouté des cours de remédiation pour les filles déplacées, et le bailleur a salué le rapport pour avoir montré l'écart au lieu de le cacher dans la moyenne.","Write the numerator and denominator of three indicators from your logframe":"Écrivez le numérateur et le dénominateur de trois indicateurs de votre cadre logique","Check in the reference sheets which disaggregations each indicator requires":"Vérifiez dans les fiches de référence quelles désagrégations chaque indicateur exige","Build a COUNTIFS table in Excel with one row per sex and one column per location":"Construisez un tableau COUNTIFS dans Excel avec une ligne par sexe et une colonne par localité","Run the same disaggregation in Stata or SPSS and compare the figures with Excel":"Faites la même désagrégation dans Stata ou SPSS et comparez les chiffres avec Excel","Add the n of each group next to every percentage in your next report":"Ajoutez le n de chaque groupe à côté de chaque pourcentage dans votre prochain rapport","mean: estimate means (with the over option)":"mean : estimer des moyennes (avec l'option over)","Descriptive statistics and cross-tabulations in Excel, SPSS and Stata":"Statistiques descriptives et tableaux croisés dans Excel, SPSS et Stata","Choose between mean and median and report frequencies and percentages correctly":"Choisir entre moyenne et médiane et présenter correctement les effectifs et les pourcentages","Read a cross-tabulation with row or column percentages":"Lire un tableau croisé avec des pourcentages en ligne ou en colonne","Interpret a chi-square p-value in plain words without over-claiming":"Interpréter en mots simples la valeur p d'un khi-deux, sans surinterpréter","Descriptive statistics summarise a dataset in a few numbers: how many, what share, what is typical and how spread out. Cross-tabulations compare those numbers between groups. Together they answer most questions a programme manager or a donor asks, and they can be produced in Excel, SPSS or Stata with a few clicks or one line of code.":"Les statistiques descriptives résument une base de données en quelques chiffres : combien, quelle part, quelle valeur typique et quelle dispersion. Les tableaux croisés comparent ces chiffres entre groupes. Ensemble, ils répondent à la plupart des questions d'un chef de programme ou d'un bailleur, et ils se produisent dans Excel, SPSS ou Stata en quelques clics ou en une ligne de code.","The essential descriptive statistics":"Les statistiques descriptives essentielles","Statistic":"Statistique","SPSS":"SPSS","Frequency and percentage":"Effectif et pourcentage","How many and what share fall in each category":"Combien et quelle part se trouvent dans chaque catégorie","COUNTIF, then divide by the total":"COUNTIF (NB.SI), puis diviser par le total","tab var":"tab var","FREQUENCIES":"FREQUENCIES","The average; pulled by extreme values":"La valeur moyenne ; tirée par les valeurs extrêmes","summarize var":"summarize var","DESCRIPTIVES":"DESCRIPTIVES","The middle value; resists extreme values":"La valeur du milieu ; résiste aux valeurs extrêmes","MEDIAN":"MEDIAN","summarize var, detail":"summarize var, detail","FREQUENCIES with /STATISTICS=MEDIAN":"FREQUENCIES avec /STATISTICS=MEDIAN","Minimum and maximum":"Minimum et maximum","The range; a first check for errors":"L'étendue ; un premier contrôle des erreurs","MIN, MAX":"MIN, MAX","Standard deviation":"Écart type","How spread out the values are around the mean":"La dispersion des valeurs autour de la moyenne","STDEV.S":"STDEV.S","Mean or median?":"Moyenne ou médiane ?","For income, distance, time or expenditure, a few very large values pull the mean up. When the mean is much higher than the median, report the median as the typical value and mention the mean if the donor asks for it.":"Pour le revenu, la distance, le temps ou les dépenses, quelques très grandes valeurs tirent la moyenne vers le haut. Quand la moyenne est bien supérieure à la médiane, présentez la médiane comme valeur typique et mentionnez la moyenne si le bailleur la demande.","Mean, median and range":"Moyenne, médiane et étendue","Distance in km from nine fictional households to the nearest health centre in a health district of the Centre region. Fill":"Distance en km entre neuf ménages fictifs et le centre de santé le plus proche, dans un district de santé de la région du Centre. Remplissez",", then answer in":", puis répondez en",": which is the better typical value,":": quelle est la meilleure valeur typique,","Use COUNT, AVERAGE, MEDIAN, MIN and MAX on B2:B10. One household lives 18 km away, which pulls the mean well above what most households experience.":"Utilisez COUNT, AVERAGE, MEDIAN, MIN et MAX sur B2:B10. Un ménage habite à 18 km, ce qui tire la moyenne bien au-dessus de ce que vivent la plupart des ménages.","Reading a cross-tabulation":"Lire un tableau croisé","A cross-tab counts the respondents in each combination of two variables. The key choice is the direction of the percentages. Put the group you compare in the rows and ask for row percentages: each row then adds up to 100%, and you compare the rows. Column percentages answer a different question: among those with a given outcome, what share belongs to each group.":"Un tableau croisé compte les répondants dans chaque combinaison de deux variables. Le choix clé est le sens des pourcentages. Placez le groupe que vous comparez en lignes et demandez des pourcentages en ligne : chaque ligne totalise alors 100 %, et vous comparez les lignes. Les pourcentages en colonne répondent à une autre question : parmi ceux qui ont un résultat donné, quelle part appartient à chaque groupe.","Read it row by row: 35% of displaced (IDP) children have a birth certificate, against 60% of host community children. The gap is 25 percentage points, not 25%.":"Lisez-le ligne par ligne : 35 % des enfants déplacés (PDI) ont un acte de naissance, contre 60 % des enfants de la communauté hôte. L'écart est de 25 points de pourcentage, pas de 25 %.","Row and column percentages":"Pourcentages en ligne et en colonne","Rebuild the percentages of the birth registration cross-tab above. Fill":"Reconstituez les pourcentages du tableau croisé sur l'enregistrement des naissances ci-dessus. Remplissez","with the share registered in each group (row %),":"avec la part d'enfants enregistrés dans chaque groupe (% en ligne),","with the share of all registered children who are IDP or host (column %), and":"avec la part de tous les enfants enregistrés qui sont PDI ou hôtes (% en colonne), et","with the gap in percentage points between host and IDP.":"avec l'écart en points de pourcentage entre hôtes et PDI.","Row %: registered divided by the row total, =C2/(B2+C2). Column %: registered in the group divided by all registered, =C2/C4. The gap in points is (D3-D2)*100.":"% en ligne : enregistrés divisés par le total de la ligne, =C2/(B2+C2). % en colonne : enregistrés du groupe divisés par tous les enregistrés, =C2/C4. L'écart en points est (D3-D2)*100.","What the chi-square test tells you":"Ce que dit le test du khi-deux","The chi-square test asks: if there were no real link between the two variables in the population, how likely would a gap this large be in a sample, just by chance?":"Le test du khi-deux pose la question : s'il n'y avait aucun lien réel entre les deux variables dans la population, quelle serait la probabilité d'observer un écart aussi grand dans un échantillon, par simple hasard ?","That likelihood is the p-value. If p < 0.05, the gap is called statistically significant: chance alone is an unlikely explanation.":"Cette probabilité est la valeur p. Si p < 0,05, l'écart est dit statistiquement significatif : le hasard seul est une explication peu probable.","If p ≥ 0.05, you cannot rule out chance. It does not prove that the groups are equal; the sample may be too small.":"Si p ≥ 0,05, vous ne pouvez pas écarter le hasard. Cela ne prouve pas que les groupes sont égaux ; l'échantillon est peut-être trop petit.","Significant does not mean large or important, and it never proves that one variable causes the other.":"Significatif ne veut pas dire grand ou important, et cela ne prouve jamais qu'une variable cause l'autre.","The test assumes a random sample and enough cases in each cell; with very small counts, ask a statistician.":"Le test suppose un échantillon aléatoire et assez d'observations dans chaque case ; avec de très petits effectifs, demandez l'avis d'un statisticien.","In SPSS, click Statistics and tick Chi-square, then Cells and tick Row under Percentages.":"Dans SPSS, cliquez sur Statistiques et cochez Khi-carré, puis sur Cellules et cochez Ligne sous Pourcentages.","Read the output":"Lire les résultats","Use the Stata cross-tab and the tabstat output above from the same fictional survey to answer.":"Utilisez le tableau croisé Stata et le résultat de tabstat ci-dessus, issus de la même enquête fictive, pour répondre.","Row percentages compare groups. p50 is the median. Pr is the p-value of the chi-square test.":"Les pourcentages en ligne comparent les groupes. p50 est la médiane. Pr est la valeur p du test du khi-deux.","What share of IDP children are registered?":"Quelle part des enfants PDI est enregistrée ?","Row percentage in the IDP row, Yes column: 42 out of 120 = 35%.":"Pourcentage en ligne, ligne IDP, colonne Yes : 42 sur 120 = 35 %.","What does Pr = 0.000 mean here?":"Que signifie Pr = 0.000 ici ?","A p-value below 0.05 means chance alone is an unlikely explanation. It says nothing about causes.":"Une valeur p inférieure à 0,05 signifie que le hasard seul est une explication peu probable. Elle ne dit rien des causes.","There is no difference between the groups":"Il n'y a aucune différence entre les groupes","Being displaced causes lower registration":"Le fait d'être déplacé cause un enregistrement plus faible","A gap this large would be very unlikely if registration did not differ between the groups in the population":"Un écart aussi grand serait très improbable si l'enregistrement ne différait pas entre les groupes dans la population","Zero percent of children are registered":"Zéro pour cent des enfants sont enregistrés","In the tabstat output, which value best describes the typical distance for IDP households?":"Dans le résultat de tabstat, quelle valeur décrit le mieux la distance typique des ménages PDI ?","The mean (6.42) is pulled up by a few very distant households; the median (4.5) is the typical value.":"La moyenne (6,42) est tirée vers le haut par quelques ménages très éloignés ; la médiane (4,5) est la valeur typique.","6.42 km, the mean":"6,42 km, la moyenne","4.5 km, the median":"4,5 km, la médiane","31 km, the maximum":"31 km, le maximum","0.5 km, the minimum":"0,5 km, le minimum","Type the Stata command that produced the cross-tab with row percentages and the chi-square test":"Saisissez la commande Stata qui a produit le tableau croisé avec les pourcentages en ligne et le test du khi-deux","The row option adds row percentages; chi2 adds Pearson's chi-square test and its p-value.":"L'option row ajoute les pourcentages en ligne ; chi2 ajoute le test du khi-deux de Pearson et sa valeur p.","A cross-tab shows that 48% of women and 41% of men use the health centre, with a chi-square p-value of 0.31. What is the correct conclusion?":"Un tableau croisé montre que 48 % des femmes et 41 % des hommes fréquentent le centre de santé, avec une valeur p du khi-deux de 0,31. Quelle est la bonne conclusion ?","Women use the health centre more than men; the difference is proven":"Les femmes fréquentent davantage le centre de santé que les hommes ; la différence est prouvée","The difference could well be due to chance; the data does not show a clear difference":"La différence pourrait bien être due au hasard ; les données ne montrent pas de différence claire","There is no difference at all between women and men":"Il n'y a aucune différence entre femmes et hommes","The test failed and must be repeated":"Le test a échoué et doit être refait","With p ≥ 0.05, chance remains a plausible explanation. That is not proof that women and men are equal, only that this sample cannot show a difference.":"Avec p ≥ 0,05, le hasard reste une explication plausible. Ce n'est pas la preuve que femmes et hommes sont égaux, seulement que cet échantillon ne permet pas de montrer une différence.","In a fictional protection project in the Far North, a draft report stated that displacement \"causes\" low birth registration because the chi-square test was significant. The MEAL officer rewrote it: displaced children were much less likely to be registered (35% against 60%, p < 0.001), and the team listed possible reasons, such as lost documents and distance to civil status centres, to explore in focus groups.":"Dans un projet fictif de protection dans l'Extrême-Nord, un projet de rapport affirmait que le déplacement « cause » le faible enregistrement des naissances parce que le test du khi-deux était significatif. Le chargé MEAL a réécrit : les enfants déplacés étaient beaucoup moins souvent enregistrés (35 % contre 60 %, p < 0,001), et l'équipe a listé des raisons possibles, comme la perte des documents et la distance aux centres d'état civil, à explorer en groupes de discussion.","Produce the mean, median, minimum and maximum of one numeric variable of your survey in Excel and in Stata or SPSS":"Produisez la moyenne, la médiane, le minimum et le maximum d'une variable numérique de votre enquête dans Excel et dans Stata ou SPSS","Decide for that variable whether the mean or the median is the better typical value, and write why":"Décidez pour cette variable si la moyenne ou la médiane est la meilleure valeur typique, et écrivez pourquoi","Build one cross-tab with the group in the rows and row percentages":"Construisez un tableau croisé avec le groupe en lignes et des pourcentages en ligne","Add the chi-square test and write one plain sentence about the p-value":"Ajoutez le test du khi-deux et écrivez une phrase simple sur la valeur p","Report the gap between two groups in percentage points":"Présentez l'écart entre deux groupes en points de pourcentage","tabulate twoway: two-way table of frequencies":"tabulate twoway : tableau de fréquences à deux entrées","Basic qualitative analysis: coding and themes":"Analyse qualitative de base : codage et thèmes","Build a codebook with deductive and inductive codes and apply it to transcripts":"Construire une grille de codage avec des codes déductifs et inductifs et l'appliquer aux transcriptions","Count code frequency in an Excel code matrix and select representative quotes":"Compter la fréquence des codes dans une matrice de codage Excel et choisir des citations représentatives","Triangulate qualitative themes with quantitative results":"Trianguler les thèmes qualitatifs avec les résultats quantitatifs","Focus groups and key informant interviews explain the numbers: why women do not come to the health centre, why a water point is not used, why a training did not change practice. Their answers arrive as pages of notes and transcripts. Coding turns those pages into a small number of themes you can compare, count and illustrate with quotes.":"Les groupes de discussion et les entretiens avec des informateurs clés expliquent les chiffres : pourquoi les femmes ne viennent pas au centre de santé, pourquoi un point d'eau n'est pas utilisé, pourquoi une formation n'a pas changé les pratiques. Leurs réponses arrivent sous forme de pages de notes et de transcriptions. Le codage transforme ces pages en un petit nombre de thèmes que l'on peut comparer, compter et illustrer par des citations.","From recordings to transcripts":"Des enregistrements aux transcriptions","Transcribe or write detailed notes on the same day, while the discussion is fresh.":"Transcrivez ou rédigez des notes détaillées le jour même, pendant que la discussion est encore fraîche.","Translate into the analysis language, keeping key expressions in the original language (Fulfulde, Pidgin, Ewondo…) when they carry meaning.":"Traduisez dans la langue d'analyse en gardant les expressions clés dans la langue d'origine (fulfulde, pidgin, ewondo…) lorsqu'elles portent du sens.","Give each transcript a code (FGD1, KII2) and a header: date, place, type of group, facilitator. Never use participants' names.":"Donnez à chaque transcription un code (FGD1, KII2) et un en-tête : date, lieu, type de groupe, animateur. N'utilisez jamais les noms des participants.","Number the lines or paragraphs so that every quote can be traced back.":"Numérotez les lignes ou les paragraphes pour que chaque citation puisse être retrouvée.","The codebook":"La grille de codage","Code":"Code","Example of text":"Exemple de texte","Distance":"Distance","Travel time, cost of transport or lack of transport to the service":"Temps de trajet, coût du transport ou manque de transport jusqu'au service","Deductive":"Déductif","\"The health centre is two hours on foot.\"":"« Le centre de santé est à deux heures de marche. »","Fees, drugs or other payments":"Frais, médicaments ou autres paiements","\"They ask us to buy the gloves.\"":"« On nous demande d'acheter les gants. »","Safety":"Sécurité","Fear of attack or harassment on the way or at the service":"Peur d'une agression ou d'un harcèlement en chemin ou au service","Inductive":"Inductif","\"Nobody walks on that road after four o'clock.\"":"« Personne ne marche sur cette route après seize heures. »","Staff attitude":"Attitude du personnel","How staff treat and speak to users":"La façon dont le personnel traite les usagers et leur parle","\"The nurse shouted at me in front of everyone.\"":"« L'infirmière m'a crié dessus devant tout le monde. »","Deductive and inductive codes":"Codes déductifs et inductifs","Deductive codes come from your questions, your theory of change or the indicator framework and are written before you read. Inductive codes emerge from the data: themes that participants raise and that you did not expect. A good codebook starts deductive and grows inductive codes as you read.":"Les codes déductifs viennent de vos questions, de votre théorie du changement ou du cadre des indicateurs, et sont écrits avant la lecture. Les codes inductifs émergent des données : des thèmes que les participants soulèvent et que vous n'attendiez pas. Une bonne grille de codage commence déductive et s'enrichit de codes inductifs au fil de la lecture.","Coding step by step":"Le codage étape par étape","A simple coding process":"Un processus de codage simple","Read all transcripts once without coding, and note first impressions.":"Lisez toutes les transcriptions une première fois sans coder, et notez vos premières impressions.","Apply the deductive codes, marking each passage with one or more codes.":"Appliquez les codes déductifs en marquant chaque passage d'un ou plusieurs codes.","Add an inductive code when a new idea appears in two or more transcripts, and write its definition in the codebook.":"Ajoutez un code inductif lorsqu'une idée nouvelle apparaît dans deux transcriptions ou plus, et écrivez sa définition dans la grille de codage.","Have a second person code one or two transcripts and compare; clarify definitions where you disagree.":"Faites coder une ou deux transcriptions par une deuxième personne et comparez ; clarifiez les définitions là où vous n'êtes pas d'accord.","Build the code matrix: one row per transcript, one column per code, 1 when the code appears.":"Construisez la matrice de codage : une ligne par transcription, une colonne par code, 1 lorsque le code apparaît.","Group related codes into themes and write a short summary of each theme, with its best quotes.":"Regroupez les codes proches en thèmes et rédigez un court résumé de chaque thème, avec ses meilleures citations.","Count codes in a matrix":"Compter les codes dans une matrice","Code matrix from six fictional transcripts on why women do not give birth at a health centre in a health district of the North region (1 = the code appears). Fill":"Matrice de codage de six transcriptions fictives sur les raisons pour lesquelles les femmes n'accouchent pas au centre de santé, dans un district de santé de la région du Nord (1 = le code apparaît). Remplissez","with the number of transcripts mentioning each code,":"avec le nombre de transcriptions qui mentionnent chaque code,","with the number of women's transcripts, and":"avec le nombre de transcriptions de femmes, et","with the share of women's transcripts.":"avec la part des transcriptions de femmes.","Row 8: =SUM(C2:C7). Row 9: =SUMIF($B$2:$B$7,\"Women\",C2:C7). Row 10: =C9/COUNTIF($B$2:$B$7,\"Women\").":"Ligne 8 : =SUM(C2:C7). Ligne 9 : =SUMIF($B$2:$B$7,\"Women\",C2:C7). Ligne 10 : =C9/COUNTIF($B$2:$B$7,\"Women\").","Counts show spread, not importance":"Les nombres montrent la diffusion, pas l'importance","A code that appears in four transcripts out of six is widespread, but a theme mentioned once can still be critical, for example a single report of abuse by staff. Use counts to show how common a theme is, never as a percentage of the population.":"Un code qui apparaît dans quatre transcriptions sur six est répandu, mais un thème mentionné une seule fois peut rester critique, par exemple un unique signalement d'abus par le personnel. Utilisez les nombres pour montrer à quel point un thème est courant, jamais comme un pourcentage de la population.","Choosing quotes and triangulating":"Choisir les citations et trianguler","Choose quotes that are typical of the theme, not only the most dramatic ones.":"Choisissez des citations typiques du thème, pas seulement les plus spectaculaires.","Keep quotes short, and label them with the group and place only, for example: woman, FGD, Tcholliré.":"Gardez des citations courtes et étiquetez-les uniquement avec le groupe et le lieu, par exemple : femme, FGD, Tcholliré.","Remove any detail that could identify the speaker in a small village.":"Supprimez tout détail qui pourrait identifier la personne dans un petit village.","Triangulate: set each theme next to the survey figures. Do they confirm, explain or contradict each other?":"Triangulez : placez chaque thème à côté des chiffres de l'enquête. Se confirment-ils, s'expliquent-ils ou se contredisent-ils ?","When sources disagree, say so and explain what you did to understand why.":"Quand les sources divergent, dites-le et expliquez ce que vous avez fait pour comprendre pourquoi.","Code the quotes":"Coder les citations","Apply the codebook above to extracts from the fictional transcripts, then answer the analysis questions.":"Appliquez la grille de codage ci-dessus à des extraits des transcriptions fictives, puis répondez aux questions d'analyse.","Use the definitions in the codebook. For triangulation, ask whether the qualitative theme explains a pattern seen in the survey.":"Utilisez les définitions de la grille de codage. Pour la triangulation, demandez-vous si le thème qualitatif explique une tendance observée dans l'enquête.","\"When labour starts at night, we stay at home. The bush road is not safe.\"":"« Quand le travail commence la nuit, on reste à la maison. La route de brousse n'est pas sûre. »","Fear on the road is the Safety code. Some coders would also add Distance; one passage can carry several codes.":"La peur sur la route relève du code Sécurité. Certains codeurs ajouteraient aussi Distance ; un même passage peut porter plusieurs codes.","\"We must pay for the card, the gloves and the medicines before they touch you.\"":"« Il faut payer le carnet, les gants et les médicaments avant qu'ils ne vous touchent. »","\"The motorbike to the centre costs more than a day's work, and there is often none.\"":"« La moto jusqu'au centre coûte plus qu'une journée de travail, et souvent il n'y en a pas. »","Transport cost and availability fall under Distance as defined in the codebook, not under Cost, which covers payments at the service.":"Le coût et la disponibilité du transport relèvent de Distance selon la définition de la grille, et non de Coût, qui couvre les paiements au service.","\"The midwife is young and she insults the women who scream.\"":"« La sage-femme est jeune et elle insulte les femmes qui crient. »","Safety was not in the interview guide, but participants raised it in four transcripts. What kind of code is it?":"La sécurité ne figurait pas dans le guide d'entretien, mais les participants l'ont évoquée dans quatre transcriptions. De quel type de code s'agit-il ?","A code that emerges from the data rather than from the guide is inductive.":"Un code qui émerge des données plutôt que du guide est inductif.","A quantitative variable":"Une variable quantitative","A theme to ignore because it was not asked":"Un thème à ignorer parce qu'il n'a pas été demandé","The survey shows that births at the health centre are 20 points lower in villages more than 10 km away. How do the transcripts help?":"L'enquête montre que les accouchements au centre de santé sont inférieurs de 20 points dans les villages situés à plus de 10 km. Comment les transcriptions aident-elles ?","This is triangulation: the qualitative themes explain the pattern in the numbers.":"C'est la triangulation : les thèmes qualitatifs expliquent la tendance observée dans les chiffres.","They replace the survey figure":"Elles remplacent le chiffre de l'enquête","They explain the figure: distance, night travel and safety keep women at home":"Elles expliquent le chiffre : la distance, les trajets de nuit et l'insécurité retiennent les femmes à la maison","They prove that distance causes home births":"Elles prouvent que la distance cause les accouchements à domicile","They are not useful because the samples differ":"Elles ne sont pas utiles car les échantillons diffèrent","Which practice makes qualitative analysis more reliable?":"Quelle pratique rend l'analyse qualitative plus fiable ?","Choosing only the most striking quotes":"Choisir uniquement les citations les plus frappantes","Coding alone and never changing the codebook":"Coder seul et ne jamais modifier la grille de codage","Writing code definitions and having a second person code some transcripts to compare":"Rédiger les définitions des codes et faire coder quelques transcriptions par une deuxième personne pour comparer","Reporting that 67% of the population fear the road because four of six transcripts say so":"Annoncer que 67 % de la population a peur de la route parce que quatre transcriptions sur six le disent","Clear definitions and a second coder make the coding consistent and reveal ambiguous codes. Transcript counts are not population percentages.":"Des définitions claires et un deuxième codeur rendent le codage cohérent et révèlent les codes ambigus. Le nombre de transcriptions n'est pas un pourcentage de la population.","A fictional WASH project in the North-West region found that only 40% of households used the new water kiosks. Focus groups coded in Excel showed a theme nobody expected: the kiosks closed at 5 p.m., before women returned from the farms. The team extended opening hours, and the next monitoring round showed use rising.":"Un projet EHA fictif dans la région du Nord-Ouest a constaté que seuls 40 % des ménages utilisaient les nouveaux kiosques à eau. Les groupes de discussion codés dans Excel ont fait apparaître un thème que personne n'attendait : les kiosques fermaient à 17 h, avant le retour des femmes des champs. L'équipe a prolongé les heures d'ouverture, et la collecte de suivi suivante a montré une hausse de l'utilisation.","Write a codebook of five codes, with a definition and an example for each, for one of your FGD guides":"Rédigez une grille de cinq codes, avec une définition et un exemple pour chacun, pour l'un de vos guides de FGD","Code two transcripts and add at least one inductive code":"Codez deux transcriptions et ajoutez au moins un code inductif","Ask a colleague to code one transcript and compare your codes":"Demandez à un collègue de coder une transcription et comparez vos codes","Build a code matrix in Excel and count code frequency by group":"Construisez une matrice de codage dans Excel et comptez la fréquence des codes par groupe","Write one paragraph that triangulates a theme with a survey figure":"Rédigez un paragraphe qui triangule un thème avec un chiffre d'enquête","Thematic coding":"Codage thématique","Practice lab: from raw data to disaggregated results":"Atelier pratique : des données brutes aux résultats désagrégés","Calculate rates and conditional counts from a small monitoring dataset":"Calculer des taux et des comptages conditionnels à partir d'une petite base de suivi","Run and read a disaggregated cross-tab in Stata and SPSS":"Produire et lire un tableau croisé désagrégé dans Stata et SPSS","Build disaggregated indicators that exclude missing answers from the denominator":"Construire des indicateurs désagrégés qui excluent les réponses manquantes du dénominateur","Clean a dataset with duplicates, special codes and impossible values before calculating indicators":"Nettoyer une base contenant des doublons, des codes spéciaux et des valeurs impossibles avant de calculer les indicateurs","Exercise 1: School attendance":"Exercice 1 : Assiduité scolaire","Monthly attendance rates":"Taux d'assiduité mensuels","Attendance of six pupils in a fictional primary school in the Littoral region. The school was open 20 days (":"Assiduité de six élèves d'une école primaire fictive de la région du Littoral. L'école a été ouverte 20 jours (","). Fill":"). Remplissez","with each pupil's attendance rate, then":"avec le taux d'assiduité de chaque élève, puis","D2: =C2/$G$2, copied down (the $ keeps G2 fixed). G3: =AVERAGE(D2:D7). G4: =COUNTIF(D2:D7,\">=0.8\"). G5: =COUNTIFS(B2:B7,\"F\",D2:D7,\">=0.8\").":"D2 : =C2/$G$2, recopiée vers le bas (le $ garde G2 fixe). G3 : =AVERAGE(D2:D7). G4 : =COUNTIF(D2:D7,\">=0.8\"). G5 : =COUNTIFS(B2:B7,\"F\",D2:D7,\">=0.8\").","Exercise 2: Nutrition screening":"Exercice 2 : Dépistage nutritionnel","Screening results by sex":"Résultats du dépistage par sexe","Community health workers in a fictional nutrition project in the East region screened 400 children aged 6–59 months with a MUAC tape (green = normal, yellow = moderate, red = severe acute malnutrition). Type the commands and read the output above.":"Des agents de santé communautaires d'un projet fictif de nutrition dans la région de l'Est ont dépisté 400 enfants de 6 à 59 mois avec un bracelet MUAC (vert = normal, jaune = modérée, rouge = malnutrition aiguë sévère). Saisissez les commandes et lisez les résultats ci-dessus.","Group first, outcome second, then the options after the comma. Row percentages are the second line of each row. Compare Pr with 0.05.":"Le groupe d'abord, le résultat ensuite, puis les options après la virgule. Les pourcentages en ligne sont la deuxième ligne de chaque rangée. Comparez Pr à 0,05.","Stata: the command that produced the output above":"Stata : la commande qui a produit le résultat ci-dessus","sex in the rows, MUAC category in the columns, with row percentages and the chi-square test.":"sex en lignes, catégorie MUAC en colonnes, avec les pourcentages en ligne et le test du khi-deux.","SPSS syntax: the same table with counts, row percentages and chi-square":"Syntaxe SPSS : le même tableau avec effectifs, pourcentages en ligne et khi-deux","/CELLS sets the percentages shown; /STATISTICS=CHISQ adds the Chi-Square Tests table.":"/CELLS définit les pourcentages affichés ; /STATISTICS=CHISQ ajoute le tableau des tests du khi-carré.","What percentage of boys screened were in the red category?":"Quel pourcentage des garçons dépistés était dans la catégorie rouge ?","14 of 200 boys = 7%, read on the row percentage line of the Male row.":"14 garçons sur 200 = 7 %, lu sur la ligne des pourcentages en ligne de la rangée Male.","What is the total percentage of acute malnutrition (yellow + red) among girls?":"Quel est le pourcentage total de malnutrition aiguë (jaune + rouge) chez les filles ?","12% yellow + 4% red = 16% for girls, against 25% for boys.":"12 % jaune + 4 % rouge = 16 % pour les filles, contre 25 % pour les garçons.","How should the team describe the difference between girls and boys?":"Comment l'équipe doit-elle décrire la différence entre filles et garçons ?","p = 0.080 is above 0.05: chance cannot be ruled out. Report the figures, note the gap, and keep monitoring rather than claiming a proven difference.":"p = 0,080 est supérieur à 0,05 : le hasard ne peut pas être écarté. Présentez les chiffres, signalez l'écart et poursuivez le suivi plutôt que d'annoncer une différence prouvée.","Boys are significantly more malnourished (p < 0.05)":"Les garçons sont significativement plus malnutris (p < 0,05)","Boys show more malnutrition in this sample, but with p = 0.080 the difference is not statistically significant":"Les garçons présentent plus de malnutrition dans cet échantillon, mais avec p = 0,080 la différence n'est pas statistiquement significative","There is no difference between girls and boys":"Il n'y a aucune différence entre filles et garçons","The test proves that sex causes malnutrition":"Le test prouve que le sexe cause la malnutrition","Exercise 3: Water access in a displacement setting":"Exercice 3 : Accès à l'eau en situation de déplacement","Disaggregated WASH indicators with a missing answer":"Indicateurs EHA désagrégés avec une réponse manquante","Household survey in a fictional IDP site and host community in the South-West region. W04 did not answer the water source question and must be excluded from the denominators. Fill":"Enquête ménages dans un site de PDI fictif et dans la communauté hôte, région du Sud-Ouest. W04 n'a pas répondu à la question sur la source d'eau et doit être exclu des dénominateurs. Remplissez","Valid answers are Yes plus No: =COUNTIF(D2:D11,\"Yes\")+COUNTIF(D2:D11,\"No\"). For each group, divide the COUNTIFS with Yes by the COUNTIFS with Yes plus the COUNTIFS with No, so the blank never enters the denominator. H6 needs AVERAGEIFS with two conditions.":"Les réponses valides sont Yes plus No : =COUNTIF(D2:D11,\"Yes\")+COUNTIF(D2:D11,\"No\"). Pour chaque groupe, divisez le COUNTIFS avec Yes par le COUNTIFS avec Yes plus le COUNTIFS avec No, afin que la case vide n'entre jamais dans le dénominateur. H6 demande un AVERAGEIFS à deux conditions.","Exercise 4: Livelihoods income survey":"Exercice 4 : Enquête sur les revenus des moyens d'existence","Clean first, then calculate":"D'abord nettoyer, ensuite calculer","Endline survey of a fictional livelihoods project in the North region. A record is valid only if it is the first occurrence of its ID, household size is not 99 (don't know), and monthly income is at most 1 000 000 FCFA. In":"Enquête finale d'un projet fictif de moyens d'existence dans la région du Nord. Un enregistrement n'est valide que s'il est la première occurrence de son identifiant, si la taille du ménage n'est pas 99 (ne sait pas) et si le revenu mensuel est d'au plus 1 000 000 FCFA. Dans","write":"écrivez","for valid, then fill":"pour valide, puis remplissez","using valid records only.":"en utilisant uniquement les enregistrements valides.","F2: =IF(AND(COUNTIF($A$2:A2,A2)=1,D2<>99,E2<=1000000),\"Yes\",\"No\"). The growing range $A$2:A2 counts an ID only up to the current row, so the first copy is kept and the second flagged. Then add F2:F11,\"Yes\" as a condition in every COUNTIFS and AVERAGEIFS.":"F2 : =IF(AND(COUNTIF($A$2:A2,A2)=1,D2<>99,E2<=1000000),\"Yes\",\"No\"). La plage qui s'agrandit $A$2:A2 ne compte un identifiant que jusqu'à la ligne courante : la première copie est gardée et la seconde signalée. Ajoutez ensuite F2:F11,\"Yes\" comme condition dans chaque COUNTIFS et AVERAGEIFS.","What is the first rule of data cleaning?":"Quelle est la première règle du nettoyage des données ?","Delete every incomplete record":"Supprimer tout enregistrement incomplet","Never overwrite the raw data; work on a copy and log every change":"Ne jamais écraser les données brutes ; travailler sur une copie et consigner chaque modification","Replace missing values with the mean":"Remplacer les valeurs manquantes par la moyenne","Clean only the variables the donor asks for":"Ne nettoyer que les variables demandées par le bailleur","Keeping the raw file untouched and logging each change means every correction can be checked and undone.":"Garder le fichier brut intact et consigner chaque modification permet de vérifier et d'annuler toute correction.","In a survey, 99 means \"refused\" in the age variable. What must you do before calculating the mean age?":"Dans une enquête, 99 signifie « refus » dans la variable âge. Que devez-vous faire avant de calculer l'âge moyen ?","Nothing, 99 is a plausible age":"Rien, 99 est un âge plausible","Replace 99 with 0":"Remplacer 99 par 0","Declare 99 as missing so it is excluded from the mean":"Déclarer 99 comme manquant pour qu'il soit exclu de la moyenne","Delete the respondents who refused":"Supprimer les répondants qui ont refusé","Special codes are not real values. Left in, they pull the mean up; declared as missing, they are excluded but the rest of the record is kept.":"Les codes spéciaux ne sont pas de vraies valeurs. Laissés tels quels, ils tirent la moyenne vers le haut ; déclarés manquants, ils sont exclus mais le reste de l'enregistrement est conservé.","In Stata, why can count if age > 120 give a wrong result?":"Dans Stata, pourquoi count if age > 120 peut-il donner un résultat faux ?","Because count only works with strings":"Parce que count ne fonctionne qu'avec du texte","Because age must be written in capitals":"Parce que age doit être écrit en majuscules","Because Stata rounds ages":"Parce que Stata arrondit les âges","Because missing values are treated as larger than any number and are counted too":"Parce que les valeurs manquantes sont traitées comme plus grandes que tout nombre et sont comptées aussi","Add & !missing(age) to exclude missing values from the count.":"Ajoutez & !missing(age) pour exclure les valeurs manquantes du comptage.","Out of 250 respondents, 20 did not answer and 138 said yes. What is the indicator value?":"Sur 250 répondants, 20 n'ont pas répondu et 138 ont dit oui. Quelle est la valeur de l'indicateur ?","Missing answers are excluded from the denominator: 138 ÷ 230 = 60%, reported with n = 230.":"Les réponses manquantes sont exclues du dénominateur : 138 ÷ 230 = 60 %, présenté avec n = 230.","Which Excel formula gives the percentage of women (F in column B) who answered Yes in column E?":"Quelle formule Excel donne le pourcentage de femmes (F en colonne B) ayant répondu Yes en colonne E ?","=COUNTIF(E2:E101,\"Yes\")/COUNTIF(B2:B101,\"F\")":"=COUNTIF(E2:E101,\"Yes\")/COUNTIF(B2:B101,\"F\")","=COUNTIFS(B2:B101,\"F\",E2:E101,\"Yes\")/COUNTIF(B2:B101,\"F\")":"=COUNTIFS(B2:B101,\"F\",E2:E101,\"Yes\")/COUNTIF(B2:B101,\"F\")","=AVERAGEIFS(E2:E101,B2:B101,\"F\")":"=AVERAGEIFS(E2:E101,B2:B101,\"F\")","=COUNTIFS(B2:B101,\"F\",E2:E101,\"Yes\")/COUNTA(B2:B101)":"=COUNTIFS(B2:B101,\"F\",E2:E101,\"Yes\")/COUNTA(B2:B101)","The numerator counts women who said yes; the denominator counts all women. The other options mix groups or average text.":"Le numérateur compte les femmes qui ont dit oui ; le dénominateur compte toutes les femmes. Les autres options mélangent les groupes ou font la moyenne d'un texte.","Household incomes have a mean of 145 000 FCFA and a median of 62 000 FCFA. What is the best typical value to report?":"Les revenus des ménages ont une moyenne de 145 000 FCFA et une médiane de 62 000 FCFA. Quelle est la meilleure valeur typique à présenter ?","The mean, because it uses all values":"La moyenne, parce qu'elle utilise toutes les valeurs","The median, because a few very high incomes pull the mean up":"La médiane, parce que quelques revenus très élevés tirent la moyenne vers le haut","The average of the mean and the median":"La moyenne de la moyenne et de la médiane","A mean far above the median shows a skewed distribution. The median describes the typical household better.":"Une moyenne très supérieure à la médiane révèle une distribution asymétrique. La médiane décrit mieux le ménage typique.","A cross-tab gives a chi-square p-value of 0.02. What does this mean?":"Un tableau croisé donne une valeur p du khi-deux de 0,02. Qu'est-ce que cela signifie ?","A difference this large would be unlikely if the groups did not differ in the population":"Une différence aussi grande serait peu probable si les groupes ne différaient pas dans la population","One variable causes the other":"Une variable cause l'autre","The difference between the groups is large and important":"La différence entre les groupes est grande et importante","2% of respondents are in the table":"2 % des répondants figurent dans le tableau","p < 0.05 means chance alone is an unlikely explanation. It does not measure size or importance, and it does not show cause.":"p < 0,05 signifie que le hasard seul est une explication peu probable. Cela ne mesure ni la taille ni l'importance, et ne montre pas de cause.","In qualitative analysis, what is an inductive code?":"En analyse qualitative, qu'est-ce qu'un code inductif ?","A code taken from the indicator framework before reading":"Un code tiré du cadre des indicateurs avant la lecture","A code that counts the number of participants":"Un code qui compte le nombre de participants","A code used only in Stata":"Un code utilisé uniquement dans Stata","A code that emerges from the data, for a theme the team did not anticipate":"Un code qui émerge des données, pour un thème que l'équipe n'avait pas prévu","Deductive codes come from your questions or framework; inductive codes come from what participants actually said.":"Les codes déductifs viennent de vos questions ou de votre cadre ; les codes inductifs viennent de ce que les participants ont réellement dit.","Reporting, Accountability and Learning":"Rapportage, redevabilité et apprentissage","Indicator tracking, dashboards, donor reports and briefs, feedback and complaints mechanisms, evaluation and adaptive management.":"Suivi des indicateurs, tableaux de bord, rapports aux bailleurs et notes de synthèse, mécanismes de gestion des plaintes et des retours, évaluation et gestion adaptative.","Indicator tracking tables and dashboards":"Tableaux de suivi des indicateurs et tableaux de bord","Build an indicator tracking table with cumulative actuals, % of target and a status":"Construire un tableau de suivi des indicateurs avec les réalisations cumulées, le % de la cible et un statut","Design a simple dashboard with a few KPIs, a trend chart and a map":"Concevoir un tableau de bord simple avec quelques indicateurs clés, un graphique de tendance et une carte","Choose between Excel, Power BI and KoboToolbox reports for a given need":"Choisir entre Excel, Power BI et les rapports KoboToolbox selon le besoin","Data collected every month is only useful if someone can see, at a glance, whether the project is where it should be. The":"Les données collectées chaque mois ne sont utiles que si quelqu'un peut voir, d'un coup d'œil, si le projet est là où il devrait être. Le","indicator tracking table (ITT)":"tableau de suivi des indicateurs (ITT)","answers that question for every indicator in the logframe, and a dashboard shows the few numbers that managers watch most closely.":"répond à cette question pour chaque indicateur du cadre logique, et un tableau de bord présente les quelques chiffres que les responsables surveillent de plus près.","What goes into an ITT":"Ce que contient un ITT","Common mistake":"Erreur fréquente","The exact wording from the logframe and the indicator reference sheet":"La formulation exacte du cadre logique et de la fiche de référence de l'indicateur","Rewording the indicator, so it no longer matches the donor's version":"Reformuler l'indicateur, qui ne correspond alors plus à la version du bailleur","The value before the project started":"La valeur avant le démarrage du projet","Leaving it empty, so progress cannot be judged":"La laisser vide, ce qui empêche de juger les progrès","The value to reach, for the year or for the whole project":"La valeur à atteindre, pour l'année ou pour toute la durée du projet","Mixing annual and life-of-project targets in one column":"Mélanger cibles annuelles et cibles sur la durée du projet dans une même colonne","Actuals by quarter":"Réalisations par trimestre","What was achieved in each quarter (Q1, Q2, Q3, Q4)":"Ce qui a été réalisé à chaque trimestre (T1, T2, T3, T4)","Typing a cumulative figure in a quarterly column":"Saisir un chiffre cumulé dans une colonne trimestrielle","Cumulative":"Cumul","Total achieved so far, or the latest value for a rate":"Total réalisé à ce jour, ou dernière valeur pour un taux","Adding up percentages from several quarters":"Additionner des pourcentages de plusieurs trimestres","% achieved":"% réalisé","Cumulative divided by target":"Le cumul divisé par la cible","Dividing by the quarterly target instead of the annual one":"Diviser par la cible trimestrielle au lieu de la cible annuelle","On track, behind, or at risk, often shown as a traffic light":"Dans les temps, en retard ou à risque, souvent présenté sous forme de feu tricolore","Choosing the colour by feeling instead of a written rule":"Choisir la couleur au jugé plutôt que selon une règle écrite","Counts add up, rates do not":"Les effectifs s'additionnent, les taux non","Latrines built or people trained can be summed across quarters. A rate such as the percentage of functional water points cannot: report the latest measured value, or recalculate it from the underlying numbers.":"Les latrines construites ou les personnes formées peuvent s'additionner d'un trimestre à l'autre. Un taux, comme le pourcentage de points d'eau fonctionnels, ne le peut pas : indiquez la dernière valeur mesurée, ou recalculez-le à partir des chiffres de base.","Setting the status rule":"Fixer la règle de statut","Write the rule down before the first report, so nobody argues about colours later. A simple rule compares % achieved with the share of the year that has passed: after three quarters, an indicator at 75% of its annual target or more is on track.":"Écrivez la règle avant le premier rapport, pour que personne ne discute des couleurs ensuite. Une règle simple compare le % réalisé à la part de l'année écoulée : après trois trimestres, un indicateur à 75 % ou plus de sa cible annuelle est dans les temps.","Complete a WASH indicator tracking table":"Compléter un tableau de suivi des indicateurs WASH","The Eau Saine Est project (East region) has reported three quarters. Fill":"Le projet Eau Saine Est (région de l'Est) a rendu compte de trois trimestres. Remplissez","with the cumulative actuals,":"avec les réalisations cumulées,","with the % of the annual target achieved, and":"avec le % de la cible annuelle atteint, et","with \"On track\" if at least 75% of the target is reached, otherwise \"Behind\".":"avec « On track » si au moins 75 % de la cible est atteint, sinon « Behind ».","F2 is =SUM(C2:E2). G2 divides the cumulative by the annual target: =F2/B2. H2 is =IF(G2>=0.75,\"On track\",\"Behind\"). Copy each formula down.":"F2 est =SUM(C2:E2) (SOMME). G2 divise le cumul par la cible annuelle : =F2/B2. H2 est =IF(G2>=0.75,\"On track\",\"Behind\") (SI). Recopiez chaque formule vers le bas.","Traffic lights in Excel":"Feux tricolores dans Excel","Styles":"Styles","Icon Sets":"Jeux d'icônes","Or use Highlight Cells Rules › Text that Contains to colour \"Behind\" in red.":"Ou utilisez Règles de mise en surbrillance des cellules › Texte qui contient pour colorer « Behind » en rouge.","Colour the status column":"Colorer la colonne de statut","Select the status cells, for example H2:H30.":"Sélectionnez les cellules de statut, par exemple H2:H30.","Open Conditional Formatting and choose Highlight Cells Rules › Text that Contains.":"Ouvrez Mise en forme conditionnelle et choisissez Règles de mise en surbrillance des cellules › Texte qui contient.","Type Behind and choose a red fill; add a second rule for On track with a green fill.":"Tapez Behind et choisissez un remplissage rouge ; ajoutez une seconde règle pour On track avec un remplissage vert.","Add a short legend under the table that states the rule, for example \"On track = 75% or more after Q3\".":"Ajoutez sous le tableau une courte légende qui énonce la règle, par exemple « On track = 75 % ou plus après le T3 ».","A dashboard people actually read":"Un tableau de bord que l'on lit vraiment","Few KPIs":"Peu d'indicateurs clés",": four to six headline numbers at the top, each with its target.":": quatre à six chiffres phares en haut de page, chacun avec sa cible.","One trend chart":"Un seul graphique de tendance",": a line showing a key indicator month by month.":": une courbe qui montre un indicateur clé mois par mois.","One map or breakdown":"Une carte ou une ventilation",": results by health area, commune or site, so managers see where to act.":": les résultats par aire de santé, commune ou site, pour que les responsables voient où agir.","Date and source":"Date et source","on every page, so readers know how fresh the data is.":"sur chaque page, pour que les lecteurs sachent à quel point les données sont récentes.","Children screened for malnutrition, January to June 2026":"Enfants dépistés pour la malnutrition, janvier à juin 2026","The nutrition dashboard must show the district team whether screening is recovering after the April drop. Which chart fits the trend panel?":"Le tableau de bord nutrition doit montrer à l'équipe de district si le dépistage reprend après la baisse d'avril. Quel graphique convient au panneau de tendance ?","A line joins the months in order, so the April dip and the recovery in May and June are visible at once. A pie would treat the months as shares of a whole and hide the time order.":"Une courbe relie les mois dans l'ordre : la baisse d'avril et la reprise de mai et juin sont visibles d'un coup. Un camembert traiterait les mois comme les parts d'un tout et masquerait l'ordre chronologique.","Which tool for which job":"Quel outil pour quel usage","Good for":"Adapté pour","Limits":"Limites","ITTs, small dashboards, work offline, easy to share":"ITT, petits tableaux de bord, travail hors ligne, facile à partager","Manual updates; version confusion when copies circulate by e-mail":"Mises à jour manuelles ; confusion des versions quand des copies circulent par e-mail","Power BI":"Power BI","Dashboards that refresh from several data sources, filters by region or period":"Tableaux de bord actualisés à partir de plusieurs sources de données, filtres par région ou période","Needs training and a licence to publish and share online":"Demande une formation et une licence pour publier et partager en ligne","KoboToolbox reports":"Rapports KoboToolbox","Quick charts of each question while data is coming in":"Graphiques rapides pour chaque question pendant l'arrivée des données","Basic analysis only; no ITT logic or targets":"Analyse de base uniquement ; pas de logique d'ITT ni de cibles","Reports":"Rapports","In KoboToolbox, open the project first. Reports shows a chart and a frequency table for each question.":"Dans KoboToolbox, ouvrez d'abord le projet. Rapports affiche un graphique et un tableau de fréquences pour chaque question.","Get data":"Obtenir les données","Excel workbook":"Classeur Excel","In Power BI Desktop, this connects a dashboard to your ITT workbook.":"Dans Power BI Desktop, cette commande connecte un tableau de bord à votre classeur ITT.","An indicator is \"% of health facilities with no stock-out of RUTF\". The quarterly values are 60%, 70% and 80%. What should the cumulative column show after Q3?":"Un indicateur est « % de formations sanitaires sans rupture de stock d'ATPE ». Les valeurs trimestrielles sont 60 %, 70 % et 80 %. Que doit afficher la colonne de cumul après le T3 ?","70%, the average":"70 %, la moyenne","80%, the latest value":"80 %, la dernière valeur","It must stay empty until Q4":"Elle doit rester vide jusqu'au T4","Rates cannot be added across quarters. Report the latest measured value (or recalculate from the facility counts), and compare it with the target rate.":"Les taux ne s'additionnent pas d'un trimestre à l'autre. Indiquez la dernière valeur mesurée (ou recalculez-la à partir du nombre de formations sanitaires), et comparez-la au taux cible.","In a health district of the Far North, the MEAL officer sends one ITT file to the donor and another to the district team, each updated by hand. By the third quarter the figures no longer match. Keep one master ITT on a shared drive, lock the formula cells and export copies as PDF for readers.":"Dans un district de santé de l'Extrême-Nord, le chargé MEAL envoie un fichier ITT au bailleur et un autre à l'équipe de district, chacun mis à jour à la main. Au troisième trimestre, les chiffres ne concordent plus. Gardez un seul ITT de référence sur un lecteur partagé, verrouillez les cellules de formules et exportez des copies en PDF pour les lecteurs.","Take one logframe from your organisation and list its indicators in an ITT with baseline, target and four quarterly columns":"Prenez un cadre logique de votre organisation et reportez ses indicateurs dans un ITT avec situation de référence, cible et quatre colonnes trimestrielles","Mark each indicator as a count (summed) or a rate (latest value)":"Indiquez pour chaque indicateur s'il s'agit d'un effectif (additionné) ou d'un taux (dernière valeur)","Add the cumulative, % achieved and status formulas and write the status rule under the table":"Ajoutez les formules de cumul, de % réalisé et de statut, et écrivez la règle de statut sous le tableau","Apply red and green conditional formatting to the status column":"Appliquez une mise en forme conditionnelle rouge et verte à la colonne de statut","Sketch a one-page dashboard with four KPIs, one trend chart and one breakdown by site":"Esquissez un tableau de bord d'une page avec quatre indicateurs clés, un graphique de tendance et une ventilation par site","Visualizing your data with reports":"Visualiser vos données avec les rapports","Donor reports and one-page briefs":"Rapports aux bailleurs et notes de synthèse d'une page","Structure a progress report around indicators, challenges, lessons and next steps":"Structurer un rapport d'avancement autour des indicateurs, des difficultés, des leçons et des prochaines étapes","Write findings that state the result, the comparison and the reason":"Rédiger des constats qui énoncent le résultat, la comparaison et la raison","Produce a one-page brief and a results slide for decision-makers":"Produire une note de synthèse d'une page et une diapositive de résultats pour les décideurs","A donor report is where your monitoring work becomes visible. Donors read many reports, so a clear, honest and well-structured one builds trust and makes the next funding conversation easier. Decision-makers read even less: for them, a one-page brief is often all they will see.":"Le rapport au bailleur est l'endroit où votre travail de suivi devient visible. Les bailleurs lisent beaucoup de rapports : un rapport clair, honnête et bien structuré crée la confiance et facilite la prochaine discussion de financement. Les décideurs lisent encore moins : pour eux, une note de synthèse d'une page est souvent tout ce qu'ils verront.","The structure of a progress report":"La structure d'un rapport d'avancement","Section":"Section","Typical length":"Longueur habituelle","Executive summary":"Résumé exécutif","The three to five most important results and any major issue":"Les trois à cinq résultats les plus importants et tout problème majeur","Half a page":"Une demi-page","Progress against indicators":"Progrès par rapport aux indicateurs","The ITT, then a short comment on each indicator that is off track":"L'ITT, puis un bref commentaire sur chaque indicateur en retard","One to three pages plus the ITT":"Une à trois pages plus l'ITT","Activities implemented":"Activités mises en œuvre","What was done, where and for whom, with disaggregation":"Ce qui a été fait, où et pour qui, avec désagrégation","One to two pages":"Une à deux pages","Challenges and mitigation":"Difficultés et mesures d'atténuation","What went wrong, its effect, and what you did about it":"Ce qui n'a pas marché, son effet et ce que vous avez fait","Lessons learned":"Leçons apprises","What you now know that you did not know before, and how it changes your work":"Ce que vous savez maintenant et que vous ignoriez avant, et comment cela change votre travail","Next steps":"Prochaines étapes","Main activities of the next period, with dates":"Principales activités de la période suivante, avec des dates","A short list":"Une courte liste","Always use the donor's template":"Utilisez toujours le modèle du bailleur","Most donors impose their own template and word limits. Read the reporting section of the grant agreement at the start of the project, and prepare your ITT so it matches the donor's indicator list exactly.":"La plupart des bailleurs imposent leur propre modèle et des limites de mots. Lisez la section rapportage de l'accord de subvention dès le début du projet, et préparez votre ITT pour qu'il corresponde exactement à la liste d'indicateurs du bailleur.","Writing findings clearly":"Rédiger des constats clairs","A good finding contains three things: the result, a comparison (with the target, the baseline or the last period) and, when you know it, the reason.":"Un bon constat contient trois éléments : le résultat, une comparaison (avec la cible, la situation de référence ou la période précédente) et, quand vous la connaissez, la raison.","Weak":"Faible","Clear":"Clair","Many activities were carried out in the schools.":"De nombreuses activités ont été menées dans les écoles.","Hot meals were served in 18 of the 20 planned schools (90%) during the quarter.":"Des repas chauds ont été servis dans 18 des 20 écoles prévues (90 %) au cours du trimestre.","Attendance improved a lot.":"La fréquentation s'est beaucoup améliorée.","Average attendance rose from 71% at baseline to 86%, above the 80% target.":"La fréquentation moyenne est passée de 71 % à la situation de référence à 86 %, au-dessus de la cible de 80 %.","There were some difficulties with suppliers.":"Il y a eu quelques difficultés avec les fournisseurs.","Two deliveries arrived three weeks late because the road to Mokolo was cut; schools used their reserve stock.":"Deux livraisons sont arrivées avec trois semaines de retard car la route de Mokolo était coupée ; les écoles ont utilisé leur stock de réserve.","Report bad news early":"Signalez tôt les mauvaises nouvelles","An indicator that is behind is not a failure of the report. Explain why, what you are doing about it and whether the target should be revised. Donors react far worse to a surprise at the end of the project than to an honest explanation in the second quarter.":"Un indicateur en retard n'est pas un échec du rapport. Expliquez pourquoi, ce que vous faites et si la cible doit être révisée. Les bailleurs réagissent bien plus mal à une surprise en fin de projet qu'à une explication honnête au deuxième trimestre.","The one-page brief":"La note de synthèse d'une page","Build a one-page brief":"Construire une note de synthèse d'une page","Write a title that states the main finding, not only the topic.":"Rédigez un titre qui énonce le constat principal, pas seulement le sujet.","Put the key figure near the top, in bold, with its comparison.":"Placez le chiffre clé vers le haut, en gras, avec sa comparaison.","Explain in two or three sentences why it matters for the reader.":"Expliquez en deux ou trois phrases pourquoi il compte pour le lecteur.","End with three recommendations, each starting with a verb.":"Terminez par trois recommandations, chacune commençant par un verbe.","Add one simple chart, the data source and the date.":"Ajoutez un graphique simple, la source des données et la date.","In Word, use heading styles for the title and section names instead of making text larger by hand.":"Dans Word, utilisez les styles de titre pour le titre et les noms de sections au lieu d'agrandir le texte à la main.","Format a one-page brief":"Mettre en forme une note de synthèse d'une page",", make \"Key finding\" and \"Recommendations\"":", appliquez à « Key finding » et « Recommendations » le style",", make the figure \"from 71% to 86%\"":", mettez le chiffre « from 71% to 86% » en","Click in a line and choose the style in the Styles menu. Select only the figure before clicking Bold. Select the three recommendation lines together before clicking Bullets.":"Cliquez dans une ligne et choisissez le style dans le menu Styles. Sélectionnez uniquement le chiffre avant de cliquer sur Gras. Sélectionnez ensemble les trois lignes de recommandations avant de cliquer sur Puces.","Visuals that support the message":"Des visuels au service du message","One message per chart, stated in the chart title.":"Un message par graphique, énoncé dans le titre du graphique.","Bars to compare sites or groups, a line for change over time.":"Des barres pour comparer des sites ou des groupes, une courbe pour l'évolution dans le temps.","Show the target as a line or a label so readers can judge the result.":"Montrez la cible sous forme de ligne ou d'étiquette pour que les lecteurs puissent juger le résultat.","Photos only with informed consent, and never of children in a way that exposes them.":"Des photos uniquement avec un consentement éclairé, et jamais d'enfants d'une manière qui les expose.","Tighten a results slide":"Resserrer une diapositive de résultats","This slide will be shown at the quarterly review with the health district team in Kousseri. Rewrite it with a title that":"Cette diapositive sera présentée à la revue trimestrielle avec l'équipe du district de santé de Kousseri. Réécrivez-la avec un titre qui","states the result":"énonce le résultat","in 10 words or fewer and":"en 10 mots au plus et","Put the conclusion in the title, for example \"Screening back on track after the April drop\". Keep one idea per bullet and move the details to the report.":"Mettez la conclusion dans le titre, par exemple « Dépistage de nouveau dans les temps après la baisse d'avril ». Gardez une idée par puce et renvoyez les détails au rapport.","Which sentence is the best finding for a donor report?":"Quelle phrase est le meilleur constat pour un rapport au bailleur ?","The project did very well this quarter.":"Le projet a très bien fonctionné ce trimestre.","Many women took part in the savings groups.":"De nombreuses femmes ont participé aux groupes d'épargne.","1 140 women joined savings groups, 95% of the annual target, mainly in Maroua and Mokolo.":"1 140 femmes ont rejoint des groupes d'épargne, soit 95 % de la cible annuelle, principalement à Maroua et Mokolo.","Savings groups are an important activity for women's empowerment.":"Les groupes d'épargne sont une activité importante pour l'autonomisation des femmes.","It gives the result, compares it with the target and says where. The other sentences give no figure or no comparison, so the reader cannot judge progress.":"Elle donne le résultat, le compare à la cible et précise où. Les autres phrases ne donnent ni chiffre ni comparaison, donc le lecteur ne peut pas juger les progrès.","A bilingual team in Bamenda writes its report in English for the donor, but the regional delegation reads French. Prepare the one-page brief in both languages from the same figures, and have a second person check that every number is identical in the two versions.":"Une équipe bilingue de Bamenda rédige son rapport en anglais pour le bailleur, mais la délégation régionale lit le français. Préparez la note de synthèse dans les deux langues à partir des mêmes chiffres, et faites vérifier par une deuxième personne que chaque nombre est identique dans les deux versions.","Find the reporting template and deadlines in one of your current grant agreements":"Trouvez le modèle de rapport et les échéances dans l'un de vos accords de subvention en cours","Rewrite three weak sentences from an old report so each gives a result, a comparison and a reason":"Réécrivez trois phrases faibles d'un ancien rapport pour que chacune donne un résultat, une comparaison et une raison","Write a challenge paragraph that states the problem, its effect and your mitigation":"Rédigez un paragraphe de difficulté qui énonce le problème, son effet et votre mesure d'atténuation","Draft a one-page brief with a finding title, a bold key figure and three recommendations":"Rédigez une note de synthèse d'une page avec un titre-constat, un chiffre clé en gras et trois recommandations","Replace one crowded results slide with a title that states the result and four short bullets":"Remplacez une diapositive de résultats surchargée par un titre qui énonce le résultat et quatre puces courtes","Feedback and complaints mechanisms":"Mécanismes de gestion des plaintes et des retours","Choose feedback channels that suit the community and the context":"Choisir des canaux de retour adaptés à la communauté et au contexte","Separate sensitive from non-sensitive complaints and refer them correctly":"Distinguer les plaintes sensibles des non sensibles et les orienter correctement","Log, answer and analyse feedback so that the loop is closed":"Enregistrer, traiter et analyser les retours pour boucler la boucle","Accountability to affected people means that the people a project serves can influence it, question it and complain about it safely. A":"La redevabilité envers les populations affectées signifie que les personnes qu'un projet sert peuvent l'influencer, le questionner et s'en plaindre en toute sécurité. Un","feedback and complaints mechanism":"mécanisme de gestion des plaintes et des retours","is the practical system that makes this possible: channels to speak, a team that answers, and a log that turns individual messages into lessons.":"est le système concret qui le rend possible : des canaux pour s'exprimer, une équipe qui répond et un registre qui transforme les messages individuels en leçons.","Choosing channels":"Choisir les canaux","Channel":"Canal","Strengths":"Points forts","Free hotline":"Ligne téléphonique gratuite","Fast, confidential, works in several languages":"Rapide, confidentielle, fonctionne en plusieurs langues","Needs network coverage and staff to answer; many women may not own a phone":"Nécessite une couverture réseau et du personnel pour répondre ; beaucoup de femmes n'ont pas de téléphone","Suggestion boxes":"Boîtes à suggestions","Anonymous, no phone needed":"Anonymes, pas besoin de téléphone","Excludes people who cannot write; boxes must be opened on a fixed schedule by two people":"Excluent les personnes qui ne savent pas écrire ; les boîtes doivent être ouvertes selon un calendrier fixe par deux personnes","Community committees":"Comités communautaires","Trusted, reach people who do not use phones":"Dignes de confiance, touchent les personnes qui n'utilisent pas le téléphone","Members may filter out complaints about themselves or local leaders":"Les membres peuvent écarter les plaintes qui les concernent ou qui visent les autorités locales","WhatsApp or SMS number":"Numéro WhatsApp ou SMS","Cheap, allows voice notes and photos":"Peu coûteux, permet les messages vocaux et les photos","Messages stay on personal phones; set rules on who reads them and how data is protected":"Les messages restent sur des téléphones personnels ; fixez des règles sur qui les lit et comment les données sont protégées","Help desks at distributions":"Guichets d'accueil lors des distributions","Immediate answers on registration and entitlements":"Réponses immédiates sur l'enregistrement et les droits","Crowds make it hard to speak privately":"La foule empêche de parler en privé","Ask the community which channels they prefer during the design phase, and offer at least two different ones so that people without a phone, who cannot read or who fear being seen can still speak.":"Demandez à la communauté quels canaux elle préfère pendant la phase de conception, et proposez-en au moins deux différents, pour que les personnes sans téléphone, qui ne savent pas lire ou qui craignent d'être vues puissent quand même s'exprimer.","Sensitive and non-sensitive complaints":"Plaintes sensibles et non sensibles","Examples":"Exemples","Who handles it":"Qui la traite","Non-sensitive":"Non sensible","Requests for information, broken water point, missing name on a list, quality of items":"Demandes d'information, point d'eau en panne, nom absent d'une liste, qualité des articles","The programme team, with a standard response time":"L'équipe programme, avec un délai de réponse standard","Sensitive: safeguarding and PSEA":"Sensible : protection (safeguarding) et PEAS","Sexual exploitation or abuse, harassment, abuse of a child by staff, volunteers or partners":"Exploitation ou abus sexuels, harcèlement, maltraitance d'un enfant par du personnel, des bénévoles ou des partenaires","The safeguarding / PSEA focal point only, within 24 hours":"Uniquement le point focal protection / PEAS, sous 24 heures","Sensitive: fraud and misconduct":"Sensible : fraude et faute professionnelle","Theft, bribes to be registered, diversion of aid":"Vol, pots-de-vin pour être enregistré, détournement de l'aide","The compliance or fraud focal point, often at country office level":"Le point focal conformité ou fraude, souvent au niveau du bureau pays","Never investigate a sensitive complaint yourself":"N'enquêtez jamais vous-même sur une plainte sensible","Your role is to receive the complaint respectfully, record only the essential facts, ensure the person's safety and refer immediately and confidentially. Do not question the alleged perpetrator, do not look for witnesses and do not share names with colleagues.":"Votre rôle est de recevoir la plainte avec respect, de n'enregistrer que les faits essentiels, d'assurer la sécurité de la personne et d'orienter immédiatement et en toute confidentialité. N'interrogez pas l'auteur présumé, ne cherchez pas de témoins et ne communiquez pas de noms à vos collègues.","Classify the complaints":"Classer les plaintes","A food security project in Garoua-Boulaï received these messages this week. Choose how each one must be handled.":"Un projet de sécurité alimentaire à Garoua-Boulaï a reçu ces messages cette semaine. Choisissez comment chacun doit être traité.","Ask two questions: could the person or someone else be harmed (abuse, exploitation), and does it involve theft, bribes or diversion? If neither, the programme team responds.":"Posez deux questions : la personne ou quelqu'un d'autre pourrait-il subir un préjudice (abus, exploitation), et s'agit-il de vol, de pots-de-vin ou de détournement ? Si ce n'est ni l'un ni l'autre, l'équipe programme répond.","\"The water point near the market has been broken for two weeks.\"":"« Le point d'eau près du marché est en panne depuis deux semaines. »","An operational problem: log it, pass it to the WASH team and tell the community when it will be repaired.":"Un problème opérationnel : enregistrez-le, transmettez-le à l'équipe WASH et dites à la communauté quand il sera réparé.","Non-sensitive: the programme team responds":"Non sensible : l'équipe programme répond","Sensitive: refer to the safeguarding / PSEA focal point":"Sensible : orienter vers le point focal protection / PEAS","Sensitive: refer to the fraud and compliance focal point":"Sensible : orienter vers le point focal fraude et conformité","\"A volunteer who distributes vouchers asked my daughter to meet him at night for an extra ration.\"":"« Un bénévole qui distribue les bons a demandé à ma fille de le retrouver la nuit en échange d'une ration supplémentaire. »","A possible case of sexual exploitation of a minor. Refer it at once to the PSEA focal point and ensure the girl's safety; do not investigate.":"Un cas possible d'exploitation sexuelle d'une mineure. Orientez-le immédiatement vers le point focal PEAS et assurez la sécurité de la fille ; n'enquêtez pas.","\"My name is not on the distribution list although I was registered in March.\"":"« Mon nom ne figure pas sur la liste de distribution alors que j'ai été enregistrée en mars. »","A registration issue the programme team can check against the database.":"Un problème d'enregistrement que l'équipe programme peut vérifier dans la base de données.","\"The warehouse keeper sells bags of rice at the market on Saturdays.\"":"« Le magasinier vend des sacs de riz au marché le samedi. »","Possible diversion of aid. It goes to the fraud and compliance focal point, not to the warehouse manager.":"Un détournement possible de l'aide. Le cas va au point focal fraude et conformité, pas au responsable de l'entrepôt.","\"A teacher paid by the project beats the pupils with a stick.\"":"« Un enseignant payé par le projet frappe les élèves avec un bâton. »","Physical abuse of children by someone linked to the project is a safeguarding case.":"La violence physique envers des enfants par une personne liée au projet relève de la protection (safeguarding).","\"Why do the hygiene kits no longer contain soap?\"":"« Pourquoi les kits d'hygiène ne contiennent-ils plus de savon ? »","A question about the content of kits: answer it and check whether the specification changed.":"Une question sur le contenu des kits : répondez-y et vérifiez si la spécification a changé.","Response times and closing the loop":"Délais de réponse et bouclage de la boucle","From message to closed case":"Du message au cas clôturé","Acknowledge receipt, ideally within 48 hours, and give the case number.":"Accusez réception, idéalement sous 48 heures, et donnez le numéro du cas.","Log the case the same day: date, channel, type, location, sex and age group, sensitive or not.":"Enregistrez le cas le jour même : date, canal, type, lieu, sexe et tranche d'âge, sensible ou non.","Refer sensitive cases immediately; assign others to the responsible team.":"Orientez immédiatement les cas sensibles ; attribuez les autres à l'équipe responsable.","Answer the person within the standard time, for example 7 days, even if the answer is \"not possible\".":"Répondez à la personne dans le délai standard, par exemple 7 jours, même si la réponse est « ce n'est pas possible ».","Close the case in the log and record whether the person was satisfied with the answer.":"Clôturez le cas dans le registre et notez si la personne était satisfaite de la réponse.","Share what changed with the whole community, for example at a committee meeting.":"Partagez ce qui a changé avec toute la communauté, par exemple lors d'une réunion du comité.","Closing the loop":"Boucler la boucle","A mechanism that receives messages but never answers destroys trust faster than having no mechanism at all. Tell people what happened, including when their request could not be met.":"Un mécanisme qui reçoit des messages sans jamais répondre détruit la confiance plus vite que l'absence de mécanisme. Dites aux gens ce qui s'est passé, y compris quand leur demande n'a pas pu être satisfaite.","Analysing the feedback log":"Analyser le registre des retours","Tables":"Tableaux","Useful for counting cases by channel, type or site when the log has hundreds of rows.":"Utile pour compter les cas par canal, type ou site quand le registre compte des centaines de lignes.","Analyse a feedback log":"Analyser un registre des retours","The standard response time is":"Le délai de réponse standard est de","7 days":"7 jours","with the number of hotline cases,":"avec le nombre de cas reçus par la ligne téléphonique,","with the complaints received by hotline,":"avec les plaintes reçues par la ligne téléphonique,","with the number of closed cases and":"avec le nombre de cas clôturés et","with the share of all cases closed within 7 days.":"avec la part de l'ensemble des cas clôturés en 7 jours ou moins.","H2 is a COUNTIF on the channel column. H3 needs two conditions: =COUNTIFS(B2:B10,\"Hotline\",C2:C10,\"Complaint\"). For H5, count cases that are Closed and have \"<=7\" days, then divide by all cases with COUNTA(A2:A10).":"H2 est un COUNTIF (NB.SI) sur la colonne des canaux. H3 demande deux conditions : =COUNTIFS(B2:B10,\"Hotline\",C2:C10,\"Complaint\") (NB.SI.ENS). Pour H5, comptez les cas qui sont Closed et ont \"<=7\" jours, puis divisez par l'ensemble des cas avec COUNTA(A2:A10) (NBVAL).","Look beyond the counts: which sites send no feedback at all, which topics come back every month, and whether women and people with disabilities use the channels. Silence from a group is a finding too.":"Allez au-delà des chiffres : quels sites n'envoient aucun retour, quels sujets reviennent chaque mois, et si les femmes et les personnes handicapées utilisent les canaux. Le silence d'un groupe est aussi un constat.","During a monitoring visit, a woman tells you privately that a partner staff member asked her for money to put her on the cash transfer list. What do you do?":"Lors d'une visite de suivi, une femme vous dit en privé qu'un employé d'un partenaire lui a demandé de l'argent pour l'inscrire sur la liste des transferts monétaires. Que faites-vous ?","Ask the staff member for his version of the story":"Demander à l'employé sa version des faits","Record the essential facts, reassure her and refer the case to the fraud and compliance focal point":"Noter les faits essentiels, la rassurer et orienter le cas vers le point focal fraude et conformité","Wait to see if other people make the same complaint":"Attendre de voir si d'autres personnes font la même plainte","Tell her to use the suggestion box":"Lui dire d'utiliser la boîte à suggestions","A bribe for registration is a sensitive complaint. Record only what is needed, protect her identity and refer it the same day. Investigating yourself could put her at risk and damage the case.":"Un pot-de-vin pour l'enregistrement est une plainte sensible. N'enregistrez que le nécessaire, protégez son identité et orientez le cas le jour même. Enquêter vous-même pourrait la mettre en danger et compromettre le dossier.","In an IDP site near Mora, the complaints box was opened only when the project officer visited, about once a month, and people stopped using it. The team switched to a weekly opening by two people, a free hotline in Fulfulde and French, and a monthly \"you said, we did\" board at the distribution point. Feedback tripled in two months.":"Dans un site de personnes déplacées internes près de Mora, la boîte à plaintes n'était ouverte que lors des visites du chargé de projet, environ une fois par mois, et les gens ont cessé de l'utiliser. L'équipe est passée à une ouverture hebdomadaire par deux personnes, à une ligne gratuite en fulfuldé et en français, et à un tableau mensuel « Vous avez dit, nous avons fait » au point de distribution. Les retours ont triplé en deux mois.","List the feedback channels your project offers and who in the community cannot use each one":"Listez les canaux de retour que propose votre projet et, pour chacun, qui dans la communauté ne peut pas l'utiliser","Write down the name and contact of your organisation's safeguarding / PSEA focal point":"Notez le nom et les coordonnées du point focal protection / PEAS de votre organisation","Set up a feedback log with columns for date, channel, type, sensitivity, status and days to close":"Créez un registre des retours avec des colonnes pour la date, le canal, le type, la sensibilité, le statut et le nombre de jours avant clôture","Calculate last month's % of cases closed within the response time":"Calculez le % de cas clôturés dans le délai de réponse le mois dernier","Prepare a short \"you said, we did\" message for the next community meeting":"Préparez un court message « Vous avez dit, nous avons fait » pour la prochaine réunion communautaire","Evaluation, learning and adaptive management":"Évaluation, apprentissage et gestion adaptative","Distinguish baseline, midterm, final and real-time evaluations":"Distinguer les évaluations de référence, à mi-parcours, finales et en temps réel","Match evaluation questions to the six OECD-DAC criteria":"Associer les questions d'évaluation aux six critères du CAD de l'OCDE","Run a pause-and-reflect session and turn learning into project adaptations":"Animer une séance de pause et réflexion et transformer l'apprentissage en adaptations du projet","Monitoring tells you what is happening; evaluation asks whether it is the right thing, done well, and whether it lasts. Learning closes the circle: the team uses both to change what it does. This last lesson connects the three.":"Le suivi vous dit ce qui se passe ; l'évaluation demande si c'est la bonne chose, bien faite, et si cela dure. L'apprentissage boucle le cercle : l'équipe utilise les deux pour changer ce qu'elle fait. Cette dernière leçon relie les trois.","Types of evaluation":"Types d'évaluation","Main purpose":"Objectif principal","Baseline study":"Étude de référence","Before or at the very start of activities":"Avant ou tout au début des activités","Measure starting values and set realistic targets":"Mesurer les valeurs de départ et fixer des cibles réalistes","Midterm evaluation":"Évaluation à mi-parcours","Around the middle of the project":"Vers le milieu du projet","Check progress and correct the course while there is time":"Vérifier les progrès et corriger le cap tant qu'il est temps","At or after the end":"À la fin ou après la fin","Judge results, accountability to donors, lessons for future projects":"Juger les résultats, rendre compte aux bailleurs, tirer des leçons pour les projets futurs","Real-time evaluation":"Évaluation en temps réel","In the first weeks or months of an emergency response":"Dans les premières semaines ou les premiers mois d'une réponse d'urgence","Give rapid feedback to managers while decisions are still being made":"Donner un retour rapide aux responsables pendant que les décisions sont encore en cours","Evaluations can be internal (run by your own MEAL team) or external (run by an independent consultant). External evaluations are more credible to donors; internal ones are cheaper and often more useful for learning.":"Les évaluations peuvent être internes (menées par votre propre équipe MEAL) ou externes (menées par un consultant indépendant). Les évaluations externes sont plus crédibles pour les bailleurs ; les internes coûtent moins cher et sont souvent plus utiles pour l'apprentissage.","The six OECD-DAC criteria":"Les six critères du CAD de l'OCDE","Core question":"Question centrale","Example question for a WASH project":"Exemple de question pour un projet WASH","Relevance":"Pertinence","Is the intervention doing the right things?":"L'intervention fait-elle ce qu'il faut ?","Did the choice of water points match what households said they needed most?":"Le choix des points d'eau correspondait-il à ce que les ménages disaient être leur besoin principal ?","Coherence":"Cohérence","How well does it fit with other interventions?":"L'intervention s'accorde-t-elle avec les autres interventions ?","Did the project work with the commune's water plan and other NGOs in the area?":"Le projet a-t-il travaillé avec le plan communal de l'eau et les autres ONG de la zone ?","Effectiveness":"Efficacité","Is it achieving its objectives?":"Atteint-elle ses objectifs ?","Did the share of households using safe water reach the 80% target?":"La part des ménages utilisant de l'eau potable a-t-elle atteint la cible de 80 % ?","Efficiency":"Efficience","How well are resources used?":"Les ressources sont-elles bien utilisées ?","What did each rehabilitated water point cost compared with similar projects?":"Combien a coûté chaque point d'eau réhabilité par rapport à des projets similaires ?","What difference does it make?":"Quelle différence fait-elle ?","Did diarrhoea cases among children under five fall in the served villages?":"Les cas de diarrhée chez les enfants de moins de cinq ans ont-ils diminué dans les villages desservis ?","Sustainability":"Durabilité","Will the benefits last?":"Les bénéfices vont-ils durer ?","Are water committees still collecting fees and repairing pumps a year later?":"Les comités de gestion de l'eau collectent-ils encore les cotisations et réparent-ils les pompes un an plus tard ?","Match questions to OECD-DAC criteria":"Associer les questions aux critères du CAD de l'OCDE","An external team is preparing the final evaluation of a youth employment project in Douala and Yaoundé. Choose the criterion each question belongs to.":"Une équipe externe prépare l'évaluation finale d'un projet d'emploi des jeunes à Douala et Yaoundé. Choisissez le critère auquel appartient chaque question.","Relevance is about needs, coherence about fit with others, effectiveness about objectives, efficiency about resources, impact about wider and longer-term change, sustainability about what continues after funding ends.":"La pertinence porte sur les besoins, la cohérence sur l'articulation avec les autres, l'efficacité sur les objectifs, l'efficience sur les ressources, l'impact sur les changements plus larges et à plus long terme, la durabilité sur ce qui continue après la fin du financement.","Were the trades taught (tailoring, phone repair, welding) those most in demand by local employers?":"Les métiers enseignés (couture, réparation de téléphones, soudure) étaient-ils les plus demandés par les employeurs locaux ?","Did the project duplicate the vocational training offered by the national employment fund?":"Le projet a-t-il fait double emploi avec la formation professionnelle proposée par le fonds national de l'emploi ?","Fit with other programmes in the same area is coherence.":"L'articulation avec les autres programmes de la même zone relève de la cohérence.","Did 60% of graduates find paid work within six months, as planned?":"60 % des diplômés ont-ils trouvé un emploi rémunéré dans les six mois, comme prévu ?","Was the cost per graduate reasonable compared with similar programmes?":"Le coût par diplômé était-il raisonnable par rapport à des programmes similaires ?","Has youth income in the target neighbourhoods changed, including for young people who were not trained?":"Le revenu des jeunes dans les quartiers ciblés a-t-il changé, y compris pour les jeunes qui n'ont pas été formés ?","Wider and indirect effects, positive or negative, belong to impact.":"Les effets plus larges et indirects, positifs ou négatifs, relèvent de l'impact.","Will the training centres keep running the courses after the grant ends?":"Les centres de formation continueront-ils à assurer les cours après la fin de la subvention ?","Three weeks after floods in Douala, the director wants quick feedback on the emergency response while it is still running. Which evaluation is this?":"Trois semaines après des inondations à Douala, le directeur veut un retour rapide sur la réponse d'urgence pendant qu'elle est encore en cours. De quelle évaluation s'agit-il ?","A real-time evaluation gives rapid feedback early in an emergency, when decisions can still change.":"Une évaluation en temps réel donne un retour rapide au début d'une urgence, quand les décisions peuvent encore changer.","Learning questions and pause-and-reflect":"Questions d'apprentissage et pause et réflexion","Learning questions are the few things the team most needs to understand, written at the start of the project. For example: \"Why do some mothers stop attending the nutrition sessions after the second month?\" Monitoring data, visits and feedback are then used to answer them.":"Les questions d'apprentissage sont les quelques points que l'équipe a le plus besoin de comprendre, écrits au début du projet. Par exemple : « Pourquoi certaines mères cessent-elles de venir aux séances de nutrition après le deuxième mois ? » Les données de suivi, les visites et les retours servent ensuite à y répondre.","Run an after-action review in one hour":"Mener une revue après action en une heure","What did we plan to happen?":"Qu'avions-nous prévu ?","What actually happened? Use the ITT, feedback log and field notes.":"Que s'est-il réellement passé ? Utilisez l'ITT, le registre des retours et les notes de terrain.","Why was there a difference?":"Pourquoi y a-t-il eu une différence ?","What will we keep doing, and what will we change? Name a person and a date for each change.":"Que continuerons-nous à faire, et que changerons-nous ? Nommez une personne et une date pour chaque changement.","Keep it safe to speak":"Faire en sorte que chacun puisse parler sans crainte","An after-action review is not an inspection. The most senior person should speak last, and the notes should record lessons, not blame.":"Une revue après action n'est pas une inspection. La personne la plus haut placée doit parler en dernier, et les notes doivent consigner des leçons, pas des reproches.","Using data to adapt":"Utiliser les données pour s'adapter","Adaptive management means changing activities, targets or methods when evidence shows the plan is not working. Record every decision in an action log with the evidence, the change, the owner and the deadline, and inform the donor when a change affects the budget or the logframe.":"La gestion adaptative consiste à modifier les activités, les cibles ou les méthodes quand les données montrent que le plan ne fonctionne pas. Consignez chaque décision dans un journal des actions avec les éléments probants, le changement, le responsable et l'échéance, et informez le bailleur quand un changement touche le budget ou le cadre logique.","In Excel, filter the action log by status to see which adaptations are still open.":"Dans Excel, filtrez le journal des actions par statut pour voir quelles adaptations sont encore ouvertes.","Midterm monitoring shows that only 40% of women beneficiaries collect their cash, because the only pay point is 15 km away. What is the best adaptive response?":"Le suivi à mi-parcours montre que seules 40 % des femmes bénéficiaires retirent leur transfert, car le seul point de paiement est à 15 km. Quelle est la meilleure réponse adaptative ?","Keep the plan and explain the gap in the final report":"Garder le plan et expliquer l'écart dans le rapport final","Lower the target to 40%":"Abaisser la cible à 40 %","Add a mobile pay point or mobile money option, record the decision and inform the donor":"Ajouter un point de paiement mobile ou une option de mobile money, consigner la décision et informer le bailleur","Remove women from the beneficiary list":"Retirer les femmes de la liste des bénéficiaires","The evidence points to a clear barrier that the project can remove. Changing the delivery method, documenting why and informing the donor is adaptive management.":"Les données désignent un obstacle clair que le projet peut lever. Changer le mode de distribution, documenter pourquoi et informer le bailleur, c'est de la gestion adaptative.","A livelihoods project in the West region holds a pause-and-reflect session every quarter with field staff, two farmer group leaders and the MEAL officer. In one session, the team learned that trainings clashed with market days; moving them to Tuesdays raised attendance from 55% to 80%.":"Un projet de moyens d'existence dans la région de l'Ouest tient chaque trimestre une séance de pause et réflexion avec le personnel de terrain, deux responsables de groupements de producteurs et le chargé MEAL. Lors d'une séance, l'équipe a appris que les formations tombaient les jours de marché ; les déplacer au mardi a fait passer la participation de 55 % à 80 %.","Write two learning questions for a project you know":"Rédigez deux questions d'apprentissage pour un projet que vous connaissez","Draft one evaluation question for each OECD-DAC criterion for that project":"Rédigez une question d'évaluation pour chaque critère du CAD de l'OCDE pour ce projet","Plan a one-hour after-action review with its four questions and a list of participants":"Préparez une revue après action d'une heure avec ses quatre questions et une liste de participants","Create an action log with columns for evidence, decision, owner, deadline and status":"Créez un journal des actions avec des colonnes pour les éléments probants, la décision, le responsable, l'échéance et le statut","Identify one change in your project that should be reported to the donor":"Identifiez un changement dans votre projet qui devrait être signalé au bailleur","Applying evaluation criteria thoughtfully":"Appliquer les critères d'évaluation de manière réfléchie","Practice lab: reporting, accountability and learning":"Atelier pratique : rapportage, redevabilité et apprentissage","Calculate % of target and count indicators that reach a threshold":"Calculer le % de la cible et compter les indicateurs qui atteignent un seuil","Format a donor progress report section":"Mettre en forme une section de rapport d'avancement pour un bailleur","Make accountability and adaptation decisions and write the formulas behind them":"Prendre des décisions de redevabilité et d'adaptation et écrire les formules qui les sous-tendent","Build an indicator tracking table that handles missing data and rate indicators":"Construire un tableau de suivi des indicateurs qui gère les données manquantes et les indicateurs de taux","Exercise 1: Livelihoods results in Mokolo":"Exercice 1 : résultats en moyens d'existence à Mokolo","with the % of target achieved for each indicator, then":"avec le % de la cible atteint pour chaque indicateur, puis","with the number of indicators that reached at least 90% of their target.":"avec le nombre d'indicateurs qui ont atteint au moins 90 % de leur cible.","D2 is =C2/B2; copy it down. D6 counts the cells of D2:D5 that are at least 0.9: =COUNTIF(D2:D5,\">=0.9\").":"D2 est =C2/B2 ; recopiez vers le bas. D6 compte les cellules de D2:D5 qui valent au moins 0,9 : =COUNTIF(D2:D5,\">=0.9\") (NB.SI).","Exercise 2: A quarterly report for the donor":"Exercice 2 : un rapport trimestriel pour le bailleur","Format a progress report section":"Mettre en forme une section de rapport d'avancement","centre":"centrez","it,":"le titre,","right-align":"alignez à droite","the reporting period, make \"Executive summary\", \"Challenges\" and \"Next steps\"":"la période de rapport, appliquez à « Executive summary », « Challenges » et « Next steps » le style","the first summary paragraph, make \"78% of girls surveyed\"":"le premier paragraphe du résumé, mettez « 78% of girls surveyed » en",", and turn the three next steps into a":", et transformez les trois prochaines étapes en","Work from top to bottom. Click inside a paragraph before choosing an alignment; select the three next-step lines together before clicking Numbering.":"Travaillez de haut en bas. Cliquez dans un paragraphe avant de choisir un alignement ; sélectionnez ensemble les trois lignes de prochaines étapes avant de cliquer sur Numérotation.","Exercise 3: Midterm decisions in a cash transfer project":"Exercice 3 : décisions à mi-parcours dans un projet de transferts monétaires","Accountability and adaptation decisions":"Décisions de redevabilité et d'adaptation","A cash transfer project for displaced households in the South-West region is at midterm. Answer each question. Type formulas in English with commas, starting with =.":"Un projet de transferts monétaires pour des ménages déplacés dans la région du Sud-Ouest est à mi-parcours. Répondez à chaque question. Tapez les formules en anglais avec des virgules, en commençant par =.","Sensitive cases go to a focal point, never to the person's manager. For the formulas, COUNTIFS takes pairs of range and criterion; % of target divides what was achieved by the target.":"Les cas sensibles vont à un point focal, jamais au supérieur hiérarchique de la personne en cause. Pour les formules, COUNTIFS (NB.SI.ENS) prend des paires plage et critère ; le % de la cible divise ce qui a été réalisé par la cible.","The feedback log has the channel in B2:B150 and the status in D2:D150. Type the formula that counts closed cases received by WhatsApp.":"Dans le registre des retours, le canal est en B2:B150 et le statut en D2:D150. Tapez la formule qui compte les cas clôturés reçus par WhatsApp.","Each range is followed by its criterion; the order of the pairs does not matter.":"Chaque plage est suivie de son critère ; l'ordre des paires n'a pas d'importance.","In the ITT, the cumulative value is in F7 and the annual target in B7. Type the formula for % achieved.":"Dans l'ITT, le cumul est en F7 et la cible annuelle en B7. Tapez la formule du % réalisé.","A woman calls the hotline: a community mobiliser demands part of her transfer every month or he will remove her from the list. Who handles this?":"Une femme appelle la ligne téléphonique : un mobilisateur communautaire exige une partie de son transfert chaque mois, sinon il la retirera de la liste. Qui traite ce cas ?","Extortion of aid is misconduct and fraud. Refer it confidentially; the supervisor may be close to the mobiliser.":"L'extorsion de l'aide est une faute professionnelle et une fraude. Orientez le cas en toute confidentialité ; le superviseur peut être proche du mobilisateur.","The mobiliser's supervisor":"Le superviseur du mobilisateur","The fraud and compliance focal point, with the PSEA focal point informed if there is any sexual element":"Le point focal fraude et conformité, en informant le point focal PEAS s'il y a une dimension sexuelle","The community committee":"Le comité communautaire","The MEAL officer, who investigates first":"Le chargé MEAL, qui enquête d'abord","Monitoring shows that 35% of recipients in Kumba spend a day travelling to the only cash agent. What is the best decision?":"Le suivi montre que 35 % des bénéficiaires de Kumba passent une journée à se rendre chez le seul agent de paiement. Quelle est la meilleure décision ?","Lower the target for Kumba":"Abaisser la cible pour Kumba","Add a second agent or a mobile money option, record the decision in the action log and inform the donor":"Ajouter un deuxième agent ou une option de mobile money, consigner la décision dans le journal des actions et informer le bailleur","Wait for the final evaluation":"Attendre l'évaluation finale","Stop transfers in Kumba":"Arrêter les transferts à Kumba","The evaluation team asks: \"Were the transfer amounts enough to cover the minimum expenditure basket in local markets?\" Which criterion is this?":"L'équipe d'évaluation demande : « Les montants des transferts suffisaient-ils à couvrir le panier de dépenses minimum sur les marchés locaux ? » De quel critère s'agit-il ?","Whether the design matches people's needs is relevance.":"Savoir si la conception répond aux besoins des personnes relève de la pertinence.","Another question: \"Did the project align its transfer amount with the other cash actors in the region?\" Which criterion?":"Autre question : « Le projet a-t-il aligné le montant de son transfert sur celui des autres acteurs des transferts monétaires de la région ? » Quel critère ?","The feedback log shows 40 cases but none from households headed by people with disabilities. What does this most likely mean?":"Le registre des retours compte 40 cas, mais aucun venant de ménages dirigés par des personnes handicapées. Qu'est-ce que cela signifie le plus probablement ?","Silence from a group is a finding. Test whether the channels reach them, for example through home visits or disability organisations.":"Le silence d'un groupe est un constat. Vérifiez si les canaux les atteignent, par exemple par des visites à domicile ou via des organisations de personnes handicapées.","These households are fully satisfied":"Ces ménages sont entièrement satisfaits","The channels may not be accessible to them; check and adapt the channels":"Les canaux ne leur sont peut-être pas accessibles ; vérifiez et adaptez les canaux","The log is complete":"Le registre est complet","Their feedback is not important for the report":"Leurs retours ne sont pas importants pour le rapport","Exercise 4: A nutrition ITT with traps":"Exercice 4 : un ITT nutrition avec des pièges","Indicator tracking table with missing data":"Tableau de suivi des indicateurs avec données manquantes","Three quarters have been reported in the Logone nutrition project. Fill":"Trois trimestres ont été rapportés dans le projet nutrition du Logone. Remplissez","with the value to date: the sum of the quarters, except for the rate indicator in row 4, where you report the":"avec la valeur à date : la somme des trimestres, sauf pour l'indicateur de taux de la ligne 4, pour lequel vous indiquez le","latest":"dernier","quarter. Fill":"trimestre. Remplissez","with the % of the annual target. In":"avec le % de la cible annuelle. Dans",", write \"Data missing\" if any quarter is empty, otherwise \"On track\" when % of target is at least 75% and \"Behind\" when it is not. In":", écrivez « Data missing » si un trimestre est vide, sinon « On track » quand le % de la cible est d'au moins 75 % et « Behind » dans le cas contraire. Dans",", count the indicators on track.":", comptez les indicateurs « On track ».","Row 4 is a rate: F4 is simply =E4, never a sum. The 0 in row 5 is a real result, not missing data, while the empty Q3 in row 3 is missing. Test for missing quarters with COUNTBLANK: =IF(COUNTBLANK(C2:E2)>0,\"Data missing\",IF(G2>=0.75,\"On track\",\"Behind\")). H6 is a COUNTIF on H2:H5.":"La ligne 4 est un taux : F4 est simplement =E4, jamais une somme. Le 0 de la ligne 5 est un vrai résultat, pas une donnée manquante, tandis que le T3 vide de la ligne 3 est manquant. Détectez les trimestres manquants avec COUNTBLANK (NB.VIDE) : =IF(COUNTBLANK(C2:E2)>0,\"Data missing\",IF(G2>=0.75,\"On track\",\"Behind\")). H6 est un COUNTIF (NB.SI) sur H2:H5.","In an ITT, a quarterly indicator shows 110 latrines built against an annual target of 400 after Q1 to Q3 totals of 80, 120 and 110. What is the % achieved?":"Dans un ITT, un indicateur trimestriel affiche 110 latrines construites pour une cible annuelle de 400, après des totaux de 80, 120 et 110 du T1 au T3. Quel est le % réalisé ?","The cumulative is 80 + 120 + 110 = 310, and 310 ÷ 400 = 77.5%. Dividing only the last quarter by the target gives 27.5%, which is wrong.":"Le cumul est 80 + 120 + 110 = 310, et 310 ÷ 400 = 77,5 %. Diviser seulement le dernier trimestre par la cible donne 27,5 %, ce qui est faux.","Which indicator should NOT be summed across quarters?":"Quel indicateur ne faut-il PAS additionner d'un trimestre à l'autre ?","Number of people trained":"Nombre de personnes formées","Number of latrines built":"Nombre de latrines construites","% of schools with a functional water point":"% d'écoles disposant d'un point d'eau fonctionnel","A percentage is a rate: report the latest value or recalculate it from the underlying counts.":"Un pourcentage est un taux : indiquez la dernière valeur ou recalculez-le à partir des effectifs de base.","What does a good finding in a donor report contain?":"Que contient un bon constat dans un rapport au bailleur ?","The result, a comparison and, when known, the reason":"Le résultat, une comparaison et, quand on la connaît, la raison","Only the activities carried out":"Seulement les activités réalisées","Positive news only":"Uniquement les bonnes nouvelles","A description of the team":"Une description de l'équipe","A result compared with a target, baseline or earlier period, plus the reason, lets the reader judge progress.":"Un résultat comparé à une cible, à la situation de référence ou à une période antérieure, avec la raison, permet au lecteur de juger les progrès.","What is the main purpose of a one-page brief?":"Quel est l'objectif principal d'une note de synthèse d'une page ?","To replace the financial report":"Remplacer le rapport financier","To give decision-makers the key finding and recommendations quickly":"Donner rapidement aux décideurs le constat clé et les recommandations","To list every activity of the quarter":"Lister toutes les activités du trimestre","To store raw data":"Stocker les données brutes","A brief is short and action-oriented: a finding title, a key figure and a few recommendations.":"Une note de synthèse est courte et orientée vers l'action : un titre-constat, un chiffre clé et quelques recommandations.","A community member reports that a volunteer asked for sex in exchange for food. What is the correct first step?":"Un membre de la communauté signale qu'un bénévole a demandé des rapports sexuels en échange de nourriture. Quelle est la bonne première étape ?","Ask the volunteer to explain":"Demander au bénévole de s'expliquer","Discuss it at the next committee meeting":"En discuter à la prochaine réunion du comité","Wait for more complaints":"Attendre d'autres plaintes","Record the essential facts and refer it immediately to the PSEA focal point":"Noter les faits essentiels et orienter immédiatement le cas vers le point focal PEAS","Sexual exploitation is a sensitive complaint: ensure safety, record only essentials and refer confidentially, without investigating.":"L'exploitation sexuelle est une plainte sensible : assurez la sécurité, n'enregistrez que l'essentiel et orientez en toute confidentialité, sans enquêter.","What does \"closing the loop\" mean in a feedback mechanism?":"Que signifie « boucler la boucle » dans un mécanisme de retour ?","Locking the complaints box":"Verrouiller la boîte à plaintes","Deleting old cases from the log":"Supprimer les anciens cas du registre","Telling the person, and the community, what was done in response":"Dire à la personne, et à la communauté, ce qui a été fait en réponse","Sending the log to the donor":"Envoyer le registre au bailleur","People need to hear the answer, even when their request cannot be met, or they stop using the mechanism.":"Les gens ont besoin d'entendre la réponse, même quand leur demande ne peut pas être satisfaite, sinon ils cessent d'utiliser le mécanisme.","\"Will the water committees keep repairing the pumps after the project ends?\" belongs to which OECD-DAC criterion?":"« Les comités de gestion de l'eau continueront-ils à réparer les pompes après la fin du projet ? » relève de quel critère du CAD de l'OCDE ?","Whether benefits continue after funding ends is sustainability.":"Savoir si les bénéfices se poursuivent après la fin du financement relève de la durabilité.","Which is an example of adaptive management?":"Lequel de ces exemples relève de la gestion adaptative ?","Moving trainings away from market days after attendance data showed a clash, and recording the decision":"Déplacer les formations en dehors des jours de marché après que les données de participation ont montré un conflit, et consigner la décision","Keeping the original plan whatever the data shows":"Garder le plan initial quoi que montrent les données","Changing indicators without telling the donor":"Modifier les indicateurs sans prévenir le bailleur","Collecting more data without looking at it":"Collecter plus de données sans les regarder","Adaptive management uses evidence to change activities, documents the decision and informs the donor when needed.":"La gestion adaptative utilise les données pour modifier les activités, documente la décision et informe le bailleur si nécessaire.","XLSForm lab":"Atelier XLSForm","Form preview":"Aperçu du formulaire","Clear answers":"Effacer les réponses","Add a row":"Ajouter une ligne","Refer to other questions as":"Faites référence aux autres questions avec",". In a constraint, the dot":". Dans une contrainte, le point","is the answer being checked. Cells with a formula error turn red.":"représente la réponse vérifiée. Les cellules contenant une formule erronée deviennent rouges.","Calculated values":"Valeurs calculées","Your form works. Try it in the preview.":"Votre formulaire fonctionne. Essayez-le dans l'aperçu.","Sheets":"Feuilles","Monitoring, Evaluation, Accountability and Learning for development and humanitarian programmes":"Suivi, évaluation, redevabilité et apprentissage pour les programmes de développement et humanitaires","MEAL Professional Certificate":"Certificat professionnel MEAL"};
function applyPatches(read, patches = PATCHES) {
  const out = {}, problems = [];
  for (const [file, find, repl] of patches) {
    const src = out[file] ?? read(file);
    if (src == null) { problems.push(`${file}: file not found`); continue; }
    const n = src.split(find).length - 1;
    if (n !== 1) { problems.push(`${file}: expected 1 match, found ${n} for: ${find.split("\n")[0].slice(0, 70)}`); out[file] = src; continue; }
    out[file] = src.replace(find, () => repl);
  }
  return { out, problems };
}

const crlf = {};
const read = (f) => { if (!existsSync(f)) return null; const s = readFileSync(f, "utf-8"); crlf[f] = s.includes("\r\n"); return s.replace(/\r\n/g, "\n"); };
const { out, problems } = applyPatches(read, PATCHES);
if (problems.length) fail("these files are not in the expected state:\n  " + problems.join("\n  ") + "\nSend me this message.");

// Catalogue: Module 5 now includes Stata (optional — only if the new MEAL curriculum is installed)
const ACAD = "client/src/pages/public/AcademyPage.tsx";
let acadNote = "NOTE catalogue Module 5 not renamed (run update-meal-curriculum.mjs first if you want it)";
if (existsSync(ACAD)) {
  let a = read(ACAD);
  const pairs = [['title: "Data Analysis with Excel and SPSS"', 'title: "Data Analysis with Excel, SPSS and Stata"'], ['"Descriptive statistics and cross-tabulations in Excel and SPSS"', '"Descriptive statistics and cross-tabulations in Excel, SPSS and Stata"']];
  if (a.includes(pairs[0][1])) acadNote = "OK catalogue Module 5 already says Excel, SPSS and Stata";
  else if (pairs.every(([x]) => a.split(x).length === 2)) { for (const [x, y] of pairs) a = a.replace(x, y); out[ACAD] = a; acadNote = "OK catalogue Module 5 renamed: Data Analysis with Excel, SPSS and Stata"; }
}

const frPath = "client/src/i18n/fr.ts";
let frSrc = null, added = 0;
if (existsSync(frPath)) {
  frSrc = read(frPath);
  const end = frSrc.lastIndexOf("};");
  if (end === -1) fail(frPath + ": could not find the end of the FR object");
  const nb = "\u00a0";
  const typo = (t) => t.replace(/ ([:;?!»])/g, nb + "$1").replace(/« /g, "«" + nb);
  const lines = [];
  for (const [k, v] of Object.entries(FR)) {
    if (k === v || frSrc.includes(JSON.stringify(k) + ":")) continue;
    lines.push("  " + JSON.stringify(k) + ": " + JSON.stringify(typo(v)) + ",");
    added++;
  }
  frSrc = frSrc.slice(0, end) + "  // ---- MEAL course ----\n" + lines.join("\n") + "\n" + frSrc.slice(end);
}
const eol = (f, s) => (crlf[f] ? s.replace(/\n/g, "\r\n") : s);
for (const [f, c] of Object.entries(TEXT)) { mkdirSync(dirname(f), { recursive: true }); writeFileSync(f, c, "utf-8"); }
for (const [f, b64] of Object.entries(BIN)) { mkdirSync(dirname(f), { recursive: true }); writeFileSync(f, Buffer.from(b64, "base64")); }
for (const [f, c] of Object.entries(out)) writeFileSync(f, eol(f, c), "utf-8");
if (frSrc) writeFileSync(frPath, eol(frPath, frSrc), "utf-8");
console.log("OK MEAL course added at /learn/meal: 6 modules, 24 lessons, 6 practice labs (24 exercises), 6 quizzes");
console.log("OK new XLSForm lab (KoboToolbox / ODK form builder with live preview)");
console.log("OK intro videos: client/public/media/meal-intro-en.mp4 and meal-intro-fr.mp4");
console.log(acadNote);
console.log(frSrc ? "OK " + added + " French translations added" : "NOTE French not added (translation not installed)");
